def perform_dead_code_elimination(node):
    import ast

    # recursive AST traversal to perform reaching definitions analysis
    class DefinitionFinder(ast.NodeVisitor):
        def __init__(self):
            self.defs = {}

        def visit_FunctionDef(self, node):
            self.defs = {}
            for arg in node.args.args:
                self.defs[arg.arg] = arg
            self.generic_visit(node)

        def visit_ListComp(self, node):
            for gen in node.generators:
                self.defs[gen.target.id] = gen.target
            self.generic_visit(node)

        def visit_comprehension(self, node):
            self.defs[node.target.id] = node.target
            self.generic_visit(node)

        def visit_Assign(self, node):
            for target in node.targets:
                if isinstance(target, ast.Tuple):
                    for elt in target.elts:
                        if isinstance(elt, ast.Name):
                            self.defs[elt.id] = target
                elif isinstance(target, ast.Name):
                    self.defs[target.id] = target
            self.generic_visit(node)

    # recursive AST traversal to perform dead code elimination
    class DeadCodeEliminator(ast.NodeTransformer):
        def __init__(self, finder):
            self.finder = finder
            self.in_control_flow = False

        def visit_BoolOp(self, node):
            self.generic_visit(node)
            if isinstance(node.op, ast.And) and not self.in_control_flow:
                node.values = list(filter(lambda v: isinstance(v, ast.Name) and v.id in self.finder.defs,
                                          node.values))
                if len(node.values) == 1:
                    return node.values[0]
            elif isinstance(node.op, ast.Or) and not self.in_control_flow:
                node.values = list(filter(lambda v: isinstance(v, ast.Name) and v.id not in self.finder.defs,
                                          node.values))
                if not node.values:
                    return ast.parse('False').body[0].value
                elif len(node.values) == 1:
                    return node.values[0]
            return node

        def visit_If(self, node):
            old_in_control_flow = self.in_control_flow
            self.in_control_flow = True
            node.test = self.visit(node.test)
            self.in_control_flow = old_in_control_flow

            old_defs = self.finder.defs
            self.finder.defs = {}
            self.visit(node.body)
            body_defs = self.finder.defs
            self.finder.defs = old_defs

            if node.orelse:
                old_defs = self.finder.defs
                self.finder.defs = {}
                self.visit(node.orelse)
                orelse_defs = self.finder.defs
                self.finder.defs = old_defs
            else:
                orelse_defs = {}

            unused_defs = body_defs.keys() & orelse_defs.keys()
            for unused_def in unused_defs:
                del self.finder.defs[unused_def]

            node.body = list(filter(lambda n: not isinstance(n, ast.Expr)
                                             or not isinstance(n.value, ast.Name)
                                             or n.value.id in self.finder.defs,
                                    node.body))
            node.orelse = list(filter(lambda n: not isinstance(n, ast.Expr)
                                                 or not isinstance(n.value, ast.Name)
                                                 or n.value.id in self.finder.defs,
                                       node.orelse))

            if not node.body:
                if node.orelse:
                    return ast.If(test=node.test, body=node.orelse, orelse=[], lineno=node.lineno, col_offset=node.col_offset)
                else:
                    return ast.parse('None').body[0]

            if not node.orelse:
                if len(node.body) == 1:
                    return node.body[0]

            return node

        def visit_For(self, node):
            old_in_control_flow = self.in_control_flow
            self.in_control_flow = True
            node.iter = self.visit(node.iter)
            self.in_control_flow = old_in_control_flow

            old_defs = self.finder.defs
            self.finder.defs = {}
            self.visit(node.body)
            body_defs = self.finder.defs
            self.finder.defs = old_defs

            unused_defs = {d for d in body_defs.keys() if body_defs[d].lineno > node.target.lineno}

            node.body = list(filter(lambda n: not isinstance(n, ast.Expr) or not isinstance(n.value, ast.Name)
                                             or n.value.id in self.finder.defs or isinstance(node.iter, ast.Str),
                                    node.body))

            if unused_defs:
                old_defs = self.finder.defs
                self.finder.defs = {}
                node.target = self.visit(node.target)
                self.finder.defs = old_defs

                if isinstance(node.target, ast.Tuple):
                    for i, elt in enumerate(node.target.elts):
                        if isinstance(elt, ast.Name) and elt.id in unused_defs:
                            t = list(node.target.elts)
                            t[i] = ast.parse('None').body[0].value
                            node.target.elts = tuple(t)
                            if len(node.target.elts) == 1:
                                node.target = node.target.elts[0]
                elif isinstance(node.target, ast.Name) and node.target.id in unused_defs:
                    node.target = ast.parse('None').body[0].value

                if isinstance(node.iter, ast.Str):
                    node.body = [ast.parse(f'{node.target.id} = "{s}"').body[0]] + node.body

            return node

        def visit_While(self, node):
            old_in_control_flow = self.in_control_flow
            self.in_control_flow = True
            node.test = self.visit(node.test)
            self.in_control_flow = old_in_control_flow

            old_defs = self.finder.defs
            self.finder.defs = {}
            self.visit(node.body)
            body_defs = self.finder.defs
            self.finder.defs = old_defs

            unused_defs = body_defs.keys()

            node.body = list(filter(lambda n: not isinstance(n, ast.Expr) or not isinstance(n.value, ast.Name)
                                             or n.value.id in self.finder.defs,
                                    node.body))
            node.orelse = list(filter(lambda n: not isinstance(n, ast.Expr) or not isinstance(n.value, ast.Name)
                                                 or n.value.id in self.finder.defs,
                                       node.orelse))

            if not node.body:
                if node.orelse:
                    return ast.While(test=node.test, body=node.orelse, orelse=[], lineno=node.lineno, col_offset=node.col_offset)
                else:
                    return ast.parse('None').body[0]

            if not node.orelse:
                if len(node.body) == 1:
                    return node.body[0]

            return node

        def visit_Call(self, node):
            self.generic_visit(node)
            if not hasattr(node.func, 'id'):
                return node
            if node.func.id == 'pop' and len(node.args) == 1 and isinstance(node.args[0], ast.Name):
                target = node.args[0]
                if target.id in self.finder.defs:
                    defnode = self.finder.defs[target.id]
                    if isinstance(defnode.ctx, ast.Store):
                        found_push = False
                        stack = [n for n in ast.walk(defnode) if isinstance(n, ast.Call) and
                                 hasattr(n.func, 'id') and n.func.id == 'push' and len(n.args) == 1 and
                                 isinstance(n.args[0], ast.Name) and n.args[0].id == target.id]
                        if stack:
                            stack[0].lineno = defnode.lineno
                            stack[0].col_offset = defnode.col_offset
                            found_push = True
                        if not found_push:
                            target.ctx = ast.Del()
                            del self.finder.defs[target.id]
                            return ast.parse('None').body[0].value
        return node

    # combine the definition finder and dead code eliminator
    finder = DefinitionFinder()
    finder.visit(node)
    eliminator = DeadCodeEliminator(finder)
    return eliminator.visit(node)

