    if self._fields is None:
        self._fields = {}
    if self._values is None:
        self._values = {}
    if self._dirty is None:
        self._dirty = set()
    if self._is_deleted is None:
        self._is_deleted = False
    for (field_id, field_name) in self._fields.items():
        if field_id in self._values:
            value = self._values[field_id]
            field_type = self._fields[field_id].type
            oprot.write_field_begin(field_name, field_type, field_id)
            self._write_value(oprot, field_type, value)
            oprot.write_field_end()
    oprot.write_field_begin('dirty', TType.SET, 100)
    oprot.write_set_begin(TType.I32, len(self._dirty))
    for field_id in self._dirty:
        oprot.write_i32(field_id)
    oprot.write_set_end()
    oprot.write_field_end()
    oprot.write_field_begin('is_deleted', TType.BOOL, 101)
    oprot.write_bool(self._is_deleted)
    oprot.write_field_end()
    oprot.write_struct_end()
    return self

