import rsa
import hashlib
from Crypto.Cipher import AES
from Crypto import Random

class Client:
    def __init__(self):
        self.aes_key = Random.new().read(AES.block_size)
        self.stored_key = None

    def _auth(self, load):
        # Verify that the key we are receiving matches the stored key
        if self.stored_key is None:
            self.stored_key = load

        if self.stored_key != load:
            raise ValueError("Keys do not match")

        # Make an RSA key with the pub key
        pub_key = rsa.PublicKey.load_pkcs1(load)

        # Encrypt the AES key as an encrypted salt.payload
        encrypted_aes_key = rsa.encrypt(self.aes_key, pub_key)

        # Package the return and return it
        return {
            "encrypted_aes_key": encrypted_aes_key,
            "aes_key_hash": hashlib.sha256(self.aes_key).hexdigest()
        }

