import os
import json
from lxml import etree
from fastkml import kml


def kml_to_geojson(kml_path, output_dir, separate_folders=False, style_type=None, style_filename=None):
    k = kml.KML()
    with open(kml_path, 'rb') as f:
        k.from_string(f.read())
    nsmap = {'kml': 'http://www.opengis.net/kml/2.2'}
    features = []
    if separate_folders:
        folders = k.features()
        for folder in folders:
            if hasattr(folder, 'features') and folder.features():
                features = folder.features()
                if not os.path.exists(os.path.join(output_dir, folder.name)):
                    os.makedirs(os.path.join(output_dir, folder.name))
                geojson_path = os.path.join(output_dir, folder.name, folder.name + '.geojson')
                feature_collection = {'type': 'FeatureCollection', 'features': []}
                for feature in features:
                    if hasattr(feature, 'geometry'):
                        feature_collection['features'].append(feature.__geo_interface__)
                with open(geojson_path, 'w') as outfile:
                    json.dump(feature_collection, outfile)
            else:
                features.append(folder)
        if len(features) > 0:
            geojson_path = os.path.join(output_dir, os.path.basename(kml_path) + '.geojson')
            feature_collection = {'type': 'FeatureCollection', 'features': []}
            for feature in features:
                if hasattr(feature, 'geometry'):
                    feature_collection['features'].append(feature.__geo_interface__)
            with open(geojson_path, 'w') as outfile:
                json.dump(feature_collection, outfile)
    else:
        features = list(k.features())
        if len(features) > 0:
            geojson_path = os.path.join(output_dir, os.path.basename(kml_path) + '.geojson')
            feature_collection = {'type': 'FeatureCollection', 'features': []}
            for feature in features:
                if hasattr(feature, 'geometry'):
                    feature_collection['features'].append(feature.__geo_interface__)
            with open(geojson_path, 'w') as outfile:
                json.dump(feature_collection, outfile)
    if style_type and style_filename:
        style_path = os.path.join(output_dir, style_filename)
        style_dict = {}
        for folder in k.features():
            if folder.styleUrl:
                style_url = folder.styleUrl
                if '#' in style_url:
                    style_id = style_url.split('#')[-1]
                    xpath = f"//kml:Style[@id='{style_id}']"
                    style_obj = k.xml.xpath(xpath, namespaces=nsmap)
                    if len(style_obj) > 0:
                        style_dict[style_id] = style_obj[0].text
        with open(style_path, 'w') as style_file:
            style_json = json.dumps(style_dict, indent=4)
            style_file.write(style_json)

