def incremental_sync(change_list):
    # Add your implementation here
    synced_data = []
    for change in change_list:
        if change['type'] == 'add':
            synced_data.append(change['data'])
        elif change['type'] == 'edit':
            for i in range(len(synced_data)):
                if synced_data[i]['id'] == change['id']:
                    synced_data[i].update(change['data'])
                    break
        elif change['type'] == 'delete':
            for i in range(len(synced_data)):
                if synced_data[i]['id'] == change['id']:
                    del synced_data[i]
                    break
    return synced_data

