def encode_tweet_info(tweet_generator: Generator[Dict], 
                       ) -> Tuple[sp.spmatrix, Set[int], Dict[str, int]]:
    user_id_set = set()
    node_id = 0
    edges = []
    node_to_id = {}

    for tweet in tweet_generator:
        user_id = tweet['user_id']
        user_id_set.add(user_id)
        if user_id not in node_to_id:
            node_to_id[user_id] = node_id
