                user_id_set.add(mention_id)
                if mention_id not in node_to_id:
                    node_to_id[mention_id] = node_id
                    node_id += 1
                edges.append((node_to_id[user_id], node_to_id[mention_id]))

        if 'retweeted_user' in tweet:
            retweet_id = tweet['retweeted_user']
            user_id_set.add(retweet_id)
            if retweet_id not in node_to_id:
                node_to_id[retweet_id] = node_id
                node_id += 1
            edges.append((node_to_id[user_id], node_to_id[retweet_id]))

