def parse_chinese_syllable(syllable):
    vowels = 'aeiou'
    tone_numbers = '12345'
    final_consonants = 'lmnr'

    initial = ''
    final = ''
    tone = ''

    for char in syllable:
        if char in vowels:
            final += char
        elif char in final_consonants:
            final += char
        else:
            initial += char

    for char in syllable[::-1]:
        if char in tone_numbers:
            tone = char
            break

    return initial, final, tone

