def get_past_date(start='-30d'):
    if isinstance(start, str):
        num = int(start[:-1])
        unit = start[-1]
        if unit == 'y':
            start_date = datetime.datetime.now() - datetime.timedelta(days=num*365)
        elif unit == 'w':
            start_date = datetime.datetime.now() - datetime.timedelta(weeks=num)
        elif unit == 'd':
            start_date = datetime.datetime.now() - datetime.timedelta(days=num)
        elif unit == 'h':
            start_date = datetime.datetime.now() - datetime.timedelta(hours=num)
        elif unit == 'm':
            start_date = datetime.datetime.now() - datetime.timedelta(minutes=num)
        elif unit == 's':
            start_date = datetime.datetime.now() - datetime.timedelta(seconds=num)
        else:
            raise ValueError("Invalid unit specified")
    elif isinstance(start, datetime.date) or isinstance(start, datetime.timedelta):
        start_date = datetime.datetime.now() - start
    else:
        raise ValueError("Invalid argument type for start")
    return start_date.date()

