from enum import Enum
from typing import List, Tuple


class Verbosity(Enum):
    VERBOSE = 1
    SUCCINCT = 2
    TERSE = 3


def show_partial_matches(patterns: List[str], text: str, verbosity: Verbosity = Verbosity.TERSE) -> Tuple[int, int, int]:
    matches_sum = 0
    partial_matches_sum = 0
    activations_num = 0

    for pattern in patterns:
        pattern_len = len(pattern)
        for i in range(len(text) - pattern_len + 1):
            match = True
            partial_match = 0
            for j in range(pattern_len):
                if pattern[j] != text[i+j]:
                    if match:
                        partial_match += 1
                        match = False
                    else:
                        break
            if match:
                matches_sum += 1
                activations_num += 1
                if verbosity == Verbosity.VERBOSE:
                    print(f"Pattern '{pattern}' matched at index {i}")
            elif partial_match:
                partial_matches_sum += 1
                if verbosity == Verbosity.VERBOSE:
                    print(f"Pattern '{pattern}' partial match at index {i} with {partial_match} mismatches")

        if partial_matches_sum and verbosity != Verbosity.VERBOSE:
            print(f"Pattern '{pattern}' has {partial_matches_sum} partial matches")

        if activations_num and verbosity == Verbosity.SUCCINCT:
            print(f"Pattern '{pattern}' activated {activations_num} times")

    return (matches_sum, partial_matches_sum, activations_num)

