import numpy as np

def precipitation_disaggregation(precip_daily, hourly, cascade_options, shift, test):
  # convert daily data to hourly data
  if hourly:
    precip_hourly = precip_daily.resample('H').mean()
  else:
    # disaggregate to 5-minute resolution
    level = cascade_options['level']
    segments = int(60 / (5 * level))
    precip_5min = [precip_daily[i:i+segments].sum() for i in range(0, len(precip_daily), segments)]
    precip_5min = pd.Series(precip_5min)

  # shift the data
  if shift:
    if shift > 0:
      precip_hourly = pd.concat([pd.Series([0]*shift), precip_hourly])
      precip_hourly = precip_hourly[:-shift]
    else:
      precip_hourly = pd.concat([precip_hourly[-shift:], pd.Series([0]*(-shift))])
      precip_hourly = precip_hourly[-len(precip_daily):]

  # initialize variables
  N = int(np.log2(len(precip_hourly)))
  P = {}
  P[0] = precip_hourly.to_numpy()
  T = {}

  # run cascade model
  for n in range(N):
    Q = np.zeros(len(P[n])+1)
    for i in range(len(P[n])):
      Q[2*i+1] = P[n][i]
    for i in range(2, len(Q), 2):
      Q[i] = (Q[i-1]+Q[i+1])/2
    T1 = cascade_options['a1'][n] * np.log2(P[n]+cascade_options['b1'][n])
    T2 = np.random.normal(cascade_options['a2'][n], cascade_options['b2'][n], P[n].shape[0])
    P[n+1] = T1 + T2 * Q[1:-1]**cascade_options['c'][n]
    T[n+1] = T1
    if test:
      test_output = {}
      for i in range(n+2):
        test_output[i] = T[i]

  if test:
    return test_output
  else:
    return P[N]

