def process_sequence(seq:str, material:str) -> str:
    """Validate and process sequence inputs.
    :param seq: input sequence
    :type seq: str
    :param material: DNA, RNA, or peptide
    :type: str
    :returns: Uppercase version of `seq` with the alphabet checked by check_alphabet().
    :rtype: str
    """
    alphabet = ''
    if material == 'DNA':
        alphabet = 'ATCG'
    elif material == 'RNA':
        alphabet == 'AUCG'
    elif material == 'peptide':
        alphabet = 'ACDEFGHIKLMNPQRSTVWY'
    else:
        raise ValueError('Invalid material type')

    def check_alphabet(sequence):
        """Check if input sequence only contains valid characters."""
        for char in sequence:
            if char not in alphabet:
                raise ValueError(f"Unexpected character '{char}' in {material} sequence")

    check_alphabet(seq)
    return seq.upper()

