from seaborn import SeabornTable

def html_to_seaborn_table(file_path=None, text=None, columns=None, remove_empty_rows=False, key_on=None, deliminator=",", eval_cells=False):
    if file_path is not None:
        with open(file_path, 'r') as file:
            text = file.read()
    rows = text.split('\n')
    header = rows[0].split(deliminator)
    if columns is not None:
        header = [col for col in header if col in columns]
    data = []
    for row in rows[1:]:
        if not row:
            continue
        cells = row.split(deliminator)
        if len(cells) != len(header):
            continue
        if remove_empty_rows and all([not cell.strip() for cell in cells]):
            continue
        if not eval_cells:
            data.append(dict(zip(header, cells)))
        else:
            new_cells = []
            for cell in cells:
                try:
                    new_cell = eval(cell)
                except Exception:
                    new_cell = cell
                new_cells.append(new_cell)
            data.append(dict(zip(header, new_cells)))
    if key_on is not None:
        data_dict = {}
        for row in data:
            key = tuple([row[col] for col in key_on])
            data_dict[key] = row
        data = list(data_dict.values())
    return SeabornTable(data)

