import os
from jinja2 import Environment, FileSystemLoader

def render_templates(repo_dir, context, output_dir, overwrite_if_exists=False):
    if os.path.exists(output_dir) and overwrite_if_exists:
        shutil.rmtree(output_dir)
    elif os.path.exists(output_dir) and not overwrite_if_exists:
        raise Exception("Output directory already exists and overwriting is not allowed.")
    os.makedirs(output_dir)

    env = Environment(loader=FileSystemLoader(repo_dir))

    for subdir, _, files in os.walk(repo_dir):
        for file in files:
            file_path = os.path.join(subdir, file)
            template = env.get_template(os.path.relpath(file_path, repo_dir))
            rendered = template.render(context)
            with open(os.path.join(output_dir, os.path.relpath(file_path, repo_dir)), "w") as f:
                f.write(rendered)

