def _normalize(value, min_val, max_val):
    """Helper function to normalize a given value between 0 and 1."""
    if max_val == min_val:
        return 0.0
    return (value - min_val) / (max_val - min_val)

def _denormalize(normalized_value, min_val, max_val):
    """Helper function to denormalize a given value from 0 to 1 back to its original range."""
    return normalized_value * (max_val - min_val) + min_val

def _scale(value, scale_factor):
    """Helper function to scale a given value by a scale factor."""
    return value * scale_factor

def _shift(value, shift_amount):
    """Helper function to shift a given value by a shift amount."""
    return value + shift_amount

def _apply_transformations(value, transformations):
    """Apply a series of transformations to a given value."""
    for transformation in transformations:
        if transformation['type'] == 'clip':
            value = _clip(value, transformation['lower'], transformation['upper'])
        elif transformation['type'] == 'normalize':
            value = _normalize(value, transformation['min_val'], transformation['max_val'])
        elif transformation['type'] == 'denormalize':
            value = _denormalize(value, transformation['min_val'], transformation['max_val'])
        elif transformation['type'] == 'scale':
            value = _scale(value, transformation['scale_factor'])
        elif transformation['type'] == 'shift':
            value = _shift(value, transformation['shift_amount'])
        else:
            raise ValueError(f"Unknown transformation type: {transformation['type']}")
    return value
