import ast
import networkx as nx

def create_dependency_graph(node, call_deps=False):
    # Initialize the graph and undefined set
    graph = nx.DiGraph()
    undefined = set()

    def visit(node):
        # Visit children of the node
        for child in ast.iter_child_nodes(node):
            visit(child)

        if isinstance(node, ast.Name):
            if node.id not in graph:
                undefined.add(node.id)
        elif isinstance(node, ast.Attribute):
            if node.attr not in graph:
                undefined.add(node.attr)
            visit(node.value)

            # Add edge to the graph between the value and the attribute
            graph.add_edge(getattr(node.value, 'id', node.value), node.attr)
        elif isinstance(node, ast.Call) and call_deps:
            for arg in node.args:
                visit(arg)
                graph.add_edge(node.func, arg)
                graph.add_edge(arg, node.func)

    visit(node)
    return graph, undefined

