def export_obj_to_str(obj, top=True):
    """
    Exports object to its string representation.
    Args:
        obj: The object to be exported.
        top (bool): if True appends `internal_name` before values.
            All non list objects should be exported with value top=True,
            all list objects, that are embedded in as fields in list objects
            should be exported with `top`=False
    Returns:
        str: The objects string representation.
    """
    if isinstance(obj, dict):
        if top:
            s = '{'
        else:
            s = ''
        for k, v in obj.items():
            if top:
                s += f'\'{k}\' : '
            elif isinstance(v, list):
                s += f'{k} : '
            s += export_obj_to_str(v, False) + ','
        return s[:-1] + ('}' if top else '')
    elif isinstance(obj, list):
        s = '['
        for item in obj:
            s += export_obj_to_str(item, False) + ','
        return s[:-1] + ']'
    elif isinstance(obj, (str, bool, int, float)):
        return f'{obj}'
    else:
        return f'{obj} ({obj.__class__.__name__})'

