import numpy as np

def envelope_step_DCEGM(M, C, V_T, commonM):
    M_len = len(commonM)
    C_env = np.empty(M_len)
    V_env = np.empty(M_len)
    index = 0

    for i in range(M_len):
        while M[index] < commonM[i]:
            index += 1

        if index == 0:
            C_env[i] = C[0]
            V_env[i] = V_T[0]
        elif index == len(M):
            C_env[i] = C[-1]
            V_env[i] = V_T[-1]
        else:
            slope = (V_T[index] - V_T[index - 1]) / (M[index] - M[index - 1])
            C_env[i] = ((commonM[i] - M[index - 1]) * (C[index] - C[index - 1]) /
                        (M[index] - M[index - 1]) + C[index - 1])
            V_env[i] = slope * (commonM[i] - M[index - 1]) + V_T[index - 1]

    return (C_env, V_env)

