def _get_arg_names(func):
    import inspect
    sig = inspect.signature(func)
    return [param.name for param in sig.parameters.values()]

def _get_arg_values(func, args, kwargs):
    """this returns the arg values in the order of the function signature"""
    import inspect
    sig = inspect.signature(func)
    bound_args = sig.bind(*args, **kwargs)
    bound_args.apply_defaults()
    return bound_args.arguments

def _get_arg_dict(func, args, kwargs):
    """this returns a dictionary of arg names and values in the order of the function signature"""
    arg_names = _get_arg_names(func)
    arg_values = _get_arg_values(func, args, kwargs)
    return dict(zip(arg_names, arg_values))

def _get_arg_dict_with_defaults(func):
    """this returns a dictionary of arg names and default values"""
    import inspect
    sig = inspect.signature(func)
    return {param.name: param.default for param in sig.parameters.values() if param.default is not param.empty}

def _get_arg_dict_with_defaults_filled(func, args, kwargs):
    """this returns a dictionary of arg names and values, filling in defaults where necessary"""
    arg_dict = _get_arg_dict(func, args, kwargs)
    default_dict = _get_arg_dict_with_defaults(func)
    return {**default_dict, **arg_dict}

def _get_arg_dict_with_defaults_filled_ordered(func, args, kwargs):
    """this returns a dictionary of arg names and values in the order of the function signature, filling in defaults where necessary"""
    arg_dict = _get_arg_dict(func, args, kwargs)
    default_dict = _get_arg_dict_with_defaults(func)
    combined_dict = {**default_dict, **arg_dict}
    arg_names = _get_arg_names(func)
    return {name: combined_dict[name] for name in arg_names}

