import argparse
from argcomplete.compat import FileType

def execute_module(self, module_path, args, module_class=None):
    parser = argparse.ArgumentParser()
    module_args = self._get_module_args(module_path, module_class)

    for arg in module_args:
        parser.add_argument(*arg['args'], **arg['kwargs'])

    known_args, extra_args = parser.parse_known_args(args)

    if 'help' in known_args and len(known_args) == 1:
        parser.print_help()
        return

    if module_class is None:
        module_class = self._get_module_class(module_path)

    module_instance = module_class()

    for arg in module_args:
        if hasattr(module_instance, arg['method']):
            setattr(module_instance, arg['method'], getattr(known_args, arg['dest'], None))

    for arg in module_args:
        if arg['type'] == FileType:
            file_name = getattr(module_instance, arg['dest'], None)
            if file_name is not None:
                setattr(module_instance, arg['dest'], open(file_name, arg['mode']))

    return module_instance(*extra_args)

