from web3 import Web3
def decode_event_data(event_abi, log_entry):
    event_signature = Web3.keccak(text=event_abi['name'] + '(' + ','.join([x['type'] for x in event_abi['inputs']]) + ')').hex()[:10]
    if log_entry['topics'][0] != event_signature:
        return None
    event_data = Web3().toBytes(hexstr=log_entry['data'])
    decoded_data = {
        abi['name']: Web3().toHex(value)
        for abi, value in zip(event_abi['inputs'], Web3().decode_abi(event_abi['inputs'], event_data))
    }
    return decoded_data

