def area(self):
    """Returns the area of the rectangle."""
    return self.x * self.y

def perimeter(self):
    """Returns the perimeter of the rectangle."""
    return 2 * (self.x + self.y)

def scale(self, factor):
    """Scales the dimensions of the rectangle by a given factor."""
    self.x *= factor
    self.x *= factor
    self.y *= factor

def __str__(self):
    """Returns a string representation of the rectangle."""
    return f'Rectangle(x={self.x}, y={self.y})'

def __eq__(self, other):
    """Checks if two rectangles are equal based on their dimensions."""
    if not isinstance(other, Rectangle):
        return NotImplemented
    return self.x == other.x and self.y == other.y

def __lt__(self, other):
    """Checks if this rectangle is less than another based on area."""
    if not isinstance(other, Rectangle):
        return NotImplemented
    return self.area() < other.area()

def __le__(self, other):
    """Checks if this rectangle is less than or equal to another based on area."""
    if not isinstance(other, Rectangle):
        return NotImplemented
    return self.area() <= other.area()

def __gt__(self, other):
    """Checks if this rectangle is greater than another based on area."""
    if not isinstance(other, Rectangle):
        return NotImplemented
    return self.area() > other.area()

def __ge__(self, other):
    """Checks if this rectangle is greater than or equal to another based on area."""
    if not isinstance(other, Rectangle):
