import sys
from collections import defaultdict
from itertools import islice

def getsize(obj, seen=None):
    """Recursively finds size of objects"""
    size = sys.getsizeof(obj)
    if seen is None:
        seen = set()
    obj_id = id(obj)
    if obj_id in seen:
        return 0
    seen.add(obj_id)
    if isinstance(obj, dict):
        size += sum(getsize(v, seen) for v in obj.values())
        size += sum(getsize(k, seen) for k in obj.keys())
    elif hasattr(obj, '__dict__'):
        size += getsize(obj.__dict__, seen)
    elif hasattr(obj, '__iter__') and not isinstance(obj,(str, bytes, bytearray)):
        size += sum(getsize(i, seen) for i in obj)
    return size

class Asized:
    def __init__(self, *objs, detail=1):
        self._detail_level = detail
        self._size = defaultdict(int)
        self._refs = defaultdict(int)
        if len(objs) == 1:
            self._get_sizes(objs[0])
        else:
            for obj in objs:
                self._get_sizes(obj)

    def _get_sizes(self, obj, seen=None, path=()):
        if seen is None:
            seen = set()
        obj_id = id(obj)
        if obj_id in seen:
            return
        seen.add(obj_id)
        typename = type(obj).__name__
        obj_size = getsize(obj, seen)
        self._size[path] += obj_size
        if self._detail_level > 0:
            self._refs[typename] += 1
            if isinstance(obj, dict):
                for k, value in obj.items():
                    self._get_sizes(value, seen, path + (str(k),))
            elif hasattr(obj, '__dict__'):
                for k, value in obj.__dict__.items():
                    self._get_sizes(value, seen, path + (k,))
            elif hasattr(obj, '__iter__') and not isinstance(obj,(str, bytes, bytearray)):
                for i, item in enumerate(islice(obj, 20)):
                    self._get_sizes(item, seen, path + (str(i),))

    def __str__(self):
        return self.__repr__()

    def __repr__(self):
        res = []
        for k in sorted(self._size, key=lambda x: -1 * self._size[x]):
            size = self._size[k]
            line = []
            for idx, elem in enumerate(k):
                if isinstance(elem, int):
                    line.append('[{}]' % elem)
                else:
                    line.append(str(elem))
                if idx > 1:
                    break
            line.append(f': {size}')
            res.append(''.join(line))

        if self._detail_level:
            res.append('')
            res.append('Referrers by type:')
            for typ in sorted(self._refs, key=lambda x: -1 * self._refs[x]):
                res.append(f'{typ}: {self._refs[typ]}')

        return '\n'.join(res)

    def set(self, detail=None):
        if detail is not None:
            self._detail_level = detail

