def detect_jump_targets(byte_code):
    offsets = []
    i = 0
    while i < len(byte_code):
        opcode = byte_code[i]
        if opcode >= dis.HAVE_ARGUMENT:
            arg = byte_code[i+1] | (byte_code[i+2]<<8)
            if opcode in dis.hasjrel:
                target = i + 3 + arg
                if target not in offsets:
                    offsets.append(target)
            elif opcode in dis.hasjabs:
                target = arg
                if target not in offsets:
                    offsets.append(target)
            i += 3
        else:
            i += 1
    offsets.sort()
    return offsets

