def peek(self):
    if self.cursor < len(self.source):
        return self.source[self.cursor]
    else:
        return None

def read(self):
    """Read the next character and move the cursor."""
    if self.cursor < len(self.source):
        char = self.source[self.cursor]
        self.cursor += 1
        return char
    else:
        return None

def skip_whitespace(self):
    """Skip all whitespace characters."""
    while self.peek() is not None and self.peek().isspace():
        self.read()

def read_until(self, delimiter):
    """Read characters until a delimiter is encountered."""
    result = []
    while self.peek() is not None and self.peek() != delimiter:
        result.append(self.read())
    return ''.join(result)

def read_word(self):
    """Read a word, defined as a sequence of non-whitespace characters."""
    self.skip_whitespace()
    return self.read_until(' ')

def read_number(self):
    """Read a number, defined as a sequence of digits."""
    self.skip_whitespace()
    result = []
    while self.peek() is not None and self.peek().isdigit():
        result.append(self.read())
    return ''.join(result)

def read_string(self):
    """Read a string enclosed in quotes."""
    self.skip_whitespace()
    if self.peek() == '"':
        self.read()
        result = []
        while self.peek() is not None and self.peek() != '"':
            result.append(self.read())
        self.read()
        return ''.join(result)
    else:
        return None

def read_line(self):
    """Read a line of text."""
    return self.read_until('\n')

def read_file(self):
    """Read the entire file."""
    return self.read_until(None)

def read_comment(self):
    """Read a comment, defined as a sequence of characters until a newline."""
    self.skip_whitespace()
    if self.peek() == '#':
        self.read()
        return self.read_until('\n')
    else:
        return None

def read_identifier(self):
    """Read an identifier, defined as a sequence of alphanumeric characters."""
    self.skip_whitespace()
    result = []
    while self.peek() is not None and self.peek().isalnum():
        result.append(self.read())
    return ''.join

