    window_indices = np.array(window)
    window_coordinates = coordinates[window_indices]
    center = np.mean(window_coordinates, axis=0)
    max_distance = 0
    for i in range(len(window_coordinates)):
        for j in range(i + 1, len(window_coordinates)):
            distance = np.linalg.norm(window_coordinates[i] - window_coordinates[j])
