def point_on_arc(arc, point):
    if arc.rotation != 0.0:
        return None
    v = point - arc.center
    angle = arc.start_angle + math.atan2(v.y, v.x)
    while angle < arc.start_angle:
        angle += 2.0 * math.pi
    while angle > arc.end_angle:
        angle -= 2.0 * math.pi
    if abs(angle - arc.start_angle) < 1e-6 or abs(angle - arc.end_angle) < 1e-6:
        return None
    t = (angle - arc.start_angle) / (arc.end_angle - arc.start_angle)
    if t < 0.0 or t > 1.0:
        return None
    return t

