def parse_git_log(filepath: str) -> Generator[Dict[str, str], None, None]:
    commit_pattern = r'commit\s([a-f0-9]+)'
    author_pattern = r'Author:\s(.*)\s<(.*)>'
    date_pattern = r'Date:\s+(.*)'
    message_pattern = r'\n\s{4}(.*)'

    current_commit = None
    with open(filepath, 'r') as f:
        for line in f:
            if re.match(commit_pattern, line):
                if current_commit:
                    yield current_commit
                current_commit = {'hash': re.match(commit_pattern, line).group(1)}
            elif re.match(author_pattern, line):
                current_commit['author_name'] = re.match(author_pattern, line).group(1)
                current_commit['author_email'] = re.match(author_pattern, line).group(2)
            elif re.match(date_pattern, line):
                current_commit['date'] = re.match(date_pattern, line).group(1)
            elif re.match(message_pattern, line):
                if 'message' in current_commit:
                    current_commit['message'] += "\n" + re.match(message_pattern, line).group(1)
                else:
                    current_commit['message'] = re.match(message_pattern, line).group(1)

    if current_commit:
        yield current_commit

