def find_peak(x, y, dy=None, position=None, hwhm=None, baseline=None, amplitude=None, curve='Lorentz'):
        """
        This function is deprecated, please consider using findpeak_single() instead.
        Inputs:
            x, y, dy: abscissa, ordinate and the error of the ordinate (can be None)
            position, hwhm, baseline, amplitude: first guesses for the named parameters
            curve: 'Gauss' or 'Lorentz' (default)

        Outputs:
            peak position, error of peak position, hwhm, error of hwhm, baseline,
                error of baseline, amplitude, error of amplitude.
        Notes:
            A Gauss or a Lorentz curve is fitted, depending on the value of 'curve'.
        """
        import numpy as np
        from scipy.optimize import curve_fit

        if curve not in ['Gauss', 'Lorentz']:
            raise ValueError("The curve parameter must be 'Gauss' or 'Lorentz'.")

        if dy is None:
            dy = 1

        def gauss(x, position, hwhm, baseline, amplitude):
            sigma = hwhm/2.35482004503
            return baseline + amplitude*np.exp(-0.5*(x-position)**2/sigma**2)

        def lorentz(x, position, hwhm, baseline, amplitude):
            return baseline + amplitude*(1/(1+((x-position)/hwhm)**2))

        if curve == 'Gauss':
            peak_func = gauss
        else:
            peak_func = lorentz

        if position is None:
            position = x[np.argmax(y)]
        if hwhm is None:
            hwhm = np.std(x)
        if baseline is None:
            baseline = np.mean(y)
        if amplitude is None:
            amplitude = np.max(y) - np.min(y)

        popt, pcov = curve_fit(peak_func, x, y, p0=[position, hwhm, baseline, amplitude], sigma=dy)
        peak_pos, peak_pos_err = popt[0], np.sqrt(pcov[0][0])
        hwhm_val, hwhm_err = popt[1], np.sqrt(pcov[1][1])
        baseline_val, baseline_err = popt[2], np.sqrt(pcov[2][2])
        amplitude_val, amplitude_err = popt[3], np.sqrt(pcov[3][3])

        return peak_pos, peak_pos_err, hwhm_val, hwhm_err, baseline_val, baseline_err, amplitude_val, amplitude_err

