class Promise:

    def __init__(self, executor):
        self._state = 'pending'
        self._value = None
        self._reason = None
        self._on_fulfilled_callbacks = []
        self._on_rejected_callbacks = []
        try:
            executor(self._resolve, self._reject)
        except Exception as e:
            self._reject(e)

    def _resolve(self, value):
        if self._state == 'pending':
            self._state = 'fulfilled'
            self._value = value
            for callback in self._on_fulfilled_callbacks:
                callback(self._value)

    def _reject(self, reason):
        if self._state == 'pending':
            self._state = 'rejected'
            self._reason = reason
            for callback in self._on_rejected_callbacks:
                callback(self._reason)

    def then(self, on_fulfilled=None, on_rejected=None):
        return Promise(lambda resolve, reject: self._handle_then(resolve, reject, on_fulfilled, on_rejected))

    def _handle_then(self, resolve, reject, on_fulfilled, on_rejected):
        if self._state == 'fulfilled':
            if callable(on_fulfilled):
                try:
                    resolve(on_fulfilled(self._value))
                except Exception as e:
                    reject(e)
            else:
                resolve(self._value)
        elif self._state == 'rejected':
            if callable(on_rejected):
                try:
                    resolve(on_fulfilled(self._value))
                except Exception as e:
                    reject(e)
            else:
                reject(self._reason)
        else:
            self._on_fulfilled_callbacks.append(lambda value: self._handle_then(resolve, reject, on_fulfilled, on_rejected))
            self._on_rejected_callbacks.append(lambda reason: self._handle_then(resolve, reject, on_fulfilled, on_rejected))

    def catch(self, on_rejected):
        return self.then(None, on_rejected)

