    return line.strip().startswith('#')

def _is_docstring(line):
    """Return True if the line is a docstring."""
    stripped_line = line.strip()
    return stripped_line.startswith('"""') or stripped_line.startswith("'''")

def _is_code(line):
    """Return True if the line is a line of code."""
    return not _is_blank(line) and (not _is_comment(line)) and (not _is_docstring(line))

def _get_next_line(lines, current_index):
    """Return the next line in the list of lines, or None if there is no next line."""
    if current_index + 1 < len(lines):
        return lines[current_index + 1]
    return None

def _get_previous_line(lines, current_index):
    """Return the previous line in the list of lines, or None if there is no previous line."""
    if current_index - 1 >= 0:
        return lines[current_index - 1]
    return None

def _get_next_non_blank_line(lines, current_index):
    """Return the next non-blank line in the list of lines, or None if there is no next non-blank line."""
    next_index = current_index + 1
    while next_index < len(lines):
        if not _is_blank(lines[next_index]):
            return lines[next_index]
        next_index += 1
    return None

def _get_previous_non_blank_line(lines, current_index):
    """Return the previous non-blank line in the list of lines, or None if there is no previous non-blank line."""
    previous_index = current_index - 1
    while previous_index >= 0:
        if not _is_blank(lines[previous_index]):
            return lines[previous_index]
        previous_index -= 1
    return None

