def merge_guides(gg):
    """
    Merge overlapped guides

    Parameters:
    gg (ggplot object): ggplot object with overlapped guides

    Returns:
    ggplot object without overlapped guides
    """
    from ggplot.utils import merge_duplicates

    new_aes = {}
    for k, v in gg.aesthetics.items():
        if isinstance(v, basestring):
            new_aes[k] = v
        else:
            new_aes[k] = tuple(v)
    gg.aesthetics = new_aes

    guides = {}
    seen_names = set()
    for layer in gg.layers:
        for k, v in layer.layer.params().items():
            if "guide" in k:
                if v is None:
                    continue

                if v in seen_names:
                    continue
                else:
                    seen_names.add(v)

                if v not in guides:
                    guides[v] = []
                guides[v].append((layer.geom.__name__, layer.aes))

    all_guides = []
    for name, layers in guides.items():
        if len(layers) == 1:
            all_guides.append(layers[0][1])
            continue

        new_aes = {}
        for aes in (a for l in layers for a in l[1].items()):
            key, value = aes
            if key in new_aes:
                new_aes[key].append(value)
            else:
                new_aes[key] = [value]

        merged_aes = {}
        for k, v in new_aes.items():
            merged_aes[k] = merge_duplicates(v)

        all_guides.append(merged_aes)

    gg.guides = merge_duplicates(all_guides)
    return gg

