def serialize(obj):
    """
    Recursively serialize a lot of types, and in cases where it doesn't recognize the type,
    it will fall back to Django's `smart_unicode`.
    Returns `dict`.
    """
    if isinstance(obj, (list, tuple)):
        return [serialize(item) for item in obj]
    elif isinstance(obj, set):
        return list(serialize(item) for item in obj)
    elif isinstance(obj, dict):
        return dict((key, serialize(value)) for key, value in obj.items())
    elif isinstance(obj, bool):
        return obj
    elif isinstance(obj, (int, float, long, complex)):
        return obj
    elif isinstance(obj, basestring):
        return smart_unicode(obj)
    elif obj is None:
        return obj
    else:
        try:
            return serialize(obj.__dict__)
        except AttributeError:
            return smart_unicode(obj)

