    else:
        return None

def is_atom(expression):
    """Checks if the given expression is an atom."""
    return not isinstance(expression, (list, tuple))

def is_list(expression):
    """Checks if the given expression is a list."""
    return isinstance(expression, list)

def is_tuple(expression):
    """Checks if the given expression is a tuple."""
    return isinstance(expression, tuple)

def is_expression(expression):
    """Checks if the given expression is an expression."""
    return isinstance(expression, (list, tuple))

def evaluate_expression(expression):
    """Evaluates the given expression."""
    if is_atom(expression):
        return expression
    elif is_list(expression):
        head = get_head(expression)
        tail = get_tail(expression)
        if head == '+':
            return sum((evaluate_expression(arg) for arg in tail))
        elif head == '-':
            return evaluate_expression(tail[0]) - sum((evaluate_expression(arg) for arg in tail[1:]))
        elif head == '*':
            result = 1
            for arg in tail:
                result *= evaluate_expression(arg)
            return result
        elif head == '/':
            result = evaluate_expression(tail[0])
            for arg in tail[1:]:
                result /= evaluate_expression(arg)
            return result
        else:
            raise ValueError(f'Unknown operator: {head}')
    elif is_tuple(expression):
        raise ValueError('Tuples are not supported as expressions.')
    else:
        raise ValueError('Invalid expression type.')

