    line = []
    history_index = len(history)
    while True:
        char = sys.stdin.read(1)
        if char == '\n':
            break
        elif char == '\x08':
            if line:
                line.pop()
                self._move_cursor_left()
                self._write(' ')
                self._move_cursor_left()
        elif char == '\x1b[A':
            if history_index > 0:
                history_index -= 1
                self._clear_line()
                self._write(history[history_index])
                line = list(history[history_index])
        elif char == '\x1b[B':
