def scaled(value, input_min, input_max, output_min, output_max):
    """Scales a given *value* from an input range to an output range. For example,
    to scale a potentiometer's value (which ranges from 0 to 1) to a PWM LED's
    brightness (which also ranges from 0 to 1)::

        from gpiozero import MCP3008, PWMLED
        from gpiozero.tools import scaled
        from signal import pause

        pot = MCP3008(channel=0)
        led = PWMLED(4)

        led.source = scaled(pot, 0, 1, 0, 1)

        pause()"""
    if input_min == input_max:
        raise ValueError('input_min and input_max cannot be the same')
    if output_min == output_max:
        raise ValueError('output_min and output_max cannot be the same')
    return (value - input_min) * (output_max - output_min) / (input_max - input_min) + output_min

