def a_star_search(start_node, goal_node, heuristic):
    """A* search algorithm implementation.
    Args:
        start_node: The starting node of the search.
        goal_node: The goal node of the search.
        heuristic: A function that estimates the cost from a node to the goal.
    Returns:
        A list of nodes representing the path from start_node to goal_node.
    """
    open_set = {start_node}
    closed_set = set()
    start_node.g_cost = 0
    start_node.h_cost = heuristic(start_node, goal_node)
    start_node.f_cost = start_node.g_cost + start_node.h_cost
    while open_set:
        current_node = min(open_set, key=lambda node: node.f_cost)
        if current_node == goal_node:
            return backtrace(current_node)
        open_set.remove(current_node)
        closed_set.add(current_node)
        for neighbor in current_node.neighbors:
            if neighbor in closed_set:
                continue
            tentative_g_cost = current_node.g_cost + current_node.distance_to(neighbor)
            if neighbor not in open_set or tentative_g_cost < neighbor.g_cost:
                neighbor.parent = current_node
                neighbor.g_cost = tentative_g_cost
                neighbor.h_cost = heuristic(neighbor, goal_node)
                neighbor.f_cost = neighbor.g_cost + neighbor.h_cost
                if neighbor not in open_set:
                    open_set.add(neighbor)
    return None

