def encrypt_key(key):
    aes_gcm = AESGCM(key)
    nonce = aes_gcm.generate_nonce()
    return nonce + aes_gcm.encrypt(nonce, key, None)


def create_key_pair(private_key=None):
    if private_key is None:
        private_key = x25519.X25519PrivateKey.generate().private_bytes(
            serialization.Encoding.Raw,
            serialization.PrivateFormat.Raw,
            serialization.NoEncryption()
        )

    public_key = x25519.X25519PrivateKey.from_private_bytes(private_key).public_key().public_bytes()

    shared_key = x25519.X25519PrivateKey.generate().exchange(
        x25519.X25519PublicKey.from_public_bytes(public_key)
    )

    key = HKDF(
        algorithm = SHA256(),
        length = 32,
        salt = None,
        info = shared_key,
        backend=default_backend()
    ).derive(b"enc")

    encrypted_key = encrypt_key(key)

    return KeyPair(private_key, public_key)

