import math

def closest_pair_of_points(S):
    def euclidean_distance(p, q):
        return math.sqrt((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2)

    def merge(left, right, delta):
        x_bar = right[0][0]
        all_points = sorted(left + right, key=lambda x: x[1])
        n = len(all_points)
        for i in range(n):
            for j in range(i + 1, min(i + 8, n)):
                if all_points[j][1] - all_points[i][1] >= delta:
                    break
                dist = euclidean_distance(all_points[i], all_points[j])
                if dist < delta:
                    delta = dist
        return delta

    def closest_pair(S):
        n = len(S)
        if n <= 3:
            return min(euclidean_distance(S[i], S[j]) for i in range(n) for j in range(i + 1, n))
        middle = n // 2
        left = S[:middle]
        right = S[middle:]
        delta = min(closest_pair(left), closest_pair(right))
        return merge(left, right, delta)

    S = sorted(S)
    return closest_pair(S)

