from datetime import datetime, timedelta

def create_repeated_expenses(start_date, end_date, frequency, amount):
    expenses = []
    current_date = start_date
    while current_date <= end_date:
        expenses.append((current_date, amount))
        if frequency == "daily":
            current_date += timedelta(days=1)
        elif frequency == "weekly":
            current_date += timedelta(weeks=1)
        elif frequency == "monthly":
            current_month = current_date.month
            current_year = current_date.year
            current_month_days = (datetime(current_year, current_month+1, 1) - datetime(current_year, current_month, 1)).days
            if current_date.day + 31 <= current_month_days:
                current_date += timedelta(days=31)
            else:
                current_date += timedelta(days=current_month_days - current_date.day)
    return expenses

