def examine_asn1_type_for_subtype_relationship_with_other_asn1_type(self, other):
        if not hasattr(other, '__class__'):
            raise TypeError('Parameter of a pyasn1 type is expected')
        if other.__class__ == self.__class__:
            return True
        elif not hasattr(self, 'subtypeSpec'):
            # base types are supersets of any other types
            return False
        # Go through the subsetSpec at most once wrt to other
        subtypeSpec = self.subtypeSpec
        while subtypeSpec and subtypeSpec.getEffective() is not None:
            implicitTag, explicitTag, subtypeSpec = subtypeSpec.getEffective()
            if implicitTag.tagSet != explicitTag.tagSet:
                # Wrong tag intersection
                return False
            otherImplicitTag, otherExplicitTag = other.getTagSet()
            if not otherImplicitTag <= implicitTag or not explicitTag <= otherExplicitTag:
                # wrong tags intersection
                return False
            constraint = subtypeSpec.get('constraint')
            if constraint is not None:
                if not constraint.isSuperTypeOf(other):
                    # wrong constraint intersection
                    return False
        return True

