class FiniteField:

    class Value:

        def __init__(self, value, field):
            self.value = value
            self.field = field

        def __repr__(self):
            return f'FiniteField.Value({self.value}, {self.field.order})'

        def __eq__(self, other):
            if isinstance(other, FiniteField.Value):
                return self.value == other.value and self.field == other.field
            return False

        def __add__(self, other):
            if isinstance(other, FiniteField.Value):
                if self.field != other.field:
                    raise ValueError('Cannot add values from different fields')
                return self.field.Value((self.value + other.value) % self.field.order, self.field)
            return NotImplemented

        def __sub__(self, other):
            if isinstance(other, FiniteField.Value):
                if self.field != other.field:
                    raise ValueError('Cannot subtract values from different fields')
                return self.field.Value((self.value - other.value) % self.field.order, self.field)
            return NotImplemented

        def __mul__(self, other):
            if isinstance(other, FiniteField.Value):
                if self.field != other.field:
                    raise ValueError('Cannot multiply values from different fields')
                return self.field.Value(self.value * other.value % self.field.order, self.field)
            return NotImplemented

