def get_git_branch(path='.'):
    """Returns the current branch of the given git repository
    :param path: path to check
    :return: current branch name as a string"""
    import subprocess
    try:
        result = subprocess.run(['git', '-C', path, 'rev-parse', '--abbrev-ref', 'HEAD'], capture_output=True, text=True, check=True)
        return result.stdout.strip()
    except subprocess.CalledProcessError:
        return 'Error: Unable to get current branch.'

def get_git_commit_hash(path='.'):
