def display_prediction(basis, num_basis=4, wlim=(-1.,1.), fig=None, ax=None, xlim=None, ylim=None, num_points=1000, offset=0.0, **kwargs):
    import numpy as np
    import pylab as plt
    if fig is not None:
        if ax is None:
            ax = fig.gca()
    if xlim is None:
        if ax is not None:
            xlim = ax.get_xlim()
        else:
            xlim = (-2., 2.)
    if ylim is None:
        if ax is not None:
            ylim = ax.get_ylim()
        else:
            ylim = (-1., 1.)
    # initialise X and set up W arguments.
    x = np.zeros((num_points, 1))
    x[:, 0] = np.linspace(xlim[0], xlim[1], num_points)
    param_args = {}
    for i in range(num_basis):
        lim = list(wlim)
        if i ==0:
            lim[0] += offset
            lim[1] += offset
        param_args['w_' + str(i)] = tuple(lim)
    # helper function for making basis prediction.
    def predict_basis(w, basis, x, num_basis, **kwargs):
        Phi = basis(x, num_basis, **kwargs)
        f = np.dot(Phi, w)
        return f, Phi

    if type(basis) is dict:
        use_basis = basis[list(basis.keys())[0]]
    else:
        use_basis = basis
    f, Phi = predict_basis(np.zeros((num_basis, 1)),
                           use_basis, x, num_basis,
                           **kwargs)
    if fig is None:
        fig, ax=plt.subplots(figsize=(12,4))
        ax.set_ylim(ylim)
        ax.set_xlim(xlim)
    predline = ax.plot(x, f, linewidth=2)[0]
    basislines = []
    for i in range(num_basis):
        basislines.append(ax.plot(x, Phi[:, i], 'r')[0])
    ax.set_ylim(ylim)
    ax.set_xlim(xlim)
    def generate_function(basis, num_basis, predline, basislines, basis_args, display_basis, offset, **kwargs):
        w = np.zeros((num_basis, 1))
        for i in range(num_basis):
            w[i] = kwargs['w_'+ str(i)]
        f, Phi = predict_basis(w, basis, x, num_basis, **basis_args)
        predline.set_xdata(x[:, 0])
        predline.set_ydata(f)
        for i in range(num_basis):
            basislines[i].set_xdata(x[:, 0])
            basislines[i].set_ydata(Phi[:, i])
        if display_basis:
            for i in range(num_basis):
                basislines[i].set_alpha(1) # make visible
        else:
            for i in range(num_basis):
                basislines[i].set_alpha(0) 
        display(fig)
    if type(basis) is not dict:
        basis = fixed(basis)
    plt.close(fig)
    interact(generate_function, 
             basis=basis,
             num_basis=fixed(num_basis),
             predline=fixed(predline),
             basislines=fixed(basislines),
             basis_args=fixed(kwargs),
             offset = fixed(offset),
             display_basis = False,
             **param_args)

def absent(name, **kwargs):
    connection_args = {}
    if '_connection_user' in kwargs:
        connection_args['_connection_user'] = kwargs['_connection_user']
    if '_connection_password' in kwargs:
        connection_args['_connection_password'] = kwargs['_connection_password']
    if '_connection_url' in kwargs:
        connection_args['_connection_url'] = kwargs['_connection_url']
    ret = {'name': name, 'changes': {}, 'result': False, 'comment': ''}
    # Comment and change messages
    comment_mediatype_deleted = 'Mediatype {0} deleted.'.format(name)
    comment_mediatype_notdeleted = 'Unable to delete mediatype: {0}. '.format(name)
    comment_mediatype_notexists = 'Mediatype {0} does not exist.'.format(name)
    changes_mediatype_deleted = {name: {'old': 'Mediatype {0} exists.'.format(name),
                                        'new': 'Mediatype {0} deleted.'.format(name),
                                        }
                                 }
    mediatype_exists = __salt__['zabbix.mediatype_get'](name, **connection_args)
    # Dry run, test=true mode
    if __opts__['test']:
        if not mediatype_exists:
            ret['result'] = True
            ret['comment'] = comment_mediatype_notexists
        else:
            ret['result'] = None
            ret['comment'] = comment_mediatype_deleted
        return ret
    if not mediatype_exists:
        ret['result'] = True
        ret['comment'] = comment_mediatype_notexists
    else:
        try:
            mediatypeid = mediatype_exists[0]['mediatypeid']
            mediatype_delete = __salt__['zabbix.mediatype_delete'](mediatypeid, **connection_args)
        except KeyError:
            mediatype_delete = False
        if mediatype_delete and 'error' not in mediatype_delete:
            ret['result'] = True
            ret['comment'] = comment_mediatype_deleted
            ret['changes'] = changes_mediatype_deleted
        else:
            ret['result'] = False
            ret['comment'] = comment_mediatype_notdeleted + six.text_type(mediatype_delete['error'])
    return ret

