class Pagination:

    def __init__(self, query, page, per_page, total, search=None, order_by=None):
        self.query = query
        self.page = page
        self.per_page = per_page
        self.total = total
        self.search = search
        self.order_by = order_by

    def prev(self, error_out=False):
        """Return a :class:`Pagination` object for the previous page."""
        if self.page == 1:
            if error_out:
                raise ValueError('Already at the first page')
            return None
        return Pagination(self.query, self.page - 1, self.per_page, self.total, self.search, self.order_by)

    def next(self, error_out=False):
        """Return a :class:`Pagination` object for the next page."""
        if self.page * self.per_page >= self.total:
            if error_out:
                raise ValueError('Already at the last page')
            return None
        return Pagination(self.query, self.page + 1, self.per_page, self.total, self.search, self.order_by)

    def iter_pages(self, left_edge=2, left_current=2, right_current=5, right_edge=2):
        """Iterates over the page numbers in the pagination.  The four
        parameters control the thresholds how many numbers should be produced
        from the sides.  Skipped page numbers are represented as `None`.
        """
        last = 0
        for num in range(1, self.pages + 1):
            if num <= left_edge or (num > self.page - left_current - 1 and num < self.page + right_current) or num > self.total - right_edge:
