def prox_min(X, step, thresh=0):
    return np.maximum(X - step, thresh)

def prox_l1(X, step):
    """Projection onto the L1 ball"""
    return np.sign(X) * np.maximum(np.abs(X) - step, 0)

def prox_l2(X, step):
    """Projection onto the L2 ball"""
    norm = np.linalg.norm(X)
    if norm > step:
        return X * (1 - step / norm)
    else:
        return X

def prox_linf(X, step):
    """Projection onto the L-infinity ball"""
    return np.clip(X, -step, step)

def prox_l21(X, step):
    """Projection onto the L21 ball"""
    norms = np.linalg.norm(X, axis=1)
    proj_norms = np.maximum(norms - step, 0)
    proj_X = X.copy()
    for i in range(X.shape[0]):
        if norms[i] > 0:
            proj_X[i] *= proj_norms[i] / norms[i]
    return proj_X

def prox_l12(X, step):
    """Projection onto the L12 ball"""
    norms = np.linalg.norm(X, axis=0)
    proj_norms = np.maximum(norms - step, 0)
    proj_X = X.copy()
    for j in range(X.shape[1]):
        if norms[j] > 0:
            proj_X[:, j] *= proj_norms[j] / norms[j]
    return proj_X

def prox_l21_l1(X, step1, step2):
    """Projection onto the L21 ball followed by L1 ball"""
    return prox_l1(prox_l21(X, step1), step2)

def prox_l12_l1(X, step1, step2):
    """Projection onto the L12 ball followed by L1 ball"""
    return prox_l1(prox_l12(X, step1), step2)

def prox_l21_l2(X, step1, step2):
    """Projection onto the L21 ball followed by L2 ball"""
    return prox_l2(prox_l21(X, step1), step2)

