def get_non_lonely_species(tax_ids):
    """
    Return a set of species tax_ids which will makes those in *tax_ids* not lonely.
    The returned species will probably themselves be lonely.
    """
    all_species = set()
    for tax_id in tax_ids:
        all_species.add(tax_id.split('.')[0])

    non_lonely_species = set()
    for species in all_species:
        count = 0
        for tax_id in tax_ids:
            if species in tax_id:
                count += 1
        if count > 1:
            non_lonely_species.add(species)

    return non_lonely_species

