def main() -> None:
    parser = argparse.ArgumentParser(description='Find recovered OpenXML files in a directory.')
    parser.add_argument('directory', type=str, help='The directory to search in.')
    parser.add_argument('--output', type=str, default='recovered_files.txt', help='The output file to write the results to.')
    parser.add_argument('--verbose', action='store_true', help='Enable verbose output.')
    args = parser.parse_args()
    if not os.path.isdir(args.directory):
        print(f"Error: The directory '{args.directory}' does not exist.")
        sys.exit(1)
    recovered_files = find_recovered_openxml_files(args.directory)
    with open(args.output, 'w') as f:
        for file in recovered_files:
            f.write(file + '\n')
    if args.verbose:
        print(f'Recovered OpenXML files found: {len(recovered_files)}')
        for file in recovered_files:
            print(file)

def find_recovered_openxml_files(directory: str) -> List[str]:
    """Find recovered OpenXML files in the specified directory."""
    recovered_files = []
    for (root, _, files) in os.walk(directory):
        for file in files:
            if file.endswith('.docx') or file.endswith('.xlsx') or file.endswith('.pptx'):
                recovered_files.append(os.path.join(root, file))
    return recovered_files

