    target_text = target.text
    target_type_lines = {}

    for dep_type, dep_lines in target.dependency_lines.items():
        if dep_lines:
            target_type_lines[dep_type] = target.formatted_dependency_type_lines(dep_type)

    for dep_type, formatted_lines in target_type_lines.items():
        old_lines = target.dependency_lines[dep_type]

        if old_lines:
            from_line, to_line = min(old_lines), max(old_lines)

            formatted_lines = [l + '\n' for l in formatted_lines]

            target_text = target_text.splitlines()

            target_text[from_line - 1:to_line] = formatted_lines
            target_text = '\n'.join(target_text)

    return target_text

