        def get_keys(node, default_ns):
            keys = Composer(self.device, node).keys
            ret = {}
            for key in keys:
                if origin=='openconfig' or origin == '':
                    key_ns, key_val = gNMIParser.parse_tag(key)
                else:
                    key_ns, key_val = self.device.convert_tag(default_ns,
