def typedargs(func):
    """Decorator to enforce type checking on function arguments and return values.

    Args:
        func (function): The function to be decorated."""

    def wrapper(*args, **kwargs):
        for (i, arg) in enumerate(args):
            expected_type = func.__annotations__.get(func.__code__.co_varnames[i])
            if expected_type and (not isinstance(arg, expected_type)):
                raise TypeError(f'Argument {i} must be of type {expected_type.__name__}')
        for (key, value) in kwargs.items():
            expected_type = func.__annotations__.get(key)
            if expected_type and (not isinstance(value, expected_type)):
                raise TypeError(f'Argument {key} must be of type {expected_type.__name__}')
        result = func(*args, **kwargs)
        expected_return_type = func.__annotations__.get('return')
        if expected_return_type and (not isinstance(result, expected_return_type)):
            raise TypeError(f'Return value must be of type {expected_return_type.__name__}')
        return result
    return wrapper

