def half_cauchy_pdf(x, alpha, beta):
    """Probability Density Function (PDF) of the half-Cauchy distribution."""
    if x < alpha:
        return 0
    return 2 * beta / (np.pi * (beta ** 2 + (x - alpha) ** 2))

def half_cauchy_cdf(x, alpha, beta):
    """Cumulative Distribution Function (CDF) of the half-Cauchy distribution."""
    if x < alpha:
