def _ListWrapper(lst):
    """Wraps a list with a class that overrides all methods that modify
    the list to call on_modify before executing the original method."""

    class WrappedList(list):

        def __init__(self, lst):
            super().__init__(lst)
            self._original_list = lst

        def on_modify(self):
            print('List modified')

        def __setattr__(self, name, value):
            if name == '_original_list':
                super().__setattr__(name, value)
            else:
                self.on_modify()
                super().__setattr__(name, name)

        def __setitem__(self, key, value):
            self.on_modify()
            super().__setitem__(key, value)

        def __delitem__(self, key):
            self.on_modify()
            super().__delitem__(key)

        def __iadd__(self, other):
            self.on_modify()
            return super().__iadd__(other)

        def __imul__(self, other):
            self.on_modify()
            return super().__imul__(other)

        def append(self, item):
            self.on_modify()
            super().append(item)

        def extend(self, iterable):
            self.on_modify()
            super().extend(iterable)

        def insert(self, index, item):
            self.on_modify()
            super().insert(index, item)

        def pop(self, index=-1):
            self.on_modify()
            return super().pop(index)

        def remove(self, value):
            self.on_modify()
            super().remove(value)

        def clear(self):
            self.on_modify()
            super().clear()

        def sort(self, *args, **kwargs):
            self.on_modify()
            super().sort(*args, **kwargs)

        def reverse(self):
            self.on_modify()
            super().reverse()
    return WrappedList(lst)
