def search_shortest_basis(lattice, method, tolerance):
    import numpy as np
    from scipy.spatial import Delaunay
    from pyxtal import symmetry
    from pyxtal.symmetry import reduce_chernikov
    from pyxtal.tolerance import tol_matrix

    if method == "delaunay":
        reduced_lattice = Delaunay(lattice).points[:3]
    elif method == "niggli":
        reduced_lattice = reduce_chernikov(lattice)
    else:
        raise ValueError("Invalid method. Please choose delaunay or niggli.")

    tol_mat = tol_matrix(reduced_lattice, tolerance)
    B = np.linalg.inv(lattice)
    v = []
    for i in range(-1, 2):
        for j in range(-1, 2):
            for k in range(-1, 2):
                v.append(np.dot(np.array([i,j,k]), B))
    v = np.dot(v, tol_mat)
    v = np.unique(np.round(v, decimals=8), axis=0) # this is to avoid all the duplicates
    v = np.dot(v, reduced_lattice)
    return v for v in v if np.allclose(v, np.round(v, decimals=8))]

