def recurrenceNextInstance(start_date, frequency):
    if frequency == "once":
        return None

    current_date = start_date.date()

    if frequency == "weekly":
        days = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
        weekday = days.index(start_date.strftime("%A").lower())
        delta = (7 + days.index(weekday)) % 7
        next_date = current_date + timedelta(days=delta)

    elif frequency == "monthly":
        next_date = current_date.replace(day=start_date.day) + timedelta(days=30)

    elif frequency == "yearly":
        next_date = current_date.replace(day=start_date.day, month=start_date.month) + timedelta(
            days=365 if start_date.year % 4 != 0 else 366)

    return datetime.combine(next_date, start_date.time())

