    visited = set()
    parent = {}

    def dfs(v, time):
        visited.add(v)
        low[v] = time
        time += 1
        is_cut_vertex = False
        children = 0

        for w in graph[v]:
            if w not in visited:
                children += 1
                parent[w] = v
                dfs(w, time)
                low[v] = min(low[v], low[w])
                if parent[v] is None and children > 1:
                    is_cut_vertex = True
                if parent[v] is not None and low[w] >= time:
                    is_cut_vertex = True
            elif w != parent[v]:
                low[v] = min(low[v], low[w])

        if parent[v] is None and children > 1:
            is_cut_vertex = True

        if is_cut_vertex:
            vertices.remove(v)

    for v in graph.keys():
        if v not in visited:
            parent[v] = None
            dfs(v, 0)

