    @staticmethod
    def new(version):
        """
        Creates a new header instance with the specified version.
        """
        return LasHeader(version)

    @staticmethod
    def convert_header(old_header, new_version):
        """
        Converts a header to another version.
        """
        old_version = old_header.version
        new_version = float(new_version)

        if old_version == new_version:
            # header already in desired version
            return old_header

        # create new header with desired version
        new_header = LasHeader(new_version)

        # transfer curve data to new header
        for curve in old_header.curves:
            curve_data = old_header.curve_data(curve)
            new_header.add_curve(curve, curve_data['data'], curve_data['description'])

        # transfer other data to new header
        for section_name in old_header.sections:
            if section_name == 'CURVE':
                # we already transferred curve data
                continue

            section_data = old_header._data[section_name]
            new_header._data[section_name] = section_data

        return new_header

