def convert_to_split_node(toL):
    for hdl_obj in toL:
        if isinstance(hdl_obj, tuple):
            sig_list = [toL[sig] for sig in hdl_obj]
            toL[hdl_obj] = tuple(sig_list)
        else:
            for attr, value in toL[hdl_obj].items():
                if '[' in value and ']' in value:
                    sig_idx = value[value.find('[')+1:value.find(']')]
                    if sig_idx.isdigit():
                        sig_idx = int(sig_idx)
                        sig_name = value[:value.find('[')]
                        if sig_idx == 0:
                            sig_list = [toL[hdl_obj][f'{sig_name}[{i}]'] for i in range(toL[hdl_obj][f'{sig_name}.length'])]
                            toL[hdl_obj][sig_name] = tuple(sig_list)
                            for i in range(sig_idx, toL[hdl_obj][f'{sig_name}.length']):
                                del toL[hdl_obj][f'{sig_name}[{i}]']
                        else:
                            toL[hdl_obj][f'{sig_name}[0]'] = toL[hdl_obj][f'{sig_name}[{sig_idx}]']
                            del toL[hdl_obj][f'{sig_name}[{sig_idx}]']
