def read_sentence(sentence):
    nodes = {}
    root_id = sentence.get('id')
    for node in sentence.iter('node'):
        attrs = dict(node.attrib)
        attrs.pop('id')
        nodes[node.get('id')] = attrs
    sort_key = lambda node: int(node['off'])
    tokens = sorted(nodes.values(), key=sort_key)
    tokens = [token['id'] for token in tokens]
    sentence.attrib['tokens'] = ' '.join(tokens)
    return {
        'id': root_id,
        'tokens': tokens,
        'nodes': nodes,
    }

