def is_connected(G):
    """is_connected(G) checks if the graph G is connected."""
    if not G:
        return True
    start_node = next(iter(G[0]))
    visited = set()
    stack = [start_node]
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            stack.extend(neighbors(G, node) - visited)
    return len(visited) == len(set((arc[0] for arc in G)) | set((arc[2] for arc in G)))

def is_tree(G):
    """is_tree(G) checks if the graph G is a tree."""
    return is_connected(G) and len(G) == len(set((arc[0] for arc in G)) | set((arc[2] for arc in G))) - 1
