def prompt(message: str, text_input: bool, timeout_s: float, cli_color: str) -> str:
    if cli_color:
        message = f"{cli_color}{message}\033[0m"
    prompts: List[Tuple[str, bool]] = []
    for prompt in prompts:
        if prompt[1]:
            raise MultiplePromptsError("There is an existing prompt already")
    prompts.append((message, text_input))
    response = ""
