def peek(self):
    if self._pos >= len(self._tokens):
        return None
    return self._tokens[self._pos]

def consume(self):
    """Consume the next token and return it.

        At the end of input, ``None`` is returned."""
    if self._pos >= len(self._tokens):
        return None
    token = self._tokens[self._pos]
    self._pos += 1
    return token

def consume_until(self, token_type):
    """Consume tokens until a token of the specified type is encountered.

        The token of the specified type is not consumed. Returns a list of
        consumed tokens."""
    consumed_tokens = []
    while True:
        current_token = self.peek()
        if current_token is None or current_token.type == token_type:
            break
        consumed_tokens.append(self.consume())
    return consumed_tokens

def consume_until_any(self, token_types):
    """Consume tokens until a token of any of the specified types is encountered.

        The token of the specified type is not consumed. Returns a list of
        consumed tokens."""
    consumed_tokens = []
    while True:
        current_token = self.peek()
        if current_token is None or current_token.type in token_types:
            break
        consumed_tokens.append(self.consume())
    return consumed_tokens

def consume_all(self):
    """Consume all remaining tokens and return them as a list."""
    consumed_tokens = []
    while True:
        current_token = self.peek()
        if current_token is None:
            break
        consumed_tokens.append(self.consume())
    return consumed_tokens

