from sympy import isprime

def generate_pseudo_prime(a, b):
    while True:
        p = random.randint(a, b)
        if isprime(p):
            continue
        if pow(2, p-1, p) != 1:
            continue
        if isprime((p-1)//2):
            return p

def generate_keys(a, b):
    p, q = generate_pseudo_prime(a, b), generate_pseudo_prime(a, b)
    n = p*q
    phi_n = (p-1)*(q-1)
    e = random.randint(2, phi_n - 1)
    gcd, _, _ = extended_gcd(e, phi_n)
    while gcd != 1:
        e = random.randint(2,phi_n - 1)
        gcd, _, _ = extended_gcd(e, phi_n)
    d = pow(e, -1, phi_n)
    return (n, e), (n, d)

def extended_gcd(a, b):
    x, y, u, v = 0, 1, 1, 0
    while a != 0:
        q, r = b // a, b % a
        m, n = x - u * q, y - v * q
        b, a, x, y, u, v = a, r, u, v, m, n
    gcd = b
    return gcd, x, y

def find_large_pseudo_primes(a, b):
    for _ in range(100):
        p, q = random.randint(a, b), random.randint(a, b)
        if isprime(p) and isprime(q):
            n = p*q
            if n.bit_length() >= 1024:
                return (p, q)
    raise ValueError("Could not find large prime numbers within range")

