def get_left_right(seq):
    left = 0
    right = len(seq) - 1
    while left < right:
        if seq[left] == 'N':
            left += 1
        elif seq[right] == 'N':
            right -= 1
        else:
            break
    return (left, right)

def get_sequence_length(seq):
    """Calculate the length of the sequence excluding 'N' bases"""
    (left, right) = get_left_right(seq)
    return right - left + 1

def get_gc_content(seq):
    """Calculate the GC content of the sequence excluding 'N' bases"""
    (left, right) = get_left_right(seq)
    gc_count = sum((1 for base in seq[left:right + 1] if base in 'GCgc'))
    return gc_count / (right - left + 1) if right - left + 1 > 0 else 0

def get_at_content(seq):
    """Calculate the AT content of the sequence excluding 'N' bases"""
    (left, right) = get_left_right(seq)
    at_count = sum((1 for base in seq[left:right + 1] if base in 'ATat'))
    return at_count / (right - left + 1) if right - left + 1 > 0 else 0

