def euclidean(x, y):
    """Euclidean distance.

    ..math::
        D(x, y) = \\sqrt{\\sum_i (x_i - y_i)^2}"""
    return sum(((xi - yi) ** 2 for (xi, yi) in zip(x, y))) ** 0.5

def manhattan(x, y):
    """Manhattan or l1 distance.

    ..math::
        D(x, y) = \\sum_i |x_i - y_i|"""
    return sum((abs(xi - yi) for (xi, yi) in zip(x, y)))

def minkowski(x, y, p):
    """Minkowski distance.

    ..math::
        D(x, y) = \\left(\\sum_i |x_i - y_i|^p\right)^{1/p}"""
    return sum((abs(xi - yi) ** p for (xi, yi) in zip(x, y))) ** (1 / p)

def cosine(x, y):
    """Cosine distance.

    ..math::
        D(x, y) = 1 - \x0crac{\\sum_i x_i y_i}{\\sqrt{\\sum_i x_i^2} \\sqrt{\\sum_i y_i^2}}"""
    numerator = sum((xi * yi for (xi, yi) in zip(x, y)))
    denominator = sum((xi ** 2 for xi in x)) ** 0.5 * sum((yi ** 2 for yi in y)) ** 0.5
    return 1 - numerator / denominator

def jaccard(x, y):
    """Jaccard distance.

    ..math::
        D(x, y) = 1 - \x0crac{|x \\cap y|}{|x \\cup y|}"""
    set_x = set(x)
    set_y = set(y)
    intersection = set_x.intersection(set_y)
    union = set_x.union(set_y)
    return 1 - len(intersection) / len(union)

