    queue = [(start, [])]
    visited = set()
    while queue:
        (node, path) = queue.pop(0)
        if node not in visited:
            visited.add(node)
            path = path + [node]
            if node == end:
                return path
            for neighbor in self._graph[node]:
                queue.append((neighbor, path))
    return None

def _findShortestPathWithLabels(self, start, end):
    """Finds the shortest path from start to end in the graph and returns the path with edge labels"""
    queue = [(start, [])]
    visited = set()
    while queue:
        (node, path) = queue.pop(0)
        if node not in visited:
            visited.add(node)
            path = path + [(node, self._edgeLabel(node, path[-1][0]) if path else None)]
            if node == end:
                return path

