class SuiteObject:
    """Represents a suite of values."""

    def __init__(self, name=''):
        self.name = name
        self.values = []

    def Add(self, value):
        """Adds a value to the suite.

        Args:
            value: number to be added"""
        self.values.append(value)

    def Mean(self):
        """Computes the mean of the values in the suite.

        Returns:
            float mean of the values"""
        return sum(self.values) / len(self.values)

    def Median(self):
        """Computes the median of the values in the suite.

        Returns:
            float median of the values"""
        sorted_values = sorted(self.values)
        n = len(sorted_values)
        if n % 2 == 1:
            return sorted_values[n // 2]
        else:
            return (sorted_values[n // 2 - 1] + sorted_values[n // 2]) / 2

    def Mode(self):
        """Computes the mode of the values in the suite.

        Returns:
            float mode of the values"""
        from collections import Counter
        count = Counter(self.values)
        max_count = max(count.values())
        modes = [k for (k, v) in count.items() if v == max_count]
        if len(modes) == 1:
            return modes[0]
        else:
            return modes

    def Variance(self):
        """Computes the variance of the values in the suite.

        Returns:
            float variance of the values"""
        mean = self.Mean()
        return sum(((x - mean) ** 2 for x in self.values)) / len(self.values)

    def StdDev(self):
        """Computes the standard deviation of the values in the suite.

        Returns:
            float standard deviation of the values"""
        return self.Variance() ** 0.5

