def occultquad(z, u1, u2, p0, return_components=False):
    import numpy as np
    from scipy.integrate import quad

    def limb_darkening(r, u1, u2):
        return 1 - u1 * (1 - r ** 2) - u2 * (1 - r ** 2) ** 2

    def integrand(r, z, u1, u2):
        if r <= 1:
            return limb_darkening(r, u1, u2)
        else:
            return 0

    def compute_integral(z, u1, u2):
        if z >= 1 + 1:
            return 0
        elif z <= 1 - 1:
            return np.pi
        else:
            (result, _) = quad(integrand, 0, 1, args=(z, u1, u2))
            return result
    if isinstance(z, (int, float)):
        flux = 1 - p0 * compute_integral(z, u1, u2)
    elif isinstance(z, np.ndarray):
        flux = 1 - p0 * np.array([compute_integral(zi, u1, u2) for zi in z])
    else:
        raise ValueError('z must be a float, int, or numpy array')
    if return_components:
        return (flux, compute_integral(z, u1, u2))
    else:
        return flux

