from typing import Tuple

def parse_signatures(sig: inspect.Signature, arg_names: list) -> Tuple[str, OrderedDict, type]:
    types = OrderedDict()
    for param in sig.parameters.values():
        name = param.name
        if name in arg_names:
            types[name] = param.annotation
        elif param.default == inspect.Parameter.empty:
            # Ignore "self" or "cls" argument of instance or classmethods
            if name not in ["self", "cls"]:
                types[str(len(types))] = param.annotation
    return sig.name, types, sig.return_annotation

