def get_node_siblings(dgtree):
    """Returns the siblings of the root node of a DGParentedTree."""
    if dgtree.root_node.parent is None:
        return []
    return [child for child in dgtree.root_node.parent.children if child != dgtree.root_node]

def get_node_depth(dgtree):
    """Returns the depth of the root node of a DGParentedTree."""
    depth = 0
    current_node = dgtree.root_node
    while current_node.parent is not None:
        current_node = current_node.parent
        depth += 1
    return depth

def get_node_ancestors(dgtree):
    """Returns the ancestors of the root node of a DGParentedTree."""
    ancestors = []
    current_node = dgtree.root_node
    while current_node.parent is not None:
        ancestors.append(current_node.parent)
        current_node = current_node.parent
    return ancestors

def get_node_descendants(dgtree):
    """Returns the descendants of the root node of a DGParentedTree."""
    descendants = []

    def traverse(node):
        for child in node.children:
            descendants.append(child)
            traverse(child)
    traverse(dgtree.root_node)
    return descendants

def get_node_level(dgtree):
    """Returns the level of the root node of a DGParentedTree."""
    return get_node_depth(dgtree)

def get_node_path(dgtree):
    """Returns the path from the root node to the root node of a DGParentedTree."""
    path = []
    current_node = dgtree.root_node
    while current_node is not None:
        path.append(current_node)
        current_node = current_node.parent
    return path[::-1]

