def object_to_string(obj, top=True):
    if isinstance(obj, list):
        if top:
            result = ""
            for item in obj:
                result += object_to_string(item, top=False) + "\n"
            return result
        else:
            result = "["
            for item in obj:
                result += object_to_string(item, top=False) + ", "
            return result.rstrip(", ") + "]"
    elif isinstance(obj, dict):
        result = "{"
        for key, value in obj.items():
            result += f"{key}: {object_to_string(value, top=False)}, "
        return result.rstrip(", ") + "}"
    else:
        if top:
            return f"{obj.__class__.__name__}({obj})"
        else:
            return f"{obj}"

