        """Insert a new line at the specified 1-indexed line number"""
        if lnum < 1:
            raise ValueError('Line number must be 1-indexed')
        if lnum > len(self.lines) + 1:
            raise ValueError('Line number exceeds the number of lines plus one')
        self.lines.insert(lnum - 1, content)

