def map_coordinates(func, obj):
    if not isinstance(obj, (Point, LineString, MultiPoint, MultiLineString, Polygon, MultiPolygon)):
        raise ValueError('Object must be a valid GeoJSON geometry or feature.')
    result = []
    if isinstance(obj, (Point, MultiPoint)):
        coords = obj.coords[:]
        for i in range(len(coords)):
            coords[i] = tuple(map(func, coords[i]))
        result.append(coords)
    elif isinstance(obj, (LineString, MultiLineString)):
        lines = obj.coords[:]
        for i in range(len(lines)):
            coords = lines[i]
            for j in range(len(coords)):
                coords[j] = tuple(map(func, coords[j]))
            lines[i] = coords
        result.append(lines)
    elif isinstance(obj, (Polygon, MultiPolygon)):
        polys = obj.coords[:]
        for i in range(len(polys)):
            rings = polys[i]
            for j in range(len(rings)):
                coords = rings[j]
                for k in range(len(coords)):
                    coords[k] = tuple(map(func, coords[k]))
                rings[j] = coords
            polys[i] = rings
        result.append(polys)

    return result

