import numpy as np

def count_bit_errors(tx_data, rx_data, Ncorr=2):
    if Ncorr % 2 != 0:
        raise ValueError("Ncorr needs to be even")
    tx_data_delay = np.roll(tx_data, -Ncorr // 2)
    rx_data_delay = np.roll(rx_data, Ncorr // 2)
    rx_data_delay[np.abs(rx_data_delay) < np.abs(-rx_data_delay)] = -rx_data_delay[np.abs(rx_data_delay) < np.abs(-rx_data_delay)]
    tx_data_delay[np.abs(tx_data_delay) < np.abs(-tx_data_delay)] = -tx_data_delay[np.abs(tx_data_delay) < np.abs(-tx_data_delay)]
    return int(np.sum(np.abs(np.sign(tx_data_delay + rx_data_delay))))

