def get_io_stats():
    with open('/proc/stat') as f:
        content = f.readlines()

    io_stats = {}
    for line in content:
        if line.startswith('ios'):
            dev_stats = line.split()[1:]
            devices = [dev_stats[i] for i in range(len(dev_stats)) if i%3 == 0]
            r_ios = [int(dev_stats[i]) for i in range(len(dev_stats)) if i%3 == 1]
            w_ios = [int(dev_stats[i]) for i in range(len(dev_stats)) if i%3 == 2]
            io_stats = {dev: [r_ios[i], w_ios[i]] for i, dev in enumerate(devices)}

    return io_stats

