class PCapStream:

    def __init__(self, filename):
        self.filename = filename
        self.file = open(filename, 'rb')
        self.header = self.read_header()

    def read_header(self):
        """Reads the global header from the PCap file."""
        header = self.file.read(24)
        if len(header) != 24:
            raise ValueError('Invalid PCap file header')
        return header

    def read(self):
        """Reads the next packet from the PCap file."""
        packet_header = self.file.read(16)
        if len(packet_header) != 16:
            raise ValueError('Invalid packet header')
        packet_length = int.from_bytes(packet_header[8:12], byteorder='little')
        packet_data = self.file.read(packet_length)
        if len(packet_data) != packet_length:
            raise ValueError('Invalid packet data')
        return (packet_header, packet_data)

    def close(self):
        """Closes the PCap file."""
        self.file.close()

