def teetab(source: Union[str, IO], sink: Optional[Union[str, IO]] = None,
           encoding: Optional[str] = None, errors: Optional[str] = None,
           compression: Optional[str] = None,
           write_header: bool = True, suffix: Optional[str] = None,
           **kwargs: Any) -> Union[List[List[str]], IO]:

    def add_suffix(filename: str, suffix: Optional[str]) -> str:
        return f'{filename}{f".{suffix}" if suffix else ""}'

    sniffer_params = {'delimiter': '\t', 'doublequote': True,
                      'escapechar': None, 'quotechar': '"',
                      'skipinitialspace': False, 'strict': False}

    reader_params = dict(sniffer_params)
    writer_params = dict(sniffer_params)

    if encoding or errors:
        if encoding:
            reader_params['encoding'] = encoding
            writer_params['encoding'] = encoding
        if errors:
            reader_params['errors'] = errors
            writer_params['errors'] = errors

    if compression:
        reader_params['mode'] = f'rt:{compression}'
        writer_params['mode'] = f'wt:{compression}'
    else:
        reader_params['mode'] = 'rt'
        writer_params['mode'] = 'wt'

    # handle suffix
    if not sink and suffix:
        raise ValueError('if suffix is provided, sink must be a filename')
    elif sink and suffix:
        sink = add_suffix(sink, suffix)

    source = read_source(source, **reader_params)
    writer: Optional[csv.writer] = None
    target: Union[IO, List[List[str]]]

    try:
        for row in csv.reader(source, **sniffer_params):
            if write_header and writer is None:
                # write header only in first time
                if sink:
                    if not isinstance(sink, str):
                        raise ValueError('for tab delimiter, only filenames are '
                                         'supported as sinks (not file handles)')
                    with open(sink, **writer_params) as f:
                        writer = csv.writer(f, **writer_params)
                        writer.writerow(row)
                target = [row]
            else:
                if writer:
                    writer.writerow(row)
                target.append(row)
            yield row
    finally:
        if writer:
            writer.close()

    # handle sink
    if sink:
        target = write_source(target, sink, **writer_params)
        if compression:
            with open(target, reader_params['mode']) as f:
                return f.read()
        else:
            return target
    else:
        return target

