def format_time(amount, maxunits=3):
    assert maxunits >= 1, "maxunits should be greater than or equal to 1"
    units = [('day', 86400), ('hour', 3600), ('minute', 60), ('second', 1)]
    parts = []
    for unit, value in units:
        if amount >= value:
            count = amount // value
            amount -= count * value
            parts.append('{} {}{}'.format(count, unit, '' if count == 1 else 's'))
        if amount == 0:
            break
    if len(parts) > maxunits:
        parts = parts[:maxunits]
    return ', '.join(parts)

