    """If this span is within the given span."""
    return self.start >= span.start and self.end <= span.end

def overlaps(self, span):
    """If this span overlaps with the given span."""
    return self.start < span.end and self.end > span.start

def abuts(self, span):
    """If this span abuts the given span."""
    return self.end == span.start or self.start == span.end

def adjacent(self, span):
    """If this span is adjacent to the given span."""
    return self.end == span.start or self.start == span.end

def gap(self, span):
    """If there is a gap between this span and the given span."""
    return self.end < span.start or self.start > span.end

def distance(self, span):
    """Calculate the distance between this span and the given span."""
    if self.end < span.start:
        return span.start - self.end
    elif self.start > span.end:
        return self.start - span.end
    else:
        return 0

