    class BinaryOp(Expr):
        def __init__(self, op, lhs, rhs):
            self.op = op
            self.lhs = lhs
            self.rhs = rhs

        def _repr(self):
            return '{} {} {}'.format(self.lhs, self.op, self.rhs)

        def _eval(self, values):
            lhs_val = self.lhs.eval(values)
            rhs_val = self.rhs.eval(values)

            if self.op == '+':
                return lhs_val + rhs_val
            elif self.op == '-':
                return lhs_val - rhs_val
            elif self.op == '*':
