def zmq_socket(self, key):
    """Return a ZeroMQ socket to the module with the provided key."""
    if key in self.module_sockets:
        return self.module_sockets[key]
    else:
        raise KeyError(f'No socket found for module with key: {key}')

def zmq_connect(self, key):
    """Establish a ZeroMQ connection to the module with the provided key."""
    address = self.zmq_address(key)
    context = zmq.Context()
    socket = context.socket(zmq.REQ)
    socket.connect(address)
    self.module_sockets[key] = socket
    return socket

def zmq_send(self, key, message):
    """Send a message to the module with the provided key."""
    socket = self.zmq_socket(key)
    socket.send_string(message)
    response = socket.recv_string()
    return response

def zmq_close(self, key):
    """Close the ZeroMQ socket for the module with the provided key."""
    if key in self.module_sockets:
        socket = self.module_sockets[key]
        socket.close()
        del self.module_sockets[key]
    else:
        raise KeyError(f'No socket found for module with key: {key}')

def zmq_disconnect(self, key):
    """Disconnect the ZeroMQ socket for the module with the provided key."""
    self.zmq_close(key)

