    """
    Compute the accumulated cost matrix, and return it.
    Return ``None`` if the accumulated cost matrix cannot be computed
    because one of the two waves is empty after masking (if requested).

    :param mask: Mask to remove invalid paths. ``True`` means that the
                 path is invalid.
    :type mask: 2D bool array. Mask shape must agree with input arrays
                shape.
    :param out: Optional output array. If provided, ``out`` must have
                the same shape as the accumulated cost matrix and
                must be a numpy array (32 bits dtype).
    :type out: numpy.ndarray
    :rtype: :class:`numpy.ndarray` (2D)
    :raises: RuntimeError: if both the C extension and
                           the pure Python code did not succeed.
    """
    if mask is not None:
        if mask.dtype != np.bool:
            raise ValueError("The mask must have a boolean dtype.")
        if mask.shape != self.shape:
            raise ValueError("The mask shape must agree with the input arrays shape.")

    if out is not None:
        if out.dtype != np.int32:
            raise ValueError("The output array must have a 32-bit integer dtype.")
        if out.shape != self.shape:
            raise ValueError("The output array shape must agree with the input arrays shape.")

    if self.M == 0 or self.N == 0:
        return None

    if self.use_c:
        try:
            return self._accumulate_c(mask=mask, out=out)
        except RuntimeError as e:
            if self.verbose > 0:
                print("_accumulate_c failed: {}".format(str(e)))
            pass

    if not self.use_c or self.force_python:

        try:
            return self._accumulate_python(mask=mask, out=out)
        except RuntimeError as e:
            if self.verbose > 0:
                print("_accumulate_python failed: {}".format(str(e)))
            if self.use_c:
                raise RuntimeError("Both the C extension and the pure Python implementation have failed. "
                                   "See above for more information.") from e
            pass

    if self.use_c and not self.force_python:
        raise RuntimeError("The C extension has failed, but the pure Python implementation has not been attempted. "
                           "Set force_python=True to use pure Python.")

