class IRCMappingDict(dict):

    def __init__(self, in_dict, casemapping):
        super().__init__()
        self.casemapping = casemapping
        for (key, value) in in_dict.items():
            self[key] = value

    def __setitem__(self, key, value):
        super().__setitem__(self._normalize_key(key), value)

    def __getitem__(self, key):
        return super().__getitem__(self._normalize_key(key))

    def __delitem__(self, key):
        super().__delitem__(self._normalize_key(key))

    def __contains__(self, key):
        return super().__contains__(self._normalize_key(key))

    def _normalize_key(self, key):
        if self.casemapping == 'rfc1459':
            return key.lower()
        elif self.casemapping == 'strict-rfc1459':
            return key.lower().replace('[', '{').replace(']', '}').replace('\\', '|').replace('^', '~')
        elif self.casemapping == 'ascii':
            return key.lower()
        else:
            raise ValueError(f'Unknown casemapping: {self.casemapping}')

    def keys(self):
        return super().keys()

    def items(self):
        return super().items()

    def values(self):
        return super().values()

    def get(self, key, default=None):
        return super().get(self._normalize_key(key), default)

    def pop(self, key, default=None):
        return super().pop(self._normalize_key(key), default)

    def update(self, *args, **kwargs):
        for (key, value) in dict(*args, **kwargs).items():
            self[key] = value

    def setdefault(self, key, default=None):
        return super().setdefault(self._normalize_key(key), default)

    def clear(self):
        super().clear()

    def copy(self):
        return

