    return not is_absolute_path(path)

def get_parent_directory(path):
    """Get the parent directory of a path."""
    if is_absolute_path(path):
        components = split_path(path)
        if len(components) > 1:
            return '/'.join(components[:-1])
        return '/'
    else:
        components = split_path(path)
