def _is_in_comment_type(token_type):
    return token_type in {'COMMENT', 'DOCSTRING'}

def _is_in_string_type(token_type):
    """Return true if this kind of token can be inside a string."""
    return token_type in {'STRING', 'BYTES'}

def _is_in_code_type(token_type):
    """Return true if this kind of token can be inside code."""
    return token_type in {'CODE', 'KEYWORD', 'OPERATOR', 'NAME', 'NUMBER'}

def _is_in_type(token_type, context_type):
    """Return true if the token type is valid in the given context type."""
    if context_type == 'COMMENT':
        return _is_in_comment_type(token_type)
    elif context_type == 'STRING':
        return _is_in_string_type(token_type)
    elif context_type == 'CODE':
        return _is_in_code_type(token_type)
    else:
        raise ValueError(f'Unknown context type: {context_type}')

def _get_context_type(token):
    """Determine the context type of a token based on its type."""
    if token.type in {'COMMENT', 'DOCSTRING'}:
        return 'COMMENT'
    elif token.type in {'STRING', 'BYTES'}:
        return 'STRING'
    elif token.type in {'CODE', 'KEYWORD', 'OPERATOR', 'NAME', 'NUMBER'}:
        return 'CODE'
    else:
        raise ValueError(f'Unknown token type: {token.type}')

def _validate_token(token, context_type):
    """Validate if a token is valid in the given context type."""
    if not _is_in_type(token.type, context_type):
        raise ValueError(f'Token type {token.type} is not valid in context type {context_type}')

