def uri_split_tree(uri):
    def split_authority(auth):
        if '@' in auth:
            creds, host = auth.split('@')
            user, passwd = creds.split(':')
        else:
            user, passwd, host = None, None, auth
        if ':' in host:
            host, port = host.split(':')
        else:
            port = None
        return user, passwd, host, port

    def split_query(query):
        query_dict = {}
        for q in query.split('&'):
            k, v = q.split('=')
            k = unquote_plus(k)
            v = unquote_plus(v)
            query_dict[k] = v
        return tuple(query_dict.items())

    scheme, netloc, path, query, fragment = urlparse(uri)
    try:
        auth, host = netloc.split('@')[-1], netloc.split('@')[-1]
    except ValueError:
        auth, host = None, netloc
    else:
        auth, host = netloc.split('@')
    auth_split = split_authority(auth)
    query_split = split_query(query)
    return scheme, auth_split, path, query_split, fragment

