def _parse(self):
    elements = []
    with open(self.input_file, 'r') as file:
        content = file.readlines()
    for line in content:
        stripped_line = line.strip()
        if stripped_line.startswith('"""') or stripped_line.startswith("'''"):
            docstring = stripped_line
            while not (docstring.endswith('"""') or docstring.endswith("'''")):
                next_line = content.pop(0).strip()
                docstring += '\n' + next_line
            elements.append(docstring)
        elif stripped_line.startswith('def ') or stripped_line.startswith('class '):
            element_name = stripped_line.split()[1].split('(')[0]
            elements.append(element_name)
    return elements

