def http_endpoint(event, context):
    import boto3
    import json
    import decimal

    dynamodb = boto3.resource('dynamodb')

    if 'TableName' in event['queryStringParameters']:
        table = dynamodb.Table(event['queryStringParameters']['TableName'])
    else:
        return {
            'statusCode': 400,
            'body': json.dumps('Table name not provided')
        }

    if event['httpMethod'] == 'GET':
        response = table.scan()
        return {
            'statusCode': 200,
            'body': json.dumps(response['Items'])
        }

    elif event['httpMethod'] in ['POST', 'PUT', 'DELETE']:
        try:
            payload = json.loads(event['body'], parse_float=decimal.Decimal)
        except Exception as e:
            return {
                'statusCode': 400,
                'body': json.dumps('Error: Failed to parse request body')
            }

        if event['httpMethod'] == 'POST':
            table.put_item(Item=payload)
        elif event['httpMethod'] == 'PUT':
            table.update_item(
                Key={
                    'primaryKey': payload['primaryKey']
                },
                UpdateExpression='SET data = :val1',
                ExpressionAttributeValues={
                    ':val1': payload['data']
                }
            )
        elif event['httpMethod'] == 'DELETE':
            table.delete_item(
                Key={
                    'primaryKey': payload['primaryKey']
                }
            )
        return {
            'statusCode': 200,
            'body': json.dumps('Success')
        }
    else:
        return {
            'statusCode': 400,
            'body': json.dumps('Error: Unsupported HTTP method')
