    - Tuple[str, Optional[str]] - a tuple containing the updated group and the new current group, if any.
    """

    if token == "(":
        return "", ""
    elif token == ")":
        return current_group, ""
    elif token == ",":
        return current_group + ",", ""
    elif current_group is not None:
        return current_group + " " + token, current_group
    else:
        return token, ""

