def check_perms(path, ret, user=None, group=None, mode=None, follow_symlinks=False, selinux=None):
    """
    Check the permissions on files, modify attributes and chown if needed. File
    attributes are only verified if lsattr(1) is installed.
    """
    def chown(path, user, group):
        """
        Change the ownership of a file
        """
        # Strip any domain info from user and group
        if user:
            user = user.split('\\')[-1]
        if group:
            group = group.split('\\')[-1]
        uid = __salt__['file.user_to_uid'](user)
        gid = __salt__['file.group_to_gid'](group)
        if uid == None or gid == None:
            log.warning('Ownership change failed, user or group not found')
            return False
        os.chown(path, uid, gid)
        return True

    def chmod(path, mode):
        """
        Change the mode of a file
        """
        # Normalize the permissions to a string
        try:
            mode = str(mode).lstrip('0')
        except Exception as e:
            log.warning('Invalid mode: {0}. {1}'.format(mode, e))
            return False

        # Only change the mode if it is not the expected mode
        if oct(os.stat(path).st_mode)[-3:] != mode:
            try:
                os.chmod(path, int(mode, 8))
            except Exception as e:
                log.warning('Chmod failed: {0}'.format(e))
                return False

        return True

    def run_lsattr(path):
        """
        Run the lsattr command and return the attributes or None if not installed
        """
        try:
            out = subprocess.check_output(['lsattr', path])
        except Exception as e:
            return None
        ret = ''
        for attr in out.split():
            if attr.isalpha():
                ret += attr
        return ret

    def set_attributes(path, attrs):
        """
        Set attributes of a file
        """
        if run_lsattr(path) != attrs:
            try:
                subprocess.check_call(['chattr', attrs, path])
            except Exception as e:
                log.warning('chattr failed: {0}'.format(e))
                return False
        return True

    def check_selinux(path, fmode, uret, uact):
        """
        Check the SELinux security context of the file
        """
        if not selinux:
            return True

        # Determine the expected context
        try:
            bin_uact = uact.split('\\')[-1]
            context = __salt__['selinux.fcontext_get'](path, bin_uact, True)
            if not context:
                return True
            expected = context[0]['selabel']
        except Exception as e:
            log.warning('Unable to lookup expected SELinux context for {0}: {1}'.format(path, e))
            return False

        # Resolve the current context
        current = __salt__['selinux.fcontext_path'](path, fmode)

        # Compare the contexts
        if current != expected:
            try:
                __salt__['selinux.fcontext_modify'](path, uret, uact, expected)
            except Exception as e:
                log.warning('Unable to apply desired SELinux context {0} to {1}: {2}'.format(expected, path, e))
                return False
        return True

    if not os.path.exists(path):
        log.warning('File not found: {0}'.format(path))
        return False

    if follow_symlinks:
        path = os.path.realpath(path)

    # Verify the UID/GID
    stats = os.stat(path)
    uid = __salt__['file.user_from_uid'](stats.st_uid)
    gid = __salt__['file.group_from_gid'](stats.st_gid)
    if user and uid != user:
        if not chown(path, user, None):
            return False
    if group and gid != group:
        if not chown(path, None, group):
            return False

    # Verify the mode
    if mode:
        if not chmod(path, mode):
            return False

    # Verify the file attributes
    if run_lsattr(path):
        if not set_attributes(path, ret):
