def image_import(self, image_name, url, image_meta, remote_host=None):
    existing_image = self.image_db.get(image_name)
    if existing_image:
        raise ValueError(f'Image {image_name} already exists in the database.')
    if not url.startswith(('http://', 'https://')):
        raise ValueError('Invalid URL. URL must start with http:// or https://.')
    if not isinstance(image_meta, dict):
        raise ValueError('Image metadata must be a dictionary.')
    prov_method = image_meta.get('prov_method', 'unknown')
    os_version = image_meta.get('os_version', 'unknown')
    image_repository = self.config.get('image_repository', '/opt/sdk/images')
    image_path = os.path.join(image_repository, prov_method, os_version, image_name)
    os.makedirs(image_path, exist_ok=True)
    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ValueError(f'Failed to download image from {url}: {e}')
    image_file_path = os.path.join(image_path, image_name)
    with open(image_file_path, 'wb') as f:
        for chunk in response.iter_content(chunk_size=8192):
            f.write(chunk)
    image_record = {'name': image_name, 'url': url, 'metadata': image_meta, 'path': image_file_path, 'remote_host': remote_host}
    self.image_db[image_name] = image_record
    return image_record

