import paramiko

def find_hostkey(hostname):
    client=paramiko.Transport((hostname,22))
    client.start_client()
    keys=client.get_remote_server_key()
    key_details={}
    keytypes={
        'ssh-rsa':paramiko.RSAKey,
        'ssh-dss': paramiko.DSSKey
    }
    for keytype, key in keys.items():
        if keytype in keytypes:
            pkey=keytypes[keytype].from_private_key_file('path/to/private/key')
            if key.compare(pkey)==True:
                key_details[keytype]=pkey
    if key_details:
        return key_details
    else:
        return None

