import hashlib

def calculate_fingerprint(x509_cert: str, alg: str) -> str:
    cert_bytes = x509_cert.encode('utf-8')
    if alg == 'md5':
        digest = hashlib.md5(cert_bytes).hexdigest()
    elif alg == 'sha1':
        digest = hashlib.sha1(cert_bytes).hexdigest()
    elif alg == 'sha256':
        digest = hashlib.sha256(cert_bytes).hexdigest()
    else:
        raise ValueError('Invalid algorithm provided.')
    return digest

