def detect_reserved_keywords(code):
    import keyword
    from ast import parse, walk, FunctionDef, AsyncFunctionDef, ClassDef, Attribute, Name, keyword

    reserved = set(keyword.kwlist)

    def check_names(node):
        if isinstance(node, (FunctionDef, AsyncFunctionDef, ClassDef)):
            if node.name in reserved:
                return [('definition', type(node).__name__, node.name)]
        elif isinstance(node, Attribute):
            if node.attr in reserved:
                return [('definition', 'attribute', node.attr)]
        elif isinstance(node, Name):
            if node.id in reserved:
                return [('definition', 'local variable', node.id)]

    tree = parse(code)
    definitions = []
    for node in walk(tree):
        res = check_names(node)
        if res is not None:
            definitions.extend(res)

    return definitions

