def dbscan(points, eps, min_samples):
    """Density-Based Spatial Clustering of Applications with Noise (DBSCAN) algorithm"""
    labels = np.full(len(points), -1)
    cluster_id = 0
    for (i, point) in enumerate(points):
        if labels[i] != -1:
            continue
        neighbors = get_neighbors(point, points, eps)
        if len(neighbors) < min_samples:
            labels[i] = -1
        else:
            cluster_id += 1
            labels[i] = cluster_id
            expand_cluster(point, neighbors, cluster_id, points, eps, min_samples, labels)
    return labels

def expand_cluster(point, neighbors, cluster_id, points, eps, min_samples, labels):
    """Expand the cluster to include density-reachable points"""
    i = 0
    while i < len(neighbors):
        neighbor_index = neighbors[i]
        if labels[neighbor_index] == -1:
            labels[neighbor_index] = cluster_id
        elif labels[neighbor_index] == 0:
