def parse_lines(self, file, boundary, content_length):
    # Read the file line by line
    for line in file:
        # Check if the line is the boundary
        if line.strip() == boundary:
            # Return the end of the form or file
            yield ('end', None)
        elif line.strip() == boundary + '--':
            # Return the end of the form or file
            yield ('end', None)
        elif line.startswith('Content-Disposition'):
            # This is a form or file
            if 'filename' in line:
                # This is a file
                headers = line.split(';')
                name = headers[0].split('=')[1].strip()
                filename = headers[1].split('=')[1].strip()
                yield ('begin_file', (headers, name, filename))
            else:
                # This is a form
                headers = line.split(';')
                name = headers[0].split('=')[1].strip()
                yield ('begin_form', (headers, name))
        else:
            # This is content
