import numpy as np
from scipy.optimize import linear_sum_assignment

def EMD(d1: np.ndarray, d2: np.ndarray) -> float:
    num_rows, num_cols = d1.shape
    cost_matrix = np.zeros((num_rows, num_rows))

    for i in range(num_cols):
        col_dif = np.abs(d1[:, i:i+1] - d2[:, i:i+1].T)
        row_inds, col_inds = linear_sum_assignment(col_dif)
        cost_matrix += col_dif[row_inds, col_inds]

    return np.sum(cost_matrix)

