import tensorflow as tf

def slicewise_function(input_shapes, output_shape, mesh_impl):
    def einsum_slice_fn(tensor_input):
        return tf.einsum("ij...,j...->i...", *mesh_impl.split(tensor_input, input_shapes))

    flattened_output_shape = tf.TensorShape([output_shape.num_elements()])
    output_sizes = mesh_impl.compute_unsplit_sizes(flattened_output_shape, input_shapes)

    reduced_mesh_axes = [axis for axis, size in enumerate(output_shape) if size == 1]

    return einsum_slice_fn, reduced_mesh_axes

