def parse_date_string(date_string, date_format='%Y-%m-%d', start_date=None, end_date=None):
    """
    Parse a date string extracted to a datetime.datetime object and apply the customizations like date range, date completion etc.

    :param date_string: str, date string in given format
    :param date_format: str, format of date string, default is '%Y-%m-%d'
    :param start_date: str or datetime, start date of acceptable date range, default is None (no restrictions)
    :param end_date: str or datetime, end date of acceptable date range, default is None (no restrictions)
    :return: datetime.datetime object
    """
    date_obj = datetime.strptime(date_string, date_format)

    # Check if the parsed date is within the acceptable date range
    if start_date:
        if isinstance(start_date, str):
            start_date = datetime.strptime(start_date, date_format)
        if date_obj < start_date:
            return start_date
    if end_date:
