import numpy as np

def check_similarity_matrix(similarities, verbose=False):
    n_samples = similarities.shape[0]
    if similarities.shape != (n_samples, n_samples):
        if verbose:
            print("The provided matrix of similarities does not have the proper shape.")
        return None

    diag = np.diag(similarities)
    if not np.allclose(diag, 1.0):
        if verbose:
            print("The diagonal of the provided matrix of similarities does not consist of ones.")
        similarities = similarities / np.sqrt(np.outer(diag, diag))

    if not np.all(np.isreal(similarities)):
        if verbose:
            print("The provided matrix of similarities contains complex entries.")
        similarities = np.real(similarities)

    eigenvalues, eigenvectors = np.linalg.eigh(similarities)
    if np.min(eigenvalues) < -1e-6:
        min_eigenvalue_index = np.argmin(eigenvalues)
        if verbose:
            print("The provided matrix of similarities is not a proper similarity matrix.")
            print("The minimum eigenvalue is {:.6f}.".format(eigenvalues[min_eigenvalue_index]))
        similarities -= eigenvalues[min_eigenvalue_index] * np.outer(eigenvectors[:, min_eigenvalue_index], eigenvectors[:, min_eigenvalue_index])
        similarities = 0.5 * (similarities + similarities.T)

    return similarities

