def phasicTonic(self, m1=None, m2=None, chunkMs=50, quietPercentile=10):
    quiet_threshold = np.percentile(self.data, quietPercentile)
    phasic = []
    tonic = []
    chunk_size = int(chunkMs * self.sampling_rate / 1000)
    for i in range(0, len(self.data), chunk_size):
        chunk = self.data[i:i + chunk_size]
        mean_chunk = np.mean(chunk[chunk != 0])
        if mean_chunk < quiet_threshold:
            tonic.append(mean_chunk)
        else:
            phasic.append(mean_chunk)
    return (phasic, tonic)

