def read_input_registers(self, reg_addr, reg_nb=1):
    if not 0 <= reg_addr <= 65535:
        raise ValueError('Register address must be between 0 and 65535')
    if not 1 <= reg_nb <= 125:
        raise ValueError('Number of registers to read must be between 1 and 125')
    request = struct.pack('>BHH', 4, reg_addr, reg_nb)
    response = self._send_receive(request)
    if response is None:
        return None
    (function_code, byte_count) = struct.unpack('>BH', response[:3])
    if function_code != 4:
        raise ValueError('Invalid function code in response')
    if byte_count != 2 * reg_nb:
        raise ValueError('Invalid byte count in response')
    registers = struct.unpack('>' + 'H' * reg_nb, response[3:])
    return list(registers)

