def embedRasters(element, options):
    if not isinstance(element, dict):
        raise TypeError('element must be a dictionary')
    if not isinstance(options, dict):
        raise TypeError('options must be a dictionary')
    if 'rasterReferences' not in options:
        raise KeyError("options must contain 'rasterReferences' key")
    if not isinstance(options['rasterReferences'], dict):
        raise TypeError("options['rasterReferences'] must be a dictionary")
    rasterReferences = options['rasterReferences']
    for (key, value) in element.items():
