def sanity_check_states(states_spec: Union[None, dict]) -> Tuple[str, bool]:
    if states_spec is None:
        raise ValueError("states_spec cannot be None.")

    if not isinstance(states_spec, dict):
        raise TypeError("states_spec must be a dictionary.")

