        elif len(state_space[i]) < 1 or len(state_space[i]) > 2:
            raise ValueError(f"state_space[{i}] must have length 1 or 2.")
        elif isinstance(state_space[i][0], str):
            continue
        elif isinstance(state_space[i][0], list):
            mismatch_warning = True
