def update_item(event, updated_attributes, calendar_item_update_operation_type):
    """Saves updates to an event in the store. Only request changes for attributes that have actually changed."""

    # Check if the event exists
    if not event:
        return "Event does not exist"

    # Check if the updated attributes are different from the current attributes
    for attribute, value in updated_attributes.items():
        if getattr(event, attribute) != value:
            # Update the attribute
            setattr(event, attribute, value)

    # Save the changes to the store
    event.save()

    return "Event updated successfully"

