def resolve_tokens(input_str, aws_resources, secure_credentials, version_registry, built_in_context, params):
    while True:
        match = re.search(r'\{\{(.+?)\}\}', input_str)
        if not match:
            break
        token = match.group(1).strip()
        # Lookup AWS resource identifiers
        if token in aws_resources:
            replacement = aws_resources[token]
        # Lookup secure credentials
        elif token in secure_credentials:
            replacement = secure_credentials[token]
        # Lookup version registry for versioned content
        elif token in version_registry:
            replacement = version_registry[token]
        # Lookup built-in context (such as "ENV")
        elif token in built_in_context:
            replacement = built_in_context[token]
        # Lookup parameters from a parameter file/dictionary of params
        elif token in params:
            replacement = params[token]
        else:
            raise ValueError(f"Failed to resolve token: {token}")
        input_str = input_str.replace(f"{{{{{token}}}}}", replacement)
    return input_str

