def process(in_path, annot_beats=False, feature='mfcc', framesync=False):
    import librosa
    import numpy as np
    import os
    (y, sr) = librosa.load(in_path, sr=None)
    if feature == 'mfcc':
        features = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=13)
    elif feature == 'chroma':
