def seek(self, offset, whence=0):
    """Seek to a new position in the data source.

    Args:
        offset (int): The offset to seek to.
        whence (int): The reference point for the offset. 0 means absolute position, 1 means relative to the current position, and 2 means relative to the end of the data source.
    """
    if whence == 0:
        self.offset = offset
    elif whence == 1:
        self.offset += offset
    elif whence == 2:
        self.offset = self.data_source.size() - offset
    else:
