def estimate_hit_counts(time_series_list, interval):
    """
    :param time_series_list: list of time series, where each time series is a list of values representing hits per second
    :param interval: string representing the time interval for calculating hit counts (e.g. 'day', 'hour', 'minute')
    :return: list of hit counts for each interval
    """
    import numpy as np

    intervals_per_second = {
        'second': 1,
        'minute': 60,
        'hour': 3600,
        'day': 86400
    }

    interval_seconds = intervals_per_second[interval]

    interval_hits = np.zeros(len(time_series_list[0]) // interval_seconds + 1)

    for time_series in time_series_list:
        for i in range(len(time_series)):
            interval_hits[i // interval_seconds] += time_series[i]

    return interval_hits.tolist()

