@SuppressWarnings("unchecked")
private static Object[] resolveArguments(Method method, TestContext context, ApplicationContext applicationContext) {
    Class<?>[] parameterTypes = method.getParameterTypes();
    Object[] args = new Object[parameterTypes.length];

    for (int i = 0; i < parameterTypes.length; i++) {
        if (AnnotationUtils.findAnnotation(method.getParameterAnnotations()[i], CitrusEndpoint.class) != null) {
            args[i] = resolveEndpoint(method.getParameterAnnotations()[i], parameterTypes[i], applicationContext);
        } else if (AnnotationUtils.findAnnotation(method.getParameterAnnotations()[i], CitrusMessage.class) != null) {
            args[i] = resolveMessage(method.getParameterAnnotations()[i], parameterTypes[i], context.getMessageStore());
