private static Endpoint createEndpoint(CitrusEndpoint citrusEndpoint, ApplicationContext applicationContext) {
    EndpointFactory endpointFactory = getEndpointFactory(citrusEndpoint.type(), applicationContext);
    Endpoint endpoint = endpointFactory.createEndpoint(
            citrusEndpoint.name(),
            citrusEndpoint.uri(),
            citrusEndpoint.properties(),
            citrusEndpoint.messageCorrelator());

    MessageValidator<?> validator = applicationContext.getBean(citrusEndpoint.messageValidator(), MessageValidator.class);
    endpoint.setMessageValidator(validator);

    DestinationResolver<?> destinationResolver = applicationContext.getBean(citrusEndpoint.destinationResolver(), DestinationResolver.class);
    endpoint.setDestinationResolver(destinationResolver);

    endpoint.setActor(citrusEndpoint.actor());
    endpoint.setActorContext(applicationContext.getBean(citrusEndpoint.actorContextName(), Map.class));

    if (endpointFactory.supportsSendAndReceive() &&
            (citrusEndpoint.timeout() > 0 || citrusEndpoint.timeoutString().length() > 0)) {
        long timeout = citrusEndpoint.timeout() > 0 ? citrusEndpoint.timeout() : applicationContext.getBean(citrusEndpoint.timeoutString(), Long.class);
        endpoint.setTimeout(timeout);
    }

    return endpoint;
}

private static EndpointFactory getEndpointFactory(CitrusEndpoint.EndpointType type, ApplicationContext applicationContext) {
    switch (type) {
        case ACTIVEMQ:
        case JMS:
            return applicationContext.getBean(JmsEndpointFactory.class);
        case SOCKET:
            return applicationContext.getBean(TcpServerEndpointFactory.class);
        case DIRECT:
            return applicationContext.getBean(DirectEndpointFactory.class);
