import org.newdawn.slick.particles.ParticleEmitter;
import org.newdawn.slick.particles.ParticleSystem;
import org.newdawn.slick.util.ResourceLoader;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

public ParticleSystem loadConfiguredEmitters(InputStream ref, Image mask) throws SlickException, IOException {

    DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
    DocumentBuilder db = dbf.newDocumentBuilder();
    Document doc = db.parse(ref);
    doc.getDocumentElement().normalize();

    int maxParticlesPerEmitter = 1000;
    List<ParticleEmitter> emitters = new ArrayList<>();

    NodeList nodeList = doc.getElementsByTagName("emitter");
    for (int emitterIndex = 0; emitterIndex < nodeList.getLength(); emitterIndex++) {

        Node node = nodeList.item(emitterIndex);
        if (node.getNodeType() == Node.ELEMENT_NODE) {

            Element eElement = (Element) node;

            String imageName = eElement.getAttribute("imageName");
            Image image = new Image(ResourceLoader.getResourceAsStream(imageName), imageName, false);
            int numParticles = Integer.parseInt(eElement.getAttribute("numParticles"));
            boolean usePoints = Boolean.parseBoolean(eElement.getAttribute("usePoints"));
            boolean orient = Boolean.parseBoolean(eElement.getAttribute("oriented"));
            ConfigurableEmitter emitter = new ConfigurableEmitter(image, numParticles);
            emitter.usePoints(usePoints);
            emitter.setOriented(orient);

            NodeList nl = eElement.getElementsByTagName("spawnInterval");
            if (nl.getLength() > 0) {
                emitter.setSpawnInterval(Float.parseFloat(nl.item(0).getTextContent()));
            }
            nl = eElement.getElementsByTagName("initialLife");
            if (nl.getLength() > 0) {
                emitter.setInitialLife(Float.parseFloat(nl.item(0).getTextContent()));
            }
            nl = eElement.getElementsByTagName("particlesPerSpawn");
            if (nl.getLength() > 0) {
                emitter.setParticlesPerSpawn(Float.parseFloat(nl.item(0).getTextContent()));
            }
            nl = eElement.getElementsByTagName("spawnCount");
            if (nl.getLength() > 0) {
                emitter.spawnCount.setValue(Float.parseFloat(nl.item(0).getTextContent()), Float.parseFloat(nl.item(0).getTextContent()));
            }
            nl = eElement.getElementsByTagName("velocity");
            if (nl.getLength() > 0) {
                emitter.setVelocity(Float.parseFloat(nl.item(0).getTextContent()), Float.parseFloat(nl.item(1).getTextContent()), 0f);
            }
            nl = eElement.getElementsByTagName("spread");
            if (nl.getLength() > 0) {
                emitter.spread.setValue(Float.parseFloat(nl.item(0).getTextContent()), Float.parseFloat(nl.item(1).getTextContent()));
            }
            nl = eElement.getElementsByTagName("scale");
            if (nl.getLength() > 0) {
                emitter.setScale(Float.parseFloat(nl.item(0).getTextContent()), Float.parseFloat(nl.item(1).getTextContent()));
            }
            nl = eElement.getElementsByTagName("offset");
            if (nl.getLength() > 0) {
                emitter.setPosition(Float.parseFloat(nl.item(0).getTextContent()), Float.parseFloat(nl.item(1).getTextContent()), 0f);
            }
            nl = eElement.getElementsByTagName("imageColor");
            if (nl.getLength() > 0) {
                Color color = new Color(Float.parseFloat(nl.item(0).getTextContent()), Float.parseFloat(nl.item(1).getTextContent()), Float.parseFloat(nl.item(2).getTextContent()), Float.parseFloat(nl.item(3).getTextContent()));
                emitter.setImageColor(color);
            }
            nl = eElement.getElementsByTagName("alpha");
            if (nl.getLength() > 0) {
                emitter.alpha.setMinValue(Float.parseFloat(nl.item(0).getTextContent()));
            }
            nl = eElement.getElementsByTagName("initialDistance");
            if (nl.getLength() > 0) {
                emitter.initialDistance.setMinValue(Float.parseFloat(nl.item(0).getTextContent()));
            }
            nl = eElement.getElementsByTagName("endBehaviour");
            if (nl.getLength() > 0) {
                String endBehaviour = nl.item(0).getTextContent().toLowerCase();
                if (endBehaviour.equals("play")) {
                    emitter.setLooping(true);
                } else if (endBehaviour.equals("once")) {
                    emitter.setLooping(false);
                } else if (endBehaviour.equals("bounce")) {
                    emitter.setLooping(true);
                    emitter.bounce = true;
                }
            }

            if(mask != null) {
                Color[][] colorArray = new Color[mask.getWidth()][mask.getHeight()];
                for (int x = 0; x < mask.getWidth(); x++) {
                    for (int y = 0; y < mask.getHeight(); y++) {
                        colorArray[x][y] = new Color(mask.getColor(x, y));
                    }
                }
                emitter.setImageColorMask(colorArray);
            }

            emitters.add(emitter);
        }
    }

    ParticleSystem system = new ParticleSystem(null, maxParticlesPerEmitter, mask);
    for (ParticleEmitter emitter : emitters) {
        system.addEmitter(emitter);
    }
    return system;
}

