									it.append("return ");  
								}
								it.append(sourceName);
								it.append("(");  
								it.append(IterableExtensions.join(args, ", "));  
								it.append(");");  
							});
						} else {
							operation2.setDefault(false);
							operation2.setAbstract(true);
						}

