public void importJobDefsFromXml(String path, Connection cnx) throws JqmEngineException {
    try {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        File file = new File(path);
        Document doc = builder.parse(file);
        doc.getDocumentElement().normalize();
        NodeList jobDefs = doc.getElementsByTagName("JobDef");

        cnx.setAutoCommit(false);

        for (int i = 0; i < jobDefs.getLength(); i++) {
            Node jobDefNode = jobDefs.item(i);
            if (jobDefNode.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) jobDefNode;
                // parse jobDef data from xml file and store into jobDef object
                JobDef jobDef = new JobDef();
                jobDef.setName(element.getElementsByTagName("Name").item(0).getTextContent());
                jobDef.setClassName(element.getElementsByTagName("ClassName").item(0).getTextContent());
                jobDef.setQueueName(element.getElementsByTagName("QueueName").item(0).getTextContent());
                jobDef.setPriority(Integer.parseInt(element.getElementsByTagName("Priority").item(0).getTextContent()));
                jobDef.setPath(element.getElementsByTagName("Path").item(0).getTextContent());
                jobDef.setDescription(element.getElementsByTagName("Description").item(0).getTextContent());
                jobDef.setExecutablePath(element.getElementsByTagName("ExecutablePath").item(0).getTextContent());
                jobDef.setModulePath(element.getElementsByTagName("ModulePath").item(0).getTextContent());
                jobDef.setParameters(element.getElementsByTagName("Parameters").item(0).getTextContent());

                // insert jobDef object to database
                JobDefDAO.create(jobDef, cnx);
            }
        }

        cnx.commit();
    } catch (Exception e) {
        try {
            cnx.rollback();
        } catch (SQLException e1) {
            throw new JqmEngineException(e1);
        }
        throw new JqmEngineException(e);
    }
}

