public static List<EigenPair> lanczosApproximateEigenpairs(Matrix A, int k) {
    assert(A.isSymmetric());

    int n = A.getNumRows();

    double[] alpha = new double[k];
    double[] beta = new double[k - 1];
    double[] q = new double[n];
    double[] w = new double[n];
    double[] e1 = new double[n];
    Arrays.fill(e1, 0.0);
    e1[0] = 1.0;

    List<EigenPair> eigenPairs = new ArrayList<>(k);

    for (int j = 0; j < k; j++) {
        if (j == 0) {
            q = e1.clone();
        } else {
            double[] u = eigenPairs.get(j - 1).getEigenvector();
            double[] v = Arrays.copyOfRange(q, 0, n);
            for (int i = 0; i < n; i++) {
                q[i] = v[i] - u[i] * alpha[j - 1];
            }
            if (j > 1) {
                double[] v1 = Arrays.copyOfRange(q, 0, n);
                double[] v2 = Arrays.copyOfRange(q, 0, n);
                for (int i = 0; i < n; i++) {
                    v1[i] = v1[i] - beta[j - 2] * w[i];
                }
                for (int i = 0; i < n; i++) {
                    v2[i] = v2[i] - beta[j - 2] * q[i];
                }
                w = Arrays.copyOfRange(v1, 0, n);
                q = Arrays.copyOfRange(v2, 0, n);
            }
        }

        for (int i = 0; i < n; i++) {
            w[i] = A.apply(q)[i];
        }

        alpha[j] = Stream.of(q).mapToDouble(x -> x).reduce(0, (acc, x) -> acc + x * w[i]);

        if (j < k - 1) {
            for (int i = 0; i < n; i++) {
                w[i] = w[i] - alpha[j] * q[i] - beta[j - 1] * e1[i];
            }
            beta[j - 1] = Stream.of(w).mapToDouble(x -> x).reduce(0, (acc, x) -> acc + x * w[i]);
            if (beta[j - 1] < 0.0) {
                eigenPairs.forEach(pair -> {
                    pair.negateEigenvalue();
                });
                alpha[0] = -alpha[0];
                beta[0] = -beta[0];
                for (int i = 0; i < n; i++) {
                    q[i] = -q[i];
                }
            }
            beta[j - 1] = Math.sqrt(beta[j - 1]);
            for (int i = 0; i < n; i++) {
                q[i] = e1[i];
                e1[i] = w[i] / beta[j - 1];
            }
        } else {
            EigenPair pair = new EigenPair(alpha[j], Arrays.copyOfRange(q, 0, n));
            eigenPairs.add(pair);
        }
    }

    return eigenPairs;
}

