public static String convert(final String aCode) {
        String langName;
        switch (aCode.length()) {
            case 2:
                langName = ISO639_1_MAP.get(aCode.toLowerCase());
                break;
            case 3:
                langName = ISO639_2_MAP.get(aCode.toLowerCase());
                break;
            default:
                langName = aCode;
        }
        return langName == null ? aCode : langName;
    }

