public static <T> T insertAnnotatedObject(Connection connection, T target) throws SQLException {
        String sql = buildInsertStatement(target);
        PreparedStatement statement = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS);
        try {
            setStatementParameters(statement, target);
            statement.executeUpdate();
            ResultSet rs = statement.getGeneratedKeys();
            if (rs.next()) {
                setGeneratedId(target, rs.getLong(1));
            }
            rs.close();
            return target;
        } finally {
            statement.close();
        }
    }

    private static <T> String buildInsertStatement(T target) {
        AnnotatedClass ac = new AnnotatedClass(target.getClass());
        StringBuilder sb = new StringBuilder("insert into ");
        sb.append(ac.getTable().name());
        sb.append(" (");
        for (AnnotatedField field : ac.getFields()) {
            if (field.isId() && field.isAutoGenerated()) {
                continue;
            }
            sb.append(field.getColumn().name());
            sb.append(", ");
        }
        sb.setLength(sb.length() - 2);
        sb.append(") values (");
        for (int i = 0; i < ac.getFields().size(); i++) {
            if (ac.getFields().get(i).isId() && ac.getFields().get(i).isAutoGenerated()) {
                continue;
            }
            sb.append("?, ");
        }
        sb.setLength(sb.length() - 2);
        sb.append(")");
        return sb.toString();
    }

    private static <T> void setStatementParameters(PreparedStatement statement, T target) throws SQLException {
        AnnotatedClass ac = new AnnotatedClass(target.getClass());
        int i = 1;
        for (AnnotatedField field : ac.getFields()) {
            if (field.isId() && field.isAutoGenerated()) {
                continue;
            }
            Object value;
            try {
                value = field.get(target);
            } catch (IllegalAccessException e) {
                throw new SQLException(e);
            }
            statement.setObject(i, value);
            i++;
        }
    }

    private static <T> void setGeneratedId(T target, Long id) throws SQLException {
        AnnotatedClass ac = new AnnotatedClass(target.getClass());
        for (AnnotatedField field : ac.getFields()) {
            if (field.isId() && field.isAutoGenerated()) {
                try {
                    field.set(target, id);
                } catch (IllegalAccessException e) {
                    throw new SQLException(e);
                }
            }
        }
    }

