private static class ZipStreamParser {
  private final InputStream stream;
  private final String cacheKey;
  private final LottieImageAssetManager assetManager = new LottieImageAssetManager();
  private final Map<String, List<String>> precomps = new HashMap<>();

  ZipStreamParser(InputStream stream, String cacheKey) {
    this.stream = stream;
    this.cacheKey = cacheKey;
  }

  private LottieTask<LottieComposition> parseTask() {
    return LottieTask.call(() -> parse());
  }

  private LottieComposition parse() throws IOException {
    ZipInputStream zip = new ZipInputStream(stream);
    ZipEntry entry;
    while ((entry = zip.getNextEntry()) != null) {
      if (entry.getName().equals("manifest.json")) {
        break;
      }
    }
    return parseJson(Utils.toInputStream(zip), cacheKey);
  }

  private LottieComposition parseJson(InputStream stream, String cacheKey) throws IOException {
    try {
      JsonReader reader = new JsonReader(Utils.utf8Reader(stream));
      return LottieCompositionParser.parse(reader);
    } finally {
      Utils.closeQuietly(stream);
    }
  }

  private List<Bitmap> bitmaps;

  private void readBitmaps(ZipInputStream zip, LottieComposition composition) {
    bitmaps = new ArrayList<>();
    LottieImageAssetDelegate assetDelegate = composition.getImageAssetDelegate();
    ZipEntry ze;
    try {
      while ((ze = zip.getNextEntry()) != null) {
        String filename = ze.getName();
        if (filename.contains("__MACOSX")) {
          // Ignore macos "resource fork" files.
          continue;
        }
        if (!filename.endsWith(".png") && !filename.endsWith(".webp")) {
          // We only care about .png and .webp images.
          continue;
        }

        BitmapFactory.Options options = new BitmapFactory.Options();
        options.inScaled = true;
        options.inDensity = 160;
        options.inTargetDensity = composition.getBounds().width();
        options.inScreenDensity = Utils.dpScale();
        options.inSampleSize = Utils.calculateSampleSize(options.inDensity, options.inTargetDensity);
        Bitmap bitmap = BitmapFactory.decodeStream(zip, null, options);

        if (bitmap == null) {
          break;
        }

        String id = extractId(filename);
        LottieImageAsset imageAsset = new LottieImageAsset(options.inDensity,
            options.inDensity, id, filename, bitmap);
        if (!assetDelegate.hasSameImageAssets(imageAsset)) {
          bitmaps.add(bitmap);
          assetDelegate.setDelegate(id, new OneShotBitmapProvider(bitmap));
        } else {
          bitmap.recycle();
        }

        assetManager.addAsset(id, imageAsset);
      }
    } catch (IOException e) {
      Log.w(L.TAG, "Unable to parse bitmap in composition " + cacheKey, e);
    }
  }

  private static String extractId(String file) {
    int start = file.lastIndexOf('/');
    if (start < 0) {
      start = 0;
    } else {
      start++;
    }
    int end = file.lastIndexOf('.');
    return file.substring(start, end);
  }
}

