public static double biConjugateGradient(double[][] A, double[] b, double[] x) {
    int n = b.length;
    double[] r = new double[n];
    double[] r_tld = new double[n];
    multiply(A, x, r);
    subtract(b, r, r);
    copy(r, r_tld);
    double rho = dotProduct(r_tld, r);
    double rho_prev = 0.0;
    double[] p = new double[n];
    double[] p_tld = new double[n];
    double[] v = new double[n];
    double[] v_tld = new double[n];
    double[] y = new double[n];
    double[] z = new double[n];
    double error = norm(r) / norm(b);

    for (int i = 0; i < maxIter && error > tolerance; i++) {
        rho_prev = rho;
        rho = dotProduct(r_tld, r);
        double beta = rho / rho_prev;
        add(p, multiply(v, beta), p_tld);
        add(r, multiply(v, beta), y);
        multiply(A, y, z);
        double alpha = rho / dotProduct(r_tld, z);
        subtract(y, multiply(v_tld, alpha), p);
        subtract(r, multiply(z, alpha), r_tld);
        copy(y, x);
        multiply(A, x, r);
        subtract(b, r, r);
        error = norm(r) / norm(b);

        if (error < tolerance) {
            break;
        }

        double beta_tld = dotProduct(r_tld, r) / rho;
        add(p_tld, multiply(v_tld, beta_tld), v);
        add(r, multiply(v_tld, beta_tld), v_tld);
    }
    return error;
}

public static void multiply(double[][] A, double[] x, double[] y) {
    int n = x.length;
    Arrays.fill(y, 0.0);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            y[i] += A[i][j] * x[j];
        }
    }
}

public static void subtract(double[] x, double[] y, double[] z) {
    int n = x.length;
    for (int i = 0; i < n; i++) {
        z[i] = x[i] - y[i];
    }
}

public static void add(double[] x, double[] y, double[] z) {
    int n = x.length;
    for (int i = 0; i < n; i++) {
        z[i] = x[i] + y[i];
    }
}

public static double dotProduct(double[] x, double[] y) {
    int n = x.length;
    double dotProduct = 0.0;
    for (int i = 0; i < n; i++) {
        dotProduct += x[i] * y[i];
    }
    return dotProduct;
}

public static void multiply(double[] x, double a, double[] y) {
    int n = x.length;
    for (int i = 0; i < n; i++) {
        y[i] = a * x[i];
    }
}

public static double norm(double[] x) {
    double norm = 0.0;
    for (double value : x) {
        norm += value * value;
    }
    return Math.sqrt(norm);
}

public static void copy(double[] x, double[] y) {
    int n = x.length;
    for (int i = 0; i < n; i++) {
        y[i] = x[i];
    }
}

