public static String findWord(char[] c, int pos) throws IOException {
    StringBuilder word = new StringBuilder();
    boolean wordFound = false;
    int i = pos;

    while (i < c.length) {
        if (Character.isLetterOrDigit(c[i])) {
            word.append(c[i]);
        } else {
            wordFound = true;
            break;
        }
        i++;
    }

    if (!wordFound) {
        return null;
    }

    return word.toString();
}

