import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.java.typeutils.RowTypeInfo;
import org.apache.parquet.schema.MessageType;
import org.apache.parquet.schema.PrimitiveType;
import org.apache.parquet.schema.Type;
import org.apache.parquet.schema.Types;
import org.apache.parquet.schema.Types.Builder;

public static MessageType toParquetType(TypeInformation<?> typeInformation, boolean legacyMode) {
    Builder typeBuilder = Types.buildGroup(null);

    if (typeInformation instanceof RowTypeInfo) {
        RowTypeInfo rowTypeInfo = (RowTypeInfo) typeInformation;
        for (int i = 0; i < rowTypeInfo.getArity(); i++) {
            Type fieldType = toParquetType(rowTypeInfo.getTypeAt(i), legacyMode);
            typeBuilder.addField(fieldType);
        }
    } else {
        PrimitiveType primitiveType = Types.primitive(null, PrimitiveType.PrimitiveTypeName.BINARY, PrimitiveType.Repetition.OPTIONAL);
        typeBuilder.addField(primitiveType);
    }

    return typeBuilder.named(null);
}

