public class HttpPostCall {

    public static String performPostCall(String endpoint, String params, File file) {
        HttpURLConnection urlConnection = null;
        OutputStream outputStream = null;

        try {
            URL url = new URL(endpoint);
            urlConnection = (HttpURLConnection) url.openConnection();
            urlConnection.setRequestMethod("POST");
            urlConnection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
            urlConnection.setRequestProperty("Content-Length", "" + Integer.toString(params.getBytes().length));
            urlConnection.setUseCaches(false);
            urlConnection.setDoInput(true);
            urlConnection.setDoOutput(true);

            // Write the parameters to the connection
            outputStream = new FileOutputStream(file);
            outputStream.write(params.getBytes());
            outputStream.flush();

            // Get the response from the connection
            int responseCode = urlConnection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                return urlConnection.getInputStream().toString();
            } else {
                return "HTTP Error code: " + responseCode;
            }
        } catch (IOException e) {
            return e.toString();
        } finally {
            if (urlConnection != null) {
                urlConnection.disconnect();
            }

            if (outputStream != null) {
                try {
                    outputStream.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

