public Type mapTypeParameters(Type toMapType, Type typeAndParams) {
    if (typeAndParams instanceof ParameterizedType) {
        Map<TypeVariable<?>, Type> typeArguments = new HashMap<>();
        ParameterizedType parameterizedType = (ParameterizedType) typeAndParams;
        TypeVariable<?>[] typeParameters = ((Class<?>) parameterizedType.getRawType()).getTypeParameters();
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        for (int i = 0; i < typeParameters.length; i++) {
            typeArguments.put(typeParameters[i], actualTypeArguments[i]);
        }
        return mapTypeParameters(toMapType, typeArguments);
    } else if (typeAndParams instanceof Class<?> && ((Class<?>) typeAndParams).getTypeParameters().length > 0) {
        return mapTypeParameters(toMapType, Collections.emptyMap());
    }
    return toMapType;
}

private Type mapTypeParameters(Type type, Map<TypeVariable<?>, Type> typeArguments) {
    if (type instanceof TypeVariable<?> && typeArguments.containsKey(type)) {
        return typeArguments.get(type);
    } else if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Type[] mappedTypeArguments = new Type[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            mappedTypeArguments[i] = mapTypeParameters(actualTypeArguments[i], typeArguments);
        }
        return new ParameterizedTypeImpl(parameterizedType.getRawType(), parameterizedType.getOwnerType(), mappedTypeArguments);
    } else if (type instanceof GenericArrayType) {
        GenericArrayType genericArrayType = (GenericArrayType) type;
        return new GenericArrayTypeImpl(mapTypeParameters(genericArrayType.getGenericComponentType(), typeArguments));
    } else if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        Type[] lowerBounds = wildcardType.getLowerBounds();
        Type[] upperBounds = wildcardType.getUpperBounds();
        if (lowerBounds.length == 0 && upperBounds.length == 1) {
            Type mappedBound = mapTypeParameters(upperBounds[0], typeArguments);
            if (mappedBound == upperBounds[0]) {
                return wildcardType;
            } else {
                return new WildcardTypeImpl(new Type[]{mappedBound}, new Type[0]);
            }
        } else if (lowerBounds.length == 1 && upperBounds.length == 1) {
            Type mappedLower = mapTypeParameters(lowerBounds[0], typeArguments);
            Type mappedUpper = mapTypeParameters(upperBounds[0], typeArguments);
            if (mappedLower == lowerBounds[0] && mappedUpper == upperBounds[0]) {
                return wildcardType;
            } else {
                return new WildcardTypeImpl(new Type[]{mappedUpper}, new Type[]{mappedLower});
            }
        } else {
            throw new IllegalArgumentException("Unsupported wildcard type: " + wildcardType);
        }
    } else {
        return type;
    }
}

private static class ParameterizedTypeImpl implements ParameterizedType {
    private final Type rawType;
    private final Type ownerType;
    private final Type[] actualTypeArguments;

    public ParameterizedTypeImpl(Type rawType, Type ownerType, Type[] actualTypeArguments) {
        this.rawType = rawType;
        this.ownerType = ownerType;
        this.actualTypeArguments = actualTypeArguments;
    }

    public Type[] getActualTypeArguments() {
        return actualTypeArguments.clone();
    }

    public Type getRawType() {
        return rawType;
    }

    public Type getOwnerType() {
        return ownerType;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true; // If it's the same object, it's equal.
        if (!(o instanceof ParameterizedType)) return false;
        ParameterizedType that = (ParameterizedType) o;
        return Arrays.equals(actualTypeArguments, that.getActualTypeArguments()) &&
                Objects.equals(ownerType, that.getOwnerType()) &&
                Objects.equals(rawType, that.getRawType());
    }

    @Override
    public int hashCode() {
        int result = Objects.hash(ownerType, rawType);
        result = 31 * result + Arrays.hashCode(actualTypeArguments);
        return result;
    }
}

private static class GenericArrayTypeImpl implements GenericArrayType {
    private final Type genericComponentType;

    public GenericArrayTypeImpl(Type genericComponentType) {
        this.genericComponentType = genericComponentType;
    }

    public Type getGenericComponentType() {
        return genericComponentType;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof GenericArrayType)) return false;
        GenericArrayType that = (GenericArrayType) o;
        return Objects.equals(genericComponentType, that.getGenericComponentType());
    }

    @Override
    public int hashCode() {
        return Objects.hash(genericComponentType);
    }
}

private static class WildcardTypeImpl implements WildcardType {
    private final Type[] upperBounds;
    private final Type[] lowerBounds;

    public WildcardTypeImpl(Type[] upperBounds, Type[] lowerBounds) {
        this.upperBounds = upperBounds;
        this.lowerBounds = lowerBounds;
    }

    public Type[] getUpperBounds() {
        return upperBounds.clone();
    }

    public Type[] getLowerBounds() {
        return lowerBounds.clone();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof WildcardType)) return false;
        WildcardType that = (WildcardType) o;
        return Arrays.equals(upperBounds, that.getUpperBounds()) &&
                Arrays.equals(lowerBounds, that.getLowerBounds());
    }

    @Override
    public int hashCode() {
        return Objects.hash(Arrays.hashCode(upperBounds), Arrays.hashCode(lowerBounds));
    }
}

