public Object removeInterval(Node root, int start, int end) {
    Node node = findInterval(root, start, end);
    if(node == null) {
        return null;
    }
    else {
        Object value = node.value;
        deleteNode(node);
        return value;
    }
}

private Node findInterval(Node root, int start, int end) {
    if(root == null) {
        return null;
    }
    if(start < root.start) {
        return findInterval(root.left, start, end);
    }
    else if(start > root.start) {
        return findInterval(root.right, start, end);
    }
    else if(end < root.end) {
        return findInterval(root.left, start, end);
    }
    else if(end > root.end) {
        return findInterval(root.right, start, end);
    }
    else {
        return root;
    }
}

private void deleteNode(Node node) {
    if(node.left == null && node.right == null) {
        if(node.parent.left == node) {
            node.parent.left = null;
        }
        else {
            node.parent.right = null;
        }
    }
    else if(node.left == null) {
        if(node.parent.left == node) {
            node.parent.left = node.right;
        }
        else {
            node.parent.right = node.right;
        }
    }
    else if(node.right == null) {
        if(node.parent.left == node) {
            node.parent.left = node.left;
        }
        else {
            node.parent.right = node.left;
        }
    }
    else {
        Node successor = findSuccessor(node.right);
        node.value = successor.value;
        deleteNode(successor);
    }
}

private Node findSuccessor(Node node) {
    if(node.left == null) {
        return node;
    }
    else {
        return findSuccessor(node.left);
    }
}

