public LocalDate seekToSeason(String seasonString, String direction, int seekAmount) {
    LocalDate currentDate = LocalDate.now();
    Month currentMonth = currentDate.getMonth();

    switch (seasonString.toLowerCase()) {
        case "spring":
            if (currentMonth.compareTo(Month.MARCH) >= 0 && currentMonth.compareTo(Month.JUNE) <= 0)
                return currentDate;

            if (currentMonth.compareTo(Month.MARCH) < 0 || currentMonth.compareTo(Month.JUNE) > 0)
                return seek(direction, seekAmount, currentMonth, Month.MARCH, Month.JUNE);
            break;

        case "summer":
            if (currentMonth.compareTo(Month.JUNE) >= 0 && currentMonth.compareTo(Month.SEPTEMBER) <= 0)
                return currentDate;

            if (currentMonth.compareTo(Month.JUNE) < 0 || currentMonth.compareTo(Month.SEPTEMBER) > 0)
                return seek(direction, seekAmount, currentMonth, Month.JUNE, Month.SEPTEMBER);
            break;

        case "autumn":
        case "fall":
            if (currentMonth.compareTo(Month.SEPTEMBER) >= 0 && currentMonth.compareTo(Month.DECEMBER) <= 0)
                return currentDate;

            if (currentMonth.compareTo(Month.SEPTEMBER) < 0 || currentMonth.compareTo(Month.DECEMBER) > 0)
                return seek(direction, seekAmount, currentMonth, Month.SEPTEMBER, Month.DECEMBER);
            break;

        case "winter":
            if (currentMonth.compareTo(Month.DECEMBER) >= 0 || currentMonth.compareTo(Month.MARCH) <= 0)
                return currentDate;

            if (currentMonth.compareTo(Month.MARCH) > 0 && currentMonth.compareTo(Month.DECEMBER) < 0)
                return seek(direction, seekAmount, currentMonth, Month.DECEMBER, Month.MARCH);
            break;
    }

    return currentDate;
}

private LocalDate seek(String direction, int seekAmount, Month currentMonth, Month startMonth, Month endMonth) {
    int directionValue = direction.equalsIgnoreCase("back") ? -1 : 1;
    int targetMonthValue = startMonth.getValue() + directionValue * 3;
    int currentMonthValue = currentMonth.getValue();

    if (targetMonthValue <= 0) {
        targetMonthValue += 12;
    } else if (targetMonthValue > 12) {
        targetMonthValue -= 12;
    }

    if (direction.equalsIgnoreCase("back") && currentMonth.compareTo(startMonth) < 0) {
        targetMonthValue -= 12;
    } else if (direction.equalsIgnoreCase("forward") && currentMonth.compareTo(endMonth) > 0) {
        targetMonthValue += 12;
    }

    int year = LocalDate.now().getYear();
    if (direction.equalsIgnoreCase("back") && targetMonthValue > currentMonthValue) {
        year -= 1;
    } else if (direction.equalsIgnoreCase("forward") && targetMonthValue < currentMonthValue) {
        year += 1;
    }

    return LocalDate.of(year + seekAmount, Month.of(targetMonthValue), 1);
}

