import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.Arrays;
import java.util.Objects;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class FieldGetterStream {

    public static Stream<String> allFieldsAndGetterMethods(Object obj) {
        return allFields(obj)
                .concat(getters(obj, ignorePredicate()));
    }

    public static Stream<String> allFieldsAndGetterMethods(Object obj, Predicate<String> ignore) {
        return allFields(obj)
                .concat(getters(obj, ignore));
    }

    public static Stream<String> allFields(Object obj) {
        return Arrays.stream(obj.getClass().getFields())
                .map(field -> {
                    try {
                        return field.getName() + "=" + field.get(obj);
                    } catch (Exception e) {
                        return null;
                    }
                })
                .filter(Objects::nonNull);
    }

    public static Stream<String> getters(Object obj, Predicate<String> ignore) {
        return Arrays.stream(obj.getClass().getMethods())
                .filter(m -> Modifier.isPublic(m.getModifiers()))
                .filter(m -> m.getParameterCount() == 0)
                .filter(m -> m.getReturnType() != void.class)
                .filter(m -> m.getName().matches("(get|is).+"))
                .filter(m -> !ignore.test(m.getName()))
                .map(getter -> {
                    try {
                        return getter.getName() + "=" + getter.invoke(obj);
                    } catch (Exception e) {
                        return null;
                    }
                })
                .filter(Objects::nonNull);
    }

    private static Predicate<String> ignorePredicate() {
        return name -> name.matches("class|id");
    }
}

