                                    byte[] newFrameData = concatenate(bom, copyright.getBytes(StandardCharsets.UTF_8));
                                    byte[] newTagSize = {(byte)((tagSize >> 21) & 0x7F), (byte)((tagSize >> 14) & 0x7F), (byte)((tagSize >> 7) & 0x7F), (byte)(tagSize & 0x7F)};
                                    mp3File.seek(position + 10 + framePos + 8);
                                    mp3File.write(newFrameSize);
