public static List<Method> readClassMethods(String className) throws IOException, ClassfileFormatException {
    try (FileInputStream fis = new FileInputStream(className + ".class")) {
        ClassReader reader = new ClassReader(fis);
        ClassNode classNode = new ClassNode();
        reader.accept(classNode, 0);
        List<MethodNode> methodNodes = classNode.methods;
        List<Method> methods = new ArrayList<>();
        for (MethodNode methodNode : methodNodes) {
            Method method = new Method(methodNode.name, methodNode.desc);
            methods.add(method);
        }
        return methods;
    } catch (IOException e) {
        throw new IOException("Error occurred while reading class file: " + className);
    } catch (ClassFormatError e) {
        throw new ClassfileFormatException("Class file format error found in the class file: " + className);
    }
}

