public static Type inferType(Expression expression, Type rootType, TypeDeclaration typeDeclaration) {
    if (expression instanceof Literal) {
        return ((Literal) expression).getType();
    } else if (expression instanceof VariableAccess) {
        String varName = ((VariableAccess) expression).getName();
        return typeDeclaration.getType(varName);
    } else if (expression instanceof BinaryExpression) {
        BinaryExpression binaryExp = (BinaryExpression) expression;
        Type leftType = inferType(binaryExp.getLeft(), rootType, typeDeclaration);
        Type rightType = inferType(binaryExp.getRight(), rootType, typeDeclaration);
        // type checking for the binary operation
        if (binaryExp.getOperator() == Operator.ADD && leftType == Type.STRING) {
            return Type.STRING;
        } else if (leftType == Type.DOUBLE || rightType == Type.DOUBLE) {
            return Type.DOUBLE;
        } else if (leftType == Type.INT && rightType == Type.INT) {
            return Type.INT;
        } else {
            return Type.ERROR; // type error
        }
    } else if (expression instanceof MethodCall) {
        MethodCall methodCall = (MethodCall) expression;
        String methodName = methodCall.getName();
        Type[] argTypes = new Type[methodCall.getArguments().size()];
        int argIndex = 0;
        for (Expression argExp : methodCall.getArguments()) {
            argTypes[argIndex] = inferType(argExp, rootType, typeDeclaration);
            argIndex++;
        }
        return typeDeclaration.getMethodReturnType(rootType, methodName, argTypes);
    } else {
        return Type.ERROR; // invalid expression
    }
}

