public double[][] inverseDCT(double[][] block) {
    int n = block.length;
    double[][] result = new double[n][n];
    double alpha_i, alpha_j, temp;
    double sqrt_2 = Math.sqrt(2);
    double C_0 = 1.0 / sqrt_2;
    double C_i = 1.0;
    double C_j = 1.0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            double sum = 0.0;
            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    alpha_i = (i == 0) ? C_0 : C_i;
                    alpha_j = (j == 0) ? C_0 : C_j;
                    temp = alpha_i * alpha_j * block[x][y] *
                            Math.cos((2 * x + 1) * i * Math.PI / (2 * n)) *
                            Math.cos((2 * y + 1) * j * Math.PI / (2 * n));
                    sum += temp;
                }
            }
            result[i][j] = sum / (2 * n);

        }
    }
    return result;
}

