public CompactMealy minimizeMealy(MealyMachine mealy, Alphabet alphabet) {
        CompactMealy.Builder builder = new CompactMealy.Builder(alphabet);

        Set<Set<State>> partitions;

        // Perform state equivalences computation

        // Prune the states
        Set<State> reachableStates = mealy.getInitialStates();
        Set<State> prunedStates = mealy.getStates().stream()
                .filter(state -> !reachableStates.contains(state))
                .collect(Collectors.toSet());

        // Add states to the minimized Mealy machine
        for (Set<State> partition : partitions) {
            State representative = partition.iterator().next(); // First State is the representative
            State newState = new State(representative.getName());
            newState.setOutput(representative.getOutput());
            newState.setInputPartition(partition);

            if (reachableStates.containsAll(partition)) {
                newState.setType(State.Type.NORMAL);
            } else {
                newState.setType(State.Type.SINK);
            }

            if (partition.contains(mealy.getInitialState())) {
                builder.setInitialState(newState.getName());
            }

            builder.setState(newState);
        }

        // Add transitions to the minimized Mealy machine
        for (State state : mealy.getStates()) {
            if (prunedStates.contains(state)) {
                continue;
            }
            StringBuilder sb = new StringBuilder();
            for (Object input : alphabet) {
                State transitionState = mealy.getTransition(state, input);
                if (transitionState == null || prunedStates.contains(transitionState)) {
                    continue;
                }
                sb.append(transitionState.getName())
                        .append("|")
                        .append(input.toString())
                        .append("|")
                        .append(transitionState.getOutput())
                        .append(",");
            }
            if (sb.length() > 0) {
                sb.deleteCharAt(sb.length() - 1);
                builder.addTransition(state.getName(), sb.toString());
            }
        }

        return builder.build();
    }

