    public static BootstrapText toTextViewMarkdown(@NonNull Context context,
                                                    @NonNull String markdown,
                                                    boolean editMode) {

        final BootstrapText.Builder builder = new BootstrapText.Builder(context);
        final Parser parser = Parser.builder().build();
        final Node parsed = parser.parse(markdown);

        final MarkdownToSpannableVisitor visitor = new MarkdownToSpannableVisitor(context,
                builder, editMode);

        parsed.accept(visitor);

        return builder.build();
    }

    private static class MarkdownToSpannableVisitor extends AbstractVisitor {
        private int listItemCounter = 0;

        private final Context context;
        private final BootstrapText.Builder builder;
        private final boolean editMode;
        private final List<Integer> listIndents;

        public MarkdownToSpannableVisitor(@NonNull Context context,
                                          @NonNull BootstrapText.Builder builder,
                                          boolean editMode) {
            this.context = context;
            this.builder = builder;
            this.editMode = editMode;

            listIndents = new ArrayList<>();
        }

        @Override
        public void visit(Text text) {
            builder.append(text.getLiteral());
        }

        @Override
        public void visit(Emphasis emphasis) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownEmphasisEdit :
                                    R.style.BootstrapTextAppearanceMarkdownEmphasis),
                    () -> true);
            openSpan();
            visitChildren(emphasis);
            closeSpan();
        }

        @Override
        public void visit(StrongEmphasis strongEmphasis) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownStrongEdit :
                                    R.style.BootstrapTextAppearanceMarkdownStrong),
                    () -> true);
            openSpan();
            visitChildren(strongEmphasis);
            closeSpan();
        }

        @Override
        public void visit(Paragraph paragraph) {
            visitChildren(paragraph);
            builder.append("\n");
        }

        @Override
        public void visit(Link link) {
            final String url = link.getDestination();
            builder.setSpan(new ClickableSpan() {
                @Override
                public void onClick(@NonNull View view) {
                    if (!TextUtils.isEmpty(url)) {
                        context.startActivity(new Intent(Intent.ACTION_VIEW,
                                Uri.parse(url)));
                    }
                }
            }, () -> true);
            openSpan();
            visitChildren(link);
            closeSpan();
        }

        @Override
        public void visit(Image image) {
            final String url = image.getDestination();
            if (editMode && TextUtils.isEmpty(url)) {
                builder.append("[image]");
            } else if (url != null) {
                builder.setSpan(new ImageSpan(context, url), () -> true);
            }
        }

        @Override
        public void visit(FencedCodeBlock fencedCodeBlock) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownCodeEdit :
                                    R.style.BootstrapTextAppearanceMarkdownCode),
                    () -> true);

            builder.append(fencedCodeBlock.getLiteral());
        }

        @Override
        public void visit(Code code) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownCodeEdit :
                                    R.style.BootstrapTextAppearanceMarkdownCode),
                    () -> true);

            builder.append(code.getLiteral());
        }

        @Override
        public void visit(BlockQuote blockQuote) {
            builder.setSpan(new TextAppearanceSpan(context,
                            R.style.BootstrapTextAppearanceMarkdownBlockquote),
                    () -> true);
            builder.startBlockQuote();
            visitChildren(blockQuote);
            builder.endBlockQuote();
        }

        @Override
        public void visit(Heading heading) {
            final int fontWeight;
            final int fontSizeResId;

            switch (heading.getLevel()) {
                case 1:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH1;
                    break;
                case 2:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH2;
                    break;
                case 3:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH3;
                    break;
                case 4:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH4;
                    break;
                case 5:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH5;
                    break;
                case 6:
                    fontWeight = R.style.FontWeightBold;
                    fontSizeResId = R.style.TextAppearanceH6;
                    break;
                default:
                    throw new IllegalStateException("Unknown header level: " + heading.getLevel());
            }

            builder.setSpan(new TextAppearanceSpan(context, fontWeight), () -> true);
            builder.setSpan(new TextAppearanceSpan(context, fontSizeResId), () -> true);

            visitChildren(heading);
            builder.append("\n");
        }

        @Override
        public void visit(HardLineBreak hardLineBreak) {
            builder.append("\n");
        }

        @Override
        public void visit(SoftLineBreak softLineBreak) {
            builder.append(" ");
        }

        @Override
        public void visit(IndentedCodeBlock indentedCodeBlock) {
            builder.setSpan(new TextAppearanceSpan(context,
                            editMode ? R.style.BootstrapTextAppearanceMarkdownCodeEdit :
                                    R.style.BootstrapTextAppearanceMarkdownCode),
                    () -> true);
            builder.append(indentedCodeBlock.getLiteral());
