        @Override
        public void visit(Strikethrough strikethrough) {
            builder.setSpan(new StrikethroughSpan(), () -> true);
            visitChildren(strikethrough);
            closeSpan();
        }

        @Override
        public void visit(BulletList bulletList) {
            final int listItemIndent = listIndents.size() * 2;

            listIndents.add(listItemIndent);

            visitChildren(bulletList);

            listIndents.remove(listIndents.size() - 1);
        }

        @Override
        public void visit(OrderedList orderedList) {
            final int listItemIndent = listIndents.size() * 2;

            listIndents.add(listItemIndent);

            visitChildren(orderedList);

            listIndents.remove(listIndents.size() - 1);
        }

        @Override
        public void visit(ListItem listItem) {
            final int listItemIndent = listIndents.size() * 2;

            final int bulletPointWidth = 4;

            // Add bullet point line:
            for (int i = 0; i < listItemIndent; i++) {
                builder.append(" ");
            }
            if (listItem.getParent() instanceof BulletList) {
                builder.append("\u2022 ");
            } else if (listItem.getParent() instanceof OrderedList) {
                listItemCounter++;
                builder.append(listItemCounter + ". ");
                if (listItem.getPrevious() != null && listItem.getPrevious() instanceof ListItem) {
                    listItemCounter = Integer.parseInt(
                            listItem.getPrevious().getFirstChild().getLiteral()) + 1;
                }
            }

            // Bullet point ends at this position, so that nested lists start on a new line:
            final int bulletPointEndPosition = builder.length();

            visitChildren(listItem);

            // Indent nested list elements:
            final int blockQuoteWitdth = 2;
            for (final Integer listItemIndentation : listIndents) {
                for (int i = 0; i < listItemIndentation + bulletPointWidth +
                        blockQuoteWitdth; i++) {
                    builder.insert(bulletPointEndPosition, " ");
                }
            }

