        public void appendIcon(@NonNull String iconCode) {
            final int iconSize = context.getResources()
                    .getDimensionPixelSize(R.dimen.bootstrap_glyphicons_font_size);
            final float iconBaselineOffset = 0.23f;
            final int iconColor;
            if (editMode) {
                iconColor = MaterialColors.getColor(context, R.attr.colorControlActivated, R.color.bootstrap_glyphicon_default_foreground);
            } else {
                iconColor = MaterialColors.getColor(context, R.attr.colorOnSurface, R.color.bootstrap_glyphicon_default_foreground);
            }
            final int iconBackgroundColor = MaterialColors.getColor(context, android.R.attr.colorTransparent, R.color.bootstrap_glyphicon_background);

            final Typeface glyphiconTypeface = ResourcesCompat.getFont(context, R.font.glyphicon_halflings_regular);
            final int iconCharCode = Integer.parseInt(iconCode, 16);
            final char iconChar = (char) iconCharCode;

            final StaticLayout glyphLayout = new StaticLayout(Character.toString(iconChar), new TextPaint(), iconSize, Layout.Alignment.ALIGN_NORMAL, 1.0f, iconBaselineOffset, false);
            final Bitmap bmp = Bitmap.createBitmap(glyphLayout.getWidth(), glyphLayout.getHeight(), Bitmap.Config.ARGB_8888);
            final Canvas canvas = new Canvas(bmp);
            canvas.drawColor(iconBackgroundColor);

            final int saveCount = canvas.save();
            glyphLayout.draw(canvas);
            canvas.restoreToCount(saveCount);

            final Drawable drawable = new BitmapDrawable(context.getResources(), bmp);
            drawable.setBounds(0, 0, bmp.getWidth(), bmp.getHeight());
            drawable.setColorFilter(iconColor, PorterDuff.Mode.SRC_ATOP);

            final GlobalColorSpan span = new GlobalColorSpan(drawable);

            builder.setSpan(span, () -> true);
        }

