        @Override
        public void visit(org.commonmark.node.Heading heading) {
            builder.append("\n\n");
            switch (heading.getLevel()) {
                case 1:
                    builder.startBlockQuote().append("# ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
                case 2:
                    builder.startBlockQuote().append("## ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
                case 3:
                    builder.startBlockQuote().append("### ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
                case 4:
                    builder.startBlockQuote().append("#### ")
                            .append(heading.getLiteral())
