                            .endBlockQuote();
                    break;
                case 5:
                    builder.startBlockQuote().append("##### ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
                case 6:
                    builder.startBlockQuote().append("###### ")
                            .append(heading.getLiteral())
                            .append(" ")
                            .endBlockQuote();
                    break;
            }
        }

        @Override
        public void visit(ThematicBreak thematicBreak) {
            builder.startBlockQuote().append("***").endBlockQuote();
        }

        @Override
        public void visit(org.commonmark.node.BlockQuote blockQuote) {
            builder.startBlockQuote().append("> ");
            visitChildren(blockQuote);
            builder.endBlockQuote();
        }

        @Override
        public void visit(org.commonmark.node.BulletList bulletList) {
            final List<ListItem> listItems = bulletList.getMutableChildren();
            final int numListItems = listItems.size();
            final Integer[] indents = Arrays.copyOf(listIndents.toArray(new Integer[0]), listIndents.size(), Integer[].class);

            for (int i = 0; i < numListItems; i++) {
                if (i > 0) {
                    indentNewItem(indents, true);
                }
                visit(listItems.get(i));
                if (i < (numListItems - 1)) {
                    builder.append("\n");
                }
            }
        }

        @Override
        public void visit(org.commonmark.node.OrderedList orderedList) {
            final List<ListItem> listItems = orderedList.getMutableChildren();
            final boolean isOrdered = true;
            final int numListItems = listItems.size();
            final Integer[] indents = Arrays.copyOf(listIndents.toArray(new Integer[0]), listIndents.size(), Integer[].class);

            for (int i = 0; i < numListItems; i++) {
                if (i > 0) {
                    indentNewItem(indents, false);
                }
                final String listItemMarker = orderedList.getDelimiter().toString() + " ";
                visitChildren(new ListItem(Arrays.asList(new Text(listItemMarker)), orderedList.getBulletMarker(), null));
                visit(listItems.get(i));
                if (i < (numListItems - 1)) {
                    builder.append("\n");
                }
            }
        }

        private void indentNewItem(@NonNull Integer[] indents, boolean createBullet) {
            // the standard is four spaces, but that may depend on font prefs
            int listIndent = indents.length * 4;
            // create the bullet point
            if (createBullet) {
                builder.append("> ");
                listIndent += 2;
            }
            // add indentation for list nesting
            for (int i = 0; i < indents.length; i++) {
                listIndent += indents[i];
            }
            builder.append(Strings.repeat(' ', listIndent));
        }
    }
}

