public class Page {

    public static PageSnapshot takeSnapshot(WebDriver driver, ScrollStrategy scroll, boolean useDevicePixelRatio) throws InterruptedException {

        // Scroll down the page if required
        if (scroll == ScrollStrategy.VERTICAL || scroll == ScrollStrategy.BOTH) {
            Long height = (Long) ((JavascriptExecutor) driver).executeScript("return Math.max(" +
                "document.documentElement.clientHeight, window.innerHeight || 0);");
            Long previousY = (Long) ((JavascriptExecutor) driver).executeScript("return window.scrollY");
            Long currentY = 0L;
            do {
                ((JavascriptExecutor) driver).executeScript("window.scrollBy(0, arguments[0]);", height);
                currentY = (Long) ((JavascriptExecutor) driver).executeScript("return window.scrollY");
                Thread.sleep(500);
            } while (currentY > previousY);
        }

        // Scroll right the page if required
        if (scroll == ScrollStrategy.HORIZONTAL || scroll == ScrollStrategy.BOTH) {
            Long width = (Long) ((JavascriptExecutor) driver).executeScript("return Math.max(" +
                "document.documentElement.clientWidth, window.innerWidth || 0);");
            Long previousX = (Long) ((JavascriptExecutor) driver).executeScript("return window.scrollX");
            Long currentX = 0L;
            do {
                ((JavascriptExecutor) driver).executeScript("window.scrollBy(arguments[0], 0);", width);
                currentX = (Long) ((JavascriptExecutor) driver).executeScript("return window.scrollX");
                Thread.sleep(500);
            } while (currentX > previousX);
        }

        // Take the screenshot
        Screenshot screenshot = new AShot().
                takeScreenshot(driver);

        // Create a PageSnapshot object and return it
        return new PageSnapshot(screenshot.getImage(), useDevicePixelRatio);
    }
}

