import java.util.List;
import java.util.Set;
import java.util.jar.JarEntry;
import java.util.jar.JarInputStream;

public class ManifestVerifier {

    public void verify(List<File> manifestFiles, List<String> filters) throws ManifestVerifyException {
        int numberOfEntries = -1;
        Set<String> checksums = new HashSet<String>();
        for (File manifestFile : manifestFiles) {
            if (!manifestFile.exists()) {
                throw new ManifestVerifyException("Manifest file does not exist: " + manifestFile.getAbsolutePath());
            }

            if (!manifestFile.isFile()) {
                throw new ManifestVerifyException("Manifest file is not a file: " + manifestFile.getAbsolutePath());
            }

            if (!manifestFile.canRead()) {
                throw new ManifestVerifyException("Cannot read manifest file: " + manifestFile.getAbsolutePath());
            }

            int currentNumberOfEntries = -1;
            Set<String> currentChecksums = new HashSet<String>();
            JarInputStream jarStream = null;

            try {
                jarStream = new JarInputStream(new FileInputStream(manifestFile));
                JarEntry jarEntry = null;
                while ((jarEntry = jarStream.getNextJarEntry()) != null) {
                    String entryName = jarEntry.getName();
                    if (!entryName.endsWith(".MF") && !entryName.endsWith(".SF")) {
                        currentNumberOfEntries++;
                        byte[] buffer = new byte[1024];
                        MessageDigest complete = MessageDigest.getInstance("MD5");
                        int numRead;
                        do {
                            numRead = jarStream.read(buffer);
                            if (numRead > 0) {
                                complete.update(buffer, 0, numRead);
                            }
                        } while (numRead != -1);
                        jarStream.closeEntry();
                        byte[] checksum = complete.digest();
                        StringBuilder result = new StringBuilder();
                        for (byte b : checksum) {
                            result.append(String.format("%02x", b));
                        }
                        currentChecksums.add(result.toString());
                    } else {
                        if (filters.contains(entryName)) {
                            continue;
                        }
                        currentNumberOfEntries++;
                        StringBuilder sb = new StringBuilder();
                        for (int i = 0; i < 8; i++) {
                            int c = jarStream.read();
                            sb.append((char)c);
                        }
                        String line = sb.toString();
                        line = line.substring(line.indexOf(":") + 1).trim();
                        MessageDigest md = MessageDigest.getInstance("MD5");
                        while (jarStream.available() > 0) {
                            int c = jarStream.read();
                            md.update((byte)c);
                        }
                        byte[] md5sum = md.digest();
                        StringBuilder result = new StringBuilder();
                        for (byte b : md5sum) {
                            result.append(String.format("%02x", b));
                        }
                        result.append(line);
                        currentChecksums.add(result.toString());
                    }
                }
            } catch (IOException e) {
                throw new ManifestVerifyException("IOException processing manifest file: " + manifestFile.getAbsolutePath(), e);
            } catch (NoSuchAlgorithmException e) {
                throw new ManifestVerifyException("MD5 algorithm not found - this should not happen", e);
            } finally {
                if (jarStream != null) {
                    try {
                        jarStream.close();
                    } catch (IOException e) {
                        // ignore
                    }
                }
            }
            if (numberOfEntries < 0) {
                numberOfEntries = currentNumberOfEntries;
            }
            if (currentNumberOfEntries != numberOfEntries) {
                throw new ManifestVerifyException("Different number of entries in manifest file: " + manifestFile.getAbsolutePath());
            }
            if (checksums.isEmpty()) {
                checksums = currentChecksums;
            } else {
                if (!checksums.equals(currentChecksums)) {
                    throw new ManifestVerifyException("Manifest files have different checksums: " + manifestFile.getAbsolutePath());
                }
            }
        }
    }
}

