public List<FailedBatch> batchSave(List<Object> objectsToSave) {
    List<FailedBatch> failedBatches = new ArrayList<>();
    List<Object> currentBatch = new ArrayList<>();
    int currentBatchSize = 0;
    int maxBatchSize = 25; //maximum number of objects that can be saved in a batch

    for (Object object : objectsToSave) {
        int objectSize = getObjectSize(object); //get object size in bytes
        if (currentBatchSize + objectSize <= maxBatchSize) {
            currentBatch.add(object);
            currentBatchSize += objectSize;
        } else {
            try {
                batchWrite(currentBatch); //call batchWriteItem API
                currentBatch.clear();
                currentBatchSize = 0;
            } catch (Exception e) {
                FailedBatch failedBatch = new FailedBatch(currentBatch, e);
                failedBatches.add(failedBatch);
            }
        }
    }

    if (currentBatch.size() > 0) {
        try {
            batchWrite(currentBatch); //call batchWriteItem API
        } catch (Exception e) {
            FailedBatch failedBatch = new FailedBatch(currentBatch, e);
            failedBatches.add(failedBatch);
