public ENUCoordinate convertWGS84ToENU(WGS84Coordinate cLL) throws MatrixException {
    double[] ecef = wgs84ToECEF(cLL);
    double[] refECEF = wgs84ToECEF(referenceCoordinate);

    double[] diff = VectorUtil.subtract(ecef, refECEF);
    double[][] rotationMatrix = calculateRotationMatrix(referenceCoordinate);

    double[] enu = MatrixUtil.multiply(rotationMatrix, diff);

    return new ENUCoordinate(enu[0], enu[1], enu[2]);
}

private double[][] calculateRotationMatrix(WGS84Coordinate referenceCoordinate) throws MatrixException {
    double lat = Math.toRadians(referenceCoordinate.getLatitude());
    double lon = Math.toRadians(referenceCoordinate.getLongitude());

    double sinLat = Math.sin(lat);
    double cosLat = Math.cos(lat);
    double sinLon = Math.sin(lon);
    double cosLon = Math.cos(lon);

    return new double[][]{{-sinLon, cosLon, 0}, {-sinLat * cosLon, -sinLat * sinLon, cosLat},
            {cosLat * cosLon, cosLat * sinLon, sinLat}};
}

private double[] wgs84ToECEF(WGS84Coordinate cLL) throws MatrixException {
    double lat = Math.toRadians(cLL.getLatitude());
    double lon = Math.toRadians(cLL.getLongitude());
    double alt = cLL.getAltitude();

    double a = Constants.WGS84_A;
    double b = Constants.WGS84_B;
    double f = Constants.WGS84_F;
    double eSq = Constants.WGS84_E_SQUARED;

    double n = a / Math.sqrt(1 - eSq * Math.sin(lat) * Math.sin(lat));
    double[] ecef = new double[]{(n + alt) * Math.cos(lat) * Math.cos(lon),
            (n + alt) * Math.cos(lat) * Math.sin(lon), (n * (1 - eSq) + alt) * Math.sin(lat)};

    return ecef;
}

