                    nonProblematicUnionSchema =
                        Schema.createUnion(nonProblematicUnionSchema, unionSchema);
                }
            }
            fieldSchema = nonProblematicUnionSchema;
        }
        Schema.Field newField =
            new Schema.Field(field.name(), fieldSchema, field.doc(), field.defaultVal(),
