    protected def createFor(final JvmTypeReference source, final JvmDeclaredType context,
            final ITypeArgumentContext argumentContext,
            final JvmGenericType container,
            final boolean isTypeParameter) {
        if (source != null) {
            val typ = source.type
            if (typ != null) {
                // Todo get rid of equal by ref, use more complex approach instead
                val equal = typeReferenceEqualityComparer.equals(source, typ)
                if (!equal) {
