private JvmOperation getJvmOperation(IMethod method, JvmType context) throws JavaModelException {
    JvmOperation operation = new JvmOperation();

    // Set the operation name
    operation.setName(method.getElementName());

    // Set the operation return type
    operation.setReturnType(context.getType());

    // Set the operation parameters
    IParameter[] parameters = method.getParameters();
    for (IParameter parameter : parameters) {
        JvmParameter jvmParameter = new JvmParameter();
        jvmParameter.setName(parameter.getElementName());
        jvmParameter.setType(parameter.getType().getJavaElementName());
        operation.addParameter(jvmParameter);
    }

    return operation;
}

