private JvmOperation getJvmOperation(IMethod method, JvmType context) throws JavaModelException {
	// Create a new JvmOperation instance
    JvmOperation operation = new JvmOperation();

    // Set the name of the operation to the name of the method
    operation.setName(method.getElementName());

    // Set the visibility of the operation based on the method's flags
    int flags = method.getFlags();
    if (Flags.isPublic(flags)) {
        operation.setVisibility(JvmVisibility.PUBLIC);
    } else if (Flags.isProtected(flags)) {
        operation.setVisibility(JvmVisibility.PROTECTED);
    } else if (Flags.isPrivate(flags)) {
        operation.setVisibility(JvmVisibility.PRIVATE);
    } else {
        operation.setVisibility(JvmVisibility.DEFAULT);
    }

    // Set the static flag of the operation based on the method's flags
    operation.setStatic(Flags.isStatic(flags));

    // Set the abstract flag of the operation based on the method's flags
    operation.setAbstract(Flags.isAbstract(flags));

    // Set the final flag of the operation based on the method's flags
    operation.setFinal(Flags.isFinal(flags));

    // Set the return type of the operation
    String returnType = method.getReturnType();
    operation.setReturnType(context.getType(returnType));

    // Set the parameters of the operation
    IParameter[] parameters = method.getParameters();
    for (IParameter parameter : parameters) {
        String parameterType = parameter.getTypeSignature();
        JvmType parameterJvmType = context.getType(parameterType);
        operation.addParameter(parameter.getName(), parameterJvmType);
    }

    // Set the exceptions that the operation can throw
    String[] exceptionTypes = method.getExceptionTypes();
    for (String exceptionType : exceptionTypes) {
        JvmType exceptionJvmType = context.getType(exceptionType);
        operation.addException(exceptionType, exceptionJvmType);
    }

    // Return the created JvmOperation
    return operation;
}

