public boolean scanContent(XMLTokener x, JSONObject context, String name) throws JSONException {
    if (name != null && name.length() > 0) {
        context.accumulate(name, "");
    }

    char c;
    int i;

    do {
        c = x.next();

    } while (Character.isWhitespace(c));

    if (c == 0) {
        throw x.syntaxError("Unfinished element");
    }

    if (c == '>') {
        return false;
    }

    x.back();

    String string = x.nextCDATA();

    if (string == null) {
        string = x.nextContent();
        if (string == null) {
            throw x.syntaxError("Unfinished element");
        }
        if (string.length() == 0) {
            return false;
        }
    }

    context.accumulate(name, string);
    return false;
}

