import java.io.*;
import java.util.*;
import java.util.zip.*;

public void changeZipEntries(File zip, List<ZipEntry> entries) throws IOException {
    // Open the existing ZIP file
    try (ZipFile zipFile = new ZipFile(zip)) {
        // Prepare the output stream
        File tempFile = File.createTempFile("temp", ".zip");
        try (ZipOutputStream outputStream = new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(tempFile)))) {
            // Copy all entries from the old ZIP file to the new one,
            // except for the ones that we want to add or replace
            Enumeration<? extends ZipEntry> zipEntries = zipFile.entries();
            while (zipEntries.hasMoreElements()) {
                ZipEntry entry = zipEntries.nextElement();
                if (!entries.contains(entry)) {
                    outputStream.putNextEntry(entry);
                    try (BufferedInputStream inputStream = new BufferedInputStream(zipFile.getInputStream(entry))) {
                        byte[] buffer = new byte[4096];
                        int bytesRead;
                        while ((bytesRead = inputStream.read(buffer)) > 0) {
                            outputStream.write(buffer, 0, bytesRead);
                        }
                    }
                    outputStream.closeEntry();
                }
            }
            // Add or replace the specified entries
            for (ZipEntry entry : entries) {
                outputStream.putNextEntry(entry);
                try (BufferedInputStream inputStream = new BufferedInputStream(new FileInputStream(entry.getName()))) {
                    byte[] buffer = new byte[4096];
                    int bytesRead;
                    while ((bytesRead = inputStream.read(buffer)) > 0) {
                        outputStream.write(buffer, 0, bytesRead);
                    }
                }
                outputStream.closeEntry();
            }
        }
        // Replace the original ZIP file with the modified one
        if (!zip.delete()) {
            throw new IOException("Failed to delete the original ZIP file.");
        }
        if (!tempFile.renameTo(zip)) {
            throw new IOException("Failed to rename the modified ZIP file.");
        }
    }
}

