public static void removeBlankNodeId(Map<String, Object> input) {
    Set<String> blankNodeIdSet = new HashSet<>();
    Map<String, Integer> blankNodeIdFreqMap = new HashMap<>();

    // Find frequency of each blank node identifier used in any property value within input
    for (Map.Entry<String, Object> entry : input.entrySet()) {
        Object value = entry.getValue();
        if (value instanceof Map) {
            extractBlankNodeId((Map<String, Object>) value, blankNodeIdFreqMap, blankNodeIdSet);
        } else if (value instanceof Object[]) {
            for (Object obj : (Object[]) value) {
                if (obj instanceof Map) {
                    extractBlankNodeId((Map<String, Object>) obj, blankNodeIdFreqMap, blankNodeIdSet);
                }
            }
        }
    }

    // Remove @id member of each node object where the member value is a blank node identifier which appears only once
    for (Map.Entry<String, Object> entry : input.entrySet()) {
        Object value = entry.getValue();
        if (value instanceof Map) {
            Map<String, Object> mapValue = (Map<String, Object>) value;
            String idValue = (String) mapValue.get("@id");

            // Check if idValue is a blank node identifier and appears only once in any property value within input
            if (idValue != null && idValue.startsWith("_:")) {
                boolean isUnique = blankNodeIdFreqMap.get(idValue) == 1;
                if (isUnique && blankNodeIdSet.contains(idValue)) {
                    mapValue.remove("@id");
                }
            }
            removeBlankNodeId(mapValue);
        } else if (value instanceof Object[]) {
            for (Object obj : (Object[]) value) {
                if (obj instanceof Map) {
                    removeBlankNodeId((Map<String, Object>) obj);
                }
            }
        }
    }
}

private static void extractBlankNodeId(Map<String, Object> map, Map<String, Integer> freqMap, Set<String> idSet) {
    Object idValue = map.get("@id");
    if (idValue != null && idValue instanceof String && ((String) idValue).startsWith("_:")) {
        String id = (String) idValue;
        freqMap.put(id, freqMap.getOrDefault(id, 0) + 1);
        idSet.add(id);
    }
    map.values().forEach(value -> {
        if (value instanceof Map) {
            extractBlankNodeId((Map<String, Object>) value, freqMap, idSet);
        } else if (value instanceof Object[]) {
            for (Object obj : (Object[]) value) {
                if (obj instanceof Map) {
                    extractBlankNodeId((Map<String, Object>) obj, freqMap, idSet);
                }
            }
        }
    });
}

