import java.io.*;

public static void compressDirectory(File sourceDir, OutputStream os, RenameCallback mapper) throws IOException {

    ZipOutputStream zos = new ZipOutputStream(new BufferedOutputStream(os));

    compressDirectoryImpl(sourceDir, zos, "", mapper);

    zos.flush();
    zos.close();
}

private static void compressDirectoryImpl(File directory, ZipOutputStream zos, String prefix, RenameCallback mapper) throws IOException {

    File[] files = directory.listFiles();
    byte[] buffer = new byte[4096];
    for (File file : files) {
        if (file.isDirectory()) {
            String entryName = prefix + mapper.rename(file).replace(File.separatorChar, '/') + "/";
            ZipEntry ze = new ZipEntry(entryName);
            zos.putNextEntry(ze);
            compressDirectoryImpl(file, zos, entryName, mapper);
        } else {
            FileInputStream fis = new FileInputStream(file);
            try {
                String entryName = prefix + mapper.rename(file).replace(File.separatorChar, '/');
                ZipEntry ze = new ZipEntry(entryName);
                zos.putNextEntry(ze);
                int len;
                while ((len = fis.read(buffer)) > 0) {
                    zos.write(buffer, 0, len);
                }
                zos.closeEntry();
            } finally {
                fis.close();
            }
        }
    }
}

public interface RenameCallback {
    public String rename(File file);
}

