private int readMethod( final ClassVisitor classVisitor, final Context context, final int methodInfoOffset) {
	// Read the access flags of the method
    int accessFlags = readUnsignedShort(methodInfoOffset);
    // Read the name index of the method
    int nameIndex = readUnsignedShort(methodInfoOffset + 2);
    // Read the descriptor index of the method
    int descriptorIndex = readUnsignedShort(methodInfoOffset + 4);
    // Read the number of attributes of the method
    int attributesCount = readUnsignedShort(methodInfoOffset + 6);
    // Create a MethodVisitor for the method
    MethodVisitor methodVisitor = classVisitor.visitMethod(accessFlags, context.constantPool.getUtf8(nameIndex), context.constantPool.getUtf8(descriptorIndex), null, null);
    // Initialize the offset to the start of the attributes
    int currentOffset = methodInfoOffset + 8;
    // Visit each attribute of the method
    for (int i = 0; i < attributesCount; i++) {
        currentOffset = readAttribute(methodVisitor, context, currentOffset);
    }
    // Return the offset of the first byte following the method_info structure
    return currentOffset;
}

