public void relabelImage(int[][] input, int[][] output, int[] regionMemberCount) {
    int rows = input.length;
    int cols = input[0].length;
    int currentLabel = 1;

    for (int row = 0; row < rows; row++) {
        for (int col = 0; col < cols; col++) {
            int pixelValue = input[row][col];
            if (pixelValue > 0) {
                if (output[row][col] == 0) {
                    // perform depth-first search to group pixels with the same label
                    Stack<int[]> stack = new Stack<>();
                    stack.push(new int[] {row, col});
                    output[row][col] = currentLabel;
                    int count = 1;

                    while (!stack.isEmpty()) {
                        int[] currentPixel = stack.pop();
                        int currentRow = currentPixel[0];
                        int currentCol = currentPixel[1];

                        // check neighboring pixels
                        for (int i = -1; i <= 1; i++) {
                            for (int j = -1; j <= 1; j++) {
                                int neighborRow = currentRow + i;
                                int neighborCol = currentCol + j;
                                if (neighborRow >= 0 && neighborRow < rows && neighborCol >= 0 && neighborCol < cols) {
                                    if (input[neighborRow][neighborCol] == pixelValue && output[neighborRow][neighborCol] == 0) {
                                        output[neighborRow][neighborCol] = currentLabel;
                                        count++;
                                        stack.push(new int[] {neighborRow, neighborCol});
                                    }
                                }
                            }
                        }
                    }

                    // update regionMemberCount with count of pixels in grouped region
                    regionMemberCount[currentLabel] = count;
                    currentLabel++;
                } else {
                    // pixel already assigned to a group
                    regionMemberCount[output[row][col]]++;
                }
            }
        }
    }
}

