import java.io.*;
import java.util.Scanner;

public class PGM {
    private int width;
    private int height;
    private int[][] pixels;

    public PGM(InputStream fileName, int[][] storage) throws IOException {
        Scanner inFile = new Scanner(fileName);
        String magicNumber = inFile.nextLine();

        if (!magicNumber.equals("P2")) {
            throw new IOException("Cannot load PGM file: wrong file format.");
        }

        String comment = inFile.nextLine();

        // Skips comments until it reaches the line that holds dimensions information
        while (comment.charAt(0) == '#') {
            comment = inFile.nextLine();
        }

        String[] dimensions = comment.split("\\s+");
        width = Integer.parseInt(dimensions[0]);
        height = Integer.parseInt(dimensions[1]);
        pixels = new int[height][width];

        int maxVal = Integer.parseInt(inFile.nextLine());

        // If no storage is provided, allocate new memory for pixels
        if (storage == null) {
            storage = new int[height][width];
        }

        // Read and store all the pixels in the storage provided
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                storage[y][x] = inFile.nextInt();
            }
        }

        this.pixels = storage;
    }

    // Getters for the PGM image
    public int getWidth() {
        return width;
    }

    public int getHeight() {
        return height;
    }

    public int[][] getPixels() {
        return pixels;
    }
}

