import android.graphics.Bitmap;
import android.graphics.BitmapFactory;

public Bitmap loadBitmapWithReuse(String fileName, Bitmap dest) throws ImageLoadException {
    BitmapFactory.Options options = new BitmapFactory.Options();
    options.inJustDecodeBounds = true;
    BitmapFactory.decodeFile(fileName, options);

    int srcWidth = options.outWidth;
    int srcHeight = options.outHeight;
    int inSampleSize = 1; // default value

    if(dest != null && android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.KITKAT) {
        options.inMutable = true;
        options.inBitmap = dest;
        options.inSampleSize = calculateInSampleSize(options, dest.getWidth(), dest.getHeight());

        if(srcWidth/options.inSampleSize > dest.getWidth() || srcHeight/options.inSampleSize > dest.getHeight()) {
            dest = null;
        }
    }

    if(dest == null) {
        options.inMutable = true;
        options.inBitmap = null;
        options.inSampleSize = calculateInSampleSize(options, srcWidth, srcHeight);
    }

    options.inJustDecodeBounds = false;
    Bitmap bmp = BitmapFactory.decodeFile(fileName, options);
    if(bmp == null) {
        throw new ImageLoadException("Unable to load file");
    }

    return bmp;
}

public int calculateInSampleSize(BitmapFactory.Options options, int reqWidth, int reqHeight) {
    final int height = options.outHeight;
    final int width = options.outWidth;
    int inSampleSize = 1;

    if (height > reqHeight || width > reqWidth) {
        final int heightRatio = Math.round((float) height / (float) reqHeight);
        final int widthRatio = Math.round((float) width / (float) reqWidth);

        inSampleSize = heightRatio < widthRatio ? heightRatio : widthRatio;
    }

    return inSampleSize;
}

