public ResolvedInfo resolveUri(String uri) throws WebdavException {
    if (uri == null || uri.isEmpty()) {
        throw new WebdavException("URI cannot be null or empty.");
    }

    ResolvedInfo resolvedInfo = new ResolvedInfo();
    URI parsedUri = null;
    try {
        parsedUri = new URI(uri);
    } catch (URISyntaxException e) {
        throw new WebdavException("Invalid URI: " + uri, e);
    }

    String scheme = parsedUri.getScheme();
    if (scheme == null || (!scheme.equals("http") && !scheme.equals("https"))) {
        // URI does not match a known scheme, throw exception
        throw new WebdavException("URI must start with http:// or https://");
    }

    String authority = parsedUri.getAuthority();
    if (authority == null || authority.isEmpty()) {
        // URI does not have an authority, throw exception
        throw new WebdavException("URI missing authority");
    }

    String[] parts = parsedUri.getPath().split("/", 3);
    if (parts.length < 2) {
        // URI does not have enough path segments, throw exception
        throw new WebdavException("URI missing required path components; must be in the format /repo/ws/[path]");
    }

    resolvedInfo.setRepositoryName(parts[1]);
    if (parts.length == 2) {
        // URI only contains repository and workspace names
        resolvedInfo.setWorkspaceName(parts[2]);
        return resolvedInfo;
    }

    // URI contains a path component
    resolvedInfo.setWorkspaceName(parts[2]);
    resolvedInfo.setNodePath(parts[3]);
    return resolvedInfo;
}

