import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class ConnectionPool {
    private final int maxConnections;
    private final BlockingQueue<MCWrapper> pool;

    public ConnectionPool(int maxConnections) {
        this.maxConnections = maxConnections;
        this.pool = new LinkedBlockingQueue<>(maxConnections);
    }

    public MCWrapper getConnection() throws ResourceAllocationException {
        if (pool.size() < maxConnections) {
            MCWrapper wrapper = new MCWrapper();
            pool.add(wrapper);
            return wrapper;
        } else {
            throw new ResourceAllocationException("Maximum connection limit reached");
        }
    }

    public void returnConnection(MCWrapper wrapper) {
        pool.remove(wrapper);
    }
}

