protected MCWrapper createManagedConnectionWithMCWrapper( ManagedConnectionFactory managedConnectionFactory, Subject subject, ConnectionRequestInfo cri, boolean connectionSharing, int hashCode) throws ResourceAllocationException {
	// Check if the maximum connection limit has been reached
    if (this.currentConnections >= this.maxConnections) {
        // Queue the request
        this.requestQueue.add(new ConnectionRequest(managedConnectionFactory, subject, cri, connectionSharing, hashCode));
        throw new ResourceAllocationException("Maximum connection limit reached. Request queued.");
    } else {
        // Create a new MCWrapper
        MCWrapper mcWrapper = new MCWrapper(managedConnectionFactory, subject, cri, connectionSharing, hashCode);
        this.currentConnections++;
        return mcWrapper;
    }
}

