import org.apache.thrift.TBase;
import org.apache.thrift.TFieldIdEnum;
import org.apache.thrift.TFieldRequirementType;
import org.joda.time.DateTime;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

public class ThriftEnvelopeEventCreator {

    public <T extends TBase<?, ?>> ThriftEnvelopeEvent createThriftEnvelopeEvent(
            String eventName,
            T thriftObject) {

        Map<String, Object> thriftFields = mapFields(thriftObject);

        return new ThriftEnvelopeEvent(
                eventName,
                DateTime.now(),
                thriftFields);
    }

    private <T extends TBase<?, ?>> Map<String, Object> mapFields(T thriftObject) {
        Map<String, Object> thriftFields = new HashMap<>();
        List<TFieldIdEnum> fieldIdEnums = getFieldIdEnums(thriftObject);

        for (TFieldIdEnum fieldIdEnum : fieldIdEnums) {
            TFieldRequirementType fieldRequirementType = thriftObject.getFieldType(fieldIdEnum).getReq();
            Object value = thriftObject.getFieldValue(fieldIdEnum);
            if (fieldRequirementType == TFieldRequirementType.REQUIRED ||
                    fieldRequirementType == TFieldRequirementType.OPTIONAL && value != null) {
                thriftFields.put(fieldIdEnum.getFieldName(), value);
            }
        }

        return thriftFields;
    }

    private <T extends TBase<?, ?>> List<TFieldIdEnum> getFieldIdEnums(T thriftObject) {
        List<TFieldIdEnum> fieldIdEnums = new ArrayList<>();

        Iterator<TFieldIdEnum> fieldIdEnumIterator = thriftObject.getFields().keySet().iterator();

        while (fieldIdEnumIterator.hasNext()) {
            TFieldIdEnum fieldIdEnum = fieldIdEnumIterator.next();
            fieldIdEnums.add(fieldIdEnum);
        }
        return fieldIdEnums;
    }
}

