        FAST_PARSING: {







            WALKING_BACKWARDS: for (pathIndex = pathLen - 1; pathIndex >= 0; pathIndex--) {
                final char c = path.charAt(pathIndex);
                switch (state) {
                    case NEW_ELEM:
                        switch (c) {
                            case '/':


                                break FAST_PARSING;
                            case '.':
                                state = ParseState.ONE_DOT;
                                continue WALKING_BACKWARDS;
                            default:
                                state = ParseState.IN_ELEM;
                                continue WALKING_BACKWARDS;
                        }
                    case IN_ELEM:
                        if (c == '/')
                            state = ParseState.NEW_ELEM;
                        continue WALKING_BACKWARDS;
                    case ONE_DOT:
                        switch (c) {
                            case '/':
                                state = ParseState.NEW_ELEM;
                                continue WALKING_BACKWARDS;
                            case '.':
                                state = ParseState.TWO_DOTS;
                                continue WALKING_BACKWARDS;
                            default:
                                state = ParseState.IN_ELEM;
                                continue WALKING_BACKWARDS;
                        }
                    case TWO_DOTS:
                        switch (c) {
                            case '/':


                                pathIndex += 2;

                                state = ParseState.NEW_ELEM;

                                break FAST_PARSING;
                            default:

                                state = ParseState.IN_ELEM;
                                continue WALKING_BACKWARDS;
                        }
                }
            }
            return path;
        }




        char[] buffer = path.toCharArray();
        int offset = pathIndex + 1;  
        int elemsToSkip = 0;


        WALKING_BACKWARDS: for (; pathIndex > 0; pathIndex--) {
            final char c = buffer[pathIndex];
            OUTER_HERE: switch (state) {
                case NEW_ELEM:
                    switch (c) {
                        case '/':

                            continue WALKING_BACKWARDS;
                        case '.':

                            state = ParseState.ONE_DOT;
                            continue WALKING_BACKWARDS;
                        default:
                            state = ParseState.IN_ELEM;
                            if (elemsToSkip > 0)
                                continue WALKING_BACKWARDS;
                            break OUTER_HERE;
                    }
                case IN_ELEM:
                    switch (c) {
                        case '/':
                            state = ParseState.NEW_ELEM;
                            if (elemsToSkip == 0)
                                break OUTER_HERE;
                            elemsToSkip--;
                            continue WALKING_BACKWARDS;
                        default:
                            if (elemsToSkip == 0)
                                break OUTER_HERE;
                            continue WALKING_BACKWARDS;
                    }
                case ONE_DOT:
                    switch (c) {
                        case '.':

                            state = ParseState.TWO_DOTS;
                            continue WALKING_BACKWARDS;
                        case '/':
                            state = ParseState.NEW_ELEM;
                            if (elemsToSkip == 0) {

                                buffer[--offset] = '.';
                                break OUTER_HERE;
                            }
                            elemsToSkip--;
                            continue WALKING_BACKWARDS;
                        default:
                            state = ParseState.IN_ELEM;
                            if (elemsToSkip == 0) {

                                buffer[--offset] = '.';
                                break OUTER_HERE;
                            }
                            continue WALKING_BACKWARDS;
                    }
                case TWO_DOTS:
                    switch (c) {
                        case '/':
                            state = ParseState.NEW_ELEM;

                            elemsToSkip++;

                            continue WALKING_BACKWARDS;
                        default:
                            state = ParseState.IN_ELEM;
                            if (elemsToSkip == 0) {

                                buffer[--offset] = '.';
                                buffer[--offset] = '.';
                                break OUTER_HERE;
                            }
                            continue WALKING_BACKWARDS;
                    }
            }
            buffer[--offset] = c;
            continue WALKING_BACKWARDS;
        }  



        final char c = buffer[0];
        final boolean pathHasLeadingSlash = c == '/';



        switch (state) {
            case IN_ELEM:  
                if (elemsToSkip == 0)
                    buffer[--offset] = c;
                else
                    elemsToSkip--;
                break;
            case ONE_DOT:  
                if (elemsToSkip == 0 || c == '.') {
                    buffer[--offset] = '.';
                    buffer[--offset] = c;
                } else {
                    elemsToSkip--;
                }
                break;
            case NEW_ELEM:
                if (elemsToSkip == 0) {
                    if ((offset == pathLen) || !!!pathHasLeadingSlash)
                        buffer[--offset] = c;
                } else if (!!!pathHasLeadingSlash) { 
                    elemsToSkip--;
                }
                break;
            case TWO_DOTS:
                if (elemsToSkip == 0 || pathHasLeadingSlash) {
                    buffer[--offset] = '.';
                    buffer[--offset] = '.';
                    buffer[--offset] = c;
                } else {
                    elemsToSkip--;
                }
                break;
        }
        if (elemsToSkip == 0) {
            boolean resultHasLeadingSlash = offset < pathLen && buffer[offset] == '/';

            if (pathHasLeadingSlash ^ resultHasLeadingSlash)
                if (resultHasLeadingSlash)
                    offset++;  
                else
                    buffer[--offset] = '/';  
        } else {

            if (offset < pathLen && buffer[offset] != '/')
                buffer[--offset] = '/';

            while (--elemsToSkip > 0) {
                buffer[--offset] = '.';
                buffer[--offset] = '.';
                buffer[--offset] = '/';
            }

            buffer[--offset] = '.';
            buffer[--offset] = '.';
            if (pathHasLeadingSlash)
                buffer[--offset] = '/';
        }
        return new String(buffer, offset, pathLen - offset);
    }

