public static String normalizeUnixStylePath(String path) {
    Path normalizedPath = Paths.get(path).normalize();
    String normalizedPathString = normalizedPath.toString();

    // If the original path started with a '/', make sure the normalized path starts with a '/'
    if (path.startsWith("/") && !normalizedPathString.startsWith("/")) {
        normalizedPathString = "/" + normalizedPathString;
    }

    // Remove trailing '/'
    if (normalizedPathString.endsWith("/")) {
        normalizedPathString = normalizedPathString.substring(0, normalizedPathString.length() - 1);
    }

    return normalizedPathString;
}

