            // check if it is constructor
            if (name.equals("<init>")) {
                mv = new MethodVisitor(Opcodes.ASM5, mv) {
                    @Override
                    public void visitCode() {
                        // invoke the specified class/method
                        mv.visitLdcInsn(Type.getType("L" + clazz.getName().replace(".", "/") + ";"));
                        mv.visitMethodInsn(Opcodes.INVOKESTATIC, "java/lang/Class", "forName",
                                "(Ljava/lang/String;)Ljava/lang/Class;", false);
                        mv.visitLdcInsn(methodName);
                        mv.visitInsn(Opcodes.ACONST_NULL);
                        mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/Class", "getMethod",
                                "(Ljava/lang/String;[Ljava/lang/Class;)Ljava/lang/reflect/Method;", false);
                        mv.visitInsn(Opcodes.ACONST_NULL);
                        mv.visitTypeInsn(Opcodes.NEW, cr.getClassName());
                        mv.visitInsn(Opcodes.DUP);
                        int count = Type.getArgumentTypes(descriptor).length;
                        for (int i = 0; i < count; i++) {
                            mv.visitVarInsn(Type.getType(descriptor).getOpcode(Opcodes.ILOAD), i);
                        }
                        mv.visitMethodInsn(Opcodes.INVOKESPECIAL, cr.getClassName(), "<init>", descriptor, false);
                        mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/reflect/Method", "invoke",
                                "(Ljava/lang/Object;[Ljava/lang/Object;)Ljava/lang/Object;", false);
                        mv.visitInsn(Opcodes.POP);
                        super.visitCode();
                    }
                };
            }
            return mv;
        }
    };
