import java.awt.*;
import javax.swing.*;

public class BoxPlot extends JPanel {

    private double[] data;

    public BoxPlot(double[] data) {
        this.data = data;
    }

    public void paintComponent(Graphics g) {
        super.paintComponent(g);

        double[] sortedData = data.clone();
        Arrays.sort(sortedData);

        int canvasWidth = getWidth();
        int canvasHeight = getHeight();
        int margin = 20;

        double minValue = sortedData[0];
        double maxValue = sortedData[sortedData.length - 1];
        double iqr = calculateIQR(sortedData);
        double[] quartiles = calculateQuartiles(sortedData);
        double lowerWhisker = Math.max(minValue, quartiles[0] - 1.5 * iqr);
        double upperWhisker = Math.min(maxValue, quartiles[1] + 1.5 * iqr);

        g.drawLine(margin, canvasHeight - margin, canvasWidth - margin, canvasHeight - margin);
        g.drawLine(margin, margin, margin, canvasHeight - margin);

        int boxX = canvasWidth / 2 - margin;
        int boxY = margin;
        int boxWidth = 2 * margin;
        int boxHeight = canvasHeight - 2 * margin;
        g.drawRect(boxX, boxY, boxWidth, boxHeight);

        int lowerQuartile = (int) Math.round(boxY + boxHeight * (1 - (quartiles[0] - minValue) / (maxValue - minValue)));
        int upperQuartile = (int) Math.round(boxY + boxHeight * (1 - (quartiles[1] - minValue) / (maxValue - minValue)));
        int median = (int) Math.round(boxY + boxHeight * (1 - (quartiles[2] - minValue) / (maxValue - minValue)));
        int lowerWhiskerY = (int) Math.round(boxY + boxHeight * (1 - (lowerWhisker - minValue) / (maxValue - minValue)));
        int upperWhiskerY = (int) Math.round(boxY + boxHeight * (1 - (upperWhisker - minValue) / (maxValue - minValue)));
        g.drawLine(boxX, median, boxX + boxWidth, median);
        g.drawLine(boxX + margin, lowerQuartile, boxX + boxWidth - margin, lowerQuartile);
        g.drawLine(boxX + margin, upperQuartile, boxX + boxWidth - margin, upperQuartile);
        g.drawLine((boxX + margin / 2), lowerWhiskerY, (boxX + boxWidth - margin / 2), lowerWhiskerY);
        g.drawLine((boxX + margin / 2), upperWhiskerY, (boxX + boxWidth - margin / 2), upperWhiskerY);
    }

    private double calculateIQR(double[] data) {
        double[] quartiles = calculateQuartiles(data);
        return quartiles[1] - quartiles[0];
    }

    private double[] calculateQuartiles(double[] data) {
        double[] quartiles = new double[3];
        int n = data.length;
        quartiles[1] = getMedian(data);
        if (n % 2 == 0) {
            quartiles[0] = getMedian(Arrays.copyOfRange(data, 0, n/2));
            quartiles[2] = getMedian(Arrays.copyOfRange(data, n/2, n));
        } else {
            quartiles[0] = getMedian(Arrays.copyOfRange(data, 0, n/2));
            quartiles[2] = getMedian(Arrays.copyOfRange(data, n/2 + 1, n));
        }
        return quartiles;
    }

    private double getMedian(double[] data) {
        int n = data.length;
        if (n % 2 == 0) {
            return (data[n/2 - 1] + data[n/2]) / 2;
        } else {
            return data[n/2];
        }
    }

    public static void main(String[] args) {
        JFrame frame = new JFrame("Box Plot");
        double[] data = new double[] {3.6, 5.7, 0.8, 7.9, 1.0, 3.5, 2.2, 6.5, 4.6};
        BoxPlot plot = new BoxPlot(data);
        plot.setBackground(Color.white);
        frame.add(plot);
        frame.setSize(400, 400);
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
    }

}

