import java.util.ArrayList;
import java.util.HashMap;

public class MergeFunction {
    public HashMap<String, Object> merge(HashMap<String, Object> a, HashMap<String, Object> b) {
        HashMap<String, Object> result = new HashMap<>();

        // iterate over keys in a
        for (String key : a.keySet()) {
            Object aValue = a.get(key);
            Object bValue = b.get(key);

            // if both have same key and same type of value
            if (b.containsKey(key) && aValue.getClass().equals(bValue.getClass())) {
                // if the value is a List
                if (aValue instanceof ArrayList) {
                    ArrayList<Object> mergedList = new ArrayList<>((ArrayList) aValue);
                    mergedList.addAll((ArrayList) bValue);
                    result.put(key, mergedList);
                }
                // if the value is a HashMap
                else if (aValue instanceof HashMap) {
                    HashMap<String, Object> mergedMap = this.merge((HashMap) aValue, (HashMap) bValue);
                    result.put(key, mergedMap);
                }
                // if the value is of any other type
                else {
                    result.put(key, new ArrayList<Object>() {{
                        add(aValue);
                        add(bValue);
                    }});
                }
            }
            // if only A has this key
            else {
                result.put(key, a.get(key));
            }
        }

        // iterate over keys in b that are not in a
        for (String key : b.keySet()) {
            if (!result.containsKey(key)) {
                result.put(key, b.get(key));
            }
        }

        return result;
    }
}

