public void executePutCall(String partialUrl, Object payload, Map<String, String> headers, Map<String, String> queryParams) throws Exception {
    URIBuilder uriBuilder = new URIBuilder(partialUrl);
    if (queryParams != null) {
        for (Map.Entry<String, String> queryParam : queryParams.entrySet()) {
            uriBuilder.addParameter(queryParam.getKey(), queryParam.getValue());
        }
    }

    HttpPut httpPut = new HttpPut(uriBuilder.build());

    //Add headers to request
    if (headers != null) {
        for (Map.Entry<String, String> header : headers.entrySet()) {
            httpPut.addHeader(header.getKey(), header.getValue());
        }
    }

    //Set payload entity
    if (payload != null) {
        String payloadJson = payload.toString();
        StringEntity payloadEntity = new StringEntity(payloadJson);
        payloadEntity.setContentType("application/json");
        ((HttpEntityEnclosingRequestBase) httpPut).setEntity(payloadEntity);
    }

    //Execute the PUT Request
    CloseableHttpClient httpClient = HttpClients.createDefault();
    CloseableHttpResponse response = httpClient.execute(httpPut);

    //Print response in console, you can remove this as well
