public void transferOwnershipFromGlobalToLocale(Model globalModel, Model localModel) {
    // Iterate through all items in the global model and remove each item
    // from the global model and add it to the local model.
    for (Item item : globalModel.getItems()) {
        globalModel.removeItem(item);
        localModel.addItem(item);
    }

    // Set the ownership of the local model to the current user.
    localModel.setOwner(getCurrentUser());
}

