import java.util.concurrent.*;

public class TransmittableThreadLocalExecutorService extends AbstractExecutorService {

    private final ExecutorService executor;
    private final ThreadLocal<Object> threadLocal;

    public TransmittableThreadLocalExecutorService(ExecutorService executor) {
        this.executor = executor;
        this.threadLocal = new TransmittableThreadLocal<>();
    }

    @Override
    public void shutdown() {
        executor.shutdown();
    }

    @Override
    public List<Runnable> shutdownNow() {
        return executor.shutdownNow();
    }

    @Override
    public boolean isShutdown() {
        return executor.isShutdown();
    }

    @Override
    public boolean isTerminated() {
        return executor.isTerminated();
    }

    @Override
    public boolean awaitTermination(long l, TimeUnit timeUnit) throws InterruptedException {
        return executor.awaitTermination(l, timeUnit);
    }

    @Override
    public void execute(Runnable runnable) {
        final Object value = threadLocal.get();

        executor.execute(new Runnable() {
            @Override
            public void run() {
                threadLocal.set(value);
                try {
                    runnable.run();
                } finally {
                    threadLocal.remove();
                }
            }
        });
    }

    @Override
    public <T> Future<T> submit(Callable<T> callable) {
        final Object value = threadLocal.get();

        return executor.submit(new Callable<T>() {
            @Override
            public T call() throws Exception {
                threadLocal.set(value);
                try {
                    return callable.call();
                } finally {
                    threadLocal.remove();
                }
            }
        });
    }

    @Override
    public <T> Future<T> submit(Runnable runnable, T t) {
        final Object value = threadLocal.get();

        return executor.submit(new Runnable() {
            @SuppressWarnings("unchecked")
            @Override
            public void run() {
                threadLocal.set(value);
                try {
                    runnable.run();
                } finally {
                    threadLocal.remove();
                }
            }
        }, t);
    }

    @Override
    public Future<?> submit(Runnable runnable) {
        final Object value = threadLocal.get();

        return executor.submit(new Runnable() {
            @Override
            public void run() {
                threadLocal.set(value);
                try {
                    runnable.run();
                } finally {
                    threadLocal.remove();
                }
            }
        });
    }
}

