public static List<Node> getStaticRoute(NodesMap nm, Node startNode, Node endNode) {
    // Check if start and end nodes are valid
    if (startNode == null || endNode == null || !nm.containsNode(startNode) || !nm.containsNode(endNode)) {
        return null; // If not, return null
    }

    // Implement depth-first search (DFS) algorithm to get the static route between two given nodes
    Stack<Node> stack = new Stack<>();
    Set<Node> visited = new HashSet<>();
    Map<Node, Node> parents = new HashMap<>();

    stack.push(startNode);
    visited.add(startNode);

    while (!stack.isEmpty()) {
        Node currentNode = stack.pop();

        if (currentNode.equals(endNode)) { // If we have reached the end node, we have found the route
            List<Node> route = new ArrayList<>();
            Node node = endNode;
            while (node != null) {
                route.add(node);
                node = parents.get(node);
            }
            Collections.reverse(route); // Reverse the route so it starts from the starting node
            return route;
        }

        for (Node neighbour : nm.getNeighbours(currentNode)) {
            if (!visited.contains(neighbour)) {
                visited.add(neighbour);
                stack.push(neighbour);
                parents.put(neighbour, currentNode);
            }
        }
    }
    return null; // If route is not found, return null
}

