public <T> List<T> queryByContext(ContentResolver contentResolver, Class<T> targetClass, Uri uri, String[] projection, String selection, String[] selectionArgs, String sortOrder) {
    List<T> result = new ArrayList<>();

    Cursor cursor = contentResolver.query(uri, projection, selection, selectionArgs, sortOrder);
    if (cursor != null) {
        while (cursor.moveToNext()) {
            try {
                T item = targetClass.newInstance();
                for (int i = 0; i < projection.length; i++) {
                    String column = projection[i];
                    Field field = targetClass.getDeclaredField(column);
                    field.setAccessible(true);
                    int columnIndex = cursor.getColumnIndex(column);
                    Object value = getValueForField(field, cursor, columnIndex);
                    field.set(item, value);
                }
                result.add(item);
            } catch (InstantiationException | IllegalAccessException | NoSuchFieldException e) {
                e.printStackTrace();
            }
        }
        cursor.close();
    }

    return result;
}

private Object getValueForField(Field field, Cursor cursor, int columnIndex) {
    Class<?> fieldType = field.getType();
    if (fieldType == String.class) {
        return cursor.getString(columnIndex);
    } else if (fieldType == int.class || fieldType == Integer.class) {
        return cursor.getInt(columnIndex);
    } else if (fieldType == long.class || fieldType == Long.class) {
        return cursor.getLong(columnIndex);
    } else if (fieldType == float.class || fieldType == Float.class) {
        return cursor.getFloat(columnIndex);
    } else if (fieldType == double.class || fieldType == Double.class) {
        return cursor.getDouble(columnIndex);
    } else if (fieldType == boolean.class || fieldType == Boolean.class) {
        return cursor.getInt(columnIndex) > 0;
    } else if (fieldType == byte[].class) {
        return cursor.getBlob(columnIndex);
    } else {
        throw new IllegalArgumentException("Unsupported field type: " + fieldType);
    }
}

