public List<Class<?>> resolveBaseTypes(Class<?> type, List<Class<?>> baseTypes) {
    if (type.isPrimitive()) {
        baseTypes.add(type);
        return baseTypes;
    }

    if (type.equals(Boolean.class) ||
        type.equals(Byte.class) ||
        type.equals(Short.class) ||
        type.equals(Integer.class) ||
        type.equals(Long.class) ||
        type.equals(Float.class) ||
        type.equals(Double.class) ||
        type.equals(Character.class)) {
        baseTypes.add(type);
    } else if (type.isArray()) {
        baseTypes = resolveBaseTypes(type.getComponentType(), baseTypes);
    } else if (Collection.class.isAssignableFrom(type)) {
        ParameterizedType parameterizedType = (ParameterizedType) type.getGenericSuperclass();

        if (parameterizedType != null) {
            for (Type argumentType : parameterizedType.getActualTypeArguments()) {
                if (argumentType instanceof Class) {
                    baseTypes = resolveBaseTypes((Class<?>) argumentType, baseTypes);
                }
            }
        }
    } else {
        Field[] fields = type.getDeclaredFields();

        for (Field field : fields) {
            baseTypes = resolveBaseTypes(field.getType(), baseTypes);
        }
    }

    return baseTypes;
}

