import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.file.Files;
import java.util.Map;

public class FilePoster {
    public static void postFile(String url, Map<String, String> headers, File file, StringBuilder result) throws IOException {
        HttpURLConnection conn = null;
        OutputStream os = null;

        try {
            conn = (HttpURLConnection) new URL(url).openConnection();
            conn.setRequestMethod("POST");
            conn.setUseCaches(false);
            conn.setDoOutput(true);

            // Set custom headers
            for (Map.Entry<String, String> header : headers.entrySet()) {
                conn.setRequestProperty(header.getKey(), header.getValue());
            }

            os = conn.getOutputStream();
            os.write(Files.readAllBytes(file.toPath()));
            os.flush();
            os.close();

            // Get response
            int responseCode = conn.getResponseCode();

            if (result != null) {
                result.append(responseCode).append(" ").append(conn.getResponseMessage());
            }
        } finally {
            if (os != null) {
                os.close();
            }
            if (conn != null) {
                conn.disconnect();
            }
        }
    }
}

