    private WorkspaceModelResolver workspaceResolver;

    public DependencyResolver(String localRepositoryPath, List<RemoteRepository> repositories) {
        this.repositories = repositories;
        repositorySystem = RepositorySystemFactory.newRepositorySystem();
        session = newSession(localRepositoryPath);
        workspaceResolver = new WorkspaceModelResolver();
    }

    public List<Dependency> resolve(String groupId, String artifactId, String version, String scope) {
        Artifact artifact = new DefaultArtifact(groupId, artifactId, null, "jar", version);
        DependencyNode rootNode = collectDependencies(artifact, scope);
        return extractDependencies(rootNode);
    }

    private DependencyNode collectDependencies(Artifact artifact, String scope) {
        DefaultRepositorySystemSession session = new DefaultRepositorySystemSession(this.session);
        ArtifactDescriptorResult descriptorResult = getArtifactDescriptorResult(artifact, session);
        DependencyNode rootNode = descriptorResult.getDependencyTree();

        CollectRequest collectRequest = new CollectRequest();
        collectRequest.setRoot(new Dependency(artifact, scope));
        collectRequest.setRepositories(repositories);
        collectRequest.setDependencySelector(DependencyFilterUtils.classpathFilter(scope));

        DependencyResult dependencyResult = repositorySystem.resolveDependencies(session, collectRequest);
        rootNode = dependencyResult.getRoot();

        return rootNode;
    }

    private ArtifactDescriptorResult getArtifactDescriptorResult(Artifact artifact, RepositorySystemSession session) {
        ArtifactDescriptorRequest descriptorRequest = new ArtifactDescriptorRequest();
        descriptorRequest.setArtifact(artifact);
        descriptorRequest.setRepositories(repositories);

        try {
            return repositorySystem.readArtifactDescriptor(session, descriptorRequest);
        } catch (ArtifactDescriptorException | ArtifactResolutionException | VersionRangeResolutionException e) {
            throw new RuntimeException("Failed to read artifact descriptor for " + artifact, e);
        }
    }

    private List<Dependency> extractDependencies(DependencyNode rootNode) {
        DependencyFilter classpathFilter = DependencyFilterUtils.classpathFilter(JavaScopes.COMPILE);

        DependencyVisitor visitor = new DependencyVisitor() {
            @Override
            public boolean visitEnter(DependencyNode node) {
                if (classpathFilter.accept(node, Collections.emptyList())) {
                    return true;
                }
                return false;
            }

            @Override
            public boolean visitLeave(DependencyNode node) {
                return true;
            }
        };

        rootNode.accept(visitor);

        return visitor.getDependencies();
    }

    private RepositorySystemSession newSession(String localRepositoryPath) {
        DefaultRepositorySystemSession session = MavenRepositorySystemUtils.newSession();
        LocalRepository localRepository = new LocalRepository(localRepositoryPath);
        session.setLocalRepositoryManager(repositorySystem.newLocalRepositoryManager(session, localRepository));
        Settings settings = loadSettings();
        session.setWorkspaceReader(workspaces -> {
            Model model = new Model();
            model.setModelVersion("4.0.0");
            for (Object workspace : workspaces) {
                WorkspaceReader workspaceReader = (WorkspaceReader) workspace;
                MavenXpp3Reader reader = new MavenXpp3Reader();
                try {
                    model = reader.read(workspaceReader.getPom(workspaceReader.getGroupId(), workspaceReader.getArtifactId(), workspaceReader.getVersion()));
                } catch (IOException | XmlPullParserException | UnresolvableModelException e) {
                    e.printStackTrace();
                }
            }
            return model;
        });
        session.setWorkspaceResolver(workspaceResolver);
        return session;
    }

    private Settings loadSettings() {
        DefaultSettingsBuilderFactory factory = new DefaultSettingsBuilderFactory();
        SettingsBuilder builder;
        try {
            builder = factory.newInstance().newInstance(new DefaultSettingsBuildingRequest());
            DefaultSettingsBuildingRequest request = new DefaultSettingsBuildingRequest();
            request.setSystemProperties(System.getProperties());
            return builder.build(request).getEffectiveSettings();
        } catch (SettingsBuildingException e) {
            throw new RuntimeException("Failed to load settings", e);
        }
    }

}

