import com.google.protobuf.Descriptors;
import com.google.protobuf.DynamicMessage;
import java.util.Map;
import java.util.Objects;

public byte[] serializeToProtobufMessage(Record record, Descriptors.Descriptor desc, Map<Descriptors.Descriptor, Map<Descriptors.FieldDescriptor, Object>> messageTypeToExtensionMap, Map<Descriptors.FieldDescriptor, Object> defaultValueMap) throws DataGeneratorException {
    Objects.requireNonNull(record);
    Objects.requireNonNull(desc);
    Objects.requireNonNull(messageTypeToExtensionMap);
    Objects.requireNonNull(defaultValueMap);

    try {
        DynamicMessage.Builder builder = DynamicMessage.newBuilder(desc);

        // set fields from record to builder
        for (Map.Entry<String, Object> entry : record.getFields().entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            Descriptors.FieldDescriptor fieldDescriptor = desc.findFieldByName(key);
            if (fieldDescriptor == null) {
                // check if field can be treated as proto3 unknown field
                if (messageTypeToExtensionMap.containsKey(desc)) {
                    Map<Descriptors.FieldDescriptor, Object> extensionMap = messageTypeToExtensionMap.get(desc);
                    if (extensionMap.containsKey(fieldDescriptor)) {
                        builder.setUnknownFields(builder.getUnknownFields().addField(fieldDescriptor.getNumber(), fieldDescriptor.getJavaType(), value));
                    } else {
                        throw new DataGeneratorException("Field '" + key + "' is not found in descriptor or extension map for record");
                    }
                } else {
                    throw new DataGeneratorException("Field '" + key + "' is not found in descriptor for record");
                }
            } else {
                builder.setField(fieldDescriptor, value);
            }
        }

        // set default values for unset fields
        for (Descriptors.FieldDescriptor fieldDescriptor : desc.getFields()) {
            if (!record.getFields().containsKey(fieldDescriptor.getName()) && !builder.hasField(fieldDescriptor)) {
                if (defaultValueMap.containsKey(fieldDescriptor)) {
                    builder.setField(fieldDescriptor, defaultValueMap.get(fieldDescriptor));
                } else if (fieldDescriptor.isRepeated() || fieldDescriptor.getJavaType() == Descriptors.FieldDescriptor.JavaType.ENUM) {
                    // proto3 uses empty list for repeated fields and 0 for numeric fields
                    builder.setField(fieldDescriptor, fieldDescriptor.getDefaultValue());
                } else {
                    // use null for nullable fields
                    builder.setField(fieldDescriptor, null);
                }
            }
        }

        return builder.build().toByteArray();
    } catch (Exception e) {
        throw new DataGeneratorException("Unable to serialize record to protobuf message: " + e.getMessage(), e);
    }
}

