public static Set<String> computeNegativeBackbone(List<String> formulas, Set<String> variables) {
    Solver solver = SolverFactory.newDefault();
    solver.setTimeout(3600); // 1 hour timeout
    solver.newVar(variables.size());
    solver.setDBSimplificationAllowed(true);

    for (String formula : formulas) {
        try {
            Formula parsedFormula = Parser.parse(formula);
            solver.addClause(parsedFormula.posLits(), parsedFormula.negLits());
        } catch (ParseException e) {
            System.err.println("Failed to parse formula: " + formula);
            return null;
        }
    }

    Set<String> negativeBackbone = new HashSet<>();
    try {
        solver.newVar();
        solver.addClause();
        for (String variable : variables) {
            int varIndex = toVarIndex(variable);
            int valueIndex = solver.get(vkLit(new Var(varIndex, false)));

            // Skip variables that have no assignments or are always true
            if (valueIndex == -1 || valueIndex == 1) {
                continue;
            }

            solver.newVar();
            solver.addClause(vkLit(new Var(varIndex, !solver.modelValue(varIndex))));
            if (solver.isSatisfiable()) {
                negativeBackbone.add(variable);
            }
        }
    } catch (ContradictionException e) {
        return null;
    }

    return negativeBackbone;
}

// Method to convert variable names to indices
private static int toVarIndex(String name) {
    return Integer.parseInt(name.substring(1));
}

