public Pair<VocabCache<VocabWord>, GloveWeightLookupTable> train(JavaRDD<String> rdd) throws Exception {
	// Initialize vocab and weights
    VocabCache<VocabWord> vocab = new VocabCache<>();
    GloveWeightLookupTable weights = new GloveWeightLookupTable();

    // Tokenize the RDD
    JavaRDD<List<String>> tokenizedRDD = rdd.map(line -> tokenize(line));

    // Build the vocabulary
    vocab.buildVocab(tokenizedRDD.collect());

    // Initialize weights
    weights.initWeights(vocab);

    // Build co-occurrence matrix
    JavaRDD<CoOccurrence> coOccurrences = buildCoOccurrences(tokenizedRDD, vocab);

    // Train the model
    trainModel(coOccurrences, weights);

    // Return the vocab and weights
    return new Pair<>(vocab, weights);
}

private List<String> tokenize(String line) {
    // Tokenize the line into words
    return Arrays.asList(line.split("\\s+"));
}

private JavaRDD<CoOccurrence> buildCoOccurrences(JavaRDD<List<String>> tokenizedRDD, VocabCache<VocabWord> vocab) {
    // Build co-occurrence matrix from tokenized RDD
    return tokenizedRDD.flatMap(tokens -> {
        List<CoOccurrence> coOccurrences = new ArrayList<>();
        for (int i = 0; i < tokens.size(); i++) {
            for (int j = i + 1; j < tokens.size() && j <= i + WINDOW_SIZE; j++) {
                VocabWord wordI = vocab.wordFor(tokens.get(i));
                VocabWord wordJ = vocab.wordFor(tokens.get(j));
                if (wordI != null && wordJ != null) {
                    coOccurrences.add(new CoOccurrence(wordI.getIndex(), wordJ.getIndex(), 1.0));
                }
            }
        }
        return coOccurrences.iterator();
    });
}

private void trainModel(JavaRDD<CoOccurrence> coOccurrences, GloveWeightLookupTable weights) {
    // Train the model using the co-occurrence matrix and weights
    coOccurrences.foreachPartition(partition -> {
        while (partition.hasNext()) {
            CoOccurrence coOccurrence = partition.next();
            weights.updateWeights(coOccurrence);
        }
    });
}

