public class CycleBasis {

    public List<Set<Integer>> getConnectedComponents(List<Set<Integer>> cycles) {
        List<Set<Integer>> connected = new ArrayList<>();
        Set<Set<Integer>> circuits = new HashSet<>();
        for (Set<Integer> cycle : cycles) {
            boolean added = false;
            for (Set<Integer> circuit : circuits) {
                if (containsAllEdges(cycle, circuit)) {
                    circuit.addAll(cycle);
                    added = true;
                    break;
                }
            }
            if (!added) {
                Set<Integer> newCircuit = new HashSet<>(cycle);
                circuits.add(newCircuit);
            }
        }
        for (Set<Integer> circuit : circuits) {
            connected.add(getCyclesInCircuit(circuit, cycles));
        }
        return connected;
    }

    private boolean containsAllEdges(Set<Integer> cycle, Set<Integer> circuit) {
        for (Integer edge : cycle) {
            if (!circuit.contains(edge)) {
                return false;
            }
        }
        return true;
    }

    private Set<Integer> getCyclesInCircuit(Set<Integer> circuit, List<Set<Integer>> cycles) {
        Set<Integer> result = new HashSet<>();
        for (Set<Integer> cycle : cycles) {
            for (Integer edge : cycle) {
                if (circuit.contains(edge)) {
                    result.add(edge);
                    break;
                }
            }
        }
        return result;
    }
}

