import java.awt.geom.Point2D;

public static Circle computeBoundingCircle(List<Point2D> geometry) {
    double minX = Double.POSITIVE_INFINITY;
    double minY = Double.POSITIVE_INFINITY;
    double maxX = Double.NEGATIVE_INFINITY;
    double maxY = Double.NEGATIVE_INFINITY;

    // Determine the minimum and maximum coordinates of the geometry
    for (Point2D point : geometry) {
        if (point.getX() < minX) {
            minX = point.getX();
        }
        if (point.getY() < minY) {
            minY = point.getY();
        }
        if (point.getX() > maxX) {
            maxX = point.getX();
        }
        if (point.getY() > maxY) {
            maxY = point.getY();
        }
    }

    // Calculate the center and the radius of the bounding circle
    double centerX = (minX + maxX) / 2.0;
    double centerY = (minY + maxY) / 2.0;
    double radius = Math.sqrt(Math.pow(maxX - centerX, 2) + Math.pow(maxY - centerY, 2));

    return new Circle(centerX, centerY, radius);
}

public static class Circle {
    private double x, y, r;

    public Circle(double x, double y, double r) {
        this.x = x;
        this.y = y;
        this.r = r;
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public double getRadius() {
        return r;
    }
}

