    Map<String, Map<String, Double>> transitions = new HashMap<>();
    Map<String, Double> emissions = new HashMap<>();

    // Define transitions
    transitions.put("B", new HashMap<>());
    transitions.get("B").put("I", 0.5);
    transitions.get("B").put("O", 0.5);
    transitions.put("I", new HashMap<>());
    transitions.get("I").put("I", 0.4);
    transitions.get("I").put("O", 0.6);
    transitions.put("O", new HashMap<>());
    transitions.get("O").put("B", 0.3);
    transitions.get("O").put("O", 0.7);

    // Define emissions
    emissions.put("B", 0.1);
    emissions.put("I", 0.2);
    emissions.put("O", 0.7);

    // Evaluate the acronym based on transitions and emissions
    String[] tokens = acronym.getTokens();
    double probability = 1.0;
    String previousTag = "O"; // Start with 'O' tag

    for (String token : tokens) {
        // Calculate transition probability
        double transitionProb = transitions.get(previousTag).getOrDefault(token, 0.0);
        probability *= transitionProb;

        // Calculate emission probability
        double emissionProb = emissions.getOrDefault(token, 0.0);
        probability *= emissionProb;

        // Update previous tag
        previousTag = token;
    }

    // Set the probability of the acronym
    acronym.setProbability(probability);
}

