public static Frame merge(final Frame leftFrame, final Frame riteFrame, final int leftCols[], final int riteCols[], boolean allLeft, int[][] id_maps, int[] ascendingL, int[] ascendingR) {
	// Initialize the result frame
    Frame resultFrame = new Frame();
    // Assuming Frame has a method to add columns
    for (int col : leftCols) {
        resultFrame.addColumn(leftFrame.getColumn(col));
    }
    for (int col : riteCols) {
        resultFrame.addColumn(riteFrame.getColumn(col));
    }

    // Merge logic
    int leftIndex = 0;
    int rightIndex = 0;
    int leftSize = leftFrame.getRowCount();
    int rightSize = riteFrame.getRowCount();

    while (leftIndex < leftSize && rightIndex < rightSize) {
        int comparison = compareRows(leftFrame, riteFrame, leftIndex, rightIndex, leftCols, riteCols, ascendingL, ascendingR);
        if (comparison < 0) {
            if (allLeft) {
                resultFrame.addRow(leftFrame.getRow(leftIndex));
            }
            leftIndex++;
        } else if (comparison > 0) {
            rightIndex++;
        } else {
            // Rows match, add both rows to the result frame
            resultFrame.addRow(leftFrame.getRow(leftIndex));
            resultFrame.addRow(riteFrame.getRow(rightIndex));
            leftIndex++;
            rightIndex++;
        }
    }

    // Add remaining rows from leftFrame if allLeft is true
    if (allLeft) {
        while (leftIndex < leftSize) {
            resultFrame.addRow(leftFrame.getRow(leftIndex));
            leftIndex++;
        }
    }

    return resultFrame;
}

