public static String getMixedIP(String ip) {
  String[] blocks = ip.split(":");
  int emptyCount = 0;
  for (String block : blocks) {
    if (block.isEmpty()) {
      emptyCount++;
    }
  }
  if (emptyCount > 1) {
    StringBuilder sb = new StringBuilder();
    int lastEmptyIndex = -1;
    for (int i = 0; i < blocks.length; i++) {
      if (blocks[i].isEmpty()) {
        if (i == 0 || i == blocks.length - 1 || i - lastEmptyIndex > 1) {
          sb.append(":");
        }
        lastEmptyIndex = i;
      } else {
        sb.append(blocks[i]).append(":");
      }
    }
    sb.setLength(sb.length() - 1);
    return sb.toString();
  }
  int ipv4BlockIndex = -1;
  for (int i = 0; i < blocks.length; i++) {
    if (blocks[i].contains(".")) {
      ipv4BlockIndex = i;
      break;
    }
  }
  if (ipv4BlockIndex == -1) {
    return ip;
  }
  int ipv6BlockCount = 8 - (blocks.length - 1 - ipv4BlockIndex);
  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < ipv4BlockIndex; i++) {
    sb.append(blocks[i]).append(":");
  }
  String[] ipv4Blocks = blocks[ipv4BlockIndex].split("\\.");
  for (int i = 0; i < ipv4Blocks.length; i++) {
    sb.append(String.format("%x", Integer.parseInt(ipv4Blocks[i]))).append(":");
  }
  for (int i = 0; i < ipv6BlockCount; i++) {
    sb.append("0:").toString();
  }
  for (int i = ipv4BlockIndex + 1; i < blocks.length; i++) {
    sb.append(blocks[i]).append(":");
  }
  sb.setLength(sb.length() - 1);
  return sb.toString();
}

