public List<Tile> computeTiles(List<Point> points) {
    List<Tile> tiles = new ArrayList<>();

    // Compute the bounding box of the list of points
    BoundingBox boundingBox = computeBoundingBox(points);

    // Compute the tiles overlapping the bounding box
    int minZoomLevel = 0;
    int maxZoomLevel = 20;
    for (int zoomLevel = minZoomLevel; zoomLevel <= maxZoomLevel; zoomLevel++) {
        List<Tile> overlappingTiles = computeOverlappingTiles(boundingBox, zoomLevel);
        tiles.addAll(overlappingTiles);
    }

    // Sort the tiles by ascending zoom level
    Collections.sort(tiles, new Comparator<Tile>() {
        @Override
        public int compare(Tile tile1, Tile tile2) {
            return Integer.compare(tile1.getZoomLevel(), tile2.getZoomLevel());
        }
    });

    return tiles;
}

private BoundingBox computeBoundingBox(List<Point> points) {
    double minLatitude = Double.POSITIVE_INFINITY;
    double maxLatitude = Double.NEGATIVE_INFINITY;
    double minLongitude = Double.POSITIVE_INFINITY;
    double maxLongitude = Double.NEGATIVE_INFINITY;

    for (Point point : points) {
        double latitude = point.getLatitude();
        double longitude = point.getLongitude();
        if (latitude < minLatitude) {
            minLatitude = latitude;
        }
        if (latitude > maxLatitude) {
            maxLatitude = latitude;
        }
        if (longitude < minLongitude) {
            minLongitude = longitude;
        }
        if (longitude > maxLongitude) {
            maxLongitude = longitude;
        }
    }

    return new BoundingBox(minLatitude, maxLatitude, minLongitude, maxLongitude);
}

private List<Tile> computeOverlappingTiles(BoundingBox boundingBox, int zoomLevel) {
    List<Tile> overlappingTiles = new ArrayList<>();

    Tile topLeftTile = fromCoordinatesToTile(boundingBox.getMaxLatitude(), boundingBox.getMinLongitude(), zoomLevel);
    Tile bottomRightTile = fromCoordinatesToTile(boundingBox.getMinLatitude(), boundingBox.getMaxLongitude(), zoomLevel);

    for (int x = topLeftTile.getX(); x <= bottomRightTile.getX(); x++) {
        for (int y = topLeftTile.getY(); y <= bottomRightTile.getY(); y++) {
            Tile tile = new Tile(x, y, zoomLevel);
            overlappingTiles.add(tile);
        }
    }

    return overlappingTiles;
}

private Tile fromCoordinatesToTile(double latitude, double longitude, int zoomLevel) {
    int x = (int) Math.floor((longitude + 180.0) / 360.0 * (1 << zoomLevel));
    int y = (int) Math.floor((1.0 - Math.log(Math.tan(Math.toRadians(latitude)) + 1.0 / Math.cos(Math.toRadians(latitude))) / Math.PI) / 2.0 * (1 << zoomLevel));
    return new Tile(x, y, zoomLevel);
}

