import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.AdaptiveRecvByteBufAllocator;
import io.netty.channel.Channel;
import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelOption;
import io.netty.channel.EventLoopGroup;
import io.netty.channel.epoll.EpollChannelOption;
import io.netty.channel.epoll.EpollMode;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioServerSocketChannel;
import io.netty.channel.socket.nio.NioSocketChannel;

public class TcpServer {

    private final int port;
    private final EventLoopGroup eventLoopGroup;
    private final Class<? extends Channel> channelClass;

    public TcpServer(int port, EventLoopGroup eventLoopGroup, Class<? extends Channel> channelClass) {
        this.port = port;
        this.eventLoopGroup = eventLoopGroup;
        this.channelClass = channelClass;
    }

    public ChannelFuture createServer() {
        ServerBootstrap b = new ServerBootstrap();
        b.group(eventLoopGroup)
         .channel(channelClass)
         .option(ChannelOption.SO_BACKLOG, 1024)
         .option(ChannelOption.RCVBUF_ALLOCATOR, new AdaptiveRecvByteBufAllocator())
         .childOption(ChannelOption.SO_REUSEADDR, true)
         .childOption(ChannelOption.TCP_NODELAY, true)
         .childOption(ChannelOption.SO_KEEPALIVE, true);

        if (channelClass.equals(NioServerSocketChannel.class)) {
            b.childOption(EpollChannelOption.SO_REUSEPORT, true);
        } else if (channelClass.equals(NioSocketChannel.class)) {
            b.option(EpollChannelOption.TCP_FASTOPEN_CONNECT, true);
        }

        return b.bind(port);
    }

    public static void main(String[] args) {
        int port = 8080; // for example
        EventLoopGroup group = new NioEventLoopGroup(); // you can use another group instead
        TcpServer server = new TcpServer(port, group, NioServerSocketChannel.class);
        server.createServer();
    }
}

