public Set<String> findEssentialRings(Graph graph) {
    Set<String> essentialRings = new HashSet<>();

    // Find all rings in the graph
    List<String> allRings = new ArrayList<>();
    for (int i = 0; i < graph.getVertexCount(); i++) {
        List<List<DefaultEdge>> cycles = new ArrayList<>();
        List<DefaultEdge> visitedEdges = new ArrayList<>();
        Graphs.findCycles(graph, graph.getVertex(i), cycles, visitedEdges);
        for (List<DefaultEdge> cycle : cycles) {
            StringBuilder sb = new StringBuilder();
            for (DefaultEdge edge : cycle) {
                sb.append(graph.getEdgeTarget(edge));
            }
            allRings.add(sb.toString());
        }
    }

    // Find the essential rings
    Map<String, Integer> ringCount = new HashMap<>();
    for (String ring : allRings) {
        for (int i = 0; i < ring.length(); i++) {
            String rotatedRing = ring.substring(i) + ring.substring(0, i);
            int count = ringCount.getOrDefault(rotatedRing, 0);
            ringCount.put(rotatedRing, count + 1);
        }
    }
    for (Map.Entry<String, Integer> entry : ringCount.entrySet()) {
        if (entry.getValue() == allRings.size()) {
            essentialRings.add(entry.getKey());
        }
    }

    return essentialRings;
}

