import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import org.w3c.dom.Document;

public static Document callMethodAndReturnDOM(String method, List<Object> paramPairs) throws Exception {
    // Create a URL connection to the server with the given method name
    URL url = new URL("http://example.com/server/" + method);
    URLConnection conn = url.openConnection();
    conn.setDoOutput(true);

    // Create an XML request body with the given parameters
    DocumentBuilderFactory docFactory = DocumentBuilderFactory.newInstance();
    DocumentBuilder docBuilder = docFactory.newDocumentBuilder();
    Document requestDoc = docBuilder.newDocument();
    Element rootElement = requestDoc.createElement("methodCall");
    requestDoc.appendChild(rootElement);
    Element methodName = requestDoc.createElement("methodName");
    methodName.appendChild(requestDoc.createTextNode(method));
    rootElement.appendChild(methodName);
    Element paramsElement = requestDoc.createElement("params");
    rootElement.appendChild(paramsElement);

    for (Object param : paramPairs) {
        Element paramElement = requestDoc.createElement("param");
        paramsElement.appendChild(paramElement);
        Element valueElement = requestDoc.createElement("value");
        paramElement.appendChild(valueElement);

        if (param instanceof String) {
            Element stringElement = requestDoc.createElement("string");
            stringElement.appendChild(requestDoc.createTextNode((String)param));
            valueElement.appendChild(stringElement);
        } else if (param instanceof Integer) {
            Element intElement = requestDoc.createElement("int");
            intElement.appendChild(requestDoc.createTextNode(String.valueOf((Integer)param)));
            valueElement.appendChild(intElement);
        } else if (param instanceof Double) {
            Element doubleElement = requestDoc.createElement("double");
            doubleElement.appendChild(requestDoc.createTextNode(String.valueOf((Double)param)));
            valueElement.appendChild(doubleElement);
        } else if (param instanceof Boolean) {
            Element booleanElement = requestDoc.createElement("boolean");
            booleanElement.appendChild(requestDoc.createTextNode(String.valueOf((Boolean)param)));
            valueElement.appendChild(booleanElement);
        }
    }

    // Send the XML request and read the response from the server
    OutputStreamWriter writer = new OutputStreamWriter(conn.getOutputStream());
    writer.write(xmlToString(requestDoc));
    writer.flush();
    writer.close();
    BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
    StringBuilder responseBuilder = new StringBuilder();
    String line;
    while ((line = reader.readLine()) != null) {
        responseBuilder.append(line);
    }
    reader.close();

    // Parse the response into a DOM document and return it
    Document responseDoc = docBuilder.parse(new InputSource(new ByteArrayInputStream(responseBuilder.toString().getBytes("utf-8"))));
    return responseDoc;
}

private static String xmlToString(Node node) throws Exception {
    StringWriter writer = new StringWriter();
    TransformerFactory tf = TransformerFactory.newInstance();
    Transformer transformer = tf.newTransformer();
    transformer.setOutputProperty(OutputKeys.OMIT_XML_DECLARATION, "yes");
    transformer.transform(new DOMSource(node), new StreamResult(writer));
    return writer.getBuffer().toString();
}

