public class TokenManager {
    private Map<ManagedObject, Token> tokenMap = new HashMap<>();

    public Token allocate(ManagedObject objectToStore) throws ObjectManagerException {
        if (objectToStore == null) {
            throw new ObjectManagerException("ManagedObject cannot be null");
        }

        if (tokenMap.containsKey(objectToStore)) {
            throw new ObjectManagerException("ManagedObject already has a token");
        }

        Token newToken = new Token();
        tokenMap.put(objectToStore, newToken);

        return newToken;
    }
}

