import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.List;

public class HtmlReportGenerator {

    public void generate(List<File> reportInputDataDirs, File reportOutputDir) {
        for (File dir : reportInputDataDirs) {
            if (dir.isDirectory()) {
                for (File file : dir.listFiles()) {
                    if (file.isFile()) {
                        String fileName = file.getName();
                        String htmlFileName = fileName.substring(0, fileName.lastIndexOf('.')) + ".html";
                        File htmlFile = new File(reportOutputDir, htmlFileName);
                        try {
                            FileWriter writer = new FileWriter(htmlFile);
                            writer.write("<html><body>" + fileName + "</body></html>");
                            writer.close();
                        } catch (IOException e) {
                            e.printStackTrace();
                        }
                    }
                }
            }
        }
    }
}

