public void generate(List<File> reportInputDataDirs, File reportOutputDir) throws IllegalDataStructureException, IllegalTestScriptException {
	// Validate input directories
    for (File dir : reportInputDataDirs) {
        if (!dir.isDirectory()) {
            throw new IllegalDataStructureException("Input directory " + dir.getAbsolutePath() + " is not a directory.");
        }
    }

    // Validate output directory
    if (!reportOutputDir.isDirectory()) {
        throw new IllegalDataStructureException("Output directory " + reportOutputDir.getAbsolutePath() + " is not a directory.");
    }

    // Process each input directory
    for (File inputDataDir : reportInputDataDirs) {
        processInputDirectory(inputDataDir, reportOutputDir);
    }
}

private void processInputDirectory(File inputDataDir, File reportOutputDir) throws IllegalDataStructureException, IllegalTestScriptException {
    // List all files in the input directory
    File[] files = inputDataDir.listFiles();
    if (files == null) {
        throw new IllegalDataStructureException("Failed to list files in directory " + inputDataDir.getAbsolutePath());
    }

    // Process each file in the input directory
    for (File file : files) {
        if (file.isFile() && file.getName().endsWith(".html")) {
            processHtmlFile(file, reportOutputDir);
        }
    }
