public void copyIndex(String srcIndexName, String dstIndexName, List<String> scopes) {
    RestHighLevelClient client = new RestHighLevelClient(
                RestClient.builder(new HttpHost("localhost", 9200, "http")));

    try {
        // Check if the destination index already exists
        GetIndexRequest getIndexRequest = new GetIndexRequest(dstIndexName);
        boolean exists = client.indices().exists(getIndexRequest, RequestOptions.DEFAULT);

        // If the destination index already exists, delete it
        if (exists) {
            DeleteIndexRequest deleteIndexRequest = new DeleteIndexRequest(dstIndexName);
            client.indices().delete(deleteIndexRequest, RequestOptions.DEFAULT);
        }

        // Copy the source index to the destination index
        CopyIndexRequest copyIndexRequest = new CopyIndexRequest(srcIndexName, dstIndexName);
        copyIndexRequest.setSettings(Settings.builder()
                                .put("index.number_of_shards", 1)
                                .put("index.number_of_replicas", 0));

        // Set the scopes to copy
        copyIndexRequest.setQueryHint("_name:" + String.join(",", scopes));

        // Execute the copy request
        IndicesClient indicesClient = client.indices();
        CopyIndexResponse copyIndexResponse = indicesClient.copy(copyIndexRequest, RequestOptions.DEFAULT);

        // Print the response
        System.out.println(copyIndexResponse.toString());

    } catch (IOException e) {
        e.printStackTrace();
    }
}

