import java.io.*;
import java.util.zip.*;

public static void removeEntryFromZip(String zipFile, String path) throws IOException {
    File file = new File(zipFile);

    // create a temporary file
    File tempFile = File.createTempFile(file.getName(), null);

    // open the zip file and the corresponding output stream
    try (ZipInputStream zis = new ZipInputStream(new FileInputStream(file)); 
         ZipOutputStream zos = new ZipOutputStream(new FileOutputStream(tempFile))) {

        // iterate over the entries in the zip file
        ZipEntry entry = zis.getNextEntry();
        while (entry != null) {
            // if the entry is not the one to remove, copy it to the output stream
            if (!entry.getName().equals(path)) {
                zos.putNextEntry(new ZipEntry(entry.getName()));
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = zis.read(buffer)) > 0) {
                    zos.write(buffer, 0, bytesRead);
                }
                zos.closeEntry();
            }
            entry = zis.getNextEntry();
        }
    }

    // delete the original file and rename the temporary file to the original name
    if (file.delete()) {
        tempFile.renameTo(file);
    } else {
        throw new IOException("Failed to delete the original file");
    }
}

