public static String locrian(String note) {
    if (!note.toLowerCase().startsWith("loc")) {
        return "Invalid input";
    }
    // set the root note and the mode
    String root = note.substring(0, 3);
    String mode = note.substring(3);

    // apply the locrian mode pattern for flat 2nd and 5th
    String flatSecond = Note.getHalfStepLower(Note.getNoteFrom(root + "b"));
    String flatFifth = Note.getHalfStepLower(Note.getNoteFrom(root + "b", 5));

    // return the notes in the minor scale with flat 2nd and 5th
    return root + " " + flatSecond + " " + "m" + " " + " " + flatFifth + " " + "dim";
}

public static class Note {
    // mapping of note letters to half steps
    static Map<Character, Integer> noteHalfSteps = new HashMap<>();

    static {
        noteHalfSteps.put('C', 0);
        noteHalfSteps.put('D', 2);
        noteHalfSteps.put('E', 4);
        noteHalfSteps.put('F', 5);
        noteHalfSteps.put('G', 7);
        noteHalfSteps.put('A', 9);
        noteHalfSteps.put('B', 11);
    }

    public static int getHalfStepsFrom(char noteLetter) {
        return noteHalfSteps.get(noteLetter);
    }

    public static String getHalfStepLower(String note) {
        char noteLetter = note.charAt(0);
        int octave = Integer.parseInt(note.substring(1));
        int halfSteps = getHalfStepsFrom(noteLetter);
        // adjust for flat and wrap around for A or B flat
        if (note.charAt(1) == 'b') {
            halfSteps--;
            if (noteLetter == 'A' || noteLetter == 'B') {
                halfSteps += 12;
            }
        }
        // adjust for octave
        halfSteps += (octave - 1) * 12;
        // wrap around to get a valid note
        halfSteps = (halfSteps + 120) % 12;
        return String.format("%c%d", getKeyWithNoteHalfSteps(halfSteps), octave);
    }

    public static String getNoteFrom(String note, int steps) {
        char noteLetter = note.charAt(0);
        int octave = Integer.parseInt(note.substring(1));
        int halfSteps = getHalfStepsFrom(noteLetter);
        // adjust for flat and wrap around
        if (note.charAt(1) == 'b') {
            halfSteps--;
            if (noteLetter == 'A' || noteLetter == 'B') {
                halfSteps += 12;
            }
        }
        // adjust for steps
        halfSteps += steps;
        // adjust octave
        if (halfSteps < 0) {
            halfSteps += 12;
            octave--;
        } else if (halfSteps > 11) {
            halfSteps -= 12;
            octave++;
        }
        return String.format("%c%d", getKeyWithNoteHalfSteps(halfSteps), octave);
    }

    public static char getKeyWithNoteHalfSteps(int noteHalfSteps) {
        for (Character c : noteHalfSteps.keySet()) {
            if (noteHalfSteps.get(c) == noteHalfSteps) {
                return c;
            }
        }
        return ' ';
    }

    public static String getNoteFrom(String note) {
        return note.substring(0, 2);
    }
}

