public class AttributeOverrideGenerator {

    public static Collection<AttributeOverride> generateAttributeOverrides(Class<?> type) {
        Collection<AttributeOverride> attributeOverrides = new ArrayList<>();

        for (Field field : type.getDeclaredFields()) {
            Annotation[] annotations = field.getDeclaredAnnotations();

            for (Annotation annotation : annotations) {
                if (annotation instanceof Column) {
                    Column column = (Column) annotation;

                    if (!column.nullable()) {
