    public static <T, K> ListMultimap<K, T> groupByParallel(Iterable<T> iterable,
                                                            Function<? super T, ? extends K> function) {
        ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        ConcurrentHashMultiset<K> keys = ConcurrentHashMultiset.create();

        iterable.forEach(t -> {
            K key = function.apply(t);
            keys.add(key);
        });

        final ListMultimap<K, T> ret = Synchronized
                .listMultimap(Multimaps.newListMultimap(Maps.<K, Collection<T>>newHashMap(), ArrayList::new));

        final long maxBatchSize = Math.max(keys.rights().stream().mapToLong(AtomicInteger::intValue).max().getAsLong() / 100,
                100 * Runtime.getRuntime().availableProcessors());

        final Collection<K> rights = keys.rights();
        int start = 0, end = 0;

        for (K k : rights) {
            end += keys.count(k);
            if (end - start > maxBatchSize) {
                final int fStart = start, fEnd = end;
                executorService.submit(() -> {
                    for (K key : rights) {
                        if (keys.contains(key)) {
                            final Collection<T> values = Lists.<T>newArrayList();
                            Iterable<T> items = Iterables.filter(iterable, t -> function.apply(t).equals(key));
