public static void packIntegers(int[] in, int inpos, int[] out, int outpos, int bit) {
    int val = 0;
    int bitsLeft = bit;
    int mask = (1 << bit) - 1;

    for (int i = inpos; i < inpos + 32; i++) {
        val = (val << bit) | (in[i] & mask);
        bitsLeft += bit;

        while (bitsLeft >= 8) {
            bitsLeft -= 8;
            out[outpos++] = (val >> bitsLeft) & 0xFF;
        }
    }

