private void writeInt(int num, int[] outBlock, int offsetInBits) {
    int offset = offsetInBits / 32;
    int shift = 32 - (offsetInBits % 32) - 32;
    outBlock[offset] |= num << shift;
    if (shift < 0) {
        outBlock[offset + 1] |= num >> (32 + shift);
    }
}

