            boolean httpOnly = cookieObject.optBoolean("httpOnly", false);
            long maxAge = cookieObject.optLong("maxAge", 0);
            String comment = cookieObject.optString("comment", "");
            Cookie cookie = new Cookie(name, value);
            if (!domain.isEmpty()) {
                cookie.setDomain(domain);
            } else {
                cookie.setDomain(url.getHost());
            }
            if (!path.isEmpty()) {
                cookie.setPath(path);
            } else {
