	// Check if the JSON is something we know how to process
    if (verify == Verification.YES) {
        if (!json.has("version") || !json.has("type")) {
            throw new BadVersionException("JSON does not contain version or type information");
        }
        String version = json.getString("version");
        String type = json.getString("type");
        if (!version.equals("1.0") || !type.equals(typeOfObject.getSimpleName())) {
            throw new BadVersionException("JSON version or type mismatch");
        }
    }

    // Create an instance of the object
    T instance;
    try {
        instance = typeOfObject.getDeclaredConstructor().newInstance();
    } catch (InstantiationException | IllegalAccessException | NoSuchMethodException | InvocationTargetException e) {
        throw new IOException("Failed to create instance of " + typeOfObject.getName(), e);
    }

    // Set the data into the object
    for (String key : json.keySet()) {
        Field field;
        try {
            field = typeOfObject.getDeclaredField(key);
        } catch (NoSuchFieldException e) {
            // If the field does not exist, we can either ignore it or throw an exception
            // Here we choose to ignore it
            continue;
        }
        field.setAccessible(true);
        try {
            field.set(instance, convertValue(json.get(key), field.getType()));
        } catch (IllegalArgumentException | IllegalAccessException e) {
            throw new IOException("Failed to set field " + field.getName() + " in " + typeOfObject.getName(), e);
        }
    }

    return instance;
}

