    int inputWidth = inputs[0].length;
    int filterCount = (inputWidth - filterWidth) / stride + 1;

    // Initialize the outputs array with zeros
    double[][] outputs = new double[filterCount][filterCount];

    // Loop over each position that the filter can occupy
    for (int i = 0; i < filterCount; i++) {
        for (int j = 0; j < filterCount; j++) {

            // Loop over each element in the filter
            double sum = 0;
            for (int k = 0; k < filterHeight; k++) {
                for (int l = 0; l < filterWidth; l++) {

                    // Calculate the index in the input array
                    int x = i * stride + k;
                    int y = j * stride + l;

                    // Add the product of the filter and input values to the sum
                    sum += inputs[x][y] * filter[k][l];
                }
            }

            // Store the result in the outputs array
