import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public static byte[] encryptAndEncode(byte[] iv, byte[] message, String encoder) throws Exception {
    // set up encryption key and algorithm
    SecretKeySpec key = new SecretKeySpec("encryptionKey".getBytes(), "AES");
    Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");

    // initialize cipher with iv
    IvParameterSpec ivSpec = new IvParameterSpec(iv);
    cipher.init(Cipher.ENCRYPT_MODE, key, ivSpec);

    // encrypt data
    byte[] cipherText = cipher.doFinal(message);

    // encode cipher text based on encoder
    switch (encoder) {
        case "RAW":
            return cipherText;
        case "HEX":
            return Base64.getEncoder().encode(cipherText);
        default:
            throw new IllegalArgumentException("Invalid encoder provided");
    }
}

