import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public static final Duration parseDuration(ProjectFile file, TimeUnit defaultUnits, String value) {
    // Regular expression to match the duration string
    // This pattern matches a string that starts with a number, followed by a space,
    // followed by a string that represents a time unit (e.g., "ms", "s", "m", "h", "d")
    Pattern pattern = Pattern.compile("(\\d+)\\s*([a-zA-Z]+)");
    Matcher matcher = pattern.matcher(value);

    if (matcher.find()) {
        long number = Long.parseLong(matcher.group(1));
        String unit = matcher.group(2);

        // Convert the time unit to a TimeUnit instance
        TimeUnit timeUnit = TimeUnit.valueOf(unit.toUpperCase());

        // Convert the number and time unit to a Duration instance
        return Duration.of(number, timeUnit.toChronoUnit());
    } else {
        // If the input string does not match the pattern, return a Duration with zero value
        return Duration.ZERO;
    }
}

