import java.nio.charset.StandardCharsets;

public class FontSubsetter {

    public byte[] buildNewFile(String fontUrl) throws IOException {
        URL url = new URL(fontUrl);
        InputStream inputStream = url.openStream();

        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();

        byte[] buffer = new byte[1024];
        int length;
        while ((length = inputStream.read(buffer)) != -1) {
            outputStream.write(buffer, 0, length);
        }

        // Here you can add your subsetting logic
        // For example, let's say you want to keep only the first 100 bytes
        byte[] subset = outputStream.toByteArray();
        if (subset.length > 100) {
            subset = new String(subset, 0, 100, StandardCharsets.UTF_8).getBytes();
        }

        return subset;
    }
}

