public Schema flattenSchema(Schema schema, boolean flattenComplexTypes) {
    List<Schema.Field> fields = schema.getFields();
    List<Schema.Field> newFields = new ArrayList<>();
    for (Schema.Field field : fields) {
        Schema.Type fieldType = field.schema().getType();
        if (fieldType == Schema.Type.RECORD) {
            Schema nestedSchema = field.schema();
            List<Schema.Field> nestedFields = nestedSchema.getFields();
            for (Schema.Field nestedField : nestedFields) {
                String flattenedName = field.name() + "." + nestedField.name();
                Schema flattenedSchema = nestedField.schema();
                if (flattenComplexTypes && flattenedSchema.getType() == Schema.Type.RECORD) {
                    flattenedSchema = flattenSchema(flattenedSchema, true);
                }
                newFields.add(new Schema.Field(flattenedName, flattenedSchema, 
                    null, JsonProperties.NULL_VALUE));
            }
        } else if (fieldType == Schema.Type.ARRAY) {
            Schema arraySchema = field.schema().getElementType();
            if (flattenComplexTypes && arraySchema.getType() == Schema.Type.RECORD) {
                arraySchema = flattenSchema(arraySchema, true);
            }
            newFields.add(new Schema.Field(field.name(), 
                Schema.createArray(arraySchema), null, JsonProperties.NULL_VALUE));
        } else if (fieldType == Schema.Type.MAP) {
            Schema valueSchema = field.schema().getValueType();
            if (flattenComplexTypes && valueSchema.getType() == Schema.Type.RECORD) {
                valueSchema = flattenSchema(valueSchema, true);
            }
            newFields.add(new Schema.Field(field.name(), 
                Schema.createMap(valueSchema), null, JsonProperties.NULL_VALUE));
        } else {
            newFields.add(field);
        }
    }
    return Schema.createRecord(schema.getName(), null, schema.getNamespace(), 
        schema.isError(), newFields);
}

