import java.util.Timer;
import java.util.TimerTask;

public class MouseStationaryDelay {
    private Timer timer;
    private long delay;
    private boolean isStationary;

    private static final int DEFAULT_DELAY = 1000; // one second delay

    public MouseStationaryDelay() {
        this(DEFAULT_DELAY);
    }

    public MouseStationaryDelay(long delay) {
        this.delay = delay;
        timer = new Timer();
        isStationary = false;
    }

    public void start(Node node, EventHandler<MouseEvent> beginEventHandler, EventHandler<MouseEvent> endEventHandler) {
        if (node != null && beginEventHandler != null && endEventHandler != null) {
            stop(); // remove any previously installed delays
            node.setOnMouseEntered(event -> {
                if (!isStationary) {
                    isStationary = true;
                    timer.schedule(new TimerTask() {
                        @Override
                        public void run() {
                            Platform.runLater(() -> {
                                beginEventHandler.handle(event.copyFor(null, null));
                            });
                        }
                    }, delay);
                }
            });
            node.setOnMouseExited(event -> {
                if (isStationary) {
                    isStationary = false;
                    timer.cancel();
                    Platform.runLater(() -> {
                        endEventHandler.handle(event.copyFor(null, null));
                    });
                }
            });
        }
    }

    public void stop() {
        timer.cancel();
        isStationary = false;
    }
}

