public JPanel addCollapsiblePanel(String title, Component component) {
  JPanel panel = new JPanel();
  panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
  panel.setBorder(BorderFactory.createLineBorder(Color.GRAY));

  JLabel titleLabel = new JLabel(title);
  titleLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
  titleLabel.setFont(new Font("SansSerif", Font.BOLD, 14));
  titleLabel.setBorder(BorderFactory.createEmptyBorder(5, 10, 5, 0));
  panel.add(titleLabel);

  JButton toggleButton = new JButton("-");
  toggleButton.setAlignmentX(Component.RIGHT_ALIGNMENT);
  toggleButton.setMaximumSize(new Dimension(20, 20));
  toggleButton.setFocusable(false);
  toggleButton.addActionListener(e -> {
      if (component.isVisible()) {
          component.setVisible(false);
          toggleButton.setText("+");
      } else {
          component.setVisible(true);
          toggleButton.setText("-");
      }
  });
  JPanel headerPanel = new JPanel();
  headerPanel.setLayout(new BoxLayout(headerPanel, BoxLayout.X_AXIS));
  headerPanel.add(Box.createHorizontalGlue());
  headerPanel.add(toggleButton);
  headerPanel.setBorder(BorderFactory.createEmptyBorder(0, 0, 5, 5));
  panel.add(headerPanel);

  panel.add(component);
  component.setVisible(false);
  return panel;
}

