public static void includeGeneratedWebXml(String generatedXmlPath, String webAppXmlPath) throws IOException {
    StringBuilder webAppXmlContent = new StringBuilder();
    try (BufferedReader reader = new BufferedReader(new FileReader(webAppXmlPath))) {
        String line = reader.readLine();
        while (line != null) {
            webAppXmlContent.append(line).append(System.lineSeparator());
            line = reader.readLine();
        }
    }
    String generatedXmlContent = new String(Files.readAllBytes(Paths.get(generatedXmlPath)));
    int insertionIndex = webAppXmlContent.indexOf("</web-app>");
    if (insertionIndex < 0) {
        throw new IllegalArgumentException("The webapp's web.xml file is invalid");
    }
    webAppXmlContent.insert(insertionIndex, generatedXmlContent);
    try (BufferedWriter writer = new BufferedWriter(new FileWriter(webAppXmlPath))) {
        writer.write(webAppXmlContent.toString());
    }
}

