	final String iterableType = iterableEvent.getAttributeByName(new QName("type")).getValue();
    final Class<?> iterableClass = Class.forName(iterableType);
    final Collection<?> collection = (Collection<?>) iterableClass.getDeclaredConstructor().newInstance();
    final Iterator<?> iterator = iterable.getIterator();
    while (iterator.hasNext()) {
        final Object item = iterator.next();
        collection.add(item);
    }
    return collection;
}

