public static Type resolveType(Type type, Class<?> declaringType, Class<?> context) {
    if (type instanceof Class) {
        return type;
    } else if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Type[] resolvedTypeArguments = new Type[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            resolvedTypeArguments[i] = resolveType(actualTypeArguments[i], declaringType, context);
        }
        return ParameterizedTypeImpl.make(
                (Class<?>) resolveType(parameterizedType.getRawType(), declaringType, context),
                resolvedTypeArguments,
                parameterizedType.getOwnerType()
        );
    } else if (type instanceof GenericArrayType) {
        GenericArrayType genericArrayType = (GenericArrayType) type;
        return GenericArrayTypeImpl.createArrayType(resolveType(genericArrayType.getGenericComponentType(), declaringType, context));
    } else if (type instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        Type resolvedType = resolveTypeVariable(typeVariable, declaringType, context);
        return resolvedType != null ? resolvedType : typeVariable;
    } else if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        Type[] lowerBounds = wildcardType.getLowerBounds();
        Type[] upperBounds = wildcardType.getUpperBounds();
        if (lowerBounds.length == 1) {
            return capture(resolveType(lowerBounds[0], declaringType, context), Object.class, declaringType);
        } else if (upperBounds.length == 1) {
            return resolveType(upperBounds[0], declaringType, context);
        } else {
            return wildcardType;
        }
    } else {
        throw new IllegalArgumentException("Type must be a Class, ParameterizedType, GenericArrayType, TypeVariable, or WildcardType.");
    }
}

private static Type resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> declaringType, Class<?> context) {
    Class<?> declaringClass = typeVariable.getGenericDeclaration() instanceof Class ?
        (Class<?>) typeVariable.getGenericDeclaration() : declaringType;
    int index = Arrays.asList(declaringClass.getTypeParameters()).indexOf(typeVariable);
    Type resolvedType = context.getTypeParameters()[index];
    if (resolvedType instanceof TypeVariable<?>) {
        resolvedType = resolveTypeVariable((TypeVariable<?>) resolvedType, declaringType, context);
    }
    return resolvedType;
}

private static Type capture(Type type, Class<?> wildcard, Class<?> declaringType) {
    if (type instanceof Class<?>) {
        return type;
    }
    TypeVariable<?> capture = declaringType.getTypeParameters()[0];
    return WildcardTypeImpl.make(
            new Type[]{type},
            new Type[]{WildcardTypeImpl.makeLowerBounds(new Type[]{wildcard})},
            capture);
}

