public int[] determineExplicitLevels(int[] resultTypes) {
    int[] result = new int[resultTypes.length];
    for (int i = 0; i < resultTypes.length; i++) {
        int level = resultTypes[i] & 0x7F; // get the low 7 bits
        boolean isOverride = (resultTypes[i] & 0x80) != 0; // check if the high bit is set
        result[i] = isOverride ? (level | 0x80) : level; // set the high bit if it is an override
    }
    return result;
}

