private static byte[] processEmbeddings(byte[] resultTypes, byte paragraphEmbeddingLevel) {
    byte[] result = new byte[resultTypes.length];

    for (int i = 0; i < resultTypes.length; i++) {
        byte level = resultTypes[i];
        boolean isOverride = (level & 0x80) != 0;
        level &= 0x7F; // clear the high bit

        if (isOverride) {
            // handle override
            result[i] = (byte) (level | (paragraphEmbeddingLevel & 0x7F));
        } else {
            // handle embedding
            result[i] = (byte) (level | (paragraphEmbeddingLevel & 0x7F) | 0x80);
        }
    }

    return result;
}

