protected void findCoordinateAxes(NetcdfDataset ds) {
	// Check if the dataset contains the attribute "coordinates"
    if (ds.findGlobalAttribute("coordinates") != null) {
        // Retrieve the value of the "coordinates" attribute
        String coordinateNames = ds.findGlobalAttribute("coordinates").getStringValue();
        // Split the value into individual coordinate names
        String[] names = coordinateNames.split("\\s+");
        // Iterate over each coordinate name
        for (String name : names) {
            // Find the variable in the dataset that matches the coordinate name
            Variable coordinateVar = ds.findVariable(name);
            if (coordinateVar != null) {
                // Check if the variable is a coordinate axis
                if (coordinateVar.isCoordinateAxis()) {
                    // Add the coordinate axis to the list of coordinate axes
                    _CoordinateAxes.add(coordinateVar);
                }
            }
        }
    }
}

