public static String formatPhoneNumberRFC3966(String pphoneNumber) {
    String formattedNumber = "";
    int cursorPosition = -1;

    // check if cursor position exists in the input string
    if(pphoneNumber.contains("cp=")) {
        cursorPosition = pphoneNumber.indexOf("cp=") + 3;
        pphoneNumber = pphoneNumber.replaceAll("cp=[0-9]+", "");
    }

    // remove non-numeric characters from the input string
    pphoneNumber = pphoneNumber.replaceAll("[^0-9]", "");

    // check the length of the phone number and format it accordingly
    if(pphoneNumber.length() == 10) {
        formattedNumber = pphoneNumber.replaceFirst("(\\d{3})(\\d{3})(\\d+)", "tel:+1-$1-$2-$3");
    } else if(pphoneNumber.length() > 10) {
        formattedNumber = pphoneNumber.replaceFirst("(\\d{1})(\\d{3})(\\d{3})(\\d+)", "tel:+$1-$2-$3-$4");
    }

    // add cursor position to the formatted string
    if(cursorPosition > -1) {
        cursorPosition += 4; // adding 4 to account for the "tel:" prefix
        if(formattedNumber.contains("-")) {
            cursorPosition += formattedNumber.length() - formattedNumber.lastIndexOf("-") - 1;
        }
        formattedNumber += ";cp=" + cursorPosition;
    }

    return formattedNumber;
}

