import java.util.ArrayList;
import java.util.List;

public class WordComponents {

    public static List<String> getAllWordComponents(String word) {
        List<String> components = new ArrayList<>();
        String[] atomicComponents = word.split("\\|");
        int numComponents = atomicComponents.length;

        for (int i = 1; i < (1 << numComponents); i++) {
            String component = "";
            for (int j = 0; j < numComponents; j++) {
                if ((i & (1 << j)) > 0) {
                    component += atomicComponents[j];
                }
            }
            components.add(component);
        }
        return components;
    }
}

