    public static ParsedSql parseSqlStatement(final String sql) {
        List<String> namedParameters = new ArrayList<>();
        Matcher matcher = Pattern.compile(":[a-zA-Z0-9_]+").matcher(sql);

        while (matcher.find()) {
            namedParameters.add(matcher.group().substring(1));
        }

        return new ParsedSql(sql, namedParameters);
    }
}

