import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.util.Map;

public class PatchRequestExecutor {

  public static void execute(String partialUrl, Object payload, Map<String, String> headers,
                              Map<String, String> queryParams) throws Exception {

    HttpClient client = HttpClient.newBuilder().build();

    StringBuilder urlBuilder = new StringBuilder(partialUrl + "?");

    for (Map.Entry<String, String> entry : queryParams.entrySet()) {
      String key = entry.getKey();
      String value = entry.getValue();
      urlBuilder.append(URLEncoder.encode(key, StandardCharsets.UTF_8)).append("=")
          .append(URLEncoder.encode(value, StandardCharsets.UTF_8)).append("&");
    }

    HttpRequest request = HttpRequest.newBuilder()
        .uri(new URI(urlBuilder.toString().substring(0, urlBuilder.length() - 1)))
          .headers(headers.entrySet().stream()
          .map(e -> e.getKey() + ": " + e.getValue())
          .toArray(String[]::new))
        .PATCH(HttpRequest.BodyPublishers.ofString(payload.toString()))
        .build();

    HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
    System.out.println(response.body());
  }
}

