public static double[] convertToLambert(double lambda, double phi) {
    double phi0 = 46.5;  // France Lambert I reference latitude
    double lambda0 = 3;   // France Lambert I reference longitude
    double n = 0.7289686274;
    double c = 11745793.39;
    double xs = 700000;
    double ys = 6600000;
    double delLam = Math.toRadians(lambda - lambda0);
    double sinPhi = Math.sin(Math.toRadians(phi));
    double sinPhi0 = Math.sin(Math.toRadians(phi0));
    double cosPhi = Math.cos(Math.toRadians(phi));
    double cosPhi0 = Math.cos(Math.toRadians(phi0));
    double num = c * Math.pow(cosPhi0, n) / n;
    double denom = Math.pow((1 + n * (sinPhi0 * sinPhi + cosPhi0 * cosPhi * Math.cos(delLam))), (1 / n));
    double x = xs + num * Math.sin(n * Math.log(denom));
    double y = ys + num * Math.cos(n * Math.log(denom)) - c * Math.pow(cosPhi0, n) * Math.tan(Math.toRadians(45 - phi / 2));
    return new double[]{x, y};
}

