public SSLConfig[] loadPropertiesFile(final String propertiesURL, final boolean multiConfigURL) {
    SSLConfig[] configs = null;

    try {
        URL url = new URL(propertiesURL);
        Properties properties = new Properties();
        properties.load(url.openStream());

        // Assuming that each property is a SSLConfig object
        if (multiConfigURL) {
            // If multiConfigURL is true, then we expect multiple properties
            configs = new SSLConfig[properties.size()];
            int i = 0;
            for (String key : properties.stringPropertyNames()) {
                String value = properties.getProperty(key);
                configs[i++] = new SSLConfig(key, value);
            }
        } else {
            // If multiConfigURL is false, then we expect a single property
            String key = properties.stringPropertyNames().iterator().next();
            String value = properties.getProperty(key);
            configs = new SSLConfig[] { new SSLConfig(key, value) };
        }
    } catch (IOException e) {
        e.printStackTrace();
    }

    return configs;
}

