public Graph convertEncodedGraph(String encodedGraph, boolean noMonth) throws GraphEncodingException {
    GraphConfiguration config = new GraphConfiguration();

    if (noMonth) {
        config.setMonthHighlightColor(null);
    }

    Graph graph = new Graph(config);

    try {
        String[] encodedNodes = encodedGraph.split(";");

        for (String encodedNode : encodedNodes) {
            String[] nodeData = encodedNode.split(",");
            String name = nodeData[0];
            int x = Integer.parseInt(nodeData[1]);
            int y = Integer.parseInt(nodeData[2]);
            Node node = new Node(name, x, y);
            graph.addNode(node);
        }

        for (String encodedNode : encodedNodes) {
            String[] nodeData = encodedNode.split(",");
            String fromName = nodeData[0];

            for (int i = 3; i < nodeData.length; i++) {
                String toName = nodeData[i];
                Node fromNode = graph.getNode(fromName);
                Node toNode = graph.getNode(toName);
                if (fromNode != null && toNode != null) {
                    graph.addEdge(fromNode, toNode);
                } else {
                    throw new GraphEncodingException("Invalid edge in the encoded graph");
                }
            }
        }
    } catch (Exception e) {
        throw new GraphEncodingException("Invalid encoded graph data", e);
    }

    return graph;
}

