public boolean compareStackWithLiteral(String seen, Stack<Object> stack) {
    if (stack.isEmpty()) {
        return false;
    }
    Object top = stack.peek();
    if (!(top instanceof String)) {
        return false;
    }
    String stringTop = (String) top;
    if (stringTop.equals(seen)) {
        return true;
    }
    return false;
}

