                                    );
                throw invalidLogRecordTypeException;
        }  
        if (Tracing.isAnyTracingEnabled() && trace.isEntryEnabled())
            trace.exit(this,
                       cclass,
                       "readNext",
                       new Object[] { logRecordRead });
