import org.hamcrest.Matcher;
import org.hamcrest.core.IsEqual;

public class ShouldHaveSameSizeAs<T> implements Matcher<Iterable<? extends T>> {
    private final Iterable<T> expected;
    private int expectedSize;

    ShouldHaveSameSizeAs(Iterable<T> expected) {
        this.expected = expected;
    }

    public boolean matches(Object actual) {
        if (actual instanceof Iterable) {
            Iterable<?> actualIterable = (Iterable<?>) actual;
            int actualSize = sizeOf(actualIterable);
            return actualSize == expectedSize;
        }
        return false;
    }

    public void describeTo(Description description) {
        description.appendText("a collection with size ").appendValue(expectedSize);
    }

    public void describeMismatch(Object actual, Description mismatchDescription) {
        mismatchDescription.appendText("collection was ").appendValue(actual)
                .appendText(" with size ")
                .appendValue(sizeOf(actual));
    }

    /**
     * Creates a new {@link ShouldHaveSameSizeAs}.
     *
     * @param expected the expected collection.
     * @param <T>      the type of the collection's elements.
     * @return a new {@code ShouldHaveSameSizeAs}.
     */
    public static <T> ShouldHaveSameSizeAs<T> shouldHaveSameSizeAs(Iterable<T> expected) {
        return new ShouldHaveSameSizeAs<T>(expected);
    }

    /**
     * Creates a new {@link ShouldHaveSameSizeAs}.
     *
     * @param expectedSize the expected size.
     * @param <T>          the type of the collection's elements.
     * @return a new {@code ShouldHaveSameSizeAs}.
     */
    public static <T> ShouldHaveSameSizeAs<T> shouldHaveSameSizeAs(int expectedSize) {
        ShouldHaveSameSizeAs<T> matcher = new ShouldHaveSameSizeAs<T>(null);
        matcher.expectedSize = expectedSize;
        return matcher;
    }

    private int sizeOf(Iterable<?> iterable) {
        return iterable instanceof Collection ? ((Collection<?>) iterable).size() : sizeOf(iterable.iterator(), 0);
    }

    private int sizeOf(Iterator<?> iterator, int size) {
        return iterator.hasNext() ? sizeOf(iterator, size + 1) : size;
    }

    public Matcher<Iterable<? extends T>> getMatcher() {
        return IsEqual.equalTo(expected);
    }
}

