            resultSet = preparedStatement.executeQuery();
            List<String> columnList = getColumns(resultSet);
            while (resultSet.next()) {
                jsonArray.put(getJsonObject(resultSet, columnList));
            }
        } catch (SQLException | JSONException e) {
            e.printStackTrace();
            throw e;
        } finally {
            try {
                if (resultSet != null) {
                    resultSet.close();
                }
                if (preparedStatement != null) {
                    preparedStatement.close();
                }
            } catch (SQLException e) {
                e.printStackTrace();
            }
        }
        return jsonArray;
    }

    private List<String> getColumns(ResultSet resultSet) throws SQLException {
        List<String> columnList = new ArrayList<>();
        int count = resultSet.getMetaData().getColumnCount();
        for (int i = 0; i < count; i++) {
            columnList.add(resultSet.getMetaData().getColumnName(i + 1).toLowerCase());
        }
        return columnList;
    }

    private JSONObject getJsonObject(ResultSet resultSet, List<String> columnList) throws SQLException, JSONException {
        JSONObject jsonObject = new JSONObject();
        for (String column : columnList) {
            String value = resultSet.getString(column);
            jsonObject.put(column, value);
        }
        return jsonObject;
    }
}

