    Vector AC = new Vector(vertexA, vertexC);
    Vector BC = new Vector(vertexB, vertexC);

    // Find vectors from A to P, B to P, and C to P
    Vector AP = new Vector(vertexA, P);
    Vector BP = new Vector(vertexB, P);
    Vector CP = new Vector(vertexC, P);

    // Find the distances between the point and the vertices
    double distA = AP.magnitude();
    double distB = BP.magnitude();
    double distC = CP.magnitude();

    // Find the area of the triangle
    double area = AB.cross(AC).magnitude() / 2;

    // Find the barycentric coordinates of the point with respect to each vertex
    double alpha = AB.cross(AP).magnitude() / (2 * area);
    double beta = AC.cross(AP).magnitude() / (2 * area);
    double gamma = 1 - alpha - beta;

    // If the point is inside the triangle, the closest point is the point itself
    if (alpha >= 0 && alpha <= 1 && beta >= 0 && beta <= 1 && gamma >= 0 && gamma <= 1) {
        closestPt.copy(P);
    }
    // Otherwise, find the closest point on the segments AB, AC, and BC
    else {
        // Find the closest point on segment AB
        Point closestOnAB = new Point();
        if (alpha < 0) {
