        if (gamma < 0) {
            closestOnBC.copy(vertexB);
        } else if (gamma > 1) {
            closestOnBC.copy(vertexC);
        } else {
            closestOnBC.copy(BC.scale(gamma).add(vertexB));
        }
        double distBC = closestOnBC.distance(P);

        // Find the closest point out of the three found points
