    Buffer[] newBuffers = new Buffer[srcBuffers.length];
    for(int i = 0; i < srcBuffers.length; i++) {
        ByteBuffer src = ((ByteBuffer) srcBuffers[i]).duplicate();
        ByteBuffer copy = ByteBuffer.allocate(src.capacity());
        copy.put(src);
        copy.flip();
        newBuffers[i] = copy;
    }
    return newBuffers;
}

