private BufferedImage resample(BufferedImage pSource, BufferedImage pDest, InterpolationFilter pFilter) {
	// Get the width and height of the source and destination images
    int srcWidth = pSource.getWidth();
    int srcHeight = pSource.getHeight();
    int destWidth = pDest.getWidth();
    int destHeight = pDest.getHeight();

    // Create a new BufferedImage to hold the resampled image
    BufferedImage resampledImage = new BufferedImage(destWidth, destHeight, pSource.getType());

    // Loop through each pixel in the destination image
    for (int y = 0; y < destHeight; y++) {
        for (int x = 0; x < destWidth; x++) {
            // Calculate the corresponding x and y coordinates in the source image
            double srcX = (double) x * srcWidth / destWidth;
            double srcY = (double) y * srcHeight / destHeight;

            // Apply the interpolation filter to get the color of the pixel
            Color color = pFilter.apply(pSource, srcX, srcY);

            // Set the color of the pixel in the resampled image
            resampledImage.setRGB(x, y, color.getRGB());
        }
    }

    // Return the resampled image
    return resampledImage;
}

