public double[][] create3DPolygon(JSONArray lineString) {
    int numPoints = lineString.length();
    double[][] polygon = new double[numPoints + 1][3];

    for (int i = 0; i < numPoints; i++) {
        JSONArray point = lineString.getJSONArray(i);
        polygon[i][0] = point.getDouble(0);
        polygon[i][1] = point.getDouble(1);
        polygon[i][2] = 0;
    }

    // Close the polygon if needed
    if (numPoints > 2) {
        JSONArray firstPoint = lineString.getJSONArray(0);
        JSONArray lastPoint = lineString.getJSONArray(numPoints - 1);

        if (firstPoint.getDouble(0) != lastPoint.getDouble(0) ||
            firstPoint.getDouble(1) != lastPoint.getDouble(1)) {
            polygon[numPoints][0] = firstPoint.getDouble(0);
            polygon[numPoints][1] = firstPoint.getDouble(1);
            polygon[numPoints][2] = 0;
        }
    }

    return polygon;
}

