public static boolean isUnboundMethod(String input) {
    int index = input.indexOf("<");
    if(index == -1 || index == input.length() - 1) {
        return false;
    }
    int endIndex = input.indexOf(">", index + 1);
    if(endIndex == -1 || endIndex == input.length() - 1) {
        return false;
    }
    String terminal = input.substring(endIndex + 1).trim();
    return terminal.equals(".") || terminal.equals("::");
}

