public static String formatPhoneNumber(String pphoneNumber, String pcountryCode) {

    String formattedPhoneNumber = "";

    //loop to remove all non-numeric characters from the phone number
    for (int i = 0; i < pphoneNumber.length(); i++) {
        if (Character.isDigit(pphoneNumber.charAt(i))) {
            formattedPhoneNumber += pphoneNumber.charAt(i);
        }
    }

    //determine if the international prefix needs to be added to the phone number
    if (!formattedPhoneNumber.startsWith(pcountryCode)) {
        formattedPhoneNumber = pcountryCode + formattedPhoneNumber;
    }

    //determine if the cursor is within the phone number to handle cursor position
    int cursorPosition = 0;
    if (pphoneNumber.contains("|")) {
        cursorPosition = formattedPhoneNumber.indexOf("|") + 1;
        formattedPhoneNumber = formattedPhoneNumber.replace("|", "");
    }

    //format the phone number in E123 national format
    String[] phoneNumArray = formattedPhoneNumber.split("");
    int numCount = 0;
    formattedPhoneNumber = "";
    for (int i = 0; i < phoneNumArray.length; i++) {
        formattedPhoneNumber += phoneNumArray[i];
        numCount++;
        if (numCount == 3 && i != phoneNumArray.length - 1) {
            formattedPhoneNumber += "-";
            numCount = 0;
        }
    }

    //add cursor position to the formatted phone number
    if (cursorPosition > 0) {
        formattedPhoneNumber = formattedPhoneNumber.substring(0, cursorPosition - 1) + "|" + formattedPhoneNumber.substring(cursorPosition - 1);
    }

    return formattedPhoneNumber;
}

