        if ("@type".equals(tagName)) { //$NON-NLS-1$
            builder.recordType(new JSTypeExpression(tagValue));
        } else if ("@lends".equals(tagName)) { //$NON-NLS-1$
            builder.recordLends(new JSTypeExpression(tagValue));
        } else if ("@param".equals(tagName) || "@arg".equals(tagName)) { //$NON-NLS-1$ //$NON-NLS-2$
            String[] subparts = tagValue.split("\\s+", 2); //$NON-NLS-1$
            String paramName = subparts[0].trim();
            String paramDescription = subparts.length > 1 ? subparts[1] : "";
            JSTypeExpression paramType = this.parameterTypeMap.get(paramName);
            if (paramType == null) {
                paramType = this.fieldType;
            }
            builder.recordParameter(new JSTypeExpression(paramType, paramName), paramDescription);
        } else if ("@parameter".equals(tagName)) { //$NON-NLS-1$
            // Obsolete name of @param.
            String[] subparts = tagValue.split("\\s+", 2); //$NON-NLS-1$
            if (subparts.length > 1 && subparts[1].startsWith("{")) { //$NON-NLS-1$
                builder.recordParameter(new JSTypeExpression(subparts[1]), subparts[0]);
            } else {
                builder.recordParameter(subparts[0], "");
            }
        } else if ("@return".equals(tagName)) { //$NON-NLS-1$
            builder.recordReturnType(new JSTypeExpression(tagValue));
        } else if ("@constructor".equals(tagName)) { //$NON-NLS-1$
            builder.recordConstructor();
        } else if ("@this".equals(tagName)) { //$NON-NLS-1$
            builder.recordThisType(new JSTypeExpression(tagValue));
        } else if ("@throws".equals(tagName)) { //$NON-NLS-1$
            builder.recordThrowType(new JSTypeExpression(tagValue));
        } else if ("@template".equals(tagName)) { //$NON-NLS-1$
            String[] subparts = tagValue.split("\\s+", 2); //$NON-NLS-1$
            if (subparts.length == 1) {
                builder.recordTemplateTypeName(new JSTypeExpression(tagValue));
            } else {
                builder.recordTemplateTypeNameAndValue(new JSTypeExpression(subparts[1]), subparts[0]);
            }
        } else {
            builder.recordInlineTag(tag);
        }
    }

    return builder.build();
}

