import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class FileComparator {

    /**
     * Compare files with the same content.
     * @param dirToSearch the dir to search
     * @return the list with the result beans
     */
    public List<FileComparisonResultBean> compareFilesWithSameContent(File dirToSearch) throws IOException, NoSuchAlgorithmException {
        List<FileComparisonResultBean> resultList = new ArrayList<>();
        Map<String, List<File>> fileMap = new HashMap<>();

        // Get a map of files with the same content
        Files.walk(dirToSearch.toPath()).filter(Files::isRegularFile).forEach(file -> {
            try {
                String hashCode = getFileHash(file.toFile());
                if (fileMap.containsKey(hashCode)) {
                    fileMap.get(hashCode).add(file.toFile());
                } else {
                    List<File> fileList = new ArrayList<>();
                    fileList.add(file.toFile());
                    fileMap.put(hashCode, fileList);
                }
            } catch (NoSuchAlgorithmException | IOException e) {
                e.printStackTrace();
            }
        });

        // Create result list with fileComparisonResultBeans
        for (List<File> fileList : fileMap.values()) {
            if (fileList.size() > 1) {
                for (int i = 0; i < fileList.size(); i++) {
                    for (int j = i + 1; j < fileList.size(); j++) {
                        FileComparisonResultBean bean = new FileComparisonResultBean();
                        bean.setFile1(fileList.get(i));
                        bean.setFile2(fileList.get(j));
                        resultList.add(bean);
                    }
                }
            }
        }
        return resultList;
    }

    private String getFileHash(File file) throws NoSuchAlgorithmException, IOException {
        MessageDigest messageDigest = MessageDigest.getInstance("MD5");
        byte[] fileBytes = Files.readAllBytes(file.toPath());
        byte[] hashBytes = messageDigest.digest(fileBytes);
        StringBuilder stringBuilder = new StringBuilder();
        for (byte b : hashBytes) {
            stringBuilder.append(String.format("%02x", b));
        }
        return stringBuilder.toString();
    }

    public static void main(String[] args) throws IOException, NoSuchAlgorithmException {
        FileComparator comparator = new FileComparator();        
        List<FileComparisonResultBean> result = comparator.compareFilesWithSameContent(new File("D:/test_dir"));
        result.forEach(System.out::println);
    }
}

