public static double[] transformCoordinates(String from, String to, double[] xy) {
    CoordinateReferenceSystem sourceCRS = CRS.decode("EPSG:" + from);
    CoordinateReferenceSystem targetCRS = CRS.decode("EPSG:" + to);

    MathTransform transform;
    try {
        transform = CRS.findMathTransform(sourceCRS, targetCRS);
    } catch (FactoryException | MismatchedDimensionException e) {
        throw new RuntimeException("Error while creating the transform function", e);
    }

    double[] result = new double[xy.length];
    try {
        transform.transform(xy, 0, result, 0, xy.length / 2);
    } catch (TransformException e) {
        throw new RuntimeException("Error while transforming the coordinates", e);
    }

    return result;
}

