                    }
                    if (relation.hasProperties()) {

                        for (final LongObjectCursor<Object> next : relation) {
                            assert next.value != null;
                            RelationType rt = typeManager.getExistingRelationType(next.key);
                            if (rt.isPropertyKey()) {



                                te.property(rt.name(), next.value);
                            } else {
