public TinkerVertex readHadoopVertex(final StaticBuffer key, Iterable<Entry> entries) {
	final TinkerVertex vertex = new TinkerVertex();
    vertex.setId(key.asByteBuffer().getLong());
    for (final Entry entry : entries) {
