public static double[] convertToWSG84(double x, double y) {
    double n = 0.7289686274;
    double C = 11754255.426;
    double xs = 700000;
    double ys = 12655612.050;

    double delX = x - xs;
    double delY = y - ys;

    double gamma = Math.atan(-delX / delY);
    double R = Math.sqrt((delX * delX) + (delY * delY));
    double latiso = Math.log(C / R) / n;
    double sinPhiit0 = Math.tanh(latiso + Math.atan(0.833333333 * Math.sinh(latiso)) - (0.003693834 * Math.sin(2.0 * latiso)) - (0.000008135 * Math.sin(4.0 * latiso)) + (0.000001965 * Math.sin(6.0 * latiso)));
    double sinPhiit1 = Math.sin(Math.asin(sinPhiit0) / 1.0000112);
    double phi = Math.asin(sinPhiit1) * 180 / Math.PI;
    double lambda = (gamma / n) + 3.0 * (Math.atan(0.725607765 * Math.tan(0.0083572073 * (phi * Math.PI / 180.0))) - 0.00001256);

    return new double[]{lambda, phi};
}

