public boolean validate() {
	// Check if all required options are present
    for (Option option : options) {
        if (option.isRequired() && !option.isProvided()) {
            if (errorMode == ErrorMode.ILLEGAL_STATE) {
                throw new IllegalStateException("Required option " + option.getName() + " is missing.");
            }
            return false;
        }
    }

    // Check if there are any invalid operands
    for (Operand operand : operands) {
        if (!operand.isValid()) {
            if (errorMode == ErrorMode.ILLEGAL_STATE) {
                throw new IllegalStateException("Invalid operand: " + operand.getValue());
            }
            return false;
        }
    }

    // Check for any conflicting options
    for (Option option : options) {
        for (Option conflictingOption : option.getConflictingOptions()) {
            if (option.isProvided() && conflictingOption.isProvided()) {
                if (errorMode == ErrorMode.ILLEGAL_STATE) {
                    throw new IllegalStateException("Conflicting options: " + option.getName() + " and " + conflictingOption.getName());
                }
                return false;
            }
        }
    }

    // Check if the number of operands is within the expected range
    if (operands.size() < minOperands || operands.size() > maxOperands) {
        if (errorMode == ErrorMode.ILLEGAL_STATE) {
            throw new IllegalStateException("Number of operands is out of range. Expected between " + minOperands + " and " + maxOperands + ", but found " + operands.size());
        }
        return false;
    }

    return true;
}

