            }

            List<Integer> currentNeighbors = relation.get(currentCluster);
            List<Integer> nextNeighbors = relation.get(nextCluster);

            boolean areNeighbors = currentNeighbors.contains(nextCluster) || nextNeighbors.contains(currentCluster);

            if (areNeighbors && Math.abs(currentCluster - nextCluster) <= ixi) {
                currentClusterList.add(nextCluster);
                clusterOrderResult.set(j, -1); // Mark cluster as visited
            }
        }

        if (currentClusterList.size() >= minpts) {
            clusters.add(currentClusterList);
        }
    }

    return clusters;
}

