public <T> T executeGetCall(String partialUrl, Class<T> returnType, Map<String,String> headers, Map<String,String> queryParams) throws IOException {
    String urlString = BASE_URL + partialUrl;
    URL url = new URL(urlString);
    HttpURLConnection connection = (HttpURLConnection) url.openConnection();
    connection.setRequestMethod("GET");
    connection.setRequestProperty("Content-Type", "application/json");

    for (Map.Entry<String,String> entry : headers.entrySet()) {
        connection.setRequestProperty(entry.getKey(), entry.getValue());
    }

    StringBuilder queryParamsBuilder = new StringBuilder();
    for (Map.Entry<String,String> entry : queryParams.entrySet()) {
        queryParamsBuilder.append(entry.getKey()).append("=").append(entry.getValue()).append("&");
    }
    String queryParamsString = queryParamsBuilder.toString();
    if (!queryParamsString.isEmpty()) {
        queryParamsString = "?" + queryParamsString.substring(0, queryParamsString.length() - 1);
    }
    urlString += queryParamsString;

    BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
    String inputLine;
    StringBuilder response = new StringBuilder();
    while ((inputLine = in.readLine()) != null) {
        response.append(inputLine);
    }
    in.close();
    connection.disconnect();

    Gson gson = new Gson();
    T result = gson.fromJson(response.toString(), returnType);
    return result;
}

