public double logProbability(ObservationSequence o) {
    int numStates = this.getNumStates();
    int seqLength = o.length();

    double[][] alpha = new double[seqLength][numStates];
    double[] scaling = new double[seqLength];
    Arrays.fill(scaling, 1.0);

    // Compute alpha values for t = 0
    for (int i = 0; i < numStates; i++) {
        alpha[0][i] = this.getStartProbability(i) * this.getEmissionProbability(i, o.get(0));
    }

    // Apply scaling procedure to avoid underflows
    scaling[0] = 1.0 / Arrays.stream(alpha[0]).sum();
    for (int i = 0; i < numStates; i++) {
        alpha[0][i] *= scaling[0];
    }

    // Compute alpha values for t > 0
    for (int t = 1; t < seqLength; t++) {
        for (int j = 0; j < numStates; j++) {
            double sum = 0.0;
            for (int i = 0; i < numStates; i++) {
                sum += alpha[t - 1][i] * this.getTransitionProbability(i, j);
            }
            alpha[t][j] = this.getEmissionProbability(j, o.get(t)) * sum;
        }

        // Apply scaling procedure to avoid underflows
        scaling[t] = 1.0 / Arrays.stream(alpha[t]).sum();
        for (int j = 0; j < numStates; j++) {
            alpha[t][j] *= scaling[t];
        }
    }

    // Compute log probability of the sequence
    double logProb = -Math.log(scaling[0]);
    for (int t = 1; t < seqLength; t++) {
        logProb -= Math.log(scaling[t]);
    }

    return logProb;
}

