  // Returns an AST node for the javadoc comment of  a specified class, method or field element.
  public String getJavaDocComment(Element element) throws IOException {
    DocTreePath docPath = getDocPath(element);
    if (docPath != null) {
      String source = docPath.getCompilationUnit().getSourceFile().toUri().getPath();
      String comment = source.substring(0, source.lastIndexOf("/"))
          + docPath.getDocTree().getSourcePosition(docPath.getTreePath().getCompilationUnit())
          + docPath.getDocTree().toString();
      return comment;
    }
    return null;
  }

  private DocTreePath getDocPath(Element element) throws IOException {
    TreePath path = null;
    switch (element.getKind()) {
      case CLASS:
      case INTERFACE:
        path = getTreePath(element, null);
        break;
      case METHOD:
      case CONSTRUCTOR:
        path = getTreePath(element.getEnclosingElement(),
            (ExecutableElement) element);
        break;
      case FIELD:
        path = getTreePath(element.getEnclosingElement(),
            (VariableElement) element);
        break;
      default:
        break;
    }

    if (path != null) {
      DocTreePath docPath = DocTreePath.getPath(path);
      if (docPath != null && docPath.getDocTree() != null) {
        return docPath;
      }
    }
    return null;
  }

  private TreePath getTreePath(Element element, ExecutableElement method) throws IOException {
    Types types = javax.lang.model.util.Types.instance(element.getEnclosingElement().getEnclosingElement().getEnclosingElement());
    Elements elements = javax.lang.model.util.Elements.instance(element.getEnclosingElement().getEnclosingElement().getEnclosingElement());
    String elementPackageName = elements.getPackageOf(element).getQualifiedName().toString();

    String className = element.getEnclosingElement().getSimpleName().toString();
    String packageName = elementPackageName;
    String classPath = packageName + "." + className;

    // Find file
    JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
    StandardJavaFileManager fileManager = compiler.getStandardFileManager(null, null, null);
    File file = getFileByName(classPath, fileManager);

    String source = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
    JavaFileObject javaFile = new JavaSourceFromString(file.getAbsolutePath(), source);
    JavaCompiler.CompilationTask task = compiler.getTask(null, fileManager, null,
        Arrays.asList(new JavaSourceFromString(file.getName(), source)),
        null, Collections.singletonList(javaFile));
    task.parse();

    // Find path
    TreePath path = null;
    for (Element e : elements.getAllMembers((TypeElement) elements.getTypeElement(classPath))) {
      if (e.getKind() == ElementKind.METHOD) {
        if (method == null) {
          method = (ExecutableElement) e;
        }
        if (((ExecutableElement) e).getSimpleName().equals(method.getSimpleName())) {
          path = TreePath.getPath(task.parse(), e);
        }
      }
      if (e.getKind() == ElementKind.FIELD) {
        if (((VariableElement) e).getSimpleName().equals(element.getSimpleName())) {
          path = TreePath.getPath(task.parse(), e);
        }
      }
    }

    return path;
  }

  private File getFileByName(String className, StandardJavaFileManager fileManager) throws IOException {
    String classNamePath = className.replace(".", "/");
    for (JavaFileObject jfo : fileManager.list(StandardLocation.SOURCE_PATH, "", Collections.singletonList(classNamePath), true)) {
      if (jfo.getName().endsWith(".java")) {
        return new File(jfo.getName());
      }
    }
    return null;
  }

  private static class JavaSourceFromString extends SimpleJavaFileObject {
    final String code;

    JavaSourceFromString(String name, String code) {
      super(URI.create("string:///" + name.replace('.', '/') + Kind.SOURCE.extension), Kind.SOURCE);
      this.code = code;
    }

    @Override
    public CharSequence getCharContent(boolean ignoreEncodingErrors) {
      return code;
    }
  }
}

