public static <T> Map<TypeVariable<?>, Type> resolveTypes(Class<? super T> superType, Class<T> subType) {
    Map<TypeVariable<?>, Type> resolvedTypes = new HashMap<TypeVariable<?>, Type>();
    // make sure both types are included in the same hierarchy
    if (!superType.isAssignableFrom(subType)) {
        return resolvedTypes;
    }
    Type type = subType;
    // dive into inheritance hierarchy until we reach supertype
    while (!getClass(type).equals(superType)) {
        if (type instanceof Class) {
            // for class types, walk up the hierarchy
            Class<?> subClass = (Class<?>) type;
            addToResolvedTypes(resolvedTypes, subClass);
            type = subClass.getGenericSuperclass();
        } else {
            // for generic types, resolve actual type arguments
            ParameterizedType parameterizedType = (ParameterizedType) type;
            Class<?> rawType = (Class<?>) parameterizedType.getRawType();
            TypeVariable<?>[] typeVariables = rawType.getTypeParameters();
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            for (int i = 0; i<actualTypeArguments.length; i++) {
                TypeVariable<?> variable = typeVariables[i];
                Type typeArgument = actualTypeArguments[i];
                if (typeArgument instanceof ParameterizedType) {
                    resolvedTypes.putAll(resolveGenericTypes(superType, (ParameterizedType) typeArgument));
                }
                if (!resolvedTypes.containsKey(variable)) {
                    resolvedTypes.put(variable, typeArgument);
                }
            }
            type = rawType.getGenericSuperclass();
        }
    }
    return resolvedTypes;
}

private static Class<?> getClass(Type type) {
