    }
    for (Type genericInterface : clazz.getGenericInterfaces()) {
        if (genericInterface instanceof ParameterizedType) {
            resolvedTypes.putAll(resolveGenericTypes((Class<?>) ((ParameterizedType) genericInterface).getRawType(), (ParameterizedType) genericInterface));
