public void sendMultipartResponse(String key) throws IOException, MessagingException {
    // Create a multi-part response
    MimeMultipart multipart = new MimeMultipart();

    // Retrieve the versioned values of the key
    List<String> values = getVersionedValues(key);

    // Add each versioned value as a new body part
    for (String value : values) {
        MimeBodyPart bodyPart = new MimeBodyPart();
        bodyPart.setText(value);
        multipart.addBodyPart(bodyPart);
    }

    // Set the content type of the response as multipart
    response.setContentType("multipart/mixed");

    // Write the response to the output stream
    OutputStream outputStream = response.getOutputStream();
    multipart.writeTo(outputStream);
    outputStream.flush();
}

