private static int computeNumberOfLayers(int inputSize, int minECCPercent) {
  int eccWords = (int) Math.ceil(inputSize * minECCPercent / 100);
  int totalWords = eccWords + inputSize;

  // Minimum number of bits in a square.
  int bitsInSquare = 11 + 4 * totalWords / (32 * 32 - 2);

  // Searching for the minimal number of layers in which the Aztec code can fit.
  int layers = 1;
  int totalArea = 0;
  int matrixSize;
  do {
    matrixSize = 2 * layers + 1;
    totalArea = matrixSize * matrixSize;

    int usableArea = (totalArea - 2) * (bitsInSquare - 1);
    if (usableArea >= totalWords * bitsInSquare) {
      break;
    }
    layers++;
  } while (layers <= 32);

  if (layers > 32) {
    throw new IllegalArgumentException("Data too large for an Aztec code");
  }

  return layers;
}

