public static void convolution2D(int[][] input, int[][] output, int[][] kernel, String border) {
    int rows = input.length;
    int cols = input[0].length;
    int kernelRows = kernel.length;
    int kernelCols = kernel[0].length;
    int rowOffset = kernelRows / 2;
    int colOffset = kernelCols / 2;

    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            int sum = 0;
            for (int subRow = -rowOffset; subRow <= rowOffset; ++subRow) {
                for (int subCol = -colOffset; subCol <= colOffset; ++subCol) {
                    int curRow = row + subRow;
                    int curCol = col + subCol;

                    if (border.equals("zero")) { // Zero Padding
                        if (curRow < 0 || curRow >= rows || curCol < 0 || curCol >= cols) {
                            sum += 0;
                        } else {
                            sum += input[curRow][curCol] * kernel[subRow + rowOffset][subCol + colOffset];
                        }

                    } else if (border.equals("replicate")) { // Replicate Padding
                        curRow = Math.max(0, Math.min(curRow, rows - 1));
                        curCol = Math.max(0, Math.min(curCol, cols - 1));
                        sum += input[curRow][curCol] * kernel[subRow + rowOffset][subCol + colOffset];

                    } else if (border.equals("reflect")) { // Reflect Padding
                        if (curRow < 0) {
                            curRow = Math.abs(curRow);
                        } else if (curRow >= rows) {
                            curRow = rows - (curRow - rows) - 2;
                        }
                        if (curCol < 0) {
                            curCol = Math.abs(curCol);
                        } else if (curCol >= cols) {
                            curCol = cols - (curCol - cols) - 2;
                        }
                        sum += input[curRow][curCol] * kernel[subRow + rowOffset][subCol + colOffset];
                    }
                }
            }
            output[row][col] = sum;
        }
    }
}

