public static boolean invertMatrix(double[][] a, double[][] inv) {
    int n = a.length;
    double[] scale = new double[n];
    int[] index = new int[n];
    for (int i = 0; i < n; ++i) {
        double max = 0;
        for (int j = 0; j < n; ++j) {
            double abs = Math.abs(a[i][j]);
            if (abs > max) max = abs;
        }
        if (max == 0) return false;
        scale[i] = 1 / max;
    }

    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < j; ++i) {
            double sum = a[i][j];
            for (int k = 0; k < i; ++k) {
                sum -= a[i][k] * a[k][j];
            }
            a[i][j] = sum;
        }
        double max = 0;
        int imax = -1;
        for (int i = j; i < n; ++i) {
            double sum = a[i][j];
            for (int k = 0; k < j; ++k) {
                sum -= a[i][k] * a[k][j];
            }
            a[i][j] = sum;
            double abs = scale[i] * Math.abs(sum);
            if (abs > max) {
                max = abs;
                imax = i;
            }
        }
        if (imax < 0) return false;
        if (j != imax) {
            for (int k = 0; k < n; ++k) {
                double temp = a[imax][k];
                a[imax][k] = a[j][k];
                a[j][k] = temp;
            }
            scale[imax] = scale[j];
        }
        index[j] = imax;
        double pivot = a[j][j];
        for (int k = j + 1; k < n; ++k) {
            a[j][k] /= pivot;
        }
        for (int i = 0; i < n; ++i) {
            if (i != j) {
                for (int k = j + 1; k < n; ++k) {
                    a[i][k] -= a[i][j] * a[j][k];
                }
            }
        }
        for (int i = 0; i < n; ++i) {
            inv[index[i]][j] = a[i][j];
        }
    }
    return true;
}

