public static boolean invert(DMatrix5x5 a, DMatrix5x5 inv) {
    double det = a.determinant();

    if (det == 0) {
        return false;
    }

    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            inv.set(i, j, a.cofactor(j, i) / det);
        }
    }

    return true;
}

