public static boolean invert( DMatrix5x5 a , DMatrix5x5 inv ) {
	// Check if the matrix is square
    if (a.numRows != a.numCols) {
        throw new IllegalArgumentException("Matrix must be square");
    }

    // Calculate the determinant of the matrix
    double det = Determinant.det(a);

    // If the determinant is zero, the matrix is not invertible
    if (det == 0) {
        return false;
    }

    // Calculate the cofactor matrix
    DMatrix5x5 cofactor = new DMatrix5x5();
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            cofactor.set(i, j, cofactor(i, j, a));
        }
    }

    // Transpose the cofactor matrix to get the adjugate matrix
    DMatrix5x5 adjugate = new DMatrix5x5();
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            adjugate.set(i, j, cofactor.get(j, i));
        }
    }

    // Scale the adjugate matrix by the reciprocal of the determinant
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            inv.set(i, j, adjugate.get(i, j) / det);
        }
    }

    return true;
}

