import java.lang.reflect.*;
import java.util.*;

public class MyClass {

    public static Map<TypeVariable<?>, Type> findInterfaceTypeArguments(Class<?> classToSearch, Class<?> interfaceToFind) {
        Map<TypeVariable<?>, Type> typeArgMap = new HashMap<TypeVariable<?>, Type>();
        Deque<Class<?>> stack = new LinkedList<Class<?>>();
        stack.push(classToSearch);
        while (!stack.isEmpty()) {
            Class<?> next = stack.pop();
            Type[] interfaces = next.getGenericInterfaces();
            for (Type iface : interfaces) {
                if (iface instanceof ParameterizedType) {
                    ParameterizedType pi = (ParameterizedType) iface;
                    Class<?> interfaceClass = (Class<?>) pi.getRawType();
                    if (interfaceClass.equals(interfaceToFind)) {
                        TypeVariable<?>[] ifaceTypeParams = interfaceClass.getTypeParameters();
                        Type[] ifaceTypeArgs = pi.getActualTypeArguments();
                        for (int i = 0; i < ifaceTypeParams.length; i++) {
                            typeArgMap.put(ifaceTypeParams[i], ifaceTypeArgs[i]);
                        }
                        return typeArgMap;
                    }
                } else if (iface instanceof Class) {
                    stack.push((Class<?>) iface);
                }
            }
            Class<?> superClass = next.getSuperclass();
            if (superClass != null) {
                stack.push(superClass);
            }
        }
        return typeArgMap;
    }
}

