public static void upperHessenberg(double[][] A) {
    int n = A.length;
    for (int j = 0; j < n - 2; j++) {
        for (int i = j + 2; i < n; i++) {
            A[i][j] = 0.0;
        }
        for (int i = j + 2; i < n; i++) {
            double factor = A[i][j] / A[j + 1][j];
            A[i][j] = 0.0;
            for (int k = j + 1; k < n; k++) {
                A[i][k] -= factor * A[j + 1][k];
            }
        }
    }
}

