import azkaban.event.Event;
import azkaban.event.EventListener;
import azkaban.executor.ExecutableFlow;
import azkaban.executor.ExecutionEvent;
import azkaban.executor.ExecutionOptions;
import azkaban.executor.ExecutorManagerException;
import azkaban.flow.Flow;
import azkaban.project.Project;
import azkaban.project.ProjectManagerException;
import azkaban.utils.Props;
import org.apache.log4j.Logger;

public class FlowEventListener implements EventListener {

    private static final Logger logger = Logger.getLogger(FlowEventListener.class);

    private final Props props;
    private final ExecutorManager executorManager;

    public FlowEventListener(Props props, ExecutorManager executorManager) {
        this.props = props;
        this.executorManager = executorManager;
    }

    @Override
    public synchronized void handleEvent(Event event) {
        if (event.getType() == ExecutionEvent.Type.FLOW_FINISHED) {
            ExecutableFlow flow = (ExecutableFlow) event.getRunner();
            Flow parentFlow = flow.getFlow();
            if (parentFlow == null) {
                logger.error("Parent flow not set. Aborting handleEvent");
                return;
            }
            int projectId = parentFlow.getProjectId();
            String projectName;
            try {
                projectName = ProjectManager.getInstance().getProject(projectId).getName();
            } catch (ProjectManagerException e) {
                logger.error("Could not get project name for project id " + projectId, e);
                return;
            }
            String jobId = parentFlow.getName();

            if (flow.getStatus() == Status.SUCCEEDED) {
                logger.debug(String.format("Flow [%s:%s] succeeded. Not doing anything further.", projectName, jobId));
                return;
            }
            FlowResult flowResult = null;
            try {
                flowResult = FlowResult.create(this.props, this.executorManager, parentFlow, flow.getExecutionOptions());
            } catch (ExecutorManagerException e) {
                logger.error("Could not create flow result for execution id " + flow.getExecutionId(), e);
                return;
            }
            if (flowResult.getFailedChildren().size() > 0) {
                logger.debug(String.format("Found %s failed children for flow [%s:%s]. Reparenting.", flowResult.getFailedChildren().size(), projectName, jobId));
                FlowRunner runner = new FlowRunner(flow, this.props, this.executorManager, flow.getExecutionOptions(), this);
                parentFlow.getFlowOptions().addAll(runner.getExecutableFlow().getFlowOptions());
                runner.setFlowFailed();
                try {
                    this.executorManager.submitExecutableFlow(runner.getExecutableFlow(), this.executorManager.getUserByProxyUser(flowResult.getFlowProxyUser()));
                } catch (ExecutorManagerException e) {
                    logger.error("Could not execute sub.failed job re-parenting for execution id " + flow.getExecutionId(), e);
                }
            } else {
                logger.debug(String.format("Flow [%s:%s] failed due to failed node(s). Not re-parenting.", projectName, jobId));
            }
        }
    }
}

