        map.get(key).add(value);
    }

    public void remove(Key key, Value value) {
        if (map.containsKey(key))
            map.get(key).remove(value);
    }

    public List<Value> get(Key key) {
        return map.getOrDefault(key, new ArrayList<>());
    }
