import org.nd4j.linalg.api.ndarray.INDArray;
import org.nd4j.linalg.indexing.NDArrayIndex;
import org.nd4j.linalg.factory.Nd4j;

public static INDArray symmetricInPlaceShuffle(INDArray[] arrays, int[] dimensions) {
    int numDims = arrays[0].rank();
    int[] swapAxis = new int[numDims];
    for(int i = 0; i < numDims; i++) {
        swapAxis[i] = i;
    }
    for(int i = 0; i < dimensions.length; i++) {
        swapAxis[dimensions[i]] = numDims - dimensions[i] - 1;
    }
    INDArray result = Nd4j.concat(swapAxis, arrays);
    for(INDArray array: arrays) {
        for(int i = 0; i < array.size(dimensions); i++) {
            NDArrayIndex[] indices = new NDArrayIndex[numDims];
            for(int j = 0; j < numDims; j++) {
                if(j == dimensions[i]) {
                    indices[j] = NDArrayIndex.interval(-i, -i + 1);
                } else {
                    indices[j] = NDArrayIndex.all();
                }
            }
            INDArray slice = array.get(indices);
            NDArrayIndex[] newIndices = new NDArrayIndex[numDims];
            for(int j = 0; j < numDims; j++) {
                if(j == dimensions[i]) {
                    newIndices[j] = NDArrayIndex.point(result.size(dimensions[i]) - 1 - i);
                } else {
                    newIndices[j] = NDArrayIndex.all();
                }
            }
            result.put(newIndices, slice);
        }
    }
    return result;
}

