public DataSet<Vertex<K, VV>> createResult() {
	// Initialize the result DataSet
    DataSet<Vertex<K, VV>> result = vertices;

    // Perform the gather-sum-apply iteration
    for (int i = 0; i < maxIterations; i++) {
        // Gather phase: collect messages from neighbors
        DataSet<Message<K, MV>> messages = vertices.flatMap(new GatherFunction<K, VV, MV>());

        // Sum phase: aggregate messages
        DataSet<Message<K, MV>> aggregatedMessages = messages.groupBy("f0").reduce(new SumFunction<MV>());

        // Apply phase: update vertex values based on aggregated messages
        result = result.join(aggregatedMessages).where("f0").equalTo("f0").with(new ApplyFunction<K, VV, MV, VV>());
    }

    return result;
}

