public static void getImplementingClasses(Class<?> interfaceClass, Map<Class<?>, Set<Class<?>>> classToImplementingClass, Map<Class<?>, Set<Class<?>>> classToSubinterface) {
    Set<Class<?>> implementingClasses = new HashSet<>();
    Set<Class<?>> subInterfaces = new HashSet<>();

    for (Class<?> clazz : getAllClassesInPackage(interfaceClass.getPackage())) {
        if (interfaceClass.isAssignableFrom(clazz)) {
            if (interfaceClass.equals(clazz)) { // Skipping the interface itself
                continue;
            }

            implementingClasses.add(clazz);

            for (Class<?> interfaceChild : clazz.getInterfaces()) {
                addClassToMap(classToImplementingClass, interfaceChild, clazz);
                addClassToMap(classToSubinterface, interfaceClass, interfaceChild);
                subInterfaces.add(interfaceChild);
            }
        }
    }

    addClassToMap(classToImplementingClass, interfaceClass, implementingClasses);
    addClassToMap(classToSubinterface, interfaceClass, subInterfaces);
}

private static void addClassToMap(Map<Class<?>, Set<Class<?>>> map, Class<?> key, Class<?> value) {
    if (!map.containsKey(key)) {
        map.put(key, new HashSet<>());
    }

    map.get(key).add(value);
}

private static void addClassToMap(Map<Class<?>, Set<Class<?>>> map, Class<?> key, Set<Class<?>> values) {
    if (!map.containsKey(key)) {
        map.put(key, new HashSet<>());
    }

    map.get(key).addAll(values);
}

private static List<Class<?>> getAllClassesInPackage(Package pkg) {
    String packagePath = pkg.getName().replaceAll("\\.", "/");
    List<Class<?>> classes = new ArrayList<>();

    try {
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
        URL packageURL = classLoader.getResource(packagePath);
        String packageFolderPath = new File(packageURL.toURI()).getAbsolutePath();
        File packageFolder = new File(packageFolderPath);

        if (packageFolder.isDirectory()) {
            File[] files = packageFolder.listFiles();
            for (File file : files) {
                if (file.isFile() && file.getName().endsWith(".class")) {
                    String className = pkg.getName() + "." + file.getName().replaceAll("\\.class$", "");
                    classes.add(Class.forName(className));
                }
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
    }

    return classes;
}

