import java.io.IOException;
import java.io.OutputStreamWriter;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLEncoder;
import java.nio.charset.Charset;
import java.util.Map;

public void doHttpPut(String url, String username, String password, int timeout, Charset charset,
                      String useragent, String proxyserver, int proxyport, String proxyuser,
                      String proxypassword, Map<String, String> headers, String body) throws IOException, PageException {

    HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();

    // Set request method and properties
    connection.setRequestMethod("PUT");
    connection.setUseCaches(false);
    connection.setDoInput(true);
    connection.setConnectTimeout(timeout);
    connection.setReadTimeout(timeout);

    if (username != null && password != null) {
        String userpass = username + ":" + password;
        String basicAuth = "Basic " + new String(java.util.Base64.getEncoder().encode(userpass.getBytes()));
        connection.setRequestProperty("Authorization", basicAuth);
    }

    if (useragent != null) {
        connection.setRequestProperty("User-Agent", useragent);
    }

    if (proxyserver != null && proxyport > 0) {
        connection = (HttpURLConnection)new URL(url).openConnection(new java.net.Proxy(java.net.Proxy.Type.HTTP,
                new java.net.InetSocketAddress(proxyserver, proxyport)));
        if (proxyuser != null && proxypassword != null) {
            String userpass = proxyuser + ":" + proxypassword;
            String basicAuth = "Basic " + new String(java.util.Base64.getEncoder().encode(userpass.getBytes()));
            connection.setRequestProperty("Proxy-Authorization", basicAuth);
        }
    }

    if (headers != null) {
        for (Map.Entry<String, String> header : headers.entrySet()) {
            connection.setRequestProperty(header.getKey(), header.getValue());
        }
    }

    // Send request body
    if (body != null) {
        connection.setDoOutput(true);
        try (OutputStreamWriter out = new OutputStreamWriter(connection.getOutputStream(), charset)) {
            out.write(body);
        }
    }

    // Handle response
    int responseCode = connection.getResponseCode();
    if (responseCode >= 400) {
        throw new PageException("HTTP PUT request failed with response code " + responseCode);
    }

    connection.disconnect();
}

