public static String minimalPrintableString(double d) {
    if (Double.isNaN(d)) {
        return "NaN";
    } else if (Double.isInfinite(d)) {
        return (d > 0) ? "Infinity" : "-Infinity";
    } else if (d == 0) {
        return "0.0";
    } else {
        String str = Double.toString(d);
        if (str.contains("E")) {
            int expIndex = str.indexOf("E");
            String mantissa = str.substring(0, expIndex);
            String exponent = str.substring(expIndex + 1);
            int exp = Integer.parseInt(exponent);
            int dotIndex = mantissa.indexOf(".");
            if (dotIndex == -1) {
                dotIndex = mantissa.length();
            }
            int newEndIndex = dotIndex + exp;
            if (newEndIndex < 0) {
                StringBuilder sb = new StringBuilder();
                sb.append("0.0");
                for (int i = 0; i < -newEndIndex; i++) {
                    sb.append("0");
                }
                return sb.toString() + mantissa.replace(".", "");
            } else if (newEndIndex >= mantissa.length()) {
                StringBuilder sb = new StringBuilder();
                sb.append(mantissa.replace(".", ""));
                for (int i = 0; i < newEndIndex - mantissa.length() + 1; i++) {
                    sb.append("0");
                }
                return sb.toString() + ".0";
            } else {
                return mantissa.substring(0, newEndIndex).replace(".", "") + "." +
                        mantissa.substring(newEndIndex).replace(".", "");
            }
        } else {
            return str;
        }
    }
}

