public class PartitionLimit {

    private final Function<Principal, String> principalToGroup;
    private final Map<String, Double> groupPercentage = new HashMap<>();
    private double totalPercentage = 0.0;

    public PartitionLimit(Function<Principal, String> principalToGroup) {
        this.principalToGroup = principalToGroup;
    }

    public PartitionLimit addGroup(String groupName, double groupPercentage) {
        this.totalPercentage += groupPercentage;
        this.groupPercentage.put(groupName, groupPercentage);
        return this;
    }

    public Map<String, Double> partitionByPrincipal(Principal principal, double limit) {
        Map<String, Double> partitionedLimits = new HashMap<>();
        String group = principalToGroup.apply(principal);
        for (Map.Entry<String, Double> entry : groupPercentage.entrySet()) {
            double percentage = entry.getValue() / totalPercentage;
            double partitionedLimit = limit * percentage;
            partitionedLimits.put(entry.getKey(), partitionedLimit);
        }
        double remainingLimit = limit - partitionedLimits.values().stream().mapToDouble(Double::doubleValue).sum();
        partitionedLimits.put(group, remainingLimit);
        return partitionedLimits;
    }
}

