public static void showSheetByMorphing(FloatingActionButton fab, long showSheetDuration, long showSheetColorDuration, AnimatorListener listener) {
    View sheet = // get the sheet view here

    // set initial sheet height to 0
    sheet.getLayoutParams().height = 0;
    sheet.setVisibility(View.VISIBLE);

    // animate sheet height to match parent height
    ValueAnimator sheetAnimator = ValueAnimator.ofInt(0, sheet.getMeasuredHeight());
    sheetAnimator.setDuration(showSheetDuration);
    sheetAnimator.addUpdateListener(new ValueAnimator.AnimatorUpdateListener() {
        @Override
        public void onAnimationUpdate(ValueAnimator animation) {
            sheet.getLayoutParams().height = (int) animation.getAnimatedValue();
            sheet.requestLayout();
        }
    });

    // animate FAB to move up and change color
    ObjectAnimator fabMoveUpAnimator = ObjectAnimator.ofFloat(fab, "translationY", -sheet.getMeasuredHeight());
    ObjectAnimator fabColorAnimator = ObjectAnimator.ofArgb(fab, "colorNormal", Color.RED);
    AnimatorSet fabAnimator = new AnimatorSet();
    fabAnimator.playTogether(fabMoveUpAnimator, fabColorAnimator);
    fabAnimator.setDuration(showSheetColorDuration);

    // play both animations together, with listener if provided
    AnimatorSet animatorSet = new AnimatorSet();
    animatorSet.playSequentially(sheetAnimator, fabAnimator);
    if (listener != null) {
        animatorSet.addListener(listener);
    }
    animatorSet.start();
}

