public static void extendClassGloballyWithCategoryMethods(Class<?> self, Class<?>... categoryClasses) {
    for (Class<?> categoryClass : categoryClasses) {
        for (Method categoryMethod : categoryClass.getMethods()) {
            try {
                self.getDeclaredMethod(categoryMethod.getName(), categoryMethod.getParameterTypes());
            } catch (NoSuchMethodException e) {
                try {
                    Method bridge = categoryClass.getMethod(categoryMethod.getName(), categoryMethod.getParameterTypes());
                    self.getDeclaredMethod(bridge.getName(), bridge.getParameterTypes());
                } catch (NoSuchMethodException e1) {
                    // category method does not override an existing method, add it to class
                    try {
                        Method method = self.getMethod(categoryMethod.getName(), categoryMethod.getParameterTypes());
                        if (method.getReturnType() == void.class) {
                            categoryMethod.invoke(null, self);
                        } else {
                            throw new RuntimeException("Category method with return type cannot be used globally");
                        }
                    } catch (NoSuchMethodException e2) {
                        // category method does not exist on current class, add it
                        try {
                            self.getDeclaredMethod(categoryMethod.getName(), categoryMethod.getParameterTypes());
                        } catch (NoSuchMethodException ex) {
                            try {
                                Method method = categoryClass.getDeclaredMethod(categoryMethod.getName(), categoryMethod.getParameterTypes());
                                method.setAccessible(true);
                                Method newMethod = new Method(method);
                                newMethod.setDeclaringClass(self);
                                self.addMethod(newMethod);
                            } catch (NoSuchMethodException ex1) {
                                throw new RuntimeException("Could not add category method to class globally: " + ex1.getMessage());
                            }
                        }
                    } catch (Exception e2) {
                        throw new RuntimeException("Could not add category method to class globally: " + e2.getMessage());
                    }
                }
            } catch (Exception e) {
                throw new RuntimeException("Could not add category method to class globally: " + e.getMessage());
            }
        }
    }
}

