public HMM learnHMM(HMM initialModel, List<List<Integer>> observations, int iterations) {
    HMM updatedModel = initialModel.copy();

    for (int i = 0; i < iterations; i++) {
        List<double[]> alphas = new ArrayList<>(observations.size());
        List<double[]> betas = new ArrayList<>(observations.size());

        // Forward-Backward algorithm
        for (List<Integer> sequence : observations) {
            double[] alpha = updatedModel.forward(sequence);
            alphas.add(alpha);

            double[] beta = updatedModel.backward(sequence);
            betas.add(beta);
        }

        // Baum-Welch algorithm
        double[][][] gamma = new double[observations.size()][][];
        double[][][] xi = new double[observations.size()][][];
        for (int j = 0; j < observations.size(); j++) {
            List<Integer> sequence = observations.get(j);

            double[] alpha = alphas.get(j);
            double[] beta = betas.get(j);
            double[][][] digamma = updatedModel.digamma(sequence, alpha, beta);

            double[][] gammaJ = new double[digamma.length][digamma[0].length];
            for (int k = 0; k < digamma.length; k++) {
                for (int l = 0; l < digamma[k].length; l++) {
                    gammaJ[k][l] = digamma[k][l][0];
                }
            }
            gamma[j] = gammaJ;
            xi[j] = digamma;
        }

        updatedModel.learn(observations, gamma, xi);
    }

    return updatedModel;
}

