import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class MyClass {

    public <T> Stream<List<T>> groupedBySizeAndTime(Stream<T> stream, int size, long time, TimeUnit t) {
        return stream.collect(Collectors.groupingByConcurrent(element -> {
            long current = System.currentTimeMillis();
            long timeBucket = (current / time) * time;
            return new GroupKey(timeBucket, element.hashCode());
        })).entrySet().stream()
                .flatMap(entry -> Stream.of(entry.getValue()))
                .map(group -> group.stream().map(GroupKey::getData).collect(Collectors.toList()))
                .filter(list -> list.size() == size);
    }

    private class GroupKey {
        private final long timeBucket;
        private final Object data;

        GroupKey(long timeBucket, Object data) {
            this.timeBucket = timeBucket;
            this.data = data;
        }

        long getTimeBucket() {
            return timeBucket;
        }

        Object getData() {
            return data;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof GroupKey)) return false;

            GroupKey groupKey = (GroupKey) o;

            if (timeBucket != groupKey.timeBucket) return false;
            return data.equals(groupKey.data);
        }

        @Override
        public int hashCode() {
            int result = (int) (timeBucket ^ (timeBucket >>> 32));
            result = 31 * result + data.hashCode();
            return result;
        }
    }
}

