import java.util.ArrayList;
import java.util.List;

public class ControllerDiscoverer {

    public static List<Class<?>> discoverControllerClasses(String[] packageNames) throws ClassNotFoundException {
        List<Class<?>> controllers = new ArrayList<>();
        for (String packageName : packageNames) {
            for (Class<?> clazz : getClasses(packageName)) {
                if (isController(clazz)) {
                    controllers.add(clazz);
                }
            }
        }
        return controllers;
    }

    private static List<Class<?>> getClasses(String packageName) throws ClassNotFoundException {
        List<Class<?>> classes = new ArrayList<>();
        String path = packageName.replace('.', '/');
        for (File file : new File(ClassLoader.getSystemResource(path).getFile()).listFiles()) {
            String filename = file.getName();
            if (filename.endsWith(".class") && !filename.contains("$")) {
                Class<?> clazz = Class.forName(packageName + '.' + filename.substring(0, filename.length() - 6));
                classes.add(clazz);
            }
        }
        return classes;
    }

    private static boolean isController(Class<?> clazz) {
        return clazz.isAnnotationPresent(Controller.class);
    }
}

