import org.eclipse.jgit.annotations.NonNull;
import org.eclipse.jgit.diff.DiffEntry;
import org.eclipse.jgit.diff.DiffEntry.Side;
import org.eclipse.jgit.diff.DiffFormatter;
import org.eclipse.jgit.diff.RawTextComparator;
import org.eclipse.jgit.lib.ObjectId;
import org.eclipse.jgit.lib.ObjectReader;
import org.eclipse.jgit.revwalk.RevTree;
import org.eclipse.jgit.revwalk.RevWalk;
import org.eclipse.jgit.treewalk.AbstractTreeIterator;
import org.eclipse.jgit.treewalk.CanonicalTreeParser;
import org.eclipse.jgit.treewalk.TreeWalk;
import org.eclipse.jgit.treewalk.filter.PathFilter;
import org.eclipse.jgit.treewalk.filter.TreeFilter;
import org.eclipse.jgit.util.io.DisabledOutputStream;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/**
 * Utility for Git diffs.
 */
public final class GitDiffUtil {

    private GitDiffUtil() {
    }

    /**
     * Compute diff entries between two git revisions, in the specified path.
     *
     * @param reader      git object reader
     * @param newerTreeId id of the newer revision
     * @param olderTreeId id of the older revision
     * @param path        path to the directory/file to compare
     * @return list of diff entries
     * @throws IOException
     */
    public static List<DiffEntry> diffEntries(
            @NonNull ObjectReader reader, @NonNull ObjectId newerTreeId, @NonNull ObjectId olderTreeId, @NonNull String path)
            throws IOException {
        final AbstractTreeIterator newTreeIter = getCanonicalTreeParser(reader, newerTreeId);
        final AbstractTreeIterator oldTreeIter = getCanonicalTreeParser(reader, olderTreeId);
        try (final TreeWalk treeWalk = new TreeWalk(reader)) {
            treeWalk.setFilter(PathFilter.create(path));
            treeWalk.setRecursive(true);
            treeWalk.addTree(oldTreeIter);
            treeWalk.addTree(newTreeIter);
            return getDiffEntries(treeWalk, reader);
        }
    }

    private static List<DiffEntry> getDiffEntries(@NonNull TreeWalk treeWalk, @NonNull ObjectReader reader) throws IOException {
        final List<DiffEntry> diffEntries = new ArrayList<>();
        try (final DiffFormatter formatter = new DiffFormatter(DisabledOutputStream.INSTANCE)) {
            formatter.setRepository(reader.getRepository());
            formatter.setDiffComparator(RawTextComparator.DEFAULT);
            formatter.setDetectRenames(true);
            for (DiffEntry entry : formatter.scan(treeWalk)) {
                final Side from = entry.getOldId().equals(ObjectId.zeroId()) ? Side.NEW : Side.OLD;
                final CanonicalTreeParser tree = (CanonicalTreeParser) treeWalk.getTree(from);
                entry.newPath = entry.getNewPath().replace(tree.getEntryPathString(), "");
                entry.oldPath = entry.getOldPath().replace(tree.getEntryPathString(), "");
                diffEntries.add(entry);
            }
        }
        return diffEntries;
    }

    private static AbstractTreeIterator getCanonicalTreeParser(@NonNull final ObjectReader reader, @NonNull final ObjectId objectId) throws IOException {
        try (final RevWalk walk = new RevWalk(reader)) {
            final RevTree tree = walk.parseTree(objectId);
            final CanonicalTreeParser parser = new CanonicalTreeParser();
            parser.reset(reader, walk.parseTree(objectId));
            return parser;
        }
    }
}

