public static void convertNv21ToRgb(byte[] data, int width, int height, InterleavedU8 output) {
    int size = width * height;
    int offset = size;
    int[] pixels = new int[size];

    int u = 0, v = 0, y1, y2, y3, y4;

    for (int i = 0; i < height; ++i) {
        int posY = i * width;
        for (int j = 0; j < width; ++j) {
            int pos = posY + j;

            int y = data[pos] & 0xff;

            if (j % 2 == 0 && i % 2 == 0) {
                v = data[offset + (i / 2) * width + (j & ~1)] & 0xff;
                u = data[offset + (i / 2) * width + (j & ~1) + 1] & 0xff;
            }

            y1 = (int) (1.164f * (y - 16) + 1.596f * (v - 128));
            y2 = (int) (1.164f * (y - 16) - 0.813f * (v - 128) - 0.391f * (u - 128));
            y3 = (int) (1.164f * (y - 16));
            y4 = (int) (1.164f * (y - 16) + 2.018f * (u - 128));

