public List<String> sortByEditDistanceAndFrequency(List<String> inputList, String target) {
    // Create a map to store the frequency count of each string
    Map<String, Integer> frequencyMap = new HashMap<>();
    for (String str : inputList) {
        frequencyMap.put(str, frequencyMap.getOrDefault(str, 0) + 1);
    }

    // Sort the input list by edit distance, using a custom comparator
    Collections.sort(inputList, new Comparator<String>() {
        @Override
        public int compare(String str1, String str2) {
            int editDistance1 = calculateEditDistance(str1, target);
            int editDistance2 = calculateEditDistance(str2, target);
            int frequencyCount1 = frequencyMap.get(str1);
            int frequencyCount2 = frequencyMap.get(str2);

            // First, compare by edit distance
            int result = Integer.compare(editDistance1, editDistance2);

            // If edit distances are equal, compare by frequency count
            if (result == 0) {
                result = Integer.compare(frequencyCount1, frequencyCount2);
            }

            return result;
        }
    });

    return inputList;
}

// Helper function to calculate the edit distance between two strings
private int calculateEditDistance(String str1, String str2) {
    int n = str1.length();
    int m = str2.length();
    int[][] dp = new int[n+1][m+1];
    for (int i = 0; i <= n; i++) {
        dp[i][0] = i;
    }
    for (int j = 0; j <= m; j++) {
        dp[0][j] = j;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (str1.charAt(i-1) == str2.charAt(j-1)) {
                dp[i][j] = dp[i-1][j-1];
            } else {
                dp[i][j] = 1 + Math.min(dp[i-1][j], Math.min(dp[i][j-1], dp[i-1][j-1]));
            }
        }
    }
    return dp[n][m];
}

