import java.util.concurrent.TimeUnit;
import java.util.function.Function;

public class ThreadLocalLoadingCache<K,V> {

    private final ThreadLocal<Cache<K,V>> cacheThreadLocal;

    private ThreadLocalLoadingCache(Function<K,? extends V> cacheLoader, long duration, TimeUnit unit) {
        this.cacheThreadLocal = ThreadLocal.withInitial(() -> new Cache<>(cacheLoader, duration, unit));
    }

    public static <K, V> ThreadLocalLoadingCache<K, V> create(Function<K,? extends V> cacheLoader, long duration, TimeUnit unit) {
        return new ThreadLocalLoadingCache<>(cacheLoader, duration, unit);
    }

    public void invalidate() {
        cacheThreadLocal.remove();
    }

    public V get(K key) {
        return cacheThreadLocal.get().get(key);
    }

    private static class Cache<K,V> {
        private final Function<K,? extends V> cacheLoader;
        private final long duration;
        private final TimeUnit unit;

        private volatile long expirationTime = Long.MIN_VALUE;
        private volatile V value;

        private Cache(Function<K,? extends V> cacheLoader, long duration, TimeUnit unit) {
            this.cacheLoader = cacheLoader;
            this.duration = duration;
            this.unit = unit;
        }

        private V get(K key) {
            long currentTime = System.nanoTime();
            if (currentTime < expirationTime) {
                return value;
            }
            value = cacheLoader.apply(key);
            expirationTime = currentTime + unit.toNanos(duration);
            return value;
        }
    }
}

