public static <T> Iterable<T> createIteratorWrapper(MetaProperty<T> prop, Class<?> beanClass, boolean allowPrimitiveArrays){
    if (prop == null || beanClass == null) {
        throw new IllegalArgumentException("MetaProperty and BeanClass should not be null");
    }

    if (!prop.propertyType().isAssignableFrom(beanClass)) {
        throw new IllegalArgumentException("MetaProperty should be assignable from BeanClass");
    }

    if (prop.metaType().isCollectionLike()) {
        if (prop.metaType().isMap()) {
            return null;
        } else {
            return () -> {
                T propertyValue = prop.get(currentBeanInstance);
                if (propertyValue == null) {
                    return Collections.emptyIterator();
                } else {
                    return ((Collection<T>)propertyValue).iterator();
                }
            };
        }
    } else if (allowPrimitiveArrays && prop.metaType().isArray()) {
        Class<?> componentType = prop.metaPropertyType();
        return () -> {
            T propertyValue = prop.get(currentBeanInstance);
            if (propertyValue == null) {
                return Collections.emptyIterator();
            } else if (componentType.isPrimitive()) {
                return new Iterator<T>() {
                    private int i = 0;
                    private final int length = Array.getLength(propertyValue);
                    @Override
                    public boolean hasNext() {
                        return i < length;
                    }
                    @Override
                    public T next() {
                        return (T) Array.get(propertyValue, i++);
                    }
                };
            } else {
                return Arrays.asList((T[])propertyValue).iterator();
            }
        };
    } else {
        return null;
    }
}

