public static Optional<VariableElement> findUnqualifiedVariableOrField(Elements env, String name) {
    return env.getAllMembers(env.getPackageElement(""))
            .stream()
            .flatMap(o -> o.getEnclosedElements().stream())
            .filter(e -> e.getKind().isField() || e.getKind().isVariable())
            .map(e -> (VariableElement) e)
            .filter(e -> !e.getModifiers().contains(Modifier.SYNTHETIC))
            .filter(e -> e.getSimpleName().contentEquals(name))
            .findFirst();
}

