public Tensor separableConv2d(Tensor inputs, Conv2DConfig conv2DConfig) {
    // extract configuration
    int kernelHeight = conv2DConfig.getKernelHeight();
    int kernelWidth = conv2DConfig.getKernelWidth();
    int paddingHeight = conv2DConfig.getPaddingHeight();
    int paddingWidth = conv2DConfig.getPaddingWidth();
    int strideHeight = conv2DConfig.getStrideHeight();
    int strideWidth = conv2DConfig.getStrideWidth();

    // compute output dimensions
    int inputChannels = inputs.shape()[0];
    int inputHeight = inputs.shape()[1];
    int inputWidth = inputs.shape()[2];
    int outputChannels = conv2DConfig.getNumFilters();
    int outputHeight = (inputHeight + 2 * paddingHeight - kernelHeight) / strideHeight + 1;
    int outputWidth = (inputWidth + 2 * paddingWidth - kernelWidth) / strideWidth + 1;

    // create output tensor
    Tensor output = new Tensor(outputChannels, outputHeight, outputWidth);

    // convolution operation
    for (int i = 0; i < outputChannels; i++) {
        // depthwise convolution
        for (int j = 0; j < inputChannels; j++) {
            Tensor kernel = conv2DConfig.getDepthwiseKernel(i, j);
            Tensor paddedInput = inputs.pad(paddingHeight, paddingWidth);
            Tensor convolved = paddedInput.conv2d(kernel, strideHeight, strideWidth);
            output.set(j * outputChannels + i, convolved);
        }

        // pointwise convolution
        Tensor pointwiseKernel = conv2DConfig.getPointwiseKernel(i);
        Tensor pointwiseOutput = output.get(i).conv2d(pointwiseKernel, 1, 1);
        output.set(i, pointwiseOutput);
    }

    return output;
}

