public class ImageLoader {

    public BufferedImage loadImageWithPlaceholder(String imagePath, int width, int height, String transform) throws IOException {
        BufferedImage image = ImageIO.read(new File(imagePath));
        BufferedImage placeholder = createPlaceholder(width, height, transform);
        Graphics2D graphics = placeholder.createGraphics();
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setClip(new Ellipse2D.Float(0, 0, width, height));
        graphics.drawImage(image, 0, 0, width, height, null);
        graphics.dispose();
        return placeholder;
