            graphics.setClip(new Ellipse2D.Float(0, 0, width, height));
            graphics.fillRect(0, 0, width, height);
            graphics.dispose();
            return placeholder;
        } else {
            return new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        }
    }
}

