import org.apache.avro.Schema;
import org.apache.flink.api.common.typeinfo.Types;
import org.apache.flink.api.java.typeutils.RowTypeInfo;
import org.apache.flink.table.api.DataTypes;
import org.apache.flink.table.types.DataType;
import org.apache.flink.table.types.logical.*;
import org.apache.flink.table.types.utils.TypeConversions;

import java.util.List;
import java.util.stream.Collectors;

public class AvroSchemaConverter {
    public static RowTypeInfo convert(String avroSchemaString) {
        Schema avroSchema = new Schema.Parser().parse(avroSchemaString);
        List<String> fieldNames = avroSchema.getFields().stream().map(Schema.Field::name).collect(Collectors.toList());
        List<LogicalType> fieldTypes = avroSchema.getFields().stream().map(field -> convertType(field.schema())).collect(Collectors.toList());
        return new RowTypeInfo(fieldTypes.stream().map(TypeConversions::fromLogicalToDataType).toArray(DataType[]::new), fieldNames.toArray(new String[0]));
    }

    private static LogicalType convertType(Schema schema) {
        switch (schema.getType()) {
            case INT:
                return new IntType();
            case LONG:
                return new BigIntType();
            case FLOAT:
                return new FloatType();
            case DOUBLE:
                return new DoubleType();
            case BOOLEAN:
                return new BooleanType();
            case STRING:
                return new VarCharType(schema.isNullable() ? StringType.IS_NULLABLE : StringType.NOT_NULLABLE);
            case ARRAY:
                return new ArrayType(convertType(schema.getElementType()), schema.isNullable());
            case MAP:
                return new MapType(convertType(schema.getValueType()), new VarCharType(schema.isNullable() ? StringType.IS_NULLABLE : StringType.NOT_NULLABLE), schema.isNullable());
            case RECORD:
                List<String> fieldNames = schema.getFields().stream().map(Schema.Field::name).collect(Collectors.toList());
                List<LogicalType> fieldTypes = schema.getFields().stream().map(field -> convertType(field.schema())).collect(Collectors.toList());
                return new RowType(fieldTypes.toArray(new LogicalType[0]), fieldNames.toArray(new String[0]), schema.isNullable());
            case UNION:
                if (schema.getTypes().size() == 2 && (schema.getTypes().get(0).getType() == Schema.Type.NULL || schema.getTypes().get(1).getType() == Schema.Type.NULL)) {
                    return convertType(schema.getTypes().get(0).getType() == Schema.Type.NULL ? schema.getTypes().get(1) : schema.getTypes().get(0));
                }
            default:
                throw new IllegalArgumentException("Unsupported Avro type " + schema.getType());
        }
    }
}

