public class LibSVMReader {
    public Problem read(String file) throws IOException, InvalidInputDataException {
        BufferedReader reader = new BufferedReader(new FileReader(file));
        Problem problem = new Problem();
        problem.bias = -1;
        String line;

        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split("\\s+");
            double target = Double.parseDouble(tokens[0]);
            int index;
            double value;

            FeatureNode[] features = new FeatureNode[tokens.length - 1];
            for (int i = 1; i < tokens.length; i++) {
                index = Integer.parseInt(tokens[i].split(":")[0]);
                value = Double.parseDouble(tokens[i].split(":")[1]);
                features[i - 1] = new FeatureNode(index, value);
            }

            problem.add(new DataPoint(target, features));
        }
        reader.close();

        if (problem.x.length == 0) {
            throw new InvalidInputDataException("No data found in " + file);
        }

        return problem;
    }
}

