    for (int i = 0; i < headers.size(); i++) {
        boolean found = false;

        for (String header : headerParams) {
            if (headers.name(i).toLowerCase(Locale.ENGLISH).startsWith(header.toLowerCase(Locale.ENGLISH))) {
                found = true;
                break;
            }
        }

        if (!found) {
            newHeaders.put(headers.name(i), headers.value(i));
        }
    }

    return newHeaders;
}

