  public List<OutputWriter> getSegmentedFileWriters(final String prefix, final String suffix) {
    List<OutputWriter> writers = new ArrayList<>();
    long count = 0;

    while (true) {
      try {
        final String fileName = prefix + "_" + count + suffix;
        final String blobName = "gs://" + bucketName + "/" + fileName;
        final BlobId blobId = BlobId.of(bucketName, fileName);
        final BlobInfo blobInfo = BlobInfo.newBuilder(blobId).build();

