        final OutputStream os = new BufferedOutputStream(Channels.newOutputStream(storage.writer(blobInfo)));
        final WritableByteChannel channel = Channels.newChannel(os);

        writers.add(new OutputWriter(blobName, os, channel));
        count += 1;
      } catch (final IOException e) {
        break;
      }
    }

    return writers;
  }

