import com.datastax.driver.core.Cluster;
import com.datastax.driver.core.PreparedStatement;
import com.datastax.driver.core.Session;
import com.datastax.driver.core.AuthProvider;
import com.datastax.driver.core.PlainTextAuthProvider;

public static Cluster getDSECluster(String hostsAndPorts, String username, String password, String authorizationId) {
    String[] hostAndPortsArr = hostsAndPorts.split(",");
    Cluster.Builder builder = Cluster.builder();
    for (String hostAndPort : hostAndPortsArr) {
        String host;
        int port;
        String[] parts = hostAndPort.split(":");
        if (parts.length > 1) {
            host = parts[0];
            port = Integer.parseInt(parts[1]);
        } else {
            host = parts[0];
            port = CqlUtils.DEFAULT_CASSANDRA_PORT;
        }
        builder.addContactPoint(host).withPort(port);
    }

    if (username != null && password != null) {
        AuthProvider authProvider = new PlainTextAuthProvider(username, password);
        builder.withAuthProvider(authProvider);
    }

    if (authorizationId != null) {
        builder.withAuthorizationId(authorizationId);
    }

    Cluster cluster = builder.build();

    return cluster;
}

