    JsonObject geoJson = new JsonObject();

    // set the type of the object to "FeatureCollection"
    geoJson.addProperty("type", "FeatureCollection");

    // create a new JSON array to hold the features
    JsonArray features = new JsonArray();

    // create a new feature object for each value in this instance
    for (Value value : this.values) {
        // create a new JSON object to hold the feature
        JsonObject feature = new JsonObject();

        // set the type of the feature to "Feature"
        feature.addProperty("type", "Feature");

