public static void doCastToPrimitive(MethodVisitor mv, ClassNode sourceType, ClassNode targetType) {
	// Check if the source type is a wrapped number type
    if (!isWrappedNumberType(sourceType)) {
        throw new IllegalArgumentException("Source type must be a wrapped number type");
    }

    // Check if the targetType is a primitive number type
    if (!isPrimitiveNumberType(targetType)) {
        throw new IllegalArgumentException("Target type must be a primitive number type");
    }

    // Generate bytecode to call the appropriate method to convert the wrapped number to a primitive number
    String methodName = getMethodNameForPrimitive(targetType);
    mv.visitMethodInsn(INVOKEVIRTUAL, sourceType.name, methodName, "()"+getDescriptorForPrimitive(targetType), false);
}

private static boolean isWrappedNumberType(ClassNode sourceType) {
    return sourceType.equals(ClassHelper.Byte_TYPE) ||
           sourceType.equals(ClassHelper.Integer_TYPE) ||
           sourceType.equals(ClassHelper.Short_TYPE) ||
           sourceType.equals(ClassHelper.Long_TYPE) ||
           sourceType.equals(ClassHelper.Float_TYPE) ||
           sourceType.equals(ClassHelper.Double_TYPE);
}

private static boolean isPrimitiveNumberType(ClassNode targetType) {
    return targetType.equals(ClassHelper.int_TYPE) ||
           targetType.equals(ClassHelper.long_TYPE) ||
           targetType.equals(ClassHelper.double_TYPE) ||
           targetType.equals(ClassHelper.float_TYPE) ||
           targetType.equals(ClassHelper.short_TYPE) ||
           targetType.equals(ClassHelper.byte_TYPE);
}

private static String getMethodNameForPrimitive(ClassNode targetType) {
    switch (targetType.getName()) {
        case "int":
            return "intValue";
        case "long":
            return "longValue";
        case "double":
            return "doubleValue";
        case "float":
            return "floatValue";
        case "short":
            return "shortValue";
        case "byte":
            return "byteValue";
        default:
            throw new IllegalArgumentException("Unsupported primitive type: " + targetType.getName());
    }
}

