public void compactTrie(Node root) {
    if (root == null) {
        return;
    }
    Queue<Node> queue = new LinkedList<>();
    queue.offer(root);
    while (!queue.isEmpty()) {
        Node curr = queue.poll();
        if (curr.isLeaf()) {
            continue;
        }
        boolean isNull = true;
        int i = 0;
        while (i < curr.getChildren().length) {
            Node child = curr.getChildren()[i];
            if (child != null) {
                queue.offer(child);
                isNull = false;
                i++;
            } else {
                break;
            }
        }
        if (isNull) {
            curr.setChildren(null);
        } else {
            Node[] array = new Node[i];
            for (int j = 0; j < i; j++) {
                array[j] = curr.getChildren()[j];
            }
            curr.setChildren(array);
        }
    }
}

