public InterleavedF32 convertNV21ToRGB(byte[] data, int width, int height, InterleavedF32 output) {
    int frameSize = width * height;
    int numPixels = frameSize * 3;

    if (output == null) {
        output = new InterleavedF32(width, height, 3);
    }

    int[] rgb = new int[3];
    for (int j = 0, yp = 0; j < height; j++) {
        int uvp = frameSize + (j >> 1) * width, u = 0, v = 0;

        for (int i = 0; i < width; i++, yp++) {
            int y = (0xff & ((int) data[yp])) - 16;
            if (y < 0)
                y = 0;
            if ((i & 1) == 0) {
                v = (0xff & data[uvp++]) - 128;
                u = (0xff & data[uvp++]) - 128;
            }

            int y1192 = 1192 * y;
            int r = (y1192 + 1634 * v);
            int g = (y1192 - 833 * v - 400 * u);
            int b = (y1192 + 2066 * u);

            rgb[0] = r > 0 ? Math.min(255, r) : 0;
            rgb[1] = g > 0 ? Math.min(255, g) : 0;
            rgb[2] = b > 0 ? Math.min(255, b) : 0;

            output.setF(i, j, 0, rgb[0]);
            output.setF(i, j, 1, rgb[1]);
            output.setF(i, j, 2, rgb[2]);
        }
    }

    return output;
}

