public String translateXmlSchemaToAvro(Reader reader, String avroNamespace, String avroSchemaName) throws Xsd2AvroTranslatorException {
    try {
        // Parse input XML schema
        InputSource inputSource= new InputSource(reader);
        org.w3c.dom.Document document = XMLUtils.newDocument(inputSource);
        String xmlSchema = XMLUtils.DocumentToString(document);
        StringReader stringReader = new StringReader(xmlSchema);

        // Parse Avro schema
        SchemaParser schemaParser = new SchemaParser();
        Schema rawSchema = schemaParser.parse(stringReader);

        // Define Avro schema
        Schema.Builder schemaBuilder = Schema.builder().setName(avroSchemaName).setNamespace(avroNamespace);
        Schema avroSchema = schemaBuilder.fields().build(rawSchema).schema();

        // Convert Avro schema to JSON string
        StringWriter stringWriter = new StringWriter();
        avroSchema.toJson(true, stringWriter);

        return stringWriter.toString();

    } catch (IOException | ParseException e) {
        throw new Xsd2AvroTranslatorException("Failed translating XML schema to Avro", e);
    }
}

