            if ( ch >= 65 && ch <= 90 ) ch += 32;


            isb.append((char)ch);


            if ( _ctype != _TYPE ) {
                tcount++;
                _TYPE = _ctype;
            }


            if ( isb.length() > config.MAX_LATIN_LENGTH ) {
