import java.security.cert.CertificateException;
import java.security.cert.X509Certificate;
import java.util.Date;
import javax.net.ssl.X509TrustManager;

public class CertificateRevocationChecker {

    public static String getRevocationStatus(X509Certificate peerCert, X509Certificate issuerCert) throws CertificateVerificationException {
        try {
            Date currentDate = new Date();

            // Create OCSP request
            OCSPReq ocspRequest = new OCSPReq(peerCert, issuerCert);

            // Send OCSP request and get response
            OCSPResp ocspResponse = ocspRequest.send();

            // Verify OCSP response
            ocspResponse.verify(issuerCert.getPublicKey(), null, currentDate);

            // Parse OCSP response to get revocation status
            BasicOCSPResp basicOcspResp = (BasicOCSPResp) ocspResponse.getResponseObject();
            SingleResp[] responses = basicOcspResp.getResponses();
            if (responses.length == 1) {
                SingleResp resp = responses[0];
                Object status = resp.getCertStatus();
                if (status == CertificateStatus.GOOD) {
                    return "Good";
                } else if (status instanceof RevokedStatus) {
                    return "Revoked";
                } else {
                    return "Unknown";
                }
            } else {
                throw new CertificateVerificationException("Invalid OCSP response.");
            }
        } catch (OCSPException | IOException  | NoSuchProviderException | NoSuchAlgorithmException | CertificateException |
                CertPathValidatorException | InvalidKeyException | SignatureException ex) {
            throw new CertificateVerificationException("Failed to verify the ocsp status of certificate.", ex);
        }
    }

    private static class OCSPReq {
        private final X509Certificate peerCert;
        private final X509Certificate issuerCert;

        public OCSPReq(X509Certificate peerCert, X509Certificate issuerCert) {
            this.peerCert = peerCert;
            this.issuerCert = issuerCert;
        }

        public OCSPResp send() throws OCSPException, IOException, NoSuchProviderException {
            byte[] nonce = BigInteger.valueOf(new SecureRandom().nextInt()).toByteArray();
            DigestCalculator digestCalculator = new SHA1DigestCalculator();
            OCSPReqGenerator ocspGen = new OCSPReqGenerator();
            ocspGen.addRequest(peerCert.getSerialNumber(), digestCalculator.getDigest(issuerCert.getEncoded()), 
                    X509CertificateUtils.getOCSPSigningCertificate(issuerCert).getIssuer(), nonce);
            OCSPReq req = ocspGen.generate();
            byte[] bytes = req.getEncoded();
            URL url = new URL(X509CertificateUtils.getOCSPUrl(peerCert));
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("POST");
            conn.setRequestProperty("Content-Type", "application/ocsp-request");
            conn.setRequestProperty("Content-Length", Integer.toString(bytes.length));
            conn.setDoOutput(true);
            OutputStream out = conn.getOutputStream();
            out.write(bytes);
            out.flush();
            out.close();
            InputStream in = conn.getInputStream();
            byte[] respBytes = new byte[in.available()];
            in.read(respBytes);
            return new OCSPResp(respBytes);
        }
    }

    private static class X509CertificateUtils extends X509TrustManager {

        private static URL getOCSPUrl(X509Certificate cert) throws CertificateEncodingException {
            byte[] extBytes = cert.getExtensionValue(OCSPObjectIdentifiers.id_pkix_ocsp.getId());
            ASN1OctetString octetString = (ASN1OctetString) ASN1Primitive.fromByteArray(extBytes);
            OCSPResponse ocsp = OCSPResponse.getInstance(ASN1Primitive.fromByteArray(octetString.getOctets()));
            RespData data = ocsp.getResponseData();
            return new URL(data.getResponderID().getResponderURL().toString());
        }

        private static X509Certificate getOCSPSigningCertificate(X509Certificate cert) throws CertificateEncodingException {
            byte[] extBytes = cert.getExtensionValue(OCSPObjectIdentifiers.id_pkix_ocsp.getId());
            ASN1OctetString octetString = (ASN1OctetString) ASN1Primitive.fromByteArray(extBytes);
            OCSPResponse ocsp = OCSPResponse.getInstance(ASN1Primitive.fromByteArray(octetString.getOctets()));
            BasicOCSPResponse basicResponse = (BasicOCSPResponse) ocsp.getResponseObject();
            X509CertificateHolder[] chain = basicResponse.getCerts();
            List<X509Certificate> certs = new ArrayList<>();
            for (X509CertificateHolder holder : chain) {
                certs.add(new JcaX509CertificateConverter().getCertificate(holder));
            }
            return certs.get(1);
        }

        @Override
        public void checkClientTrusted(X509Certificate[] xcs, String string) throws CertificateException {}

        @Override
        public void checkServerTrusted(X509Certificate[] xcs, String string) throws CertificateException {}

        @Override
        public X509Certificate[] getAcceptedIssuers() { return null; }
    }

    public static class CertificateVerificationException extends Exception {
        public CertificateVerificationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}

