public double[] decorrelateMonoSignal(double[] inputSignal, double[] allpassFilterCoefficients) {
   int signalLength = inputSignal.length;
   int filterOrder = allpassFilterCoefficients.length;
   double[] outputSignal = new double[signalLength + filterOrder - 1];

   // initialize output signal with zeros
   for (int i = 0; i < outputSignal.length; i++) {
      outputSignal[i] = 0;
   }

   // apply allpass filter to input signal
   for (int i = 0; i < signalLength; i++) {
      double y = 0;
      for (int j = 0; j < filterOrder; j++) {
         if (i >= j) {
            y += allpassFilterCoefficients[j] * inputSignal[i - j];
         }
      }
      outputSignal[i] = y;
   }

   return outputSignal;
}

