public class AllPassFilter {
    private float[] buffer;
    private int index;

    public AllPassFilter(int delay) {
        buffer = new float[delay];
        index = 0;
    }

    public float process(float input) {
        float output = -buffer[index] + input;
        buffer[index] = input;
        index = (index + 1) % buffer.length;
        return output;
    }
}

