public static void packIntegers(int[] in, int inpos, int[] out, int outpos, int bit) {
    int val = 0;
    int bitsLeft = 32;
    int shift = bit;
    int mask = (1 << bit) - 1;

    for (int i = inpos; i < inpos + 32; i++) {
        val = val << bit;
        val |= in[i] & mask;
        bitsLeft -= bit;
        if (bitsLeft < bit) {
            out[outpos++] = val << (32 - shift);
            val >>>= shift;
            bitsLeft += 32;
        }
    }
    if (bitsLeft != 32) {
        out[outpos++] = val << (32 - bitsLeft);
    }
}

