public static void fastpack(final int[] in, final int inpos, final int[] out, final int outpos, final int bit) {
    int mask = (1 << bit) - 1; // create a mask with the number of bits
    int packed = 0;
    int shift = 0;

    for (int i = inpos; i < in.length; i++) {
        packed |= (in[i] & mask) << shift; // pack the integer
        shift += bit;

        if (shift >= 32) {
            out[outpos++] = packed; // write the packed integer to the output array
            packed = 0;
            shift = 0;
        }
    }

    if (shift > 0) {
        out[outpos++] = packed; // write the remaining packed integer to the output array
    }
}

