    // Here is one possible implementation:
    try {
        URLClassLoader classLoader = (URLClassLoader) ClassLoader.getSystemClassLoader();
        Method method = URLClassLoader.class.getDeclaredMethod("getURLs");
        method.setAccessible(true);
        URL[] urls = (URL[]) method.invoke(classLoader);
        List<Class<?>> classNames = new ArrayList<>();
        for (URL url : urls) {
            File file = new File(url.getPath());
            if (file.isDirectory()) {
                classNames.addAll(findClasses(file, file.getPath()));
            } else {
                try (JarFile jar = new JarFile(file)) {
                    Enumeration<JarEntry> entries = jar.entries();
                    while (entries.hasMoreElements()) {
                        String name = entries.nextElement().getName();
                        if (name.endsWith(".class")) {
                            name = name.substring(0, name.length() - 6).replace('/', '.');
                            classNames.add(Class.forName(name));
                        }
                    }
                }
            }
        }
        return classNames.toArray(new Class<?>[classNames.size()]);
    } catch (IOException | ClassNotFoundException | NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
        throw new RuntimeException(e);
    }
}

private static List<Class<?>> findClasses(File directory, String packageName) throws ClassNotFoundException {
    List<Class<?>> classes = new ArrayList<>();
    if (!directory.exists()) {
        return Collections.emptyList();
    }
    File[] files = directory.listFiles();
    if (files == null) {
        return Collections.emptyList();
    }
    for (File file : files) {
        if (file.isDirectory()) {
            classes.addAll(findClasses(file, packageName + "." + file.getName()));
        } else if (file.getName().endsWith(".class")) {
            String className = packageName + '.' + file.getName().substring(0, file.getName().length() - 6);
            classes.add(Class.forName(className));
        }
    }
    return classes;
}

