public static int[] rearrangeArray(int[] arr, int k) {
    int temp = arr[k];
    int left = 0;
    int right = arr.length - 1;

    swap(arr, k, right);

    for(int i = 0; i < right; i++) {
        if(arr[i] < temp) {
            swap(arr, i, left);
            left++;
        }
    }

    swap(arr, left, right);

    return arr;
}

private static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
