    for (IAtom atom : molecule.atoms()) {
        volume += VdW.getVDWRadius(atom) * VdW.getVDWRadius(atom) * VdW.getVDWRadius(atom);
    }
    double scalingFactor = (4.0 / 3.0 * Math.PI);
    double volumeInAngstrom = scalingFactor * volume;
    return volumeInAngstrom;
}

