        }
    }

    rangeResult.setVersions(versions.stream().sorted().collect(Collectors.toList()));
    Version version = versionScheme.parseVersion(rangeResult.getHighestVersion().toString());
    rangeResult.setRecommendedVersion(new Recommendation(rangeResult.getHighestVersion(), version));

