public static Histogram decodeFromByteBuffer(ByteBuffer buffer, long minBarForHighestTrackableValue) throws DataFormatException {
    Inflater decompressor = new Inflater();
    byte[] compressedArray = new byte[buffer.remaining()];
    buffer.get(compressedArray);
    decompressor.setInput(compressedArray);
    long highestTrackableValue = 0;
    int numberOfSignificantValueDigits = 0;
    try {
        DataInputStream input = new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(compressedArray), decompressor));
        int cookie = input.readInt();
        if (cookie != PackedHistogram.COMPRESSED_HISTOGRAM_COOKIE) {
            throw new DataFormatException("The buffer does not contain a compressed histogram");
        }
        int version = input.readByte();
        if (version != PackedHistogram.VERSION) {
            throw new DataFormatException("Cannot decode version " + version + " histogram");
        }
        highestTrackableValue = input.readLong();
        if (highestTrackableValue < minBarForHighestTrackableValue) {
            highestTrackableValue = minBarForHighestTrackableValue;
        }
        numberOfSignificantValueDigits = input.readByte();
        PackedHistogram histogram = new PackedHistogram(highestTrackableValue, numberOfSignificantValueDigits);
        histogram.decodeFrom(input);
        return histogram;
    } catch (IOException e) {
        throw new DataFormatException("Unable to read histogram data from buffer", e);
    } finally {
        decompressor.end();
    }
}

