public static ConfigDelayedMergeObject mergeObject(ConfigOrigin origin, List<AbstractConfigValue> stack) {
    List<AbstractConfigObject> reversed = new ArrayList<>();
    for (int i = stack.size() - 1; i >= 0; i--) {
        AbstractConfigValue v = stack.get(i);
        if (v instanceof ConfigDelayedMergeObject) {
            List<AbstractConfigObject> more = ((ConfigDelayedMergeObject) v).stack;
            for (int j = more.size() - 1; j >= 0; j--) {
                reversed.add(more.get(j));
            }
        } else if (v instanceof AbstractConfigObject) {
            reversed.add((AbstractConfigObject) v);
        }
    }
    return new ConfigDelayedMergeObject(origin, reversed);
}

