public boolean fitConic(Point[] points, Conic output) {
    double xMean = 0;
    double yMean = 0;
    double xVariance = 0;
    double yVariance = 0;
    int n = points.length;

    // transform points to have zero mean and standard deviation
    for (Point p : points) {
        xMean += p.x;
        yMean += p.y;
    }
    xMean = xMean / n;
    yMean = yMean / n;
    for (Point p : points) {
        xVariance += (p.x - xMean) * (p.x - xMean);
        yVariance += (p.y - yMean) * (p.y - yMean);
    }
    xVariance = Math.sqrt(xVariance / n);
    yVariance = Math.sqrt(yVariance / n);
    for (Point p : points) {
        p.x = (p.x - xMean) / xVariance;
        p.y = (p.y - yMean) / yVariance;
    }

    // solve system of equations to find conic coefficients
    double[][] A = new double[n][6];
    double[] B = new double[n];
    for (int i = 0; i < n; i++) {
        Point p = points[i];
        A[i][0] = p.x * p.x;
        A[i][1] = p.x * p.y;
        A[i][2] = p.y * p.y;
        A[i][3] = p.x;
        A[i][4] = p.y;
        A[i][5] = 1;
        B[i] = -1;
    }
    Matrix a = new Matrix(A);
    Matrix b = new Matrix(B, n);
    Matrix x = a.solve(b);
    if (x == null) {
        return false;
    }

    // convert coefficients to conic form
    output.a = x.get(0, 0) * yVariance * yVariance;
    output.b = x.get(1, 0) * xVariance * yVariance;
    output.c = x.get(2, 0) * xVariance * xVariance;
    output.d = x.get(3, 0) * xVariance;
    output.e = x.get(4, 0) * yVariance;
    output.f = x.get(5, 0);

    return true;
}

public class Point {
    public double x;
    public double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }
}

public class Conic {
    public double a;
    public double b;
    public double c;
    public double d;
    public double e;
    public double f;
}

