import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.hbase.Cell;
import org.apache.hadoop.hbase.HBaseConfiguration;
import org.apache.hadoop.hbase.client.Connection;
import org.apache.hadoop.hbase.client.ConnectionFactory;
import org.apache.hadoop.hbase.client.Result;
import org.apache.hadoop.hbase.client.Scan;
import org.apache.hadoop.hbase.client.Table;
import org.apache.hadoop.hbase.filter.FilterList;
import org.apache.hadoop.hbase.filter.MultiRowRangeFilter;
import org.apache.hadoop.hbase.filter.PrefixFilter;
import org.apache.hadoop.hbase.util.Bytes;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.NavigableMap;

public class Scanner {
  public static List<String> scanRows(Connection client, String tsdUidTable, String search, String kindOrNull, int maxResults) throws IOException {
    Configuration conf = HBaseConfiguration.create();
    Table table = client.getTable(TableName.valueOf(tsdUidTable));
    Scan scan = new Scan();

    // Create a list of row ranges to scan over, based on the search string and kind
    List<MultiRowRangeFilter.RowRange> rowsToScan = new ArrayList<>();
    byte[] startRowKey = Bytes.toBytes(search);
    byte[] stopRowKey = Bytes.stopKeyForPrefix(startRowKey);
    byte[] kindPrefix = kindOrNull != null ? Bytes.toBytes(kindOrNull) : null;
    rowsToScan.add(new MultiRowRangeFilter.RowRange(startRowKey, true, stopRowKey, false, kindPrefix, null));

    // Set up the scan with the MultiRowRangeFilter and a PrefixFilter
    MultiRowRangeFilter rangeFilter = new MultiRowRangeFilter(rowsToScan);
    scan.setFilter(new FilterList(FilterList.Operator.MUST_PASS_ALL, rangeFilter, new PrefixFilter(startRowKey)));

    // Execute the scan and add each result row to the list of suggestions
    List<String> suggestions = new ArrayList<>();
    ResultScanner resultScanner = table.getScanner(scan);
    int count = 0;
    for (Result result : resultScanner) {
      NavigableMap<byte[], NavigableMap<byte[], NavigableMap<Long, byte[]>>> columnMap = result.getMap();
      for (NavigableMap.Entry<byte[], NavigableMap<byte[], NavigableMap<Long, byte[]>>> columnFamilyEntry : columnMap.entrySet()) {
        byte[] columnFamily = columnFamilyEntry.getKey();
        for (NavigableMap.Entry<byte[], NavigableMap<Long, byte[]>> columnEntry : columnFamilyEntry.getValue().entrySet()) {
          byte[] columnQualifier = columnEntry.getKey();
          Cell cell = result.getColumnLatestCell(columnFamily, columnQualifier);
          suggestions.add(Bytes.toString(cell.getValueArray(), cell.getValueOffset(), cell.getValueLength()));
          count++;
          if (count == maxResults){
            return suggestions;
          }
        }
      }
    }

    return suggestions;
  }

