public static double refineLocalPeak(double[] data, int peakIndex) {
    double left = data[peakIndex - 1];
    double center = data[peakIndex];
    double right = data[peakIndex + 1];

    double delta = 0.5 * (left - right) / (left - 2 * center + right);

    return peakIndex + delta;
}

