protected void subpixelPeak(int peakX, int peakY) {
	// Implement a search algorithm to refine the peak position to sub-pixel accuracy
    // This could involve using a method like gradient ascent or descent, or a more sophisticated algorithm like the Newton-Raphson method.
    // For simplicity, let's use a basic gradient ascent approach.

    double stepSize = 0.1; // Initial step size
    double tolerance = 0.001; // Tolerance for convergence
    double[][] data = getData(); // Assume this method returns the data array

    double x = peakX;
    double y = peakY;
    double currentValue = data[(int)x][(int)y];

    while (true) {
        double newX = x + stepSize * gradientX(x, y, data);
        double newY = y + stepSize * gradientY(x, y, data);

        double newValue = data[(int)newX][(int)newY];

        if (Math.abs(newValue - currentValue) < tolerance) {
            break;
        }

        x = newX;
        y = newY;
        currentValue = newValue;
    }

    // Update the peak position with the refined sub-pixel coordinates
    peakX = (int)Math.round(x);
    peakY = (int)Math.round(y);
}

private double gradientX(double x, double y, double[][] data) {
    // Calculate the gradient in the x direction
    // This is a simple finite difference approximation
    return (data[(int)(x + 1)][(int)y] - data[(int)(x - 1)][(int)y]) / 2.0;
}

private double gradientY(double x, double y, double[][] data) {
    // Calculate the gradient in the y direction
    // This is a simple finite difference approximation
    return (data[(int)x][(int)(y + 1)] - data[(int)x][(int)(y - 1)]) / 2.0;
}

