public String calculateWorkingTime(Task task, Date date1, Date date2, String format) {
    long diff = date2.getTime() - date1.getTime(); // difference in milliseconds
    long diffInMinutes = TimeUnit.MINUTES.convert(diff, TimeUnit.MILLISECONDS); // difference in minutes

    // Calculate the total duration of working time in minutes
    int durationInMinutes = calculateTotalDuration(task, date1, date2);

    // Calculate the duration of non-working time in minutes
    int nonWorkingTimeInMinutes = Math.toIntExact(diffInMinutes - durationInMinutes);

    // Convert the remaining time to the required format
    Duration duration = Duration.ofMinutes(nonWorkingTimeInMinutes);
    return duration.toString().substring(2).replaceAll("(\\d[HMS])(?!$)", "$1 ").toLowerCase();
}

private int calculateTotalDuration(Task task, Date date1, Date date2) {
    int duration = 0;
    while (date1.before(date2)) {
        if (isWorkingTime(task, date1)) {
            duration += 1;
        }
        date1 = addMinute(date1);
    }
    return duration;
}

private boolean isWorkingTime(Task task, Date date) {
    // Check if the date is a weekend
    Calendar cal = Calendar.getInstance();
    cal.setTime(date);
    if (cal.get(Calendar.DAY_OF_WEEK) == Calendar.SATURDAY || cal.get(Calendar.DAY_OF_WEEK) == Calendar.SUNDAY) {
        return false;
    }
    // Check if the date is within working hours
    int hour = cal.get(Calendar.HOUR_OF_DAY);
    return hour >= task.getStartHour() && hour < task.getEndHour();
}

private Date addMinute(Date date) {
    Calendar cal = Calendar.getInstance();
    cal.setTime(date);
    cal.add(Calendar.MINUTE, 1);
    return cal.getTime();
}

