public void fieldsToBinaryArray(BigEndianBinaryWriter bebw, Method getter, PDescriptor descriptor) throws Exception {
    if (descriptor instanceof PField) {
        PField field = (PField) descriptor;
        Object value = getter.invoke(null, null);
        PWireType wireType = field.getWireType();
        if (field.isRequired() || value != null) {
            wireType.writeTagAndValue(field.getTag(), value, bebw);
        }
    } else if (descriptor instanceof PStruct) {
        PStruct struct = (PStruct) descriptor;
        for (PDescriptor nestedDescriptor : struct.getDescriptors()) {
            fieldsToBinaryArray(bebw, getter, nestedDescriptor);
        }
    }
}

