import java.io.FileInputStream;
import java.security.Key;
import java.security.KeyStore;
import java.security.cert.CertificateFactory;
import java.security.cert.X509Certificate;
import java.util.Collections;

public KeyStore convertPemToKeystore(String pemFile) {
    try {
        FileInputStream fileInputStream = new FileInputStream(pemFile);
        CertificateFactory certificateFactory = CertificateFactory.getInstance("X.509");
        X509Certificate certificate = (X509Certificate) certificateFactory.generateCertificate(fileInputStream);

        fileInputStream.close();

        KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
        keyStore.load(null, null);

        Key key = certificate.getPublicKey();
        keyStore.setKeyEntry("alias", key, null, new X509Certificate[]{certificate});

        return keyStore;
    } catch (Exception e) {
        return null;
    }
}

