public boolean checkSquarePlanarity(Atom atomA, Atom atomB, Atom atomC, Atom atomD) {
   Vector3D vector1 = new Vector3D(atomB.getX() - atomA.getX(),
                                    atomB.getY() - atomA.getY(),
                                    atomB.getZ() - atomA.getZ());
   Vector3D vector2 = new Vector3D(atomC.getX() - atomA.getX(),
                                    atomC.getY() - atomA.getY(),
                                    atomC.getZ() - atomA.getZ());
   Vector3D vector3 = new Vector3D(atomD.getX() - atomA.getX(),
                                    atomD.getY() - atomA.getY(),
                                    atomD.getZ() - atomA.getZ());
   Vector3D normal = vector1.crossProduct(vector2);
   double dotProduct = vector3.dotProduct(normal);
   return (Math.abs(dotProduct) < 0.00001);
}

