public void fastWriteAccessMode(String path, FeatureCollection featureCollection) throws IOException {
    File file = new File(path);
    FileOutputStream fileOutputStream = new FileOutputStream(file, true);
    BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(fileOutputStream));

    SimpleFeatureType featureType = featureCollection.getSchema();
    List<AttributeDescriptor> attributes = featureType.getAttributeDescriptors();
    List<String> headers = attributes.stream().map(AttributeDescriptor::getLocalName).collect(Collectors.toList());

    bufferedWriter.write(String.join(",", headers));
    bufferedWriter.flush();

    SimpleFeatureIterator featureIterator = featureCollection.features();
    while (featureIterator.hasNext()) {
        SimpleFeature feature = featureIterator.next();
        List<Object> values = feature.getAttributes();
        String line = values.stream().map(Object::toString).collect(Collectors.joining(","));
        bufferedWriter.newLine();
        bufferedWriter.write(line);
        bufferedWriter.flush();
    }
    featureIterator.close();
    bufferedWriter.close();
    fileOutputStream.close();
}

