import org.openscience.cdk.smiles.smarts.SMARTSQueryTool;

import java.util.HashMap;
import java.util.Map;

public Map<Integer, String> obtainInChINumbers(IAtomContainer container) throws CDKException {
    Map<Integer, String> inchiAtomMap = new HashMap<>();
    InChIGeneratorFactory factory = InChIGeneratorFactory.getInstance();
    InChIToStructure ichiToStructure = factory.getInChIToStructure(container, new HashMap<>());
    IAtom[] atoms = container.getAtoms();
    for (int i = 0; i < atoms.length; i++) {
        IAtom atom = atoms[i];
        String inchi = ichiToStructure.getAtomInChI(atom);
        if (inchi != null) {
            String[] inchiParts = inchi.split("/");
            String inchiAtom = inchiParts[1];
            inchiAtomMap.put(i, inchiAtom);
        } else {
            int hLabel = 0;
            boolean isHydrogen = atom.getSymbol().equals("H");
            if (isHydrogen) {
                boolean[] connected = new boolean[6];
                int connectedCount = atom.getAtomContainer().getConnectedAtomsCount(atom);
                if (connectedCount == 1) {
                    IAtom connectedAtom = atom.getAtomContainer().getConnectedAtomsList(atom).get(0);
                    if (connectedAtom.getSymbol().equals("C")) {
                        boolean[] cConnected = new boolean[4];
                        int cConnectedCount = connectedAtom.getAtomContainer().getConnectedAtomsCount(connectedAtom);
                        if (cConnectedCount > 1) {
                            for (IAtom cAtom : connectedAtom.getAtomContainer().getConnectedAtomsList(connectedAtom)) {
                                if (cAtom.getSymbol().equals("C")) {
                                    int bondOrder = connectedAtom.getAtomContainer().getBondOrder(connectedAtom, cAtom);
                                    cConnected[bondOrder - 1] = true;
                                }
                            }
                        }
                        boolean isConnected = false;
                        for (int j = 0; j < cConnected.length; j++) {
                            if (cConnected[j]) {
                                isConnected = true;
                                break;
                            }
                        }
                        if (isConnected) {
                            SMARTSQueryTool queryTool = new SMARTSQueryTool("[H][C]");
                            queryTool.setSmartsIndex("mol");
                            boolean isBridge = queryTool.matches(atom.getAtomContainer());
                            if (!isBridge) {
                                hLabel = 1;
                            }
                        }
                    }
                }
            }
            inchiAtomMap.put(i, String.format("H%d", hLabel));
        }
    }
    return inchiAtomMap;
}

