public static List<Class<?>> removeClassesInSamePackage(Package pkg) {
    List<Class<?>> classes = new ArrayList<>();
    String packageName = pkg.getName();
    for (Class<?> clazz : getAllClasses()) {
        if (clazz.getPackage().getName().equals(packageName)) {
            continue;
        }
        classes.add(clazz);
    }
    return classes;
}

private static List<Class<?>> getAllClasses() {
    List<Class<?>> classes = new ArrayList<>();
    try {
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
        URL root = classLoader.getResource("");
        String rootPath = root.getPath();
        File rootDir = new File(rootPath);
        if (!rootDir.isDirectory()) {
            rootDir = rootDir.getParentFile();
        }
        String packageName = "";
        for (File file : rootDir.listFiles()) {
            packageName = "";
            if (file.isDirectory()) {
                packageName = file.getName();
                classes.addAll(getAllClassesInPackage(packageName));
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
    return classes;
}

private static List<Class<?>> getAllClassesInPackage(String packageName) throws ClassNotFoundException {
    List<Class<?>> classes = new ArrayList<>();
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    String path = packageName.replace('.', '/');
    Enumeration<URL> resources = classLoader.getResources(path);
    while (resources.hasMoreElements()) {
        URL resource = resources.nextElement();
        File directory = new File(resource.getFile());
        if (!directory.isDirectory()) {
            continue;
        }
        File[] files = directory.listFiles();
        for (File file : files) {
            String fileName = file.getName();
            if (fileName.endsWith(".class")) {
                String className = packageName + '.' + fileName.substring(0, fileName.length() - 6);
                Class<?> clazz = Class.forName(className);
                classes.add(clazz);
            }
        }
    }
    return classes;
}

