public boolean containsSipApplicationAnnotation(InputStream is) throws IOException {
    int MAGIC = 0xCAFEBABE;
    int MAJOR_VERSION = 49;

    DataInputStream dis = new DataInputStream(is);
    int magic = dis.readInt();
    if (magic != MAGIC) {
        throw new IllegalArgumentException("Invalid class file format");
    }

    int minorVersion = dis.readUnsignedShort();
    int majorVersion = dis.readUnsignedShort();
    if (majorVersion < MAJOR_VERSION) {
        throw new IllegalArgumentException("Unsupported class file version");
    }

    dis.skipBytes(4); // skip constant_pool_count

    int accessFlags = dis.readUnsignedShort();
    if ((accessFlags & 0x200) == 0) {
        return false; // not an interface
    }

    dis.skipBytes(2); // skip this_class

    int superClassIndex = dis.readUnsignedShort();
    if (superClassIndex != 0) {
        return false; // not a top-level interface
    }

    int interfaceCount = dis.readUnsignedShort();
    for (int i = 0; i < interfaceCount; i++) {
        int interfaceIndex = dis.readUnsignedShort();
        dis.mark(Integer.MAX_VALUE);
        dis.reset();
        if (interfaceIndex > 0 && this.getConstantPoolString(dis, interfaceIndex).equals("Ljavax/sip/SipApplication;")) {
            return true;
        }
    }

    return false;
}

private String getConstantPoolString(DataInputStream dis, int index) throws IOException {
    dis.mark(Integer.MAX_VALUE);
    dis.skipBytes(8); // skip first 8 bytes of cp_info
    for (int i = 1; i < index; i++) {
        byte tag = dis.readByte();
        switch (tag) {
            case 1:
                int length = dis.readUnsignedShort();
                dis.skipBytes(length);
                break;
            case 3:
            case 4:
                dis.skipBytes(4);
                break;
            case 5:
            case 6:
                dis.skipBytes(8);
                break;
            case 7:
            case 8:
                dis.skipBytes(2);
                break;
            case 9:
            case 10:
            case 11:
            case 12:
                dis.skipBytes(4);
                break;
            case 15:
                dis.skipBytes(4);
                dis.skipBytes(4);
                break;
            default:
                throw new IllegalArgumentException("Invalid constant pool tag");
        }
    }
    String value = dis.readUTF();
    dis.reset();
    return value;
}

