import java.util.ArrayList;
import java.util.List;

public class InlineDiff {

    public static List<String> buildInlineDiff(String previous, String next) {
        List<String> diffChunks = new ArrayList<>();

        if (previous.equals(next)) {
            diffChunks.add(previous);
            return diffChunks;
        }

        StringBuilder currentChunk = new StringBuilder();
        int i = 0;

        while (i < previous.length() && i < next.length()) {
            char c1 = previous.charAt(i);
            char c2 = next.charAt(i);

            if (c1 != c2) {
                currentChunk.append(c2);
            } else {
                if (currentChunk.length() > 0) {
                    diffChunks.add(currentChunk.toString());
                    currentChunk = new StringBuilder();
                }
                diffChunks.add(String.valueOf(c1));
            }

            i++;
        }

        if (i < next.length()) {
            currentChunk.append(next.substring(i));
        } else if (i < previous.length()) {
            diffChunks.add(currentChunk.toString());
            currentChunk = new StringBuilder();
            currentChunk.append(previous.substring(i));
        }

        if (currentChunk.length() > 0) {
            diffChunks.add(currentChunk.toString());
        }

        return diffChunks;
    }
}

