public ValidationResult checkCoverage(Entry entry) {
    ValidationResult result = new ValidationResult();
    List<Feature> features = entry.getFeatures();
    if (features == null || features.isEmpty()) {
        result.addError("No features found in the entry");
        return result;
    }
    int totalLength = entry.getSequence().getLength();
    int coveredLength = 0;
    for (Feature feature : features) {
        Location location = feature.getLocation();
        if (location == null) {
            result.addError("No location found for feature: " + feature.getName());
            continue;
        }
        coveredLength += location.getRange().getLength();
    }
    double coverage = ((double)coveredLength/totalLength) * 100;
    if (coverage < 100) {
        result.addWarning("Sequence not fully covered. Coverage is " + coverage + "%");
    }
    return result;
}

