        while (length > 0) {
            long chunkSize = Math.min(length, ASYNC_COPY_CHUNK_SIZE);
            unsafe.copyMemory(srcAddress, dstAddress, chunkSize);
            srcAddress += chunkSize;
            dstAddress += chunkSize;
            length -= chunkSize;
        }
    } else {
        byte[] srcArray = srcPointer.getByteArray(0, (int) length);
        dstBuffer.position(dstOffset);
        dstBuffer.put(srcArray);
    }
}

