public void saveEngineAsFuzzyLiteDataset(String file, Engine engine, List<String> reader) throws IOException {
    try (BufferedWriter writer = new BufferedWriter(new FileWriter(file))) {
        writer.write("[Engine]\n");
        writer.write("Name=" + engine.getName() + "\n");
        writer.write("Type=" + engine.getType() + "\n");
        writer.write("Version=" + engine.getVersion() + "\n");
        writer.write("Description=" + engine.getDescription() + "\n");
        writer.write("\n");
        writer.write("[InputVariables]\n");
        for (InputVariable inputVariable : engine.getInputVariables()) {
            writer.write(inputVariableToFuzzyLiteString(inputVariable));
            writer.write("\n");
        }
        writer.write("\n");
        writer.write("[OutputVariables]\n");
        for (OutputVariable outputVariable : engine.getOutputVariables()) {
            writer.write(outputVariableToFuzzyLiteString(outputVariable));
            writer.write("\n");
        }
        writer.write("\n");
        writer.write("[RuleBlocks]\n");
        for (RuleBlock ruleBlock : engine.getRuleBlocks()) {
            writer.write(ruleBlockToFuzzyLiteString(ruleBlock, reader));
            writer.write("\n");
        }
        writer.write("\n");
        writer.write("[Options]\n");
        writer.write("Debug=" + engine.getDebug() + "\n");
        writer.write("EngineSeed=" + engine.getEngineSeed() + "\n");
        writer.write("MaximumNumberOfThreads=" + engine.getMaximumNumberOfThreads() + "\n");
    }
}

private String inputVariableToFuzzyLiteString(InputVariable inputVariable) {
    StringBuilder sb = new StringBuilder();
    sb.append("[InputVariable]\n");
    sb.append("Name=" + inputVariable.getName() + "\n");
    sb.append("Enabled=" + inputVariable.isEnabled() + "\n");
    sb.append("Range=" + inputVariable.getMinimum() + " " + inputVariable.getMaximum() + "\n");
    sb.append("LockValueInRange=" + inputVariable.isLockValueInRange() + "\n");
    sb.append("Term\n");
    for (Term term : inputVariable.getTerms()) {
        sb.append(term.getName() + ": " + term.toString() + "\n");
    }
    sb.append("\n");
    return sb.toString();
}

private String outputVariableToFuzzyLiteString(OutputVariable outputVariable) {
    StringBuilder sb = new StringBuilder();
    sb.append("[OutputVariable]\n");
    sb.append("Name=" + outputVariable.getName() + "\n");
    sb.append("Enabled=" + outputVariable.isEnabled() + "\n");
    sb.append("Range=" + outputVariable.getMinimum() + " " + outputVariable.getMaximum() + "\n");
    sb.append("LockOutputInRange=" + outputVariable.isLockOutputInRange() + "\n");
    sb.append("Default=" + outputVariable.getDefaultValue() + "\n");
    sb.append("Accumulation=" + outputVariable.fuzzyOutput().getAccumulation().getClass().getSimpleName() + "\n");
    sb.append("Defuzzifier=" + outputVariable.getDefuzzifier().getClass().getSimpleName() + "\n");
    sb.append("Type=" + outputVariable.getOutputType() + "\n");
    sb.append("Term\n");
    for (Term term : outputVariable.getTerms()) {
        sb.append(term.getName() + ": " + term.toString() + "\n");
    }
    sb.append("\n");
    return sb.toString();
}

private String ruleBlockToFuzzyLiteString(RuleBlock ruleBlock, List<String> reader) {
    StringBuilder sb = new StringBuilder();
    sb.append("[RuleBlock]\n");
    sb.append("Name=" + ruleBlock.getName() + "\n");
    sb.append("Enabled=" + ruleBlock.isEnabled() + "\n");
    sb.append("Conjunction=" + ruleBlock.getConjunction().getClass().getSimpleName() + "\n");
    sb.append("Disjunction=" + ruleBlock.getDisjunction().getClass().getSimpleName() + "\n");
    sb.append("Activation=" + ruleBlock.getActivation().getClass().getSimpleName() + "\n");
    sb.append("\n");
    sb.append("[Rules]\n");
    for (Rule rule : ruleBlock.getRules()) {
        sb.append(ruleToFuzzyLiteString(rule, reader));
        sb.append("\n");
    }
    sb.append("\n");
    return sb.toString();
}

private String ruleToFuzzyLiteString(Rule rule, List<String> reader) {
    StringBuilder sb = new StringBuilder();
    sb.append("IF ");
    for (int i = 0; i < rule.getAntecedents().size(); ++i) {
        Term term = rule.getAntecedents().get(i).getTerm();
        String termName = term.getName().replace(" ", "_");
        sb.append(" " + termName + " " + reader.get(i));
        if (i != rule.getAntecedents().size() - 1) {
            sb.append(" " + rule.getAntecedentConnectives().get(i) + " ");
        }
    }
    sb.append(" THEN ");
    sb.append(rule.getConsequents().get(0).getVariable().getName() + " is ");
    sb.append(rule.getConsequents().get(0).getTerm().getName().replace(" ", "_"));
    sb.append(" (" + rule.getWeight() + ")");
    return sb.toString();
}

