    public static boolean verify(byte[] hash, BigInteger r, BigInteger s, PublicKey publicKey, ECParameterSpec curve, String algorithm) throws Exception {

        // Create the EC point from R value.
        ECFieldFp field = (ECFieldFp) curve.getCurve().getField();
        BigInteger x = r;
        BigInteger ySqrt = x.multiply(x).multiply(x).add(curve.getCurve().getA().multiply(x)).add(curve.getCurve().getB()).mod(field.getP()).sqrt();
        BigInteger y = ySqrt.mod(BigInteger.valueOf(2)).equals(BigInteger.ZERO) ? ySqrt : field.getP().subtract(ySqrt);
        ECPoint pointR = curve.getCurve().createPoint(x, y);

        // Create Public Key using the point.
        ECPublicKeySpec keySpec = new ECPublicKeySpec(pointR, curve);
        KeyFactory keyFactory = KeyFactory.getInstance("EC");
        PublicKey pubKey = keyFactory.generatePublic(keySpec);

        // Verify the signature.
        Signature signature = Signature.getInstance(algorithm);
        signature.initVerify(pubKey);
        signature.update(hash);
        return signature.verify(convertDerEncoding(r, s));
    }

    private static byte[] convertDerEncoding(BigInteger r, BigInteger s) {
        byte[] rb = r.toByteArray();
        byte[] sb = s.toByteArray();

        int off = 0;
        if (rb[0] == 0) {
            off++;
        }

        int len = rb.length - off + sb.length + 4;
        byte[] der = new byte[len];

        der[0] = 48;
        der[1] = (byte) (len - 2);

        der[2] = 2;
        der[3] = (byte) (rb.length - off);
        System.arraycopy(rb, off, der, 4, rb.length - off);

        int index = 4 + rb.length - off;
        if (sb[0] == 0)
            off = 1;

        der[index++] = 2;
        der[index++] = (byte) (sb.length - off);
        System.arraycopy(sb, off, der, index, sb.length - off);

        return der;
    }
}

