public double activationDegree(TNorm conjunction, SNorm disjunction, Expression node) {
    if (node.isLeaf()) {
        return node.getValue();
    }

    double degree = 0.0;
    for (Expression child : node.getChildren()) {
        double childDegree = activationDegree(conjunction, disjunction, child);
        if (node.isConjunction()) {
            degree = conjunction.apply(degree, childDegree);
        } else {
            degree = disjunction.apply(degree, childDegree);
        }
    }

    return degree;
}

