import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.jar.JarEntry;
import java.util.jar.JarOutputStream;

public class Jar {
    private File jarFile;

    public Jar(String jarFilePath) {
        this.jarFile = new File(jarFilePath);
    }

    public void addEntry(String path, String filePath) throws IOException {
        File file = new File(filePath);
        if (!file.exists()) {
            throw new IOException("File not found: " + filePath);
        }

        JarEntry entry = new JarEntry(path);
        entry.setTime(file.lastModified());
        entry.setSize(file.length());

        try (JarOutputStream jar = new JarOutputStream(new FileOutputStream(jarFile, true))) {
            jar.putNextEntry(entry);
            try (FileInputStream in = new FileInputStream(file)) {
                byte[] buffer = new byte[1024];
                int lengthRead;
                while ((lengthRead = in.read(buffer)) > 0) {
                    jar.write(buffer, 0, lengthRead);
                }
            }
            jar.closeEntry();
        }
    }
}

