public static Statement findStatement(Statement stm, int lineno) {
    if (stm.getStartPosition().getLineNumber() > lineno || stm.getEndPosition().getLineNumber() < lineno) {
        return null;
    }
    if (stm instanceof BlockStmt) {
        for (Statement s : ((BlockStmt) stm).getStatements()) {
            Statement result = findStatement(s, lineno);
            if (result != null) {
                return result;
            }
        }
    } else if (stm instanceof LabeledStmt) {
        return findStatement(((LabeledStmt) stm).getStatement(), lineno);
    } else if (stm instanceof IfStmt) {
        IfStmt ifStmt = (IfStmt) stm;
        Statement thenStmt = ifStmt.getThenStmt();
        Statement elseStmt = ifStmt.getElseStmt().orElse(null);
        Statement result = findStatement(thenStmt, lineno);
        if (result == null) {
            result = findStatement(elseStmt, lineno);
        }
        return result;
    } else if (stm instanceof ForStmt) {
        ForStmt forStmt = (ForStmt) stm;
        Statement result = findStatement(forStmt.getBody(), lineno);
        return result;
    } else if (stm instanceof ForEachStmt) {
        ForEachStmt forEachStmt = (ForEachStmt) stm;
        Statement result = findStatement(forEachStmt.getBody(), lineno);
        return result;
    } else if (stm instanceof WhileStmt) {
        WhileStmt whileStmt = (WhileStmt) stm;
        Statement result = findStatement(whileStmt.getBody(), lineno);
        return result;
    } else if (stm instanceof DoStmt) {
        DoStmt doStmt = (DoStmt) stm;
        Statement result = findStatement(doStmt.getBody(), lineno);
        return result;
    } else if (stm instanceof SwitchStmt) {
        SwitchStmt switchStmt = (SwitchStmt) stm;
        for (SwitchEntryStmt entry : switchStmt.getEntries()) {
            Statement result = findStatement(entry, lineno);
            if (result != null) {
                return result;
            }
        }
    } else if (stm instanceof SwitchEntryStmt) {
        SwitchEntryStmt switchEntryStmt = (SwitchEntryStmt) stm;
        for (Statement s : switchEntryStmt.getStatements()) {
            Statement result = findStatement(s, lineno);
            if (result != null) {
                return result;
            }
        }
    } else if (stm instanceof TryStmt) {
        TryStmt tryStmt = (TryStmt) stm;
        for (Statement s : tryStmt.getResources()) {
            Statement result = findStatement(s, lineno);
            if (result != null) {
                return result;
            }
        }
        for (CatchClause c : tryStmt.getCatchClauses()) {
            Statement result = findStatement(c.getBody(), lineno);
            if (result != null) {
                return result;
            }
        }
        Statement result = findStatement(tryStmt.getTryBlock(), lineno);
        if (result == null) {
            result = findStatement(tryStmt.getFinallyBlock().orElse(null), lineno);
        }
        return result;
    } else if (stm instanceof SynchronizedStmt) {
        SynchronizedStmt synchronizedStmt = (SynchronizedStmt) stm;
        return findStatement(synchronizedStmt.getBody(), lineno);
    } else if (stm instanceof ExpressionStmt) {
        ExpressionStmt expressionStmt = (ExpressionStmt) stm;
        return findStatement(expressionStmt.getExpression(), lineno);
    }
    return stm;
}

