public PStm findStatement(PStm stm, int lineno) {
	if (stm == null) {
        return null;
    }
    if (stm.getLineNumber() == lineno) {
        return stm;
    }
    if (stm instanceof PBlock) {
        PBlock block = (PBlock) stm;
        for (PStm subStm : block.getStatements()) {
            PStm result = findStatement(subStm, lineno);
            if (result != null) {
                return result;
            }
        }
    } else if (stm instanceof PIf) {
        PIf ifStmt = (PIf) stm;
        PStm result = findStatement(ifStmt.getThenStatement(), lineno);
        if (result != null) {
            return result;
        }
        if (ifStmt.getElseStatement() != null) {
            result = findStatement(ifStmt.getElseStatement(), lineno);
            if (result != null) {
                return result;
            }
        }
    } else if (stm instanceof PWhile) {
        PWhile whileStmt = (PWhile) stm;
        return findStatement(whileStmt.getBody(), lineno);
    } else if (stm instanceof PFor) {
        PFor forStmt = (PFor) stm;
        return findStatement(forStmt.getBody(), lineno);
    }
    return null;
}

