import javax.faces.context.FacesContext;

public static UIComponent getCompositeComponentBasedOnLocation(final FacesContext facesContext, final UIComponent location, int ccLevel) {
    UIComponent current = location;
    for (int i = 0; i < ccLevel; i++) {
        if (current.getParent() != null) {
            current = current.getParent();
        } else {
            // If the parent is null, it means we've reached the root of the component tree
            // and there's no more parents to go up.
            break;
        }
    }
    return current;
}

