private Object convertConfigElementToSingleValue(ConfigElement childElement, ExtendedAttributeDefinition attrDef, EvaluationContext context, int index, boolean ignoreWarnings) throws ConfigEvaluatorException {
	// Check if the childElement is null
    if (childElement == null) {
        return null;
    }

    // Check if the childElement is a simple value
    if (childElement.isSimpleValue()) {
        return childElement.getValue();
    }

    // Check if the childElement is a reference
    if (childElement.isReference()) {
        String referenceKey = childElement.getReferenceKey();
        Object referencedValue = context.getReference(referenceKey);
        if (referencedValue == null) {
            if (!ignoreWarnings) {
                throw new ConfigEvaluatorException("Reference key '" + referenceKey + "' not found in context.");
            }
            return null;
        }
        return referencedValue;
    }

    // Check if the childElement is a list
    if (childElement.isList()) {
        List<ConfigElement> listElements = childElement.getListElements();
        List<Object> convertedList = new ArrayList<>();
        for (ConfigElement element : listElements) {
            Object convertedValue = convertConfigElementToSingleValue(element, attrDef, context, index, ignoreWarnings);
            convertedList.add(convertedValue);
        }
        return convertedList;
    }

    // Check if the childElement is a map
    if (childElement.isMap()) {
        Map<String, ConfigElement> mapElements = childElement.getMapElements();
        Map<String, Object> convertedMap = new HashMap<>();
        for (Map.Entry<String, ConfigElement> entry : mapElements.entrySet()) {
            String key = entry.getKey();
            ConfigElement valueElement = entry.getValue();
            Object convertedValue = convertConfigElementToSingleValue(valueElement, attrDef, context, index, ignoreWarnings);
            convertedMap.put(key, convertedValue);
        }
        return convertedMap;
    }

    // If none of the above conditions are met, throw an exception
    throw new ConfigEvaluatorException("Unsupported ConfigElement type.");
}

