        char ch = (char) c;
        if (ch == symbols.getEscapeChar()) {
            c = reader.read();
            if (c != -1) {
                char nextCh = (char) c;
                if (symbols.isEscapeChar(nextCh)) {
                    writer.write(symbols.getUnescapedChar(nextCh));
                } else {
                    writer.write(ch);
                    writer.write(nextCh);
                }
            } else {
                writer.write(ch);
            }
        } else {
            writer.write(ch);
        }
    }
    writer.flush();
}

