            if (off == 0) {
                return C.listOf(this);
            }

            if (!limited || list.size() < limit) {
                list.add(substr(off, buf.length));
            }

            int resultSize = list.size();
            if (limit == 0) {
                while (resultSize > 0 && list.get(resultSize - 1).length() == 0) {
                    resultSize--;
                }
            }
