public void createJSONRepresentation(GelfMessage message, ByteBuffer byteBuffer, String additionalFieldPrefix) {
        Objects.requireNonNull(byteBuffer, "byteBuffer must not be null");
        Objects.requireNonNull(additionalFieldPrefix, "additionalFieldPrefix must not be null");

        JSONObject jsonObject = new JSONObject();

        for (GelfMessageField field : message.getFields()) {
            String key = field.getFieldName();

            // If key starts with '_' and additionalFieldPrefix is provided, use it as prefix
            if (key.startsWith("_") && additionalFieldPrefix.length() > 0) {
                key = additionalFieldPrefix + key;
            }

            if (field.getType() == GelfMessageFieldType.UNKNOWN) {
                jsonObject.put(key, field.getDefaultValue());
            } else {
                switch (field.getType()) {
                    case NUMBER:
                        try {
                            jsonObject.put(key, Double.parseDouble(field.getStringValue()));
                        } catch (NumberFormatException e) {
                            jsonObject.put(key, field.getDefaultValue());
                        }
                        break;
                    case BOOLEAN:
                        jsonObject.put(key, Boolean.parseBoolean(field.getStringValue()));
                        break;
                    case STRING:
                    case ENUM:
                        jsonObject.put(key, field.getStringValue());
                        break;
                    case LONG:
                        try {
                            jsonObject.put(key, Long.parseLong(field.getStringValue()));
                        } catch (NumberFormatException e) {
                            jsonObject.put(key, field.getDefaultValue());
                        }
                        break;
                    case FLOAT:
                        try {
                            jsonObject.put(key, Float.parseFloat(field.getStringValue()));
                        } catch (NumberFormatException e) {
                            jsonObject.put(key, field.getDefaultValue());
                        }
                        break;
                    case NULL:
                        jsonObject.put(key, JSONObject.NULL);
                        break;
                    default:
                        throw new IllegalArgumentException("Unknown field type " + field.getType());
                }
            }
        }

        byteBuffer.put(jsonObject.toString().getBytes(StandardCharsets.UTF_8));
}

