public static double[][][] averagePooling3D(double[][][] inputs, int[] pooling3DConfig) {
    int inputDepth = inputs.length;
    int inputHeight = inputs[0].length;
    int inputWidth = inputs[0][0].length;
    int poolDepth = pooling3DConfig[0];
    int poolHeight = pooling3DConfig[1];
    int poolWidth = pooling3DConfig[2];
    int outDepth = inputDepth / poolDepth;
    int outHeight = inputHeight / poolHeight;
    int outWidth = inputWidth / poolWidth;
    double[][][] outputs = new double[outDepth][outHeight][outWidth];

    for (int d = 0; d < outDepth; d++) {
        for (int h = 0; h < outHeight; h++) {
            for (int w = 0; w < outWidth; w++) {
                int startD = d * poolDepth;
                int startH = h * poolHeight;
                int startW = w * poolWidth;
                double sum = 0.0;
                int count = 0;

                for (int i = startD; i < startD + poolDepth; i++) {
                    for (int j = startH; j < startH + poolHeight; j++) {
                        for (int k = startW; k < startW + poolWidth; k++) {
                            sum += inputs[i][j][k];
                            count++;
                        }
                    }
                }

                outputs[d][h][w] = sum / count;
            }
        }
    }

    return outputs;
}

