import java.util.ArrayList;
import java.util.List;

public class FibonacciHeap<T extends Comparable<T>> {
    private List<FibonacciHeapNode<T>> roots = new ArrayList<>();

    public static class FibonacciHeapNode<T extends Comparable<T>> implements Comparable<FibonacciHeapNode<T>> {
        T key;
        List<FibonacciHeapNode<T>> children = new ArrayList<>();

        public FibonacciHeapNode(T key) {
            this.key = key;
        }

        @Override
        public int compareTo(FibonacciHeapNode<T> o) {
            return key.compareTo(o.key);
        }
    }

    public void insert(T key) {
        roots.add(new FibonacciHeapNode<>(key));
    }

    public T findMin() {
        T min = roots.get(0).key;
        for (FibonacciHeapNode<T> root : roots) {
            if (root.key.compareTo(min) < 0) {
                min = root.key;
            }
        }
        return min;
    }

    public T deleteMin() {
        T min = findMin();
        roots.removeIf(node -> node.key.equals(min));
        return min;
    }

    public boolean isEmpty() {
        return roots.isEmpty();
    }
}

