public String nthRepeat(String input) {
    String output = "";
    int index = input.indexOf("[");
    if (index >= 0) {
        int endIndex = input.indexOf("]", index + 1);
        if (endIndex >= 0) {
            String repeatStr = input.substring(index + 1, endIndex);
            int repeatCount = parseRepeatNum(repeatStr);
            if (repeatCount > 0) {
                output = input.substring(endIndex + 1);
                String repeatedText = repeatText(repeatStr);
                for (int i = 1; i < repeatCount; i++) {
                    output = output.replaceAll("\\b" + repeatStr + "\\b", repeatedText);
                }
                output = output.replaceAll("\\b" + repeatStr + "\\b", repeatedText.substring(0, repeatedText.length() - 1));
            }
        }
    }
    return output;
}

private int parseRepeatNum(String input) {
    String[] tokens = input.split(":|\\|");
    if (tokens.length == 1) {
        return Integer.parseInt(tokens[0].trim());
    } else {
        return Integer.parseInt(tokens[1].trim());
    }
}

private String repeatText(String input) {
    String[] tokens = input.split(":|\\|");
    if (tokens.length == 1) {
        char c = tokens[0].charAt(0);
        return new String(new char[c - '0' + 1]).replace('\0', c);
    } else {
        char c = tokens[0].charAt(0);
        int n = Integer.parseInt(tokens[1].trim());
        return new String(new char[n]).replace('\0', c);
    }
}

