public void handle(WebContext webContext) throws Exception {
    File file = new File("myfile.txt");
    FileInputStream fileIn = new FileInputStream(file);
    OutputStream out = webContext.getResponse().getOutputStream();

    // Set the response headers
    String mimeType = URLConnection.guessContentTypeFromName(file.getName());
    if (mimeType == null) {
        mimeType = "application/octet-stream";
    }

    webContext.getResponse().setContentType(mimeType);
    webContext.getResponse().setHeader("Content-Disposition", "attachment; filename=\"" + file.getName() + "\"");
    webContext.getResponse().setContentLength((int) file.length());

    // Write the file to the response
    byte[] buffer = new byte[4096];
    int length;
    while ((length = fileIn.read(buffer)) > 0) {
        out.write(buffer, 0, length);
    }

    // Close the streams
    fileIn.close();
    out.flush();
    out.close();
}

