public static int epollBusyWait(FileDescriptor fd, EpollEventArray events, FileDescriptor waitFd, int timeoutMs, int busyLoopMs) throws IOException {
    final long start = System.nanoTime();
    long timeout = TimeUnit.MILLISECONDS.toNanos(timeoutMs);
    long busyLoop = TimeUnit.MILLISECONDS.toNanos(busyLoopMs);
    int ready = 0;
    int n;
    do {
        n = epollWait(fd, events, waitFd, 0, (int) timeout);
        if (n == -1) {
            if (errno() == EINTR) {
                Thread.interrupted();
            }
            else {
                throw new IOException();
            }
        }
        else if (n == 0) {
            return 0;
        }
        else {
            ready = n;
        }
        final long elapsed = System.nanoTime() - start;
        timeout = TimeUnit.MILLISECONDS.toNanos(timeoutMs) - elapsed;
        if (timeout < busyLoop) {
            break;
        }
        if (ready == 0) {
            if (ThreadLocalRandom.current().nextInt(1, 100) == 1) {
                Thread.yield();
            }
            else {
                LockSupport.parkNanos(1);
            }
        }
    } while (timeout > busyLoop);
    return ready;
}

