public String genMsgPluralCodeBits(
        SoyMsgPluralPart pluralPart, MsgNode msgNode, CodeGenInfo codeGenInfo) {

    // create StringBuilder to accumulate code bits
    StringBuilder codeBits = new StringBuilder();

    // generate code for opening of plural statement
    codeBits.append("{").
             append(pluralPart.getPluralVarName()).
             append("}").
             append(" ").append("=").append(" ");
    codeBits.append(pluralPart.getExpr().toSourceString());
    codeBits.append(";");
    codeBits.append(System.lineSeparator());

    // generate code for each case statement
    for (SoyMsgPluralCaseSpec caseSpec : pluralPart.getCases()) {

        if (caseSpec.isDefault()) {
            codeBits.append("default");
        } else {
            codeBits.append("case ").append(caseSpec.getSpec()).append(":");
        }
        codeBits.append(System.lineSeparator());

        // iterate over messages in this case
        for (SoyMsgPart msgPart : caseSpec.getParts()) {
            // generate code for each message part
            if (msgPart instanceof SoyMsgRawTextPart) {
                codeBits.append(
                    EscapeHtml.INSTANCE.escape(((SoyMsgRawTextPart) msgPart).getRawText()));
            } else if (msgPart instanceof SoyMsgPluralRemainderPart) {
                codeBits.append(
                    "{" + pluralPart.getRemainderVarName() + "}");
            } else {
                // message part is not plain text or plural remainder
                // generate code for message placeholders
                codeBits.append(
                    msgPart.genBaseCode(codeGenInfo.getVarNameForMsgPart(msgPart), false, ""));
            }
            codeBits.append(System.lineSeparator());
        }

        codeBits.append("break;");
        codeBits.append(System.lineSeparator());
    }

    // generate code for closing of plural statement
    codeBits.append("}");

    return codeBits.toString();
}

