    Service service = client.services().inNamespace(serviceNamespace).withName(serviceName).get();

    if (service == null) {
        throw new IllegalArgumentException("Service not found");
    }

    String clusterIP = service.getSpec().getClusterIP();
    String port = String.valueOf(service.getSpec().getPorts().get(0).getPort());

    if (serviceExternal) {
        // If the service is external, we need to get the external IP
