        String externalIP = service.getStatus().getLoadBalancer().getIngress().get(0).getIp();
        return serviceProtocol + "://" + externalIP + ":" + port;
    } else {
        // If the service is not external, we can use the cluster IP
        return serviceProtocol + "://" + clusterIP + ":" + port;
    }
}

