public static double[][] reverseSequence(String name, double[][] x, int[] seq_lengths, int seqDim, int batchDim) {
    int length = x.length;
    int numOfSequences = x[0].length / seq_lengths[seqDim];
    double[][] reversedSequences = new double[length][x[0].length];

    for (int i = 0; i < numOfSequences; i++) {
        for (int j = 0; j < length; j++) {
            int sliceStart = i * seq_lengths[seqDim];
            int sliceEnd = sliceStart + seq_lengths[seqDim];
            int reversedSliceStart = sliceEnd - seq_lengths[seqDim];
            if (j >= reversedSliceStart) {
                int currentSeqPos = j % seq_lengths[seqDim] + sliceStart;
                int reversedSeqPos = sliceEnd - 1 - currentSeqPos;
                reversedSequences[j][i * seq_lengths[seqDim] + currentSeqPos - sliceStart] = x[j][reversedSeqPos];
            } else {
                reversedSequences[j][i * seq_lengths[seqDim] + j % seq_lengths[seqDim]] = x[j][i * seq_lengths[seqDim] + j % seq_lengths[seqDim]];
            }
        }
    }
    return reversedSequences;
}

