public static void quickSortWithoutRecursion(int[] arr, int[] brr, int n) {
    Stack<Integer> stack = new Stack<Integer>();
    stack.push(0);
    stack.push(n - 1);
    while (!stack.isEmpty()) {
        int end = stack.pop();
        int start = stack.pop();
        int pivotIndex = partition(arr, start, end, brr);
        if (pivotIndex - 1 > start) {
            stack.push(start);
            stack.push(pivotIndex - 1);
        }
        if (pivotIndex + 1 < end) {
            stack.push(pivotIndex + 1);
            stack.push(end);
        }
    }
}

private static int partition(int[] arr, int start, int end, int[] brr) {
    int pivot = arr[end];
    int i = start - 1;
    for (int j = start; j < end; j++) {
        if (arr[j] < pivot) {
            i++;
            swap(arr, i, j);
            swap(brr, i, j);
        }
    }
    i++;
    swap(arr, i, end);
    swap(brr, i, end);
    return i;
}

private static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

