public static String[] replaceProperties(String[] args, Map<String, String> data) {
    String[] replacedArgs = new String[args.length];
    for (int i = 0; i < args.length; i++) {
        String replacedArg = args[i];
        for (Map.Entry<String, String> entry : data.entrySet()) {
            String key = "${" + entry.getKey() + "}";
            String value = entry.getValue();
            replacedArg = replacedArg.replaceAll(key, value);
        }
        replacedArgs[i] = replacedArg;
    }
    return replacedArgs;
}

