private static String replaceDataReferences(final String input, final Map<String, Map<String, String>> data) {
    // Implement the method to replace embedded properties in the input String with the value from the data context
    StringBuilder result = new StringBuilder();
    int start = 0;
    int end;
    while ((start = input.indexOf("${", start)) != -1) {
        end = input.indexOf("}", start);
        if (end == -1) {
            break; // No closing brace found, break the loop
        }
        String key = input.substring(start + 2, end);
        String[] keyParts = key.split("\\.");
        String value = getValueFromDataContext(keyParts, data);
        if (value != null) {
            result.append(input, 0, start);
            result.append(value);
            start = end + 1;
        } else {
            result.append(input, 0, end + 1);
            start = end + 1;
        }
    }
    result.append(input.substring(start));
    return result.toString();
}

private static String getValueFromDataContext(final String[] keyParts, final Map<String, Map<String, String>> data) {
    // Implement the method to get the value from the data context based on the key parts
    if (keyParts.length < 2) {
