public Set<BitSet> pruneCandidates(Map<BitSet, Integer> supported, int length, int dim) {
    Set<BitSet> prunedItemsets = new HashSet<>(supported.keySet());
    for (BitSet itemset : supported.keySet()) {
        for (int i = itemset.nextSetBit(0); i >= 0 && i < dim; i = itemset.nextSetBit(i+1)) {
            BitSet flipped = (BitSet) itemset.clone();
            flipped.flip(i);
            if (!supported.containsKey(flipped)) {
                prunedItemsets.remove(itemset);
                break;
            }
        }
    }
    return prunedItemsets;
}

