public static <T> Predicate<T> mapCriteriaToPredicate(Map<String, Object> criteria) {
    return (Predicate<T>) criteria.entrySet().stream()
        .map(entry -> {
            String key = entry.getKey();
            Object value = entry.getValue();
            // Assuming key is a method name and value is the argument to that method
            return (Predicate<T>) (t -> {
                try {
                    Method method = t.getClass().getMethod(key);
                    return method.invoke(t).equals(value);
                } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
                    throw new RuntimeException("Error mapping criteria to predicate", e);
                }
            });
        })
        .reduce(Predicate::and)
        .orElse(t -> true);
}

