    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < parameters.length; i++) {
        sb.append(parameters[i].type().qualifiedTypeName());
        sb.append(" ");
        sb.append(parameters[i].name());
        if (i < parameters.length - 1) {
            sb.append(", ");
        }
    }
    return sb.toString();
}

