public static boolean clipLine(Rectangle clipRect, Line2D line) {
        // Get the end points of the line
        double x1 = line.getX1();
        double y1 = line.getY1();
        double x2 = line.getX2();
        double y2 = line.getY2();

        // Clip the line against the clip rectangle
        int code1 = outcode(clipRect, x1, y1);
        int code2 = outcode(clipRect, x2, y2);
        boolean accept = false;

        while (true) {
            if ((code1 | code2) == 0) {
                // Both points inside clip rectangle
                accept = true;
                break;
            } else if ((code1 & code2) != 0) {
                // Both points are outside the same clip
                // edge.  Reject line.
                break;
            } else {
                // At least one point is outside the clip
                // rectangle; pick it.
                int codeOut = code1 != 0 ? code1 : code2;
                double x = 0, y = 0;

                // Find intersection point; use formulas:
                //   y = y1 + slope * (x - x1),
                //   x = x1 + (1/slope) * (y - y1),
                // where slope = (y2 - y1) / (x2 - x1).
                double slope = (y2 - y1) / (x2 - x1);

                if (codeOut == TOP) {           // point is above the clip rectangle
                    x = x1 + (clipRect.y - y1) / slope;
                    y = clipRect.y;
                } else if (codeOut == BOTTOM) { // point is below the clip rectangle
                    x = x1 + (clipRect.y + clipRect.height - y1) / slope;
                    y = clipRect.y + clipRect.height;
                } else if (codeOut == RIGHT) {  // point is to the right of clip rectangle
                    y = y1 + slope * (clipRect.x + clipRect.width - x1);
                    x = clipRect.x + clipRect.width;
                } else if (codeOut == LEFT) {   // point is to the left of clip rectangle
                    y = y1 + slope * (clipRect.x - x1);
                    x = clipRect.x;
                }
                // Now we move outside point to intersection point to clip
                // and get ready for next pass.
                if (codeOut == code1) {
                    x1 = x;
                    y1 = y;
                    code1 = outcode(clipRect, x1, y1);
                } else {
                    x2 = x;
                    y2 = y;
                    code2 = outcode(clipRect, x2, y2);
                }
            }
        }
        // Update the line with the clipped points and return the result
        if (accept) {
            line.setLine(x1, y1, x2, y2);
        }
        return accept;
    }

    // Compute the outcode for a point with respect to the specified clip
    // rectangle
    private static int outcode(Rectangle clipRect, double x, double y) {
        int code = INSIDE;          // starting with the mathematical inside
        if (clipRect.width <= 0) {  // make sure rectangle has non-zero width
            clipRect.width = 1;
        }
        if (clipRect.height <= 0) { // make sure rectangle has non-zero height
            clipRect.height = 1;
        }

        if (x < clipRect.x) {       // to the left of clip rectangle
            code |= LEFT;
        } else if (x > clipRect.x + clipRect.width) { // to the right of clip rectangle
            code |= RIGHT;
        }

        if (y < clipRect.y) {       // above the clip rectangle
            code |= TOP;
        } else if (y > clipRect.y + clipRect.height) { // below the clip rectangle
            code |= BOTTOM;
        }
        return code;
    }

    // Constants to be used as codes for the outcode function
    private static final int INSIDE = 0; // 0000
    private static final int LEFT = 1;   // 0001
    private static final int RIGHT = 2;  // 0010
    private static final int BOTTOM = 4; // 0100
    private static final int TOP = 8;    // 1000

