public static List<Class<?>> resolveClassesImplementingInterface(Class<?> interfaceClass) throws IOException {
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    String path = interfaceClass.getName().replace('.', '/') + ".class";
    Enumeration<URL> resources = classLoader.getResources(path);
    List<File> dirs = new ArrayList<>();
    while (resources.hasMoreElements()) {
        URL resource = resources.nextElement();
        String fileName = resource.getFile();
        String fileNameDecoded = URLDecoder.decode(fileName, "UTF-8");
        dirs.add(new File(fileNameDecoded));
    }

    List<Class<?>> classes = new ArrayList<>();
    for (File directory : dirs) {
        classes.addAll(findClasses(directory, interfaceClass));
    }

    return classes;
}

private static List<Class<?>> findClasses(File directory, Class<?> interfaceClass) {
    List<Class<?>> classes = new ArrayList<>();
    if (!directory.exists()) {
        return classes;
    }
    File[] files = directory.listFiles();
    if (files == null) {
        return classes;
    }
    for (File file : files) {
        if (file.isDirectory()) {
            classes.addAll(findClasses(file, interfaceClass));
        } else if (file.getName().endsWith(".class")) {
            String className = file.getName().substring(0, file.getName().length() - 6);
            try {
                Class<?> clazz = Class.forName(className);
                if (interfaceClass.isAssignableFrom(clazz)) {
                    classes.add(clazz);
                }
            } catch (ClassNotFoundException e) {
                e.printStackTrace();
            }
        }
    }
    return classes;
}

