/**
 * Similar to {@link #countDuplicatesAndAddTypeInfo} and {@link #countDuplicates} but (a) only
 * adds type info if requested and (b) returns a richer object containing the data.
 *
 * @param values       values to process
 * @param typeInfoOnly if true, only add type information
 * @return an object containing count, and if requested, type information and relative positions
 */
public static <T> Map<T, CountAndTypeInfo> countDuplicatesAndAddTypeInfoIfRequested(List<T> values, boolean typeInfoOnly) {
    Map<T, CountAndTypeInfo> result = new LinkedHashMap<>();
    Map<T, List<Integer>> indices = new HashMap<>();
    Map<T, Integer> countMap = new HashMap<>();

    for (int i = 0; i < values.size(); i++) {
        T value = values.get(i);
        countMap.put(value, countMap.getOrDefault(value, 0) + 1);
        indices.computeIfAbsent(value, k -> new ArrayList<>()).add(i);
    }

    for (Map.Entry<T, Integer> entry : countMap.entrySet()) {
        T value = entry.getKey();
        int count = entry.getValue();
        List<Integer> indexList = indices.get(value);
        if (typeInfoOnly) {
            result.put(value, new CountAndTypeInfo(count, value.getClass().getSimpleName()));
        } else {
            List<Integer> relativePositions = new ArrayList<>();
            for (int i = 0; i < indexList.size(); i++) {
                relativePositions.add(indexList.get(i) - i);
            }
            result.put(value, new CountAndTypeInfo(count, value.getClass().getSimpleName(), relativePositions));
        }
    }

    return result;
}

