import javax.servlet.http.HttpServletRequest;
import org.apache.commons.codec.binary.Base64;
import org.apache.commons.lang3.StringUtils;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.SignatureException;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public static String verifySignedRequest(HttpServletRequest request, String secret) throws LtiVerificationException {
    String result;
    try {
        Map<String, String[]> paramMap = request.getParameterMap();
        String oauth_signature = paramMap.get("oauth_signature")[0]; 
        paramMap.remove("oauth_signature");
        TreeMap<String, String> orderedParams = new TreeMap<>();

        for (Map.Entry<String, String[]> entry : paramMap.entrySet()) {
            String key = entry.getKey();
            String[] values = entry.getValue();
            String value = StringUtils.join(values, ",");
            orderedParams.put(key, value);
        }

        String method = request.getMethod();
        String url = request.getRequestURL().toString().toLowerCase();
        String paramString = "";

        for (Iterator<Map.Entry<String, String>> i = orderedParams.entrySet().iterator(); i.hasNext();) {
            Map.Entry<String, String> entry = i.next();

            if (!paramString.equals("")) {
                paramString += "&";
            }

            paramString += (entry.getKey() + "=" + entry.getValue());
        }

        String baseString = method + "&" + url + "&" + paramString;

        Mac mac = Mac.getInstance("HmacSHA1");
        SecretKeySpec secretKey = new SecretKeySpec((secret).getBytes("UTF-8"), "HmacSHA1");
        mac.init(secretKey);
        byte[] rawHmac = mac.doFinal(baseString.getBytes("UTF-8"));

        Base64 encoder = new Base64();
        String signature = new String(encoder.encode(rawHmac), "UTF-8");

        if (!signature.equals(oauth_signature)) {
            throw new LtiVerificationException("The signature of the LTI message is invalid");
        } else {
            List<String> info = new ArrayList<>();
            for (String paramName : orderedParams.keySet()) {
                String value = request.getParameter(paramName);

                if (!value.equals("")) {
                    info.add(paramName + "=" + value);
                }
            }
            result = StringUtils.join(info.toArray(), "\n");
            return result;
        }
    } catch (NoSuchAlgorithmException | InvalidKeyException | SignatureException e) {
        throw new LtiVerificationException("Error verifying LTI message", e);
    }
}

