public final class DriverServiceLauncher {
  private static final Logger LOG = Logger.getLogger(DriverServiceLauncher.class.getName());

  private final JobMessageObserverBridge messageBridge;
  private final EvaluatorRequest evaluatorRequest;

  @Inject
  private DriverServiceLauncher(@Parameter(DelegateDriverConfiguration.class) final Configuration driverConfiguration,
                                 final JobMessageObserverBridge messageBridge,
                                 final EvaluatorRequest... evaluatorRequests) {
    LOG.log(Level.FINEST, "Instantiating 'DriverServiceLauncher'");
    this.messageBridge = messageBridge;
    this.evaluatorRequest = evaluatorRequests.length == 0 ? null : evaluatorRequests[0];
    BuilderUtils.notNull(driverConfiguration, "driverConfiguration");
  }

  public REEFLauncher launch() throws InjectionException, IOException {
    final DriverRuntimeConfiguration driverRuntimeConfiguration = LocalRuntimeConfiguration.CONF
        .set(LocalRuntimeMaxNumberOfEvaluators, 1)
        .build();

    final LocalRuntimeFactory localRuntimeFactory = new LocalRuntimeFactory(driverRuntimeConfiguration);
    final Configuration runtimeConfiguration = Tang.Factory.getTang()
        .newConfigurationBuilder(localRuntimeFactory.getConfiguration())
        .build();

    final Configuration driverServiceConfiguration = DriverServiceConfiguration.CONF
        .set(DriverIdentifier.class, "MyDriver")
        .set(DriverConfigurationProvider.DRIVER_CONFIGURATION, driverConfiguration)
        .build();

    final REEFLauncher driverService = Tang.Factory.getTang()
        .newInjector(runtimeConfiguration, driverServiceConfiguration)
        .getInstance(REEFLauncher.class);

    final Configuration clientConf = ClientConfiguration.CONF
        .set(ClientIdentifier.class, "MyClient")
        .set(ClientConfiguration.ON_JOB_MESSAGE, (EventHandler<JobMessage>) messageBridge)
        .build();

    final JobMessageObserver jobMessageObserver = Tang.Factory.getTang()
        .newInjector(driverService.getDriverConfiguration(), clientConf)
        .getInstance(JobMessageObserver.class);

    messageBridge.setMessageObserver(jobMessageObserver);

    if (evaluatorRequest != null) {
      driverService.submit(evaluatorRequest);
    }
    return driverService;
  }
}

