import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

public static Collection<Class<?>> getClassesFromPackages(String... packageNames) throws Exception {
    List<Class<?>> classes = new ArrayList<>();
    for (String packageName : packageNames) {
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
        String path = packageName.replace('.', '/');
        for (java.net.URL resource : Collections.list(classLoader.getResources(path))) {
            classes.addAll(findClasses(resource, packageName));
        }
    }
    return classes;
}

private static List<Class<?>> findClasses(java.net.URL directory, String packageName) throws ClassNotFoundException {
    List<Class<?>> classes = new ArrayList<>();
    File dir = new File(directory.getPath());
    if (!dir.exists()) {
        return classes;
    }
    File[] files = dir.listFiles();
    for (File file : files) {
        if (file.isDirectory()) {
            assert !file.getName().contains(".");
            classes.addAll(findClasses(new URL(directory + "/" + file.getName()), packageName + "." + file.getName()));
        } else if (file.getName().endsWith(".class")) {
            classes.add(Class.forName(packageName + '.' + file.getName().substring(0, file.getName().length() - 6)));
        }
    }
    return classes;
}

