import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import org.jctools.queues.SpscArrayQueue;
import org.jctools.queues.SpscChunkedArrayQueue;
import org.jctools.queues.SpscGrowableArrayQueue;
import org.jctools.queues.atomic.SpscAtomicArrayQueue;

public class SPSCProxyChannel {

  public static <T> T createDefaultChannel(int capacity, Class<T> iFace, WaitStrategy waitStrategy) {

    BlockingQueue<T> queue;

    if (capacity < 1) {
      queue = new LinkedBlockingQueue<>();
    } else if (capacity == 1) {
      queue = new SpscArrayQueue<>(1);
    } else if (capacity <= 32) {
      queue = new SpscGrowableArrayQueue<>(capacity);
    } else if (capacity <= 1024) {
      queue = new SpscAtomicArrayQueue<>(capacity);
    } else {
      queue = new SpscChunkedArrayQueue<>(capacity, SpscChunkedArrayQueue.DEFAULT_CHUNK_SIZE);
    }

    return iFace.cast(new SPSCProxy(queue, waitStrategy).proxy());
  }

  private static class SPSCProxy<T> {

    private final BlockingQueue<T> queue;
    private final WaitStrategy waitStrategy;

    SPSCProxy(BlockingQueue<T> queue, WaitStrategy waitStrategy) {
      this.queue = queue;
      this.waitStrategy = waitStrategy;
    }

    Object proxy() {
      return new Object() {

        @SuppressWarnings("unchecked")
        T invoke(T t) throws InterruptedException {
          while (!queue.offer(t)) {
            waitStrategy.waitForSlot(queue);
          }
          return (T) queue.poll(0, TimeUnit.MICROSECONDS);
        }

      };
    }

  }

  private interface WaitStrategy {

    void waitForSlot(BlockingQueue<?> queue) throws InterruptedException;

  }

  private static final class BlockingWaitStrategy implements WaitStrategy {

    @Override
    public void waitForSlot(BlockingQueue<?> queue) throws InterruptedException {
      queue.put(queue.take());
    }

  }

  private static final class SleepingWaitStrategy implements WaitStrategy {

    private static final int SPIN_TRIES = 100;

    @Override
    public void waitForSlot(BlockingQueue<?> queue) throws InterruptedException {
      for (int i = 0; i < SPIN_TRIES; i++) {
        if (queue.offer(null)) {
          return;
        }
      }
      Thread.sleep(1);
    }

  }

}

