import org.hamcrest.BaseMatcher;
import org.hamcrest.Description;
import org.hamcrest.Matcher;
import org.objectweb.asm.tree.ClassNode;

public class AccessibleByteCodeElementMatcher<T extends ByteCodeElement> extends BaseMatcher<T> {

    private final Class<?> type;

    public AccessibleByteCodeElementMatcher(Class<?> type) {
        this.type = type;
    }

    @Override
    public boolean matches(Object item) {
        if (!(item instanceof ByteCodeElement)) {
            return false;
        }
        ByteCodeElement byteCodeElement = (ByteCodeElement) item;
        ClassNode classNode = byteCodeElement.getClassNode();
        if (classNode == null) {
            return false;
        }
        try {
            Class<?> clazz = Class.forName(classNode.name.replace("/", "."));
            return type.isAssignableFrom(clazz);
        } catch (ClassNotFoundException e) {
            return false;
        }
    }

    @Override
    public void describeTo(Description description) {
        description.appendText("AccessibleByteCodeElementMatcher");
    }

    public static <T extends ByteCodeElement> Matcher<T> isAccessibleTo(Class<?> type) {
        return new AccessibleByteCodeElementMatcher<>(type);
    }
}

