public class ObjectManager {
    private Map<Token, ManagedObject> store = new HashMap<>();

    public ManagedObject get(Token token) throws ObjectManagerException {
        if (token == null) {
            throw new ObjectManagerException("Token cannot be null");
        }

        ManagedObject obj = store.get(token);

        if (obj == null) {
            return null;
        }

        // Reinstantiate the object
        try {
            obj = obj.getClass().newInstance();
        } catch (InstantiationException | IllegalAccessException e) {
            throw new ObjectManagerException("Failed to reinstantiate object", e);
        }

        return obj;
    }

    public void put(Token token, ManagedObject obj) {
        store.put(token, obj);
    }
}

