public static JCStatement generateNullCheck(JavacTreeMaker maker, JavacNode variable, JavacNode source) {
	// Get the variable name
    String varName = variable.getName();

    // Create the exception message
    String message = "Variable " + varName + " is null";

    // Create the exception object
    JCExpression exception = maker.NewClass(
        null, 
        List.nil(), 
        maker.Ident(source.getSymbol().getQualifiedName().append("Exception")), 
        List.of(maker.Literal(message)), 
        null
    );

    // Create the throw statement
    JCThrow throwStatement = maker.Throw(exception);

    // Create the null check condition
    JCExpression condition = maker.Binary(
        JCTree.Tag.EQ, 
        variable.getExpression(), 
        maker.Literal(TypeTag.BOT, null)
    );

    // Create the if statement
    JCIf ifStatement = maker.If(
        condition, 
        throwStatement, 
        null
    );

    return ifStatement;
}

