public static <Result> InputStream submitApiRequest(ApiRequest apiRequest, ApiKeyCache apiKeyCache, ContentStreamHandler<Result> contentStreamHandler) throws IOException {
    URL url = apiRequest.getUrl(apiKeyCache);

    HttpURLConnection connection = (HttpURLConnection) url.openConnection();
    connection.setRequestMethod(apiRequest.getRequestMethod());
    connection.setConnectTimeout(apiRequest.getTimeout());
    connection.setRequestProperty("Accept-Encoding", "gzip");

    contentStreamHandler.setHeaders(connection);
    connection.connect();

    int responseCode = connection.getResponseCode();
    if (responseCode >= 400) {
        String responseMessage = connection.getResponseMessage();
        throw new APIException(String.format("Error: %d %s", responseCode, responseMessage));
    }

    InputStream contentStream = connection.getInputStream();
    String contentEncoding = connection.getContentEncoding();
    if (contentEncoding != null && contentEncoding.equalsIgnoreCase("gzip")) {
        contentStream = new GZIPInputStream(contentStream);
    }

    return contentStream;
}

