public void bindProperty(Triple triple, Model model) throws Exception {
    if(triple == null || model == null) {
        throw new IllegalArgumentException("Both triple and model arguments are required.");
    }

    Resource subject = model.createResource(triple.getSubject().getURI());
    Property predicate = model.createProperty(triple.getPredicate().getURI());
    RDFNode object = null;
    if(triple.getObject().isURI()) {
        object = model.createResource(triple.getObject().getURI());
    } else if(triple.getObject().isLiteral()) {
        object = model.createLiteral(triple.getObject().getLiteralValue().toString());
    } else {
        throw new IllegalArgumentException("Unsupported RDF node type.");
    }

    Statement statement = model.createStatement(subject, predicate, object);
    try {
        model.add(statement);
    } catch(InvalidPropertyURIException | InvalidResourceURIException | InvalidLiteralException e) {
        throw new Exception("Failed to bind the property. " + e.getMessage());
    }
}

