public static double[] findEigenvaluesOfHessenbergMatrix(double[][] A) {
    int n = A.length;
    double[] eigenvalues = new double[n];

    for (int i = n - 1; i >= 0; i--) {
        double b = A[i][i];
        double c = 0;

        for (int j = i; j < n; j++) {
            c += A[i][j] * A[j][i];
        }

        eigenvalues[i] = b + c;

        if (i > 0) {
            double a = A[i][i-1];
            for (int j = i; j < n; j++) {
                A[i][j] -= c * A[i-1][j];
                A[j][i] -= c * A[j][i-1];
            }
            A[i][i-1] = a;
            eigenvalues[i-1] = A[i-1][i-1];
            A[i-1][i-1] = 1;
            for (int j = i-2; j >= 0; j--) {
                double w = A[j][j] - eigenvalues[i-1];
                double r = 0;
                for (int k = j+1; k < n; k++) {
                    r += A[j][k] * A[k][j];
                }
                if (A[j+1][j] != 0) {
                    double q = (A[j][j+1] - w) * (A[j+1][j] - w) - r;
                    double x = A[j+1][j+1] - w;
                    double y = 0;
                    if (q > 0) {
                        y = Math.sqrt(q);
                        if (A[j][j+1] < w) {
                            y = -y;
                        }
                        eigenvalues[j] = w - r / (A[j][j+1] - w + y);
                        eigenvalues[j+1] = w - r / (A[j][j+1] - w - y);
                    } else {
                        eigenvalues[j] = w - x - y;
                        eigenvalues[j+1] = eigenvalues[j];
                    }
                } else {
                    eigenvalues[j] = w - r / (x + Math.sqrt(x*x + r));
                }

                for (int k = j+1; k < n; k++) {
                    A[j][k] -= eigenvalues[j] * A[j][k];
                    A[k][j] -= eigenvalues[j] * A[k][j];
                }
            }
        }
    }

    return eigenvalues;
}

