    // Check if the atom's formal charge matches the atom type's formal charge
    if (atom.getFormalCharge() != atomType.getFormalCharge()) {
        return false;
    }
    // Check if the atom's hybridization state matches the atom type's hybridization state
    if (atom.getHybridization() != atomType.getHybridization()) {
        return false;
    }
    // Check if the atom's number of lone pairs matches the atom type's number of lone pairs
    if (atom.getProperty(CDKConstants.LONE_PAIR_COUNT) != atomType.getProperty(CDKConstants.LONE_PAIR_COUNT)) {
        return false;
    }
    // Check if the atom's number of radical electrons matches the atom type's number of radical electrons
    if (atom.getProperty(CDKConstants.RADICAL_ELECTRONS) != atomType.getProperty(CDKConstants.RADICAL_ELECTRONS)) {
        return false;
    }
    // Check if the atom's number of valence electrons matches the atom type's number of valence electrons
    if (atom.getProperty(CDKConstants.VALENCE_ELECTRONS) != atomType.getProperty(CDKConstants.VALENCE_ELECTRONS)) {
        return false;
    }
    // Check if the atom's number of sigma bonds matches the atom type's number of sigma bonds
    if (atom.getProperty(CDKConstants.SIGMA_ELECTRONS) != atomType.getProperty(CDKConstants.SIGMA_ELECTRONS)) {
        return false;
