    List<Deferred<ScanResult>> deferredList = new ArrayList<>();
    for (Scanner scanner : scanners) {
        try {
            deferredList.add(scanner.scanAsync());
        } catch (Exception e) {
            return new Deferred<>(e);
        }
    }
    return Deferred.group(deferredList).addCallback(results -> {
        List<ScanResult> scanResults = new ArrayList<>();
        for (ScanResult r : results) {
            if (r != null) {
                scanResults.add(r);
            }
        }
        return scanResults;
    }).addErrback(throwable -> {
        LOGGER.error("Error while executing scanner task: ", throwable);
        return throwable;
    });
}

