public List<Tree> produceTrees(List<Location> locations) {
    List<Tree> trees = new ArrayList<Tree>();
    int size = locations.size();

    // Base case: list is empty
    if (size == 0) {
        return trees;
    }

    // Base case: list contains a single location
    if (size == 1) {
        trees.add(new Tree(locations.get(0)));
        return trees;
    }

    // Find the median location
    int medianIdx = size / 2;
    Location medianLoc = locations.get(medianIdx);

    // Split the list into left and right halves
    List<Location> leftLocs = locations.subList(0, medianIdx);
    List<Location> rightLocs = locations.subList(medianIdx + 1, size);

    // Recursively produce trees for left and right halves
    List<Tree> leftTrees = produceTrees(leftLocs);
    List<Tree> rightTrees = produceTrees(rightLocs);

    // Merge the trees from left and right halves
    trees.addAll(leftTrees);
    trees.addAll(rightTrees);

    // Find any overlapping trees and split them
    for (Tree tree : trees) {
        if (tree.intersects(medianLoc)) {
            trees.remove(tree);
            trees.addAll(tree.split(medianLoc));
        }
    }

    // Add a new tree for the median location
    trees.add(new Tree(medianLoc));

    return trees;
}

