import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;

public class GraphViz {

    private static final String TEMP_FILE = "graph_temp.dot";

    private String dotPath = "dot";
    private String type = "png";

    public void setDotPath(String dotPath) {
        this.dotPath = dotPath;
    }

    public void setType(String type) {
        this.type = type;
    }

    public byte[] getGraph(String dotSource) throws IOException, GraphVizException {
        GraphVizUtils.writeToFile(dotSource, TEMP_FILE);

        ProcessBuilder processBuilder = new ProcessBuilder(dotPath, "-T" + type, TEMP_FILE);

        Process process = processBuilder.start();

        try (InputStream inputStream = process.getInputStream();
             ByteArrayOutputStream outputStream = new ByteArrayOutputStream()) {

            byte[] buffer = new byte[1024];
            int read;

            while ((read = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, read);
            }

            inputStream.close();

            if (process.waitFor() != 0) {
                throw new GraphVizException("Error generating graph");
            }

            return outputStream.toByteArray();
        } catch (InterruptedException e) {
            throw new GraphVizException("Error generating graph");
        } finally {
            GraphVizUtils.deleteFile(TEMP_FILE);
        }
    }
}

