    Charset charset = HttpConstants.DEFAULT_CHARSET;
    HttpDataFactory factory = new DefaultHttpDataFactory(DefaultHttpDataFactory.MINSIZE);
    HttpPostRequestDecoder decoder = new HttpPostRequestDecoder(factory, null, charset, HttpConstants.DEFAULT_MAX_INITIAL_LINE_LENGTH);

    try {
        if (!isMultipart) {
            String content = body.toString(charset);
            decoder.offer(new DefaultHttpContent(Unpooled.copiedBuffer(content, charset)));
        }
        while (body.readableBytes() > 0) {
            decoder.offer((HttpContent) body.readSlice(MAX_CHUNK_SIZE));
            parseBody(map, list, decoder.getBodyHttpDatas());
        }
    } catch (IOException e) {
        throw new ErrorDataDecoderException(e);
    } finally {
        decoder.destroy();
    }
}

