private static double stringToNumber(String source, int sourceStart, int sourceEnd, int radix, boolean isPrefix) {
	// Check if the source string is empty or null
    if (source == null || sourceStart >= sourceEnd) {
        return Double.NaN;
    }

    // Initialize variables
    int start = sourceStart;
    int end = sourceEnd;
    boolean negative = false;
    double result = 0.0;
    int digit;

    // Skip leading whitespace
    while (start < end && Character.isWhitespace(source.charAt(start))) {
        start++;
    }

    // Check for negative sign
    if (start < end && source.charAt(start) == '-') {
        negative = true;
        start++;
    }

    // Check for positive sign
    if (start < end && source.charAt(start) == '+') {
        start++;
    }

    // Skip leading zeros
    while (start < end && source.charAt(start) == '0') {
        start++;
    }

    // Convert digits to number
    while (start < end) {
        char c = source.charAt(start);
        if (Character.isDigit(c)) {
            digit = Character.digit(c, radix);
            if (digit < 0 || digit >= radix) {
                return Double.NaN;
            }
            result = result * radix + digit;
        } else {
            return Double.NaN;
        }
        start++;
    }

    // Apply negative sign if necessary
    if (negative) {
        result = -result;
    }

    return result;
}

