                                        sourceCompression);
      }
      else if (!userSpecifiedSourceCompression.isSupported())
      {
        throw new SnowflakeSQLException(SqlState.FEATURE_NOT_SUPPORTED,
                                        ErrorCode.COMPRESSION_TYPE_NOT_SUPPORTED.getMessageCode(),
                                        sourceCompression);
