public class FileCompressionDetector {

    private static final Map<String, String> COMPRESSION_TYPES = new HashMap<String, String>() {{
        put(".gz", "gzip");
        put(".bz2", "bzip2");
        put(".zip", "zip");
        put(".rar", "rar");
        put(".7z", "7z");
        put(".tar", "tar");
        // add more if needed
    }};

    public String detectCompressionType(File file) {
        String name = file.getName();
        int dotIndex = name.lastIndexOf('.');
        if (dotIndex > 0 && dotIndex < name.length() - 1) {
            String extension = name.substring(dotIndex).toLowerCase();
            return COMPRESSION_TYPES.getOrDefault(extension, "unknown");
        }
        return "unknown";
    }
}

