public class MACAddressSection {
    private String segments;

    public MACAddressSection(String segments) {
        this.segments = segments;
    }

    public MACAddressSection replace(int index, MACAddressSection replacement) {
        String[] segmentsArray = this.segments.split(":");
        String[] replacementArray = replacement.segments.split(":");

        if (index < 0 || index >= segmentsArray.length) {
            throw new IndexOutOfBoundsException("Index out of bounds");
        }

        for (int i = 0; i < replacementArray.length; i++) {
            if (index + i < segmentsArray.length) {
                segmentsArray[index + i] = replacementArray[i];
            } else {
                throw new IndexOutOfBoundsException("Replacement index out of bounds");
            }
        }

        return new MACAddressSection(String.join(":", segmentsArray));
    }

    @Override
    public String toString() {
        return this.segments;
    }

    public static void main(String[] args) {
        MACAddressSection mac = new MACAddressSection("00:11:22:33:44:55");
        MACAddressSection replacement = new MACAddressSection("AA:BB:CC");
        System.out.println(mac.replace(2, replacement));  // Outputs: 00:11:AA:BB:CC:55
    }
