public BoundingBox boundingBoxFromWebMercator(BoundingBox boundingBox) {
	// Assuming the feature projection is EPSG:4326 (WGS84)
    // Convert the bounding box from Web Mercator (EPSG:3857) to WGS84 (EPSG:4326)
    CoordinateReferenceSystem sourceCRS = CRS.decode("EPSG:3857");
    CoordinateReferenceSystem targetCRS = CRS.decode("EPSG:4326");

    MathTransform transform = CRS.findMathTransform(sourceCRS, targetCRS, false);

    // Create a new bounding box for the target CRS
    double minX = boundingBox.getMinX();
    double minY = boundingBox.getMinY();
    double maxX = boundingBox.getMaxX();
    double maxY = boundingBox.getMaxY();

    // Transform the corners of the bounding box
    Point2D minPoint = transform.transform(new Point2D.Double(minX, minY), null);
    Point2D maxPoint = transform.transform(new Point2D.Double(maxX, maxY), null);

    // Create the new bounding box in the target CRS
    return new BoundingBox(minPoint.getX(), minPoint.getY(), maxPoint.getX(), maxPoint.getY());
}

