private boolean fastAllPathsReturnCheck(ControlFlowGraph<Node> cfg) {
	// Check if the exit node has any incoming edges
    Node exitNode = cfg.getExitNode();
    if (exitNode.getIncomingEdges().isEmpty()) {
        return false; // No incoming edges to the exit node means not all paths return
    }
    // Check if all nodes that can reach the exit node have a return statement
    Set<Node> visited = new HashSet<>();
    Deque<Node> stack = new Deque<>();
    stack.push(cfg.getEntryNode());
    while (!stack.isEmpty()) {
        Node currentNode = stack.pop();
        if (visited.contains(currentNode)) {
            continue;
        }
        visited.add(currentNode);
        if (currentNode.hasReturnStatement()) {
            // If the current node has a return statement, all its successors can be ignored
            continue;
        }
        for (Node successor : currentNode.getSuccessors()) {
            if (!successor.hasReturnStatement() && successor.getIncomingEdges().size() == 1) {
                // If a successor has no return statement and only one incoming edge, it must be reached
                // from the current node, and thus the current node must have a return statement
                return false;
            }
            stack.push(successor);
        }
    }
    return true;
}

