public void writeCatalogToStream(Catalog catalog, OutputStream os, boolean raw) throws IOException {
    // create a new instance of DocumentBuilderFactory and DocumentBuilder
    DocumentBuilderFactory documentBuilderFactory = DocumentBuilderFactory.newInstance();
    DocumentBuilder documentBuilder = documentBuilderFactory.newDocumentBuilder();

    // create a new document
    Document document = documentBuilder.newDocument();

    // create the root element and append it to the document
    Element root = document.createElement("catalog");
    document.appendChild(root);

    // iterate through each product in the catalog
    for (Product product : catalog.getProducts()) {
        // create a new element for the product and append it to the root element
        Element productElement = document.createElement("product");
        root.appendChild(productElement);

        // create an attribute for the product's id
        Attr idAttribute = document.createAttribute("id");
        idAttribute.setValue(product.getId());
        productElement.setAttributeNode(idAttribute);

        // create elements for the product's name and price, and append them to the product element
        Element nameElement = document.createElement("name");
        nameElement.appendChild(document.createTextNode(product.getName()));
        productElement.appendChild(nameElement);

        Element priceElement = document.createElement("price");
        priceElement.appendChild(document.createTextNode(String.valueOf(product.getPrice())));
        productElement.appendChild(priceElement);
    }

    // create a transformer object to write the document to the output stream
    TransformerFactory transformerFactory = TransformerFactory.newInstance();
    Transformer transformer = transformerFactory.newTransformer();
    transformer.setOutputProperty(OutputKeys.ENCODING, "UTF-8");

    // write the document to the output stream
    if (raw) {
        transformer.setOutputProperty(OutputKeys.DOCTYPE_SYSTEM, "http://java.sun.com/dtd/properties.dtd");
        transformer.setOutputProperty(OutputKeys.DOCTYPE_PUBLIC, "-//Sun Microsystems, Inc.//DTD Properties File//EN");
    }
    transformer.transform(new DOMSource(document), new StreamResult(os));
}

