@Override
    public Map<String, Object> toMap(final Object object) {
        if ( object == null ) {
            return null;
        }
        if (object instanceof Map) {
            return (Map<String, Object>) object;
        }
        Map<String, Object> map = new LinkedHashMap<>();
        final Map<String, FieldAccess> fieldMap = Reflection.getAllAccessorFields( object.getClass() );
        List<FieldAccess> fields = new ArrayList( fieldMap.values() );
        Collections.reverse( fields );  
        for ( FieldAccess access : fields ) {
            String fieldName = access.name();
            if (access.isStatic()) {
                continue;
            }
            Object value = access.getValue(object);
            if ( value == null ) {
                continue;
            }
            switch (access.typeEnum()) {
                case BYTE:
                case BYTE_WRAPPER:
                case SHORT:
                case SHORT_WRAPPER:
                case INT:
                case INTEGER_WRAPPER:
                case LONG:
                case LONG_WRAPPER:
                case FLOAT:
                case FLOAT_WRAPPER:
                case DOUBLE:
                case DOUBLE_WRAPPER:
                case CHAR:
                case CHAR_WRAPPER:
                case BIG_DECIMAL:
                case BIG_INT:
                case BOOLEAN:
                case BOOLEAN_WRAPPER:
                case CURRENCY:
                case CALENDAR:
                case DATE:
                    map.put( fieldName, value );
                    break;
                case ARRAY:
                case ARRAY_INT:
                case ARRAY_BYTE:
                case ARRAY_SHORT:
                case ARRAY_FLOAT:
                case ARRAY_DOUBLE:
                case ARRAY_LONG:
                case ARRAY_STRING:
                case ARRAY_OBJECT:
                    if (Typ.isBasicType( access.getComponentClass() ))  {
                        map.put(fieldName, value);
                    } else {
                        int length = Arry.len(value);
                        List<Map<String, Object>> list = new ArrayList<>( length );
                        for ( int index = 0; index < length; index++ ) {
                            Object item = Arry.fastIndex( value, index );
                            list.add( toMap( item ) );
                        }
                        map.put( fieldName, list );
                    }
                    break;
                case COLLECTION:
                case LIST:
                case SET:
                    Collection<?> collection = ( Collection<?> ) value;
                    Class<?> componentType = access.getComponentClass();
                    if ( Typ.isBasicType( componentType ) ) {
                        map.put(fieldName, value);
                    } else if (Typ.isEnum(componentType)) {
                        List<String> list = new ArrayList<>(
                                collection.size() );
                        for ( Object item : collection ) {
                            if ( item != null ) {
                                list.add( item.toString() );
                            }
                        }
                        map.put( fieldName, list );
                    } else {
                        List<Map<String, Object>> list = new ArrayList<>(
                                collection.size() );
                        for ( Object item : collection ) {
                            if ( item != null ) {
                                list.add( toMap( item ) );
                            }
                        }
                        map.put( fieldName, list );
                    }
                    break;
                case MAP:
                    map.put(fieldName, value);
                    break;
                case INSTANCE:
                    map.put(fieldName, toMap(value));
                    break;
                case INTERFACE:
                case ABSTRACT:
                    final Map<String, Object> abstractMap = toMap(value);
                    abstractMap.put("class", ClassMeta.className(value));
                    map.put(fieldName, abstractMap);
                    break;
                case ENUM:
                    map.put(fieldName, value);
                    break;
                default:
                    map.put(fieldName, Conversions.toString(value));
                    break;
            }
        }
        return map;
    }

