class Graph {
    private int V;
    private List<Integer> adj[];
    private boolean visited[];
    private boolean[] recStack;

    Graph(int v) {
        V = v;
        adj = new ArrayList[v];
        for (int i = 0; i < v; ++i)
            adj[i] = new ArrayList<>();
        visited = new boolean[V];
        recStack = new boolean[V];
    }

    void addEdge(int v, int w) {
        adj[v].add(w);
    }

    void findCycles() {
        for (int i = 0; i < V; i++)
            if (!visited[i])
                if (isCyclicUtil(i, -1))
                    System.out.println("Graph contains cycle");
    }

    private boolean isCyclicUtil(int i, int parent) {
        visited[i] = true;
        recStack[i] = true;

        Iterator<Integer> it = adj[i].iterator();
        while (it.hasNext()) {
            int v = it.next();

            if (!visited[v]) {
                if (isCyclicUtil(v, i))
                    return true;
            } else if (v != parent)
                return true;
        }
        recStack[i] = false;
        return false;
    }
}

