@Deprecated
private void addReturnStatements(MethodNode node) {
    if (node.isVoid()) {
        return;
    }

    Statement lastStatement = node.getCode().getLastStatement();
    if (!(lastStatement instanceof ReturnStatement) && !isImplicitReturn(lastStatement)) {
        node.getCode().addStatement(new ReturnStatement(ConstantExpression.NULL));
    }

    List<ReturnStatement> returnStatements = new ArrayList<>();
    for (Statement statement : node.getCode().getStatements()) {
        if (isImplicitReturn(statement)) {
            returnStatements.add(new ReturnStatement(((ExpressionStatement) statement).getExpression()));
        }
    }

    if (!returnStatements.isEmpty()) {
        BlockStatement block = (BlockStatement) node.getCode();
        block.setStatements(returnStatements);
        block.addStatement(lastStatement);
    }
}

private boolean isImplicitReturn(Statement statement) {
    return statement instanceof ExpressionStatement && !(statement instanceof DeclarationExpression || statement instanceof BinaryExpression || statement instanceof UnaryMinusExpression);
}

