import java.io.File;
import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.ArrayList;

public class DirectoryScanner {
    public static ArrayList<File> getContent(String directoryPath, String[] includes, String[] excludes, boolean followSymlinks, boolean globCaseSensitive, boolean scanDirectories) throws IOException {
        final ArrayList<File> content = new ArrayList<>();

        final PathMatcher[] includeMatchers = createMatchers(includes, globCaseSensitive);
        final PathMatcher[] excludeMatchers = createMatchers(excludes, globCaseSensitive);

        Files.walkFileTree(Paths.get(directoryPath), new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
                if (scanDirectories) {
                    for (PathMatcher dirMatcher : includeMatchers) {
                        if (dirMatcher.matches(dir.getFileName())) {
                            content.add(dir.toFile());
                            return FileVisitResult.CONTINUE;
                        }
                    }
                }
                return followSymlinks ? FileVisitResult.CONTINUE : FileVisitResult.SKIP_SUBTREE;
            }

            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                for (PathMatcher includeMatcher : includeMatchers) {
                    for (PathMatcher excludeMatcher : excludeMatchers) {
                        if (includeMatcher.matches(file.getFileName()) && !excludeMatcher.matches(file.getFileName())) {
                            content.add(file.toFile());
                            break;
                        }
                    }
                }
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFileFailed(Path file, IOException e) throws IOException {
                return FileVisitResult.CONTINUE;
            }
        });

        return content;
    }

    private static PathMatcher[] createMatchers(String[] patterns, boolean globCaseSensitive) {
        ArrayList<PathMatcher> matchers = new ArrayList<>();
        for (String pattern : patterns) {
            if (globCaseSensitive) {
                matchers.add(FileSystems.getDefault().getPathMatcher("glob:" + pattern));
            } else {
                matchers.add(FileSystems.getDefault().getPathMatcher("glob:" + pattern.toLowerCase()));
                matchers.add(FileSystems.getDefault().getPathMatcher("glob:" + pattern.toUpperCase()));
            }
        }
        return matchers.toArray(new PathMatcher[0]);
    }
}

