public static void extractZip(String format, String source, String target) throws IOException {
    byte[] buffer = new byte[1024];
    ZipInputStream zis = new ZipInputStream(Files.newInputStream(Paths.get(source)));
    ZipEntry zipEntry = zis.getNextEntry();
    while (zipEntry != null) {
        File newFile = newFile(target, zipEntry);
        FileOutputStream fos = new FileOutputStream(newFile);
        int len;
        while ((len = zis.read(buffer)) > 0) {
            fos.write(buffer, 0, len);
        }
        fos.close();
        zipEntry = zis.getNextEntry();
    }
    zis.closeEntry();
    zis.close();
}

private static File newFile(String destinationDir, ZipEntry zipEntry) throws IOException {
    Path destDirPath = Paths.get(destinationDir);
    Path destFilePath = destDirPath.resolve(zipEntry.getName()).normalize();
    if (!destFilePath.startsWith(destDirPath)) {
        throw new IOException("zip entry is outside of the target dir: " + zipEntry.getName());
    }
    return destFilePath.toFile();
}

