public static Object P2() {
  // Evaluate the right-hand side expression
  Object rhs = P2();

  // Check if the expression ends with a postfix increment/decrement operator
  Token token = lexer.getCurrentToken();
  if (token == Token.INC || token == Token.DEC) {
    lexer.getNextToken(); // Consume the postfix operator

    // Perform the increment/decrement operation on the rhs value
    if (rhs instanceof Integer) {
      Integer value = (Integer)rhs;
      if (token == Token.INC) rhs = value + 1;
      else rhs = value - 1;
    }
    else {
      // Throw an error if the rhs value can't be incremented/decremented
      throw new RuntimeException("Operand must be an integer");
    }
  }

  // Check if the expression starts with a unary operator
  token = lexer.getCurrentToken();
  if (token == Token.NOT || token == Token.BIT_NOT || token == Token.TYPECAST) {
    lexer.getNextToken(); // Consume the unary operator

    // Perform the operation on the rhs value
    switch (token) {
      case NOT:
        rhs = !(boolean)rhs;
        break;
      case BIT_NOT:
        if (rhs instanceof Integer) rhs = ~((Integer)rhs);
        else throw new RuntimeException("Operand must be an integer");
        break;
      case TYPECAST:
        //TODO: Implement typecast functionality
        break;
    }
  }

  return rhs;
}

