import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        String js = "...*/igm";
        String newJs = parseJavascriptSource(js);
        System.out.println(newJs);
    }

    private static String parseJavascriptSource(String js) {
        Pattern pattern = Pattern.compile("/([^/]+)/([igm])");
        Matcher matcher = pattern.matcher(js);
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            matcher.appendReplacement(sb, "new RegExp('" + matcher.group(1) + "' + '" + matcher.group(2) + "')");
        }
        matcher.appendTail(sb);
        return sb.toString();
    }
}

