public static void sort(int[] q, int off, int k, int len) {
  if (len <= 0) {
     return;
  }
  int left = off;
  int right = off + len - 1;
  int pivot = q[off + (len / 2)];
  while (left <= right) {
     while (q[left] < pivot) {
        left++;
     }
     while (q[right] > pivot) {
        right--;
     }
     if (left <= right) {
        int temp = q[left];
        q[left] = q[right];
        q[right] = temp;
        left++;
        right--;
     }
  }
  if (off < right) {
     sort(q, off, k, right - off + 1);
  }
  if (left < off + len) {
     sort(q, left, k, off + len - left);
  }
}

