import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class RacyFunction {

    public static <T, R> Function<T, R> doneRacily(Function<T, R> f) {
        AtomicInteger counter = new AtomicInteger(0);
        Map<T, R> cache = new HashMap<>();

        return input -> {
            int currentCount = counter.incrementAndGet();
            R result = cache.get(input);

            if (result == null) {
                result = f.apply(input);
                cache.put(input, result);
            }

            if (currentCount == cache.size()) {
                cache.forEach((key, value) -> cache.replace(key, f.apply(key)));
                counter.set(0);
            }

            return cache.get(input);
        };
    }

    public static void main(String[] args) {
        // example usage
        Function<String, String> upperCaseFunction = s -> s.toUpperCase();
        Function<String, String> racyUpperCaseFunction = doneRacily(upperCaseFunction);

        Stream.of("a", "b", "c", "d", "e", "a", "b", "c", "d", "e")
                .parallel()
                .map(racyUpperCaseFunction)
                .collect(Collectors.toList())
                .forEach(System.out::println);
    }
}

