import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class EventBus {
    private Map<String, List<EventListener>> listeners = new HashMap<>();
    private ExecutorService executorService = Executors.newCachedThreadPool();

    public interface EventListener {
        void onEvent(Object... args);
    }

    public EventBus on(String event, EventListener listener) {
        listeners.computeIfAbsent(event, k -> new ArrayList<>()).add(listener);
        return this;
    }

    public EventBus emit(String event, Object... args) {
        listeners.getOrDefault(event, new ArrayList<>()).forEach(listener -> listener.onEvent(args));
        return this;
    }

    public EventBus emitAsync(String event, Object... args) {
        listeners.getOrDefault(event, new ArrayList<>()).forEach(listener -> {
            executorService.submit(() -> listener.onEvent(args));
        });
        return this;
    }
}

