public class JarInjector {

    /**
    * Injects source-context into the META-INF directory of a jar or war
    *
    * @param inputJarFile the path of the input file (.jar, .war)
    * @param sourceContext the source context to inject into META-INF
    * @throws IOException
    */
    public static void injectSourceContextIntoJar(String inputJarFile, String sourceContext) throws IOException {
        try (JarFile jarFile = new JarFile(inputJarFile)) {
            Manifest manifest = jarFile.getManifest();
            String manifestPath = "META-INF/MANIFEST.MF";
            JarEntry manifestEntry = jarFile.getJarEntry(manifestPath);
            if (manifestEntry == null) {
                throw new IOException("Manifest file not found in the input jar/war file.");
            }
            // Open the input jar/war file and create a temp file
            File tempFile = File.createTempFile("tempfile", ".jar");
            try (JarOutputStream tempJar = new JarOutputStream(new FileOutputStream(tempFile), manifest)) {
                byte[] buffer = new byte[1024];
                int bytesRead;
                try (InputStream inputStream = jarFile.getInputStream(manifestEntry)) {
                    while ((bytesRead = inputStream.read(buffer)) != -1) {
                        tempJar.write(buffer, 0, bytesRead);
                    }
                    // Add the new source context entry
                    JarEntry sourceContextEntry = new JarEntry("META-INF/source-context.txt");
                    tempJar.putNextEntry(sourceContextEntry);
                    tempJar.write(sourceContext.getBytes());
                }
            }
            // Rename the temp file to the original file name
            if (!tempFile.renameTo(new File(inputJarFile))) {
                throw new IOException("Could not rename temporary file to original file name.");
            }
        }
    }
}

