public int rangeEnd(int[] codePoints, int startingCP, int limit, int value) {
    int start = startingCP;
    int end = limit - 1;
    int mid;

    // Binary search for the start of the range
    while (start < end) {
        mid = start + (end - start) / 2;
        if (codePoints[mid] < value) {
            start = mid + 1;
        } else {
            end = mid;
        }
    }

    // Binary search for the end of the range
    end = limit - 1;
    while (start < end) {
        mid = start + (end - start + 1) / 2;
        if (codePoints[mid] > value) {
            end = mid - 1;
        } else {
            start = mid;
        }
    }

    return start;
}

