private void appendSpecial(char c) {
    // Convert the special character to its regex form and append it to the regex pattern
    switch (c) {
        case '*':
            regexPattern.append(".*");
            break;
        case '?':
            regexPattern.append(".");
            break;
        case '.':
            regexPattern.append("\\.");
            break;
        case '\\':
            regexPattern.append("\\\\");
            break;
        default:
            regexPattern.append("\\" + c);
            break;
    }
}

public String convertGlobToRegex(String glob) {
    StringBuilder regexPattern = new StringBuilder();
    for (int i = 0; i < glob.length(); i++) {
        char c = glob.charAt(i);
        if (isSpecialChar(c)) {
            appendSpecial(c);
        } else {
            appendNormal(c);
        }
    }
    return regexPattern.toString();
}

private boolean isSpecialChar(char c) {
    return c == '*' || c == '?' || c == '.' || c == '\\';
}

