public void addScrollPositionExtension(Component componentContainer, int scrollBarrier, int barrierMargin, String styleName) {
    String style = String.format("position: fixed; top: %dpx; %s: %dpx", scrollBarrier + barrierMargin, componentContainer.isRTL() ? "right" : "left", barrierMargin);
    componentContainer.getElement().getStyle().setProperty("position", "relative");
    componentContainer.addAttachHandler(new AttachEvent.Handler() {
        @Override
        public void onAttachOrDetach(AttachEvent attachEvent) {
            if (attachEvent.isAttached()) {
                Scheduler.get().scheduleDeferred(new Scheduler.ScheduledCommand() {
                    @Override
                    public void execute() {
                        Element scrollElement = componentContainer.getElement().getFirstChildElement();
                        if (scrollElement != null) {
                            scrollElement.getStyle().setProperty("position", "absolute");
                            scrollElement.getStyle().setProperty(componentContainer.isRTL() ? "right" : "left", "0px");
                            scrollElement.getStyle().setProperty("top", String.format("%dpx", scrollBarrier));
                            scrollElement.getStyle().setProperty("width", "100%");
                            scrollElement.addClassName(styleName);

                            // Create a new div element to hold the position of the scroll barrier
                            Element barrierElement = Document.get().createDivElement();
                            barrierElement.getStyle().setProperty("position", "absolute");
                            barrierElement.getStyle().setProperty(componentContainer.isRTL() ? "right" : "left", "0px");
                            barrierElement.getStyle().setProperty("top", String.format("%dpx", scrollBarrier + barrierMargin));
                            barrierElement.getStyle().setProperty("height", String.format("%dpx", barrierMargin));
                            barrierElement.getStyle().setProperty("width", "100%");
                            componentContainer.getElement().appendChild(barrierElement);
                        }
                    }
                });
            }
        }
    });
}

