    private final ResourceServerTokenServices resourceServerTokenServices;

    private final PrincipalExtractor principalExtractor;

    private final JwtAccessTokenConverter jwtAccessTokenConverter;

    public CasConfigurationServerWebSecurityConfigurer(ResourceServerProperties serverProperties, AuthorizationCodeResourceDetails authorizationCodeResourceDetails, ResourceServerTokenServices resourceServerTokenServices, CorsFilter corsFilter, PrincipalExtractor principalExtractor, JwtAccessTokenConverter jwtAccessTokenConverter) {
        this.serverProperties = serverProperties;
        this.authorizationCodeResourceDetails = authorizationCodeResourceDetails;
        this.resourceServerTokenServices = resourceServerTokenServices;
        this.principalExtractor = principalExtractor;
        this.jwtAccessTokenConverter = jwtAccessTokenConverter;
        corsFilter.setOrder(0);
    }

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http
            .logout().logoutUrl("/logout").permitAll()
            .and().authorizeRequests().antMatchers(
                "/css/**", "/img/**", "/javascript/**", "/login", "/webjars/**" 
            ).permitAll().anyRequest().authenticated()
            .and().csrf().csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())
            .and().addFilterBefore(oAuth2ClientContextFilter(), CorsFilter.class)
            .addFilterBefore(oAuth2ClientFilter(), OAuth2ClientContextFilter.class)
            .sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            .registerSessionAuthenticationStrategy(callbackSessionAuthenticationStrategy())
            .and().apply().configure(serverProperties, resourceServerTokenServices)
            .userInfoEndpoint().principalExtractor(principalExtractor)
            .and().accessTokenConverter(jwtAccessTokenConverter)
            .tokenServices(new UserInfoTokenServicesWrapper(jwtAccessTokenConverter, resourceServerTokenServices));
    }

    private OAuth2ClientContextFilter oAuth2ClientContextFilter() {
        return new OAuth2ClientContextFilter();
    }

    private OAuth2ClientAuthenticationProcessingFilter oAuth2ClientFilter() {
        OAuth2ClientAuthenticationProcessingFilter filter =
            new OAuth2ClientAuthenticationProcessingFilter(authorizationCodeResourceDetails.getAccessTokenUri());
        filter.setRestTemplate(authorizationCodeResourceDetails.getRestTemplate());
        filter.setTokenServices(new UserInfoTokenServices(authorizationCodeResourceDetails.getUserInfoUri(),
                                                           authorizationCodeResourceDetails.getClientId()));
        filter.setAuthenticationSuccessHandler((request, response, authentication) -> {
            OAuth2AccessToken accessToken = (OAuth2AccessToken) authentication.getCredentials();
            DefaultOAuth2AccessToken newAccessToken = new DefaultOAuth2AccessToken(accessToken);
            try {
                newAccessToken.setScope(null);
                newAccessToken.setAdditionalInformation(null);
                newAccessToken.setValue(getTokenValue(accessToken));
            } catch (Exception e) {
                throw new InvalidTokenException("Unable to get token value");
            }
            response.setContentType("application/json;charset=UTF-8");
            response.getWriter().write(newAccessToken.toString());
        });
        return filter;
    }

    private String getTokenValue(OAuth2AccessToken accessToken) {
        DefaultOAuth2AccessToken newToken = new DefaultOAuth2AccessToken(accessToken);
        newToken.setScope(null); // Remove the openid scope since it is not shareable between apps
        newToken.setAdditionalInformation(null); // Remove additional information for the same reason
        return jwtAccessTokenConverter.encode(newToken);
    }
