public String generateXmlSchema(List<CobolDataItem> cobolDataItems, String targetNamespace) {
    StringBuilder xmlSchemaBuilder = new StringBuilder();
    if (targetNamespace != null) {
        xmlSchemaBuilder.append(String.format("<xs:schema xmlns:xs=\"http://www.w3.org/2001/XMLSchema\" targetNamespace=\"%s\">\n", targetNamespace));
    } else {
        xmlSchemaBuilder.append("<xs:schema xmlns:xs=\"http://www.w3.org/2001/XMLSchema\">\n");
    }
    xmlSchemaBuilder.append("<xs:element name=\"root\">\n");
    xmlSchemaBuilder.append("<xs:complexType>\n<xs:sequence>\n");

    for (CobolDataItem dataItem : cobolDataItems) {
        if (dataItem.getChildren() != null && !dataItem.getChildren().isEmpty()) {
            xmlSchemaBuilder.append("<xs:element name=\"");
            xmlSchemaBuilder.append(dataItem.getName());
            xmlSchemaBuilder.append("\" type=\"");
            xmlSchemaBuilder.append(dataItem.getName());
            xmlSchemaBuilder.append("Type\"/>\n");

            xmlSchemaBuilder.append("<xs:complexType name=\"");
            xmlSchemaBuilder.append(dataItem.getName());
            xmlSchemaBuilder.append("Type\">\n<xs:sequence>\n");

            for (CobolDataItem child : dataItem.getChildren()) {
                xmlSchemaBuilder.append("<xs:element name=\"");
                xmlSchemaBuilder.append(child.getName());
                xmlSchemaBuilder.append("\"");

                if (child.getType() != null) {
                    xmlSchemaBuilder.append(" type=\"");
                    xmlSchemaBuilder.append(child.getType());
                    xmlSchemaBuilder.append("\"");
                }

                xmlSchemaBuilder.append("/>\n");
            }

            xmlSchemaBuilder.append("</xs:sequence>\n</xs:complexType>\n");
        }
    }

    xmlSchemaBuilder.append("</xs:sequence>\n</xs:complexType>\n</xs:element>\n</xs:schema>");
    return xmlSchemaBuilder.toString();
}

