public void estimateBetas(double[][] L_full, double[] y, double[] betas){

    int n = L_full.length;
    int p = L_full[0].length;

    // Initialize variables
    double[] y_hat = new double[n];
    double[][] L = new double[n][p];
    double[][] Q = new double[p][p];
    double[] c = new double[p];
    double[] r = new double[n];

    // Compute initial values
    for(int i = 0; i < n; i++){
        y_hat[i] = 0;
        for(int j = 0; j < p; j++){
            y_hat[i] += L_full[i][j] * betas[j];
            L[i][j] = L_full[i][j];
        }
        r[i] = y[i] - y_hat[i];
    }

    // Iterate until convergence
    boolean converged = false;
    while(!converged){
        for(int j = 0; j < p; j++){
            c[j] = 0;
            for(int i = 0; i < n; i++){
                c[j] += L[i][j] * r[i];
