// Solves a linear system of equations using LU decomposition
public double[] solve(double[][] A, double[] b){
    int n = A.length;

    // LU decomposition
    double[][] LU = new double[n][n];
    for(int i = 0; i < n; i++){
        for(int j = 0; j < n; j++){
            LU[i][j] = A[i][j];
        }
    }

    int[] piv = new int[n];
    for(int i = 0; i < n; i++){
        piv[i] = i;
    }

    for(int k = 0; k < n-1; k++){
        int i_max = k;
        double max = Math.abs(LU[k][k]);
        for(int i = k+1; i < n; i++){
            double abs = Math.abs(LU[i][k]);
            if(abs > max){
                max = abs;
                i_max = i;
            }
        }
        if(i_max != k){
            int temp = piv[k];
            piv[k] = piv[i_max];
            piv[i_max] = temp;
            for(int i = 0; i < n; i++){
                double temp2 = LU[k][i];
                LU[k][i] = LU[i_max][i];
                LU[i_max][i] = temp2;
            }
        }
        for(int i = k+1; i < n; i++){
            double factor = LU[i][k] / LU[k][k];
            LU[i][k] = factor;
            for(int j = k+1; j < n; j++){
                LU[i][j] -= factor * LU[k][j];
            }
        }
    }

    // Solve system using forward and backward substitution
    double[] x = new double[n];

    double[] b2 = new double[n];
    for(int i = 0; i < n; i++){
        b2[i] = b[piv[i]];
    }
    for(int i = 0; i < n; i++){
        double sum = 0;
        for(int j = 0; j < i; j++){
            sum += LU[i][j] * x[j];
        }
        x[i] = b2[i] - sum;
    }
    for(int i = n-1; i >= 0; i--){
        double sum = 0;
        for(int j = i+1; j < n; j++){
            sum += LU[i][j] * x[j];
        }
        x[i] = (x[i] - sum) / LU[i][i];
    }

    return x;
}

// Computes the Euclidean norm of a vector
public double norm(double[] x){
    double sum = 0;
    for(int i = 0; i < x.length; i++){
        sum += x[i] * x[i];
    }
    return Math.sqrt(sum);
}

