import org.apache.spark.api.java.JavaRDD;
import org.apache.spark.api.java.function.Function;
import org.apache.spark.ml.feature.LabeledPoint;
import org.deeplearning4j.datasets.iterator.impl.IteratorMultiDataSetIterator;
import org.deeplearning4j.nn.api.Model;
import org.deeplearning4j.nn.conf.MultiLayerConfiguration;
import org.deeplearning4j.nn.multilayer.MultiLayerNetwork;
import org.nd4j.linalg.dataset.DataSet;
import org.nd4j.linalg.dataset.SplitTestAndTrain;
import org.nd4j.linalg.dataset.api.iterator.DataSetIterator;
import org.nd4j.linalg.factory.Nd4j;

public MultiLayerNetwork fitMultiLayerNetwork(JavaRDD<LabeledPoint> rdd, MultiLayerConfiguration conf) {

  JavaRDD<DataSet> data = rdd.map(new Function<LabeledPoint, DataSet>() {
    @Override
    public DataSet call(LabeledPoint lp) throws Exception {
      double[] featureValues = lp.features().toArray();
      double[] labelValues = new double[(int) lp.label()];
      labelValues[lp.label()] = 1;
      return new DataSet(Nd4j.create(featureValues), Nd4j.create(labelValues));
    }
  });

  DataSetIterator iter = new IteratorMultiDataSetIterator(data);

  DataSet allData = iter.next();
  SplitTestAndTrain testAndTrain = allData.splitTestAndTrain(0.7);
  MultiLayerNetwork model = new MultiLayerNetwork(conf);
  model.init();
  model.fit(testAndTrain.getTrain());

  return model;
}

