public Quaterniond rotateTo(double fromDirX, double fromDirY, double fromDirZ, double toDirX, double toDirY, double toDirZ, Quaterniond dest) {
    double angle = Math.acos(fromDirX * toDirX + fromDirY * toDirY + fromDirZ * toDirZ);
    if (angle < 1E-6) {
        return dest.identity();
    }
    double invs = 1.0 / Math.sin(angle);
    double fromDirCrossToDirX = fromDirY * toDirZ - fromDirZ * toDirY;
    double fromDirCrossToDirY = fromDirZ * toDirX - fromDirX * toDirZ;
    double fromDirCrossToDirZ = fromDirX * toDirY - fromDirY * toDirX;
    double x = fromDirCrossToDirX * invs;
    double y = fromDirCrossToDirY * invs;
    double z = fromDirCrossToDirZ * invs;
    double w = Math.cos(angle / 2.0);
    return dest.set(w, x, y, z);
}

