public Result evaluateOutlierHistogram(Database database, OutlierResult or) {
    // initialize histogram
    int[] histogram = new int[10];

    // loop through database and count occurrences in histogram
    for (int i = 0; i < database.size(); i++) {
        int value = database.get(i);
        if (value < or.getLowerBound() || value > or.getUpperBound()) {
            int index = (int)Math.floor((value - or.getLowerBound()) / or.getBucketSize());
            if (index >= 0 && index < histogram.length) {
                histogram[index]++;
            }
        }
    }

    // create and return result object
    return new Result(histogram, or.getLowerBound(), or.getUpperBound(), or.getBucketSize());
}

