public BaseDestinationHandler recoverBaseDestinationHandler(Processor processor, Map<String, String> durableSubscriptionsTable) throws Exception {
    MessageStore messageStore = processor.getMessageStore();
    for (String subscriptionName : durableSubscriptionsTable.keySet()) {
        Destination destination = messageStore.getDestination(subscriptionName);
        if (destination instanceof Topic) {
            Topic topic = (Topic) destination;
            String subscriptionClientId = durableSubscriptionsTable.get(subscriptionName);
            if (subscriptionClientId != null) {
                Subscription subscription = topic.getDurableSubscription(subscriptionClientId);
                if (subscription != null) {
                    return subscription.getSubscriptionContext();
                }
            }
        }
    }
    return null;
}

