public class SslContextBuilderWrapper {

    public SslContextBuilder createSslContextBuilder() throws CertificateException, SSLException{
        SelfSignedCertificate certificate = new SelfSignedCertificate();
        SslContextBuilder sslContextBuilder = GrpcSslContexts.forServer(
                new File(getClass().getResource("/private_key.pem").getFile()),
                new File(getClass().getResource("/certificate.pem").getFile()),
                null);
        configure(sslContextBuilder);
        return sslContextBuilder;
    }

