public boolean canReuseConnection(HttpRequest a, HttpRequest b) {
    final String versionA = a.getVersion().toUpperCase(Locale.US);
    final String versionB = b.getVersion().toUpperCase(Locale.US);
    if (!versionA.equals(versionB)) {
        return false;
    }
    final String methodA = a.getRequestLine().getMethod().toUpperCase(Locale.US);
    // CONNECT method means that connection shouldn't be reused for non-CONNECT methods
    if (methodA.equals("CONNECT")) {
        return false;
    }
    final String methodB = b.getRequestLine().getMethod().toUpperCase(Locale.US);
    if (!methodA.equals(methodB)) {
        return false;
    }
    final String schemeA = a.getUri().getScheme();
    final String schemeB = b.getUri().getScheme();
    if (!schemeA.equals(schemeB)) {
        return false;
    }
    final String hostA = a.getUri().getHost().toLowerCase(Locale.US);
    final String hostB = b.getUri().getHost().toLowerCase(Locale.US);
    if (!hostA.equals(hostB)) {
        return false;
    }
    final int portA = a.getUri().getPort();
    final int portB = b.getUri().getPort();
    if (portA != portB) {
        return false;
    }
    return true;
}

