import java.util.Random;
import java.util.zip.CRC32;

public class HashUtil {

    private static final String CHARACTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    private static final Random random = new Random();

    /**
     * Uses {@link CRC32} to choose a random (but stable) value from within this field.
     *
     * @param str   The string to hash.
     * @param step  Increments. For example, 15 if "H/15". Or {@link #NO_STEP} to indicate
     *              the special constant for "H" without the step value.
     * @return A random value from within the field specified by the string and step values.
     */
    public static int hash(String str, int step) {
        return Math.abs(getHash(str.getBytes(), step)) % CHARACTERS.length();
    }

    private static long getHash(byte[] bytes, int step) {
        CRC32 crc = new CRC32();
        crc.update(bytes);
        long value = crc.getValue();
        if (step == NO_STEP) {
            return value;
        } else {
            return value / step;
        }
    }

    /**
     * The special constant for "H" without the step value.
     */
    public static final int NO_STEP = -1;

}

