public static String typeToClassgetname(Type type) {
    if (type instanceof Class) {
        return ((Class<?>) type).getName();
    } else if (type instanceof ParameterizedType) {
        return ((Class<?>) ((ParameterizedType) type).getRawType()).getName();
    } else if (type instanceof GenericArrayType) {
        return ((Class<?>) ((GenericArrayType) type).getGenericComponentType()).getName();
    } else if (type instanceof WildcardType) {
        return ((Class<?>) ((WildcardType) type).getUpperBounds()[0]).getName();
    } else {
        throw new IllegalArgumentException("Unknown type");
    }
}

