public static boolean solveMatrix(int order, double[] A, double[] b, double tol) {
    int n = (int) Math.sqrt(A.length);
    int[] ipiv = new int[n];
    for (int i = 0; i < n; i++) {
        ipiv[i] = i;
    }
    for (int k = 0; k < n-1; k++) {
        double max_val = Math.abs(A[k*n+k]);
        int max_row = k;
        for (int j = k+1; j < n; j++) {
            double val = Math.abs(A[j*n+k]);
            if (val > max_val) {
                max_val = val;
                max_row = j;
            }
        }
        if (max_val < tol) {
            return false;
        }
        if (max_row != k) {
            int tmp_row = ipiv[k];
            ipiv[k] = ipiv[max_row];
            ipiv[max_row] = tmp_row;
            for (int j = k; j < n; j++) {
                double tmp_val = A[k*n+j];
                A[k*n+j] = A[max_row*n+j];
                A[max_row*n+j] = tmp_val;
            }
            double tmp_val = b[k];
            b[k] = b[max_row];
            b[max_row] = tmp_val;
        }
        for (int j = k+1; j < n; j++) {
            double factor = A[j*n+k]/A[k*n+k];
            for (int i = k+1; i < n; i++) {
                A[j*n+i] -= factor*A[k*n+i];
            }
            b[j] -= factor*b[k];
        }
    }
    for (int k = n-1; k >= 0; k--) {
        for (int j = k+1; j < n; j++) {
            b[k] -= A[k*n+j]*b[j];
        }
        b[k] /= A[k*n+k];
    }
    return true;
}

