public List<ByteBuffer> fastPread(long position, int length) throws IOException {
    List<ByteBuffer> byteBuffers = new ArrayList<>();
    FileChannel fileChannel = FileChannel.open(Paths.get("file.txt"), StandardOpenOption.READ);

    long remaining = length;
    while (remaining > 0) {
        ByteBuffer byteBuffer = ByteBuffer.allocateDirect(Math.min(remaining, Integer.MAX_VALUE));
        int bytesRead = fileChannel.read(byteBuffer, position);
        if (bytesRead < 0) {
            break;
        }
        remaining -= bytesRead;
        position += bytesRead;
        byteBuffer.flip();
        byteBuffers.add(byteBuffer);
    }
    return byteBuffers;
}

