/**
 * Escapes the specified byte array for use in protocol buffer messages.
 * This method is like {@link #escapeBytes(ByteString)}, but used for byte array.
 *
 * @param input The input byte array to be escaped
 * @return The escaped byte array
 */
public static byte[] escapeBytes(final byte[] input) {
    return escapeBytes(input, 0, input.length);
}

/**
 * Escapes the specified subset of the specified byte array for use in protocol
 * buffer messages. This method is like {@link #escapeBytes(ByteString)}, but
 * used for byte array.
 *
 * @param input     The input byte array to be escaped
 * @param offset    The start offset in the data
 * @param length    The number of bytes to process
 * @return The escaped byte array
 */
public static byte[] escapeBytes(final byte[] input, final int offset, final int length) {
    final byte[] buffer = new byte[length * 2];
    int bufferPos = 0;

    for (int i = offset; i < offset + length; i++) {
        final byte b = input[i];
        if (b == '\\') {
            buffer[bufferPos++] = '\\';
            buffer[bufferPos++] = '\\';
        } else if (b >= 0 && b < 32) {
            buffer[bufferPos++] = '\\';
            buffer[bufferPos++] = (byte) ('0' + (b >> 3));
            buffer[bufferPos++] = (byte) ('0' + (b & 7));
        } else {
            buffer[bufferPos++] = b;
        }
    }

    return Arrays.copyOf(buffer, bufferPos);
}

