public static String getClassNameForResource(String path) {
    String className = null;
    if(path != null) {
        String normalizedPath = path.startsWith("/") ? path.substring(1) : path;
        String[] pathComponents = normalizedPath.split("/");
        for(int i=0; i<pathComponents.length; i++) {
            String classSegment = toClassNameSegment(pathComponents[i]);
            if(classSegment == null || classSegment.trim().length() == 0) {
                break;
            }

            className = className == null ? classSegment : className + "." + classSegment;
            if(i==pathComponents.length-1) {
                try {
                    Class.forName(className);
                } catch (ClassNotFoundException e) {
                    className = null;
                }
            }
        }
    }
    return className;
}

private static String toClassNameSegment(String str) {
    if(str == null || str.trim().length() == 0) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    boolean capitalize = true;
    for(int i=0; i<str.length(); i++) {
        char c = str.charAt(i);
        if(c == '-') {
            capitalize = true;
        } else if(capitalize) {
            result.append(Character.toUpperCase(c));
            capitalize = false;
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

