public static <P> MetaPropertyReadWrite<P> createReadWriteMetaProperty(
    final MetaBean metaBean,
    final String propertyName,
    final Class<?> declaringType,
    final Class<P> propertyType) {

    final PropertyStyle style = metaBean.style();
    final boolean derived = (style != null && style.isConventionalDerived(propertyName));
    if (derived) {
        throw new IllegalArgumentException("Derived properties not supported: " + declaringType.getName() + "." + propertyName);
    }
    final MetaProperty<P> metaProp = metaBean.metaProperty(propertyName);
    if (metaProp == null) {
        throw new IllegalArgumentException("Unable to find property: " + declaringType.getName() + "." + propertyName);
    }

    if (metaProp instanceof MetaPropertyReadWrite) {
        return (MetaPropertyReadWrite<P>) metaProp;
    }

    if (!(metaProp instanceof MetaProperty)) {
        throw new IllegalArgumentException("Property is not a valid read-write property: " + declaringType.getName() + "." + propertyName);
    }

    final MetaProperty<P> typedProperty = (MetaProperty<P>) metaProp;

    final MetaPropertyUtils.PropertyType returnType = MetaPropertyUtils.determinePropertyType(declaringType, typedProperty);

    switch (returnType) {
        case DIRECT:
            return new DirectReadWriteMetaProperty<>(metaBean, propertyName, typedProperty, propertyType);
        case ARRAY:
            return new ArrayReadWriteMetaProperty<>(metaBean, propertyName, typedProperty, propertyType);
        case INDEXED:
            return new IndexedReadWriteMetaProperty<>(metaBean, propertyName, typedProperty, propertyType);
        case MAP:
            return new MapReadWriteMetaProperty<>(metaBean, propertyName, typedProperty, propertyType);
        default:
            throw new IllegalStateException("Property type " + returnType + " is not valid");
    }
}

