public class UnionFind<E> {
    private Map<E, Node<E>> nodes = new HashMap<>();

    public void makeSet(E data) {
        nodes.put(data, new Node<>(data));
    }

    private Node<E> _find_root(Node<E> node) {
        if (node.parent == node) {
            return node;
        }
        node.parent = _find_root(node.parent); // Path compression
        return node.parent;
    }

    public Node<E> find(E data) {
        if (!nodes.containsKey(data)) {
            throw new IllegalArgumentException("Data not found");
        }
        return _find_root(nodes.get(data));
    }

    public void union(E data1, E data2) {
        Node<E> root1 = find(data1);
        Node<E> root2 = find(data2);
        if (root1 != root2) {
            root2.parent = root1;
        }
    }
}

