public BufferedImage scaleAndCropImage(BufferedImage image, int width, int height) {
    int originalWidth = image.getWidth();
    int originalHeight = image.getHeight();

    double scaleFactor = Math.min((double) width / originalWidth, (double) height / originalHeight);

    int newWidth = (int) (originalWidth * scaleFactor);
    int newHeight = (int) (originalHeight * scaleFactor);

    BufferedImage scaledImage = new BufferedImage(newWidth, newHeight, BufferedImage.TYPE_INT_RGB);
    Graphics2D graphics2D = scaledImage.createGraphics();
    graphics2D.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
    graphics2D.drawImage(image, 0, 0, newWidth, newHeight, null);
    graphics2D.dispose();

    int x = (newWidth - width) / 2;
    int y = (newHeight - height) / 2;

    BufferedImage croppedImage = scaledImage.getSubimage(x, y, width, height);

    return croppedImage;
}

