public void serialize(XmlSerializer serializer, String elementName, Object element) throws IOException {
	// Check if the element is a GenericXml object
    if (element instanceof GenericXml) {
        GenericXml genericXml = (GenericXml) element;
        // Start the element with the provided element name
        serializer.startTag(null, elementName);
        // Serialize the attributes of the GenericXml object
        for (Map.Entry<String, String> attribute : genericXml.getAttributes().entrySet()) {
            serializer.attribute(null, attribute.getKey(), attribute.getValue());
        }
        // Serialize the child elements of the GenericXml object
        for (Map.Entry<String, Object> child : genericXml.getChildren().entrySet()) {
            serialize(serializer, child.getKey(), child.getValue());
        }
        // End the element
        serializer.endTag(null, elementName);
    } 
    // Check if the element is a Map object
    else if (element instanceof Map) {
        Map<?, ?> map = (Map<?, ?>) element;
        // Start the element with the provided element name
        serializer.startTag(null, elementName);
        // Serialize the key/value pairs in the map
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            serialize(serializer, entry.getKey().toString(), entry.getValue());
        }
        // End the element
        serializer.endTag(null, elementName);
    } 
    // Check if the element is a simple object with public fields
    else {
        // Start the element with the provided element name
        serializer.startTag(null, elementName);
        // Serialize the public fields of the object
        for (Field field : element.getClass().getDeclaredFields()) {
            if (Modifier.isPublic(field.getModifiers())) {
                try {
                    serialize(serializer, field.getName(), field.get(element));
                } catch (IllegalAccessException e) {
                    throw new IOException("Failed to access field: " + field.getName(), e);
                }
            }
        }
        // End the element
        serializer.endTag(null, elementName);
    }
}

