public static double[][] createKernel(double sigma, int radius, boolean odd, boolean normalize) {
    int size = radius * 2 + 1;
    double[][] kernel = new double[size][size];
    double sum = 0;

    for (int i = -radius; i <= radius; i++) {
        for (int j = -radius; j <= radius; j++) {
            double x = i;
            double y = j;
            double val = Math.exp(-(x * x + y * y) / (2 * sigma * sigma));
            kernel[i + radius][j + radius] = val;
            sum += val;
        }
    }

    if (normalize) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                kernel[i][j] /= sum;
            }
        }
    }

    if (odd && size % 2 == 0) {
        // make the kernel odd size
        double[][] oddKernel = new double[size + 1][size + 1];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                oddKernel[i][j] = kernel[i][j];
            }
        }
        kernel = oddKernel;
    }

    return kernel;
}

