public static String decode(CharSequence chars) {
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < chars.length()) {
        char c = chars.charAt(i);
        if (c == '&') {
            int nextIdx = chars.toString().indexOf(';', i);
            if (nextIdx == -1) {
                throw new IllegalArgumentException("Cannot decode string '" + chars + "'. Invalid HTML entity encoding.");
            }
            String entity = chars.subSequence(i+1, nextIdx).toString();
            switch (entity) {
                case "lt": result.append('<'); break;
                case "gt": result.append('>'); break;
                case "amp": result.append('&'); break;
                case "apos": result.append('\''); break;
                case "quot": result.append('"'); break;
                default: throw new IllegalArgumentException("Invalid HTML entity encoding '&" + entity + ";'.");
            }
            i = nextIdx+1;
        } else {
            result.append(c);
            i++;
        }
    }
    return result.toString();
}

