public void setBackStack(List<Controller> newBackstack, ControllerChangeHandler changeHandler) {
    if (newBackstack.isEmpty()) {
        throw new IllegalArgumentException("New backstack must have at least one controller");
    }
    if (newBackstack.get(0) == null) {
        throw new IllegalArgumentException("New backstack cannot have null controller");
    }

    if (newBackstack.size() == 1) {
        setRoot(newBackstack.get(0), changeHandler);
        return;
    }

    int currentIndex = backstack.size() - 1;
    Controller currentController = backstack.get(currentIndex);
    Controller newController = newBackstack.get(newBackstack.size() - 1);

    if (currentController == newController) {
        return;
    }

    for (int i = currentIndex - 1; i >= 0; i--) {
        Controller controllerToRemove = backstack.get(i);
        if (!newBackstack.contains(controllerToRemove)) {
            removeController(controllerToRemove);
        } else {
            break;
        }
    }

    for (int i = 0; i < newBackstack.size() - 1; i++) {
        if (!backstack.contains(newBackstack.get(i))) {
            insertControllerAt(i, newBackstack.get(i));
        }
    }

    pushController(newController, changeHandler);
}

