public static String inferVendorClass(List<String> fileNames) {
    if (fileNames == null || fileNames.isEmpty()) {
        return null;
    }

    for (String fileName : fileNames) {
        if (fileName.contains("ORACLE")) {
            return "oracle.jdbc.pool.OracleDataSource";
        } else if (fileName.contains("MYSQL")) {
            return "com.mysql.jdbc.jdbc2.optional.MysqlDataSource";
        } else if (fileName.contains("POSTGRESQL")) {
            return "org.postgresql.ds.PGSimpleDataSource";
        } else if (fileName.contains("MARIADB")) {
            return "org.mariadb.jdbc.MariaDbDataSource";
        }
    }

    return null;
}

