public static int encodeDiff(int diff, byte[] buffer, int offset) {
    if (diff == 0) {
        buffer[offset++] = (byte) 0x80;
        return offset;
    }

    int sign = diff > 0 ? 1 : -1;
    diff = Math.abs(diff);

    int numBytes = diff < 0x80 ? 1 :
                   diff < 0x4000 ? 2 :
                   diff < 0x200000 ? 3 : 4;

    buffer[offset] = (byte) (0x80 | (numBytes << 4) | (sign & 0x08));

    switch (numBytes) {
        case 4:
            buffer[offset + 3] = (byte) (0x80 | (diff & 0x3f));
            diff >>= 6;
