import android.text.format.DateUtils;

public static CharSequence getRelativeTimeSpanString(Context context, ReadableInstant time, int flags) {
    long now = System.currentTimeMillis();
    long timeInMillis = time.toEpochMilli();
    long timeDifference = now - timeInMillis;

    if (flags == DateUtils.FORMAT_ABBREV_RELATIVE) {
        if (timeDifference < 60000) {
            return "just now";
        } else if (timeDifference < 3600000) {
            return (timeDifference / 60000) + " minutes ago";
        } else if (timeDifference < 86400000) {
            return (timeDifference / 3600000) + " hours ago";
        } else {
            return (timeDifference / 86400000) + " days ago";
        }
    }

    return "";
}

