public String createErrorMessage(RecognitionException e) {
	// Extract the line and column number from the exception
    int line = e.getLine();
    int column = e.getColumn();

    // Get the token that caused the error
    Token offendingToken = e.getOffendingToken();
    String tokenText = offendingToken != null ? offendingToken.getText() : "unknown";

    // Create a sensible error message
    String errorMessage = "Error at line " + line + ", column " + column + ": unexpected token '" + tokenText + "'";

    return errorMessage;
}

