public ASTMethod buildASTMethod(Method method) {
    ASTMethod astMethod = new ASTMethod();

    // set method name
    astMethod.setName(method.getName());

    // set return type
    astMethod.setReturnType(method.getReturnType());

    // set modifiers
    int modifiers = method.getModifiers();
    List<String> modifierList = new ArrayList<>();
    if (Modifier.isAbstract(modifiers)) {
        modifierList.add("abstract");
    }
    if (Modifier.isFinal(modifiers)) {
        modifierList.add("final");
    }
    if (Modifier.isNative(modifiers)) {
        modifierList.add("native");
    }
    if (Modifier.isPrivate(modifiers)) {
        modifierList.add("private");
    }
    if (Modifier.isProtected(modifiers)) {
        modifierList.add("protected");
    }
    if (Modifier.isPublic(modifiers)) {
        modifierList.add("public");
    }
    if (Modifier.isStatic(modifiers)) {
        modifierList.add("static");
    }
    if (Modifier.isStrict(modifiers)) {
        modifierList.add("strictfp");
    }
    if (Modifier.isSynchronized(modifiers)) {
        modifierList.add("synchronized");
    }
    if (Modifier.isTransient(modifiers)) {
        modifierList.add("transient");
    }
    if (Modifier.isVolatile(modifiers)) {
        modifierList.add("volatile");
    }
    astMethod.setModifiers(modifierList);

    // set parameters
    List<ASTParameter> astParameters = new ArrayList<>();
    for (Parameter parameter : method.getParameters()) {
        ASTParameter astParameter = new ASTParameter();
        astParameter.setName(parameter.getName());
        astParameter.setType(parameter.getType());
        astParameters.add(astParameter);
    }
    astMethod.setParameters(astParameters);

    // set exceptions
    List<Class<?>> exceptionTypes = Arrays.asList(method.getExceptionTypes());
    List<String> exceptions = exceptionTypes.stream()
            .map(Class::getName)
            .collect(Collectors.toList());
    astMethod.setExceptions(exceptions);

    // set method body
    astMethod.setBody(method.getDeclaringClass().getSimpleName() + "." + method.getName() + "() { }");

    return astMethod;
}

