private static Expr betaReduce(Expr expression) {
    if (!(expression instanceof Lambda)) {
        return expression;
    }

    Lambda lambda = (Lambda) expression;
    Expr argument = lambda.argument();
    Expr body = lambda.body();
    Expr result = substitute(body, argument, new HashMap<>());

    while (!(result instanceof Variable) || !((Variable) result).name().equals(argument.name())) {
        if (result instanceof Lambda) {
            Lambda lambda2 = (Lambda) result;
            result = new Lambda(lambda2.argument(), betaReduce(lambda2.body()));
        } else if (result instanceof Application) {
            Application app = (Application) result;
            Expr left = betaReduce(app.left());
            Expr right = betaReduce(app.right());
            if (left instanceof Lambda) {
                result = substitute(((Lambda) left).body(), right, new HashMap<>());
            } else {
                result = new Application(left, right);
            }
        }
    }

    return result;
}

private static Expr rename(Expr expression, Map<String, String> bindings) {
    if (expression instanceof Variable) {
        String name = ((Variable) expression).name();
        String newName = bindings.getOrDefault(name, name);
        return new Variable(newName);
    }

    if (expression instanceof Lambda) {
        Lambda lambda = (Lambda) expression;
        String name = lambda.argument().name();
        String newName = uniqueName(name, bindings.keySet());
        bindings.put(name, newName);
        return new Lambda(new Variable(newName), rename(lambda.body(), bindings));
    }

    Application application = (Application) expression;
    return new Application(rename(application.left(), bindings), rename(application.right(), bindings));
}

private static Expr substitute(Expr expression, Expr replacement, Map<String, Expr> bindings) {
    if (expression instanceof Variable) {
        Variable variable = (Variable) expression;
        return bindings.getOrDefault(variable.name(), variable);
    }

    if (expression instanceof Application) {
        Application application = (Application) expression;
        Expr left = substitute(application.left(), replacement, bindings);
        Expr right = substitute(application.right(), replacement, bindings);
        return new Application(left, right);
    }

    Lambda lambda = (Lambda) expression;
    Expr argument = lambda.argument();
    String name = argument.name();
    if (replacement instanceof Variable && ((Variable) replacement).name().equals(name)) {
        return lambda;
    }

    String newName = uniqueName(name, bindings.keySet());
    Map<String, Expr> newBindings = new HashMap<>(bindings);
    newBindings.put(name, new Variable(newName));
    Expr newBody = substitute(lambda.body(), replacement, newBindings);
    return new Lambda(new Variable(newName), newBody);
}

private static String uniqueName(String name, Set<String> takenNames) {
    if (!takenNames.contains(name)) {
        return name;
    }
    int suffix = 1;
    while (takenNames.contains(name + suffix)) {
        suffix++;
    }
    return name + suffix;
}

