public Layer aggregateReaders(List<CompletableFuture<MessageReaders>> futures, Transport transport) throws IOException {
    List<MessageReaders> readersList = futures.stream()
            .map(CompletableFuture::join)
            .collect(Collectors.toList());
    Layer layer = Layer.from("<response>");
    for (MessageReaders readers : readersList) {
        if (readers != null) {
            for (Map.Entry<String, Reader<?>> entry : readers.entrySet()) {
                Reader<?> reader = entry.getValue();
                layer.addAll(entry.getKey(), reader.read(transport));
            }
        }
    }
    return layer;
}

