public class ResponseBuilder {

    private List<Future<Reader>> futures;
    private Transport transport;

    public ResponseBuilder(List<Future<Reader>> futures, Transport transport) {
        this.futures = futures;
        this.transport = transport;
    }

    public String build() throws IOException {
        StringBuilder response = new StringBuilder();

        // Aggregate the readers from the futures
        for (Future<Reader> future : futures) {
            try {
                Reader reader = future.get();
                // Append the reader's data to the response
                response.append(reader.read());
            } catch (Exception e) {
                // Handle exceptions
            }
        }

        // Append the transport's data to the response
        response.append(transport.getData());

        return response.toString();
    }
}

