public static ReferenceType defaultMerge(ReferenceType aRef, ReferenceType bRef) {
    if (aRef == bRef) {
        return aRef; // Same type
    } else if (aRef.isAssignableFrom(bRef)) {
        return aRef; // aRef is super type
    } else if (bRef.isAssignableFrom(aRef)) {
        return bRef; // bRef is super type
    } else if (aRef instanceof ArrayType && bRef instanceof ArrayType) {
        Type aComponent = ((ArrayType) aRef).getComponentType();
        Type bComponent = ((ArrayType) bRef).getComponentType();
        if (aComponent instanceof PrimitiveType && bComponent instanceof PrimitiveType) {
            if (aComponent.equals(bComponent)) {
                return aRef;
            }
        } else if (aComponent instanceof ReferenceType && bComponent instanceof ReferenceType) {
            ReferenceType component = (ReferenceType) defaultMerge((ReferenceType) aComponent, (ReferenceType) bComponent);
            return new ArrayType(component, 1);
        }
    } else {
        // Default to the first common superclass
        Type superClass = aRef instanceof ObjectType ? aRef : bRef;
        while (!superClass.isAssignableFrom(aRef) || !superClass.isAssignableFrom(bRef)) {
            superClass = ((ObjectType) superClass).getSuperClass();
        }
        return (ReferenceType) superClass;
    }
    throw new IllegalArgumentException("Cannot merge " + aRef + " with " + bRef);
}

