        String placeholders = keySet.stream()
                .map(key -> "?")
                .collect(Collectors.joining(", "));

        // Create the SQL query
        String sql = String.format("DELETE FROM %s WHERE primary_key IN (%s)", table, placeholders);

        // Prepare the statement
