        // Set the primary key values
        int i = 1;
        for (Integer key : keySet) {
            stmt.setInt(i++, key);
        }

        // Execute the statement
        stmt.executeUpdate();

        // Close the statement and connection
        stmt.close();
        conn.close();
    }
}

