public Iterable<Module> transitiveDependencies(Module m) {
    Set<Module> visited = new HashSet<>();
    List<Module> sorted = new ArrayList<>();
    Deque<Module> stack = new ArrayDeque<>();
    visited.add(m);
    stack.push(m);
    while (!stack.isEmpty()) {
        Module current = stack.pop();
        for (Module dependency : current.getDependencies()) {
            if (!visited.contains(dependency)) {
                visited.add(dependency);
                stack.push(dependency);
            }
        }
        sorted.add(current);
    }
    sorted.remove(m);
    Collections.reverse(sorted);
    return sorted;
}

