    public InnerClassDetector(String className) {
        super(Opcodes.ASM5);
        this.className = className;
    }

    @Override
    public void visitOuterClass(String owner, String name, String desc) {
        this.outerClassName = owner;
        super.visitOuterClass(owner, name, desc);
    }

    @Override
    public MethodVisitor visitMethod(int access, String name, String desc, String signature, String[] exceptions) {
        if (outerClassName != null && !outerClassName.equals(className)) {
            isInnerClass = true;
        }
        return super.visitMethod(access, name, desc, signature, exceptions);
    }

    public boolean isInnerClass() {
        return isInnerClass;
    }

    public static boolean isInnerClass(String className) {
        InnerClassDetector detector = new InnerClassDetector(className);
        // Use ASM to visit the class
        // ...
        return detector.isInnerClass();
    }
}

