public static String eatHexCode(String s) {
    if(s == null || s.length() < 3 || s.charAt(0) != '%') {
        return s;
    }

    int i = 1;
    while(i < s.length() && s.charAt(i) == ' ') {
        i++;
    }

    if(i + 1 >= s.length()) {
        return s;
    }

    char c1 = s.charAt(i);
    char c2 = s.charAt(i + 1);
    int value = -1;

    try {
        value = Integer.parseInt(Character.toString(c1) + Character.toString(c2), 16);
    } catch(Exception e) {}

    if(value == -1) {
        return s;
    }

    if(value < 128) {
        return Character.toString((char) value) + s.substring(i + 2);
    }

    int count = 0;
    while((value << count) >= 128) {
        count++;
    }

    if(i + 2 + count > s.length()) {
        return s;
    }

    byte[] bytes = new byte[count + 1];
    bytes[0] = (byte) value;

    for(int j = 1; j < count + 1; j++) {
        char c = s.charAt(i + 1 + j);
        if(c == '%' || c == ' ') {
            return s.substring(i);
        }
        try {
            bytes[j] = (byte) Integer.parseInt(Character.toString(c), 16);
        } catch(Exception e) {
            return s.substring(i);
        }
    }

    String result = null;
    try {
        result = new String(bytes, "UTF-8");
    } catch(Exception e) {}

    if(result == null) {
        return s;
    }

    return result + s.substring(i + 2 + count);
}

