import java.io.IOException;
import java.io.Reader;
import java.sql.ResultSet;
import java.sql.SQLException;

public class ResultSetReader extends Reader {

    private ResultSet resultSet;
    private String currentLine;

    public ResultSetReader(ResultSet resultSet) throws SQLException {
        this.resultSet = resultSet;
        this.currentLine = null;
    }

    @Override
    public int read(char[] cbuf, int off, int len) throws IOException {
        int numCharsRead = 0;
        try {
            if (currentLine == null) {
                if (!resultSet.next()) {
                    return -1;
                }
                currentLine = resultSet.getString(1);
            }
            while (numCharsRead < len && currentLine != null) {
                int numCharsToCopy = Math.min(currentLine.length(), len - numCharsRead);
                currentLine.getChars(0, numCharsToCopy, cbuf, off);
                off += numCharsToCopy;
                numCharsRead += numCharsToCopy;
                if (numCharsToCopy < currentLine.length()) {
                    currentLine = currentLine.substring(numCharsToCopy);
                } else {
                    currentLine = null;
                }
            }
            return numCharsRead;
        } catch (SQLException e) {
            throw new IOException("Error while reading query result", e);
        }
    }

    @Override
    public void close() throws IOException {
        try {
            resultSet.close();
        } catch (SQLException e) {
            throw new IOException("Error while closing result set", e);
        }
    }
}

