import java.util.ArrayList;
import java.util.List;

public class GroupGenerator {

    public static List<int[]> generateGroup(int[][] permutations) {
        List<int[]> groupGenerators = new ArrayList<>();
        for (int i = 0; i < permutations.length; i++) {
            groupGenerators.add(permutations[i]);
            for (int j = i + 1; j < permutations.length; j++) {
                int[] pi = permutations[i];
                int[] pj = permutations[j];
                int[] pi_x_pj = multiplyPermutations(pi, pj);
                groupGenerators.add(pi_x_pj);
            }
            for (int k = 2; k <= permutations.length; k++) {
                int[] p_k_prime = powerPermutation(permutations[i], k);
                groupGenerators.add(p_k_prime);
            }
        }
        return groupGenerators;
    }

    private static int[] multiplyPermutations(int[] pi, int[] pj) {
        int[] result = new int[pi.length];
        for (int i = 0; i < pi.length; i++) {
            result[i] = pi[pj[i]];
        }
        return result;
    }

    private static int[] powerPermutation(int[] p, int k) {
        if (k == 1) {
            return p.clone();
        }
        int[] result = multiplyPermutations(p, p);
        for (int i = 3; i <= k; i++) {
            result = multiplyPermutations(result, p);
        }
        return result;
    }
}

