    // Loop to read the class name characters
    while (true) {
        // Check if the current character is a valid name character
        if (isNmchar(currentChar) || currentChar == '_' || currentChar == '-' || isNonascii(currentChar) || isEscape(currentChar)) {
            className.append(currentChar);
            consumeChar();
        } else {
            break;
        }
    }
    // Check if the class name is empty
