public static double[][][] squeeze(String name, double[][][] x, int axis) {
   int[] shape = getShape(x);
   int[] newShape = new int[shape.length - 1];
   int j = 0;
   for (int i = 0; i < shape.length; i++) {
      if (i != axis && shape[i] != 1) {
         newShape[j] = shape[i];
         j++;
      }
   }
   double[][][] output = new double[newShape[0]][newShape[1]][newShape[2]];
   for (int i = 0; i < newShape[0]; i++) {
      for (int j = 0; j < newShape[1]; j++) {
         for (int k = 0; k < newShape[2]; k++) {
            int[] index = new int[shape.length - 1];
            int l = 0;
            for (int m = 0; m < shape.length; m++) {
               if (m != axis && shape[m] != 1) {
                  index[l] = (m < axis) ? m : m - 1;
                  l++;
               }
            }
            output[i][j][k] = x[index[0]][index[1]][index[2]];
         }
      }
   }
   return output;
}

private static int[] getShape(double[][][] x) {
   int[] shape = new int[3];
   shape[0] = x.length;
   shape[1] = x[0].length;
   shape[2] = x[0][0].length;
