public String sendJobStatusRequest(String jobId) throws IOException {
    String url = "http://mykie-server.com/jobs/" + jobId +"/status";
    HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
    connection.setRequestMethod("GET");

    int responseCode = connection.getResponseCode();
    String status = responseCode == HttpURLConnection.HTTP_OK ? "SUCCESS" : "BAD_REQUEST";

    BufferedReader in = new BufferedReader(
            new InputStreamReader(connection.getInputStream()));
    String inputLine;
    StringBuffer response = new StringBuffer();

    while ((inputLine = in.readLine()) != null) {
        response.append(inputLine);
    }
    in.close();

    return status + ":" + response.toString();
}

