public BoundingBox boundingBoxFromWgs84(BoundingBox boundingBox) {
	// Assuming the feature projection is UTM Zone 33N
    CoordinateReferenceSystem sourceCRS = CRS.decode("EPSG:4326"); // WGS84
    CoordinateReferenceSystem targetCRS = CRS.decode("EPSG:32633"); // UTM Zone 33N

    MathTransform transform = CRS.findMathTransform(sourceCRS, targetCRS, true);

    DirectPosition2D lowerLeft = new DirectPosition2D(boundingBox.getMinX(), boundingBox.getMinY());
    DirectPosition2D upperRight = new DirectPosition2D(boundingBox.getMaxX(), boundingBox.getMaxY());

    DirectPosition2D lowerLeftTransformed = new DirectPosition2D();
    DirectPosition2D upperRightTransformed = new DirectPosition2D();

    try {
        transform.transform(lowerLeft, lowerLeftTransformed);
        transform.transform(upperRight, upperRightTransformed);
    } catch (TransformException e) {
        e.printStackTrace();
    }

    return new BoundingBox(lowerLeftTransformed.x, lowerLeftTransformed.y, upperRightTransformed.x, upperRightTransformed.y);
}

