public static String flattenIntervals(String str) {
    if(str == null || str.isEmpty()) {
        return str;
    }
    int open = str.lastIndexOf('(');
    if(open == -1) {
        return str;
    }
    int close = str.indexOf(')', open);
    if(close == -1) {
        return str;
    }
    String inner = str.substring(open + 1, close);
    String outer = str.substring(open, close + 1);
    return flattenIntervals(str.replace(outer, inner));
}

