public ValidationResult addLocusTagQualifiers(Entry entry) {
    ValidationResult result = new ValidationResult();
    List<Feature> features = entry.getFeatures();

    Map<String, String> geneToLocusTagMap = new HashMap<String, String>();
    for (Feature feature : features) {
        String geneQualifier = feature.getSingleQualifierValue("gene");
        String locusTagQualifier = feature.getSingleQualifierValue("locus_tag");
        if (geneQualifier != null && locusTagQualifier != null) {
            if (!geneToLocusTagMap.containsKey(geneQualifier)) {
                geneToLocusTagMap.put(geneQualifier, locusTagQualifier);
            } else if (!geneToLocusTagMap.get(geneQualifier).equals(locusTagQualifier)) {
                result.addError("Multiple locus_tags associated with the same gene: " + geneQualifier);
            }
        }
    }

    for (Feature feature : features) {
        String geneQualifier = feature.getSingleQualifierValue("gene");
        String locusTagQualifier = geneToLocusTagMap.get(geneQualifier);
        if (geneQualifier != null && locusTagQualifier != null && feature.getQualifier("locus_tag") == null) {
            feature.addQualifier(new Qualifier("locus_tag", locusTagQualifier));
        }
    }

