public void printXmlRepresentation() throws IOException, NotInMessageStore {
    // check if the message is in the message store
    if (!isInMessageStore()) {
        throw new NotInMessageStore();
    }

    // get the XML representation of the message
    String xml = toXml();

    // recursively print the XML representation to standard output
    printXmlRecursive(xml);
}

private void printXmlRecursive(String xml) {
    System.out.println(xml);

    // get the child nodes of the XML document
    NodeList childNodes = getNodeList(xml);

    // recursively print the XML representation of the child nodes
    for (int i = 0; i < childNodes.getLength(); i++) {
        String childXml = getNodeXml(childNodes.item(i));
        printXmlRecursive(childXml);
    }
}

private NodeList getNodeList(String xml) {
    // parse the XML document
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    factory.setIgnoringElementContentWhitespace(true);
    try {
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(new ByteArrayInputStream(xml.getBytes()));
        return document.getChildNodes();
    } catch (Exception e) {
        e.printStackTrace();
    }
    return null;
}

private String getNodeXml(Node node) {
    // get the XML representation of a node
    try {
        Transformer transformer = TransformerFactory.newInstance().newTransformer();
        transformer.setOutputProperty(OutputKeys.OMIT_XML_DECLARATION, "yes");
        StringWriter writer = new StringWriter();
        transformer.transform(new DOMSource(node), new StreamResult(writer));
        return writer.toString().replaceAll("\n|\r", "");
    } catch (Exception e) {
        e.printStackTrace();
    }
    return null;
}

