import java.net.URI;
import java.util.*;

public Map<String, Class<?>> getKnownSubclasses(Class<?> clazz, URI location) {

    Map<String, Class<?>> map = new HashMap<>();
    String className = clazz.getSimpleName();
    String packageName = clazz.getPackage().getName();

    List<Class<?>> classes = ClassFinder.find(location, packageName);
    for (Class<?> aClass : classes) {
        if (className.equals(aClass.getSuperclass().getSimpleName())) {
            map.put(aClass.getSimpleName(), aClass);
        }
    }
    return map;
}

class ClassFinder {
    private static String classFileExtension = ".class";

    static List<Class<?>> find(URI location, String packageName) {
        List<Class<?>> result = new ArrayList<>();
        try {
            String directory = location.getPath();
            directory = directory.endsWith("/") ? directory : directory + "/";
            String scannedPath = directory + packageName.replace(".", "/");

            Enumeration<URL> resourceUrls = Thread.currentThread().getContextClassLoader().getResources(scannedPath);
            while (resourceUrls.hasMoreElements()) {
                URL scannedUrl = resourceUrls.nextElement();
                if (scannedUrl.getProtocol().equals("file")) {
                    result.addAll(findClasses(new File(scannedUrl.getFile()), packageName));
                }
            }
        } catch (IOException e) {
            throw new RuntimeException("Could not scan package " + packageName, e);
        }
        return result;
    }

    private static List<Class<?>> findClasses(File directory, String packageName) {
        List<Class<?>> classes = new ArrayList<>();
        if (!directory.exists()) {
            return classes;
        }
        File[] files = directory.listFiles();
        if (files == null) {
            return classes;
        }
        for (File file : files) {
            if (file.isDirectory()) {
                assert !file.getName().contains(".");
                classes.addAll(findClasses(file, packageName + "." + file.getName()));
            } else if (file.getName().endsWith(classFileExtension)) {
                classes.add(loadClass(packageName + '.' + file.getName().substring(0, file.getName().length() - classFileExtension.length())));
            }
        }
        return classes;
    }

    private static Class<?> loadClass(String className) {
        try {
            return Class.forName(className);
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Could not load class " + className, e);
        }
    }
}

