public static Set<String> computeBackbone(Formula formula, Set<String> variables) {
    Solver solver = SolverFactory.newDefault();
    List<Literal> assumptions = new ArrayList<>();
    for (String variable : variables) {
        Literal literal = formula.getVariable(variable);
        if (literal != null) {
            // add the literal as an assumption for the solver
            assumptions.add(literal);
        } else {
            // the variable is not present in the formula, so the backbone is empty
            return Collections.emptySet();
        }
    }
    try {
        // solve the formula with the given assumptions
        Result result = solver.solve(formula, assumptions);
        if (result == Result.SAT) {
            // the formula is satisfiable, so the backbone is the set of variables that appear with the same polarity in all satisfying assignments
            Map<String, Boolean> polarities = new HashMap<>();
            for (Assignment assignment : solver.enumerateAssignments()) {
                for (Literal literal : assignment) {
                    String variable = literal.getVariable();
                    boolean polarity = literal.isPositive();
                    boolean prevPolarity = polarities.getOrDefault(variable, polarity);
                    if (polarity != prevPolarity) {
                        // the variable has different polarity in different satisfying assignments, so it is not part of the backbone
                        polarities.remove(variable);
                    } else {
                        polarities.put(variable, polarity);
                    }
                }
                if (polarities.isEmpty()) {
                    // all variables have different polarity in different satisfying assignments, so no variable is part of the backbone
                    return Collections.emptySet();
                }
            }
            return polarities.keySet();
        } else {
            // the formula is unsatisfiable, so the backbone is null
            return null;
        }
    } catch (SolverTimeoutException e) {
        // the solver timed out, so the backbone is unknown
        return null;
    }
}

