	// Check if the bean is a normal scoped bean
    if (!bean.getScope().equals(NormalScoped.class)) {
        return false;
    }

    // Check if the bean is not an alternative
    if (bean.isAlternative()) {
        return false;
    }

    // Check if the bean is not a decorator
    if (bean instanceof Decorator) {
        return false;
    }

    // Check if the bean is not an interceptor
    if (bean instanceof Interceptor) {
        return false;
    }

    // Check if the bean is not a producer method or field
    if (bean instanceof ProducerMethod || bean instanceof ProducerField) {
        return false;
    }

    // Check if the bean is not a passivation capable dependency
    if (!bean.isPassivationCapable()) {
        return false;
    }

    // Check if the bean is not a dependent scoped bean
    if (bean.getScope().equals(Dependent.class)) {
        return false;
    }

    // Check if the bean is not a singleton scoped bean
    if (!bean.getScope().equals(Singleton.class)) {
        return false;
    }

    // Check if the bean is not a session scoped bean
    if (!bean.getScope().equals(SessionScoped.class)) {
        return false;
    }

    // Check if the bean is not a request scoped bean
    if (!bean.getScope().equals(RequestScoped.class)) {
