            Class<?> elementType = fieldDef.getCollectionElementType();
            if (Model.class.isAssignableFrom(elementType)) {
                ModelDefinition<?> refModelDef = ModelUtils.getModelDefinition((Class<? extends Model>) elementType);
                ForeignKeyDefinition foreignKeyDef = refModelDef.findForeignKeyDefinition(fieldDef.getCollectionElementForeignKeyName());
