private boolean isSimilar(String str1, String str2) {
    int len1 = str1.length();
    int len2 = str2.length();
    if (Math.abs(len1 - len2) > 1) {
        return false;
    }
    int i = 0, j = 0;
    int diffCount = 0;
    while (i < len1 && j < len2) {
        if (str1.charAt(i) == str2.charAt(j)) {
            i++;
            j++;
        } else {
            if (diffCount == 1) {
                return false;
            }
            diffCount++;
            if (len1 > len2) {
                i++;
            } else if (len1 < len2) {
                j++;
            } else {
                i++;
                j++;
            }
        }
    }
    if (diffCount == 1 && i == len1 && j == len2) {
        return true;
    }
    if (diffCount == 0 && i == len1 - 1 && j == len2 - 1) {
        return true;
    }
    return false;
}

