public static <T extends Planar<T>> T meanBox(ImageGray<T> input, T output, int radius, T storage) {
    if (output != null) {
        output.reshape(input.getWidth(), input.getHeight());
    } else {
        output = input.createSameShape();
    }

    final T padded = (storage == null) ? input.createSameShape() : storage;

    int w = radius*2+1;
    int total = w*w;

    int offset[] = new int[ total ];
    int index = 0;
    for( int i = -radius; i <= radius; i++ ) {
        for( int j = -radius; j <= radius; j++ ) {
            offset[index++] = i*input.stride+j;
        }
    }

    for (int y = 0; y < input.height; y++) {
        for (int x = 0; x < input.width; x++) {
            int index1 = input.startIndex + y*input.stride + x;

            GImageMiscOps.fill(padded, 0);
            // compute the sum of all the pixel along the row axis for the first `w` columns
            for (int i = 0; i < w && x+i < input.width; i++) {
                int index2 = input.startIndex + y*input.stride + (x+i);
                for (int j = 0; j < total; j++) {
                    padded.data[index2 + offset[j]] += input.data[index1+offset[j]];
                }
            }
            // fill the rest of the padded area in the row direction
            for (int i = 0; i < total; i++) {
                for (int j = w; j < 2*radius+1; j++) {
                    int index2 = input.startIndex + y*input.stride + Math.min(x+j, input.width-1);
                    padded.data[index2 + offset[i]] += input.data[index1+offset[i]];
                }
            }

            // compute the sum of all the pixel in the padded image in the column direction
            for (int i = 0; i < w && x+i < input.width; i++) {
                int index2 = output.startIndex + y*output.stride+(x+i);
                for (int j = 0; j < total; j++) {
                    output.data[index2+offset[j]] = padded.data[index1+offset[j]];
                }
            }
            // fill the rest of the output image in the col direction
            for (int i = w; i < 2*radius+1 && x+i < input.width; i++) {
                int index2 = output.startIndex + y*output.stride+(x+i);
                for (int j = 0; j < total; j++) {
                    output.data[index2+offset[j]] = padded.data[index1+offset[j]];
                }
            }
        }
    }

    return output;
}

