public static boolean invertMatrix(double[][] matrix) {
    int n = matrix.length;
    double[][] augmented = new double[n][2 * n];

    // build the augmented matrix [A|I]
    for (int i = 0; i < n; i++) {
        System.arraycopy(matrix[i], 0, augmented[i], 0, n);
        augmented[i][n + i] = 1;
    }

    // perform Gaussian elimination
    for (int i = 0; i < n; i++) {
        if (augmented[i][i] == 0) {
            return false;
        }
        for (int j = i + 1; j < 2 * n; j++) {
            augmented[i][j] /= augmented[i][i];
        }
        augmented[i][i] = 1; // make diagonal entries equal to 1
        for (int k = 0; k < n; k++) {
            if (k != i) {
                double factor = augmented[k][i];
                for (int j = i; j < 2 * n; j++) {
                    augmented[k][j] -= factor * augmented[i][j];
                }
            }
        }
    }

    // copy the inverted matrix from [I|B] to A
    for (int i = 0; i < n; i++) {
        System.arraycopy(augmented[i], n, matrix[i], 0, n);
    }

    return true;
}

