import java.util.Set;
import java.util.concurrent.CompletionStage;

public CompletionStage<Void> copyResourcesUnderIdentifier(NamespaceService services, Session session,
        IRI resource, IRI destination, IRI baseUrl) {

    ResourceService resourceService = services.getResourceService();

    return resourceService.get(resource, session).thenApply(resourceContainer -> {
        IRI parentContainer = resourceContainer.getContainer();
        Set<IRI> parentTypes = resourceContainer.getInteractionModel();
        resourceService.create(destination, parentContainer, parentTypes, session).thenCompose(createdResource ->
                resourceService.get(createdResource.getIdentifier(), session).thenApply(createdResourceContainer -> {
                    createdResourceContainer.getBinaryMetadata().addAll(resourceContainer.getBinaryMetadata());
                    return createdResourceContainer;
                }).thenCompose(updatedResourceContainer ->
                        resourceService.update(createdResource.getIdentifier(), updatedResourceContainer.getIdentifier(), session)
                )
        );
    }).thenCompose(next -> {
        // Look for any contained resources on the original resource
        return resourceService.get(resource, session).thenCompose(resourceContainer -> {
            Set<IRI> resourceTypes = resourceContainer.getInteractionModel();
            return resourceService.get(resourceContainer.getIdentifier(), session).thenCompose(resourceBlob -> {
                if (resourceTypes.contains(LDP.Container)) {
                    // Recurse for all contained resources
                    return resourceService.getContainedBy(resourceBlob).thenCompose(children -> {
                        return CompletableFuture.allOf(children.stream().map(child -> {
                            try {
                                String childPath = child.getIdentifier().getIRIString().replace(
                                        resourceContainer.getIdentifier().getIRIString() + "/", "");
                                IRI childDestination = Trellis.Utils.getInstanceNs().resolve(childPath);
                                return copyResourcesUnderIdentifier(services, session, child.getIdentifier(), childDestination, baseUrl);
                            } catch (final Exception ex) {
                                throw new TrellisRuntimeException("Error copying resource " + child.getIdentifier() + " to " + destination + " : " + ex.getMessage(), ex);
                            }
                        }).toArray(CompletableFuture[]::new));
                    });
                } else {
                    // copy the resource
                    return resourceService.get(resourceContainer.getIdentifier(), session).thenCompose(resourceData -> {
                        final String containerPath = resourceContainer.getContainer().getIRIString().replace(baseUrl.getIRIString(), "");
                        final IRI newParent = destination.resolve(containerPath);
                        final IRI dest = newParent.resolve(resourceData.getIdentifier().getIRIString().replace(resourceContainer.getIdentifier().getIRIString() + "/", ""));
                        return copyResourceTo(service, session, resourceData, dest);
                    });
                }
            });
        });
    });
}

private CompletionStage<Void> copyResourceTo(ResourceService service, Session session, Resource data, IRI dest) {
    return service.create(dest, data.getContainer(), data.getInteractionModel(), session).thenCompose(createdResource ->
            service.get(createdResource.getIdentifier(), session).thenApply(createdResourceContainer -> {
                createdResourceContainer.getBinaryMetadata().addAll(data.getBinaryMetadata());
                createdResourceContainer.getMetadata().addAll(data.getMetadata());
                return createdResourceContainer;
            }).thenCompose(updatedContainer -> service.update(createdResource.getIdentifier(), updatedContainer, session)));
}

