public class ResourceCopier {

    public static void recursiveCopy(File source, File destination) throws IOException {
        if (source.isDirectory()) {
            if (!destination.exists()) {
                destination.mkdir();
            }
            String[] children = source.list();
            for (String child : children) {
                recursiveCopy(new File(source, child), new File(destination, child));
            }
        } else {
            Files.copy(source.toPath(), destination.toPath());
        }
    }

    public static void main(String[] args) throws IOException {
        File source = new File("path/to/source");
        File destination = new File("path/to/destination");
        recursiveCopy(source, destination);
    }
}

