import java.util.List;

public class Diff {

    public static class Operation {
        enum Type {
            DELETE,
            INSERT,
            EQUAL
        }

        public Type type;
        public String data;

        public Operation(Type type, String data) {
            this.type = type;
            this.data = data;
        }
    }

    public static class Result {
        public List<Operation> operations = new LinkedList<>();
    }

    public static Result diff(String text1, String delta) throws IllegalArgumentException {
        Result result = new Result();

        int i = 0;
        int deltaLength = delta.length();
        while (i < deltaLength) {
            char code = delta.charAt(i);
            i++;

            int numChars = 0;
            while (i < deltaLength) {
                char c = delta.charAt(i);
                i++;

                if (c < '0' || c > '9')
                    break;

                numChars = (numChars * 10) + (c - '0');
            }

            String data = delta.substring(i, i + numChars);
            i += numChars;

            // apply operation based on code
            switch (code) {
                case '0': // equal
                    result.operations.add(new Operation(Operation.Type.EQUAL, data));
                    break;
                case '1': // insert
                    result.operations.add(new Operation(Operation.Type.INSERT, data));
                    break;
                case '2': // delete
                    result.operations.add(new Operation(Operation.Type.DELETE, data));
                    break;
                default:
                    throw new IllegalArgumentException("Invalid delta code: " + code);
            }
        }

        return result;
    }
}

