					return slot;
				}
				else {

					if (queueIfNoResource) {
						CompletableFuture<LogicalSlot> future = new CompletableFuture<>();
						this.taskQueue.add(new QueuedTask(task, future));
						return future;
					}
					else if (forceExternalLocation) {
