    private static class DirectoryIteratorImpl implements Iterator<File> {

        private final File[] childrenFiles;
        private int currentIndex;
        private DirectoryIteratorImpl subIterator;

        DirectoryIteratorImpl(File directory) {
            if (!directory.isDirectory()) {
                throw new IllegalArgumentException("File must be a directory");
            }
            this.childrenFiles = directory.listFiles();
            this.currentIndex = 0;
            this.subIterator = null;
        }

        @Override
        public boolean hasNext() {
            if (currentIndex < childrenFiles.length) {
                return true;
            } else if (subIterator != null && subIterator.hasNext()) {
                return true;
            } else {
                while (currentIndex < childrenFiles.length) {
                    File child = childrenFiles[currentIndex++];
                    if (child.isDirectory()) {
                        subIterator = new DirectoryIteratorImpl(child);
                        if (subIterator.hasNext()) {
                            return true;
                        }
                    } else {
                        return true;
                    }
                }
                return false;
            }
        }

        @Override
        public File next() {
            if (hasNext()) {
                if (subIterator != null && subIterator.hasNext()) {
                    return subIterator.next();
                } else {
                    return childrenFiles[currentIndex++];
                }
            } else {
                throw new IllegalStateException("No more files in directory");
