import java.io.File;
import java.util.Iterator;
import java.util.Stack;

public class DirectoryIterator implements Iterator<File> {

    private Stack<File> stack = new Stack<>();

    public DirectoryIterator(String directory) {
        stack.push(new File(directory));
    }

    @Override
    public boolean hasNext() {
        return !stack.isEmpty();
    }

    @Override
    public File next() {
        File file = stack.pop();
        if (file.isDirectory()) {
            for (File f : file.listFiles()) {
                stack.push(f);
            }
        }
        return file;
    }
}

