private void updateCRC(byte[] pBytes, int pOff, int pLen) {
	// Calculate the CRC for the specified range of bytes
    int crc = calculateCRC(pBytes, pOff, pLen);

    // Store the CRC in the last 4 bytes of the byte array
    pBytes[pOff + pLen] = (byte) (crc & 0xFF);
    pBytes[pOff + pLen + 1] = (byte) ((crc >> 8) & 0xFF);
    pBytes[pOff + pLen + 2] = (byte) ((crc >> 16) & 0xFF);
    pBytes[pOff + pLen + 3] = (byte) ((crc >> 24) & 0xFF);
}

private int calculateCRC(byte[] pBytes, int pOff, int pLen) {
    int crc = 0xFFFFFFFF; // Initial CRC value
    for (int i = 0; i < pLen; i++) {
        crc = (crc >>> 8) ^ crcTable[(crc ^ pBytes[pOff + i]) & 0xFF];
    }
    return crc ^ 0xFFFFFFFF; // Finalize the CRC value
}

