import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class Task<T, TError> {
    private final Lock lock = new ReentrantLock();
    private final List<ISynchronizationPoint<?>> synchronizationPoints = new ArrayList<>();

    public Task<T, TError> ensureUnblocked(ISynchronizationPoint<?>... sp) {
        lock.lock();
        try {
            for (ISynchronizationPoint<?> synchronizationPoint : sp) {
                synchronizationPoints.add(synchronizationPoint);
                synchronizationPoint.unblock();
            }
        } finally {
            lock.unlock();
        }
        return this;
    }

    public void onTaskCompletion() {
        lock.lock();
        try {
            for (ISynchronizationPoint<?> synchronizationPoint : synchronizationPoints) {
                if (!synchronizationPoint.isUnblocked()) {
                    synchronizationPoint.cancel();
                }
            }
        } finally {
            lock.unlock();
        }
    }
}

