public static List<Object> enforceMemoryLimits(List<Object> queryResults, int memoryLimit) {
    if (queryResults == null || memoryLimit <= 0) {
        return new ArrayList<>();
    }
    long totalMemoryUsage = 0;
    List<Object> resultsWithinMemoryLimit = new ArrayList<>();
    for (Object queryResult : queryResults) {
        long memoryUsage = getObjectSize(queryResult);
        if (memoryUsage <= memoryLimit && totalMemoryUsage + memoryUsage <= memoryLimit) {
            totalMemoryUsage += memoryUsage;
            resultsWithinMemoryLimit.add(queryResult);
        } else {
            break;
        }
    }
    return resultsWithinMemoryLimit;
}

private static long getObjectSize(Object object) {
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    ObjectOutputStream oos;
    try {
        oos = new ObjectOutputStream(baos);
        oos.writeObject(object);
        oos.close();
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
    return baos.size();
}

