protected static StringBuilder reverse(final StringBuilder string) { 
    int length = string.length();
    for (int i = 0; i < length / 2; i++) {
        char temp = string.charAt(i);
        string.setCharAt(i, string.charAt(length - i - 1));
        string.setCharAt(length - i - 1, temp);
    }
    return string;
}

protected static StringBuilder trim(final StringBuilder string) { 
    int start = 0;
    int end = string.length() - 1;
    while (start <= end && Character.isWhitespace(string.charAt(start))) {
        start++;
    }
    while (end >= start && Character.isWhitespace(string.charAt(end))) {
        end--;
    }
    if (start > 0 || end < string.length() - 1) {
        string.delete(0, start);
        string.delete(end - start + 1, string.length());
    }
    return string;
}

protected static StringBuilder padLeft(final StringBuilder string, final int length, final char padChar) { 
    if (string.length() < length) {
        int padding = length - string.length();
        for (int i = 0; i < padding; i++) {
            string.insert(0, padChar);
        }
    }
    return string;
}

protected static StringBuilder padRight(final StringBuilder string, final int length, final char padChar) { 
    if (string.length() < length) {
        int padding = length - string.length();
        for (int i = 0; i < padding; i++) {
            string.append(padChar);
        }
    }
    return string;
}

