public Future<TransactionEvent> sendTransactionToOrderer(Collection<ProposalResponse> proposalResponses, TransactionOptions transactionOptions) throws InvalidArgumentException {

    Collection<Orderer> orderers = transactionOptions.getOrderers();
    User userContext = transactionOptions.getUserContext();
    Channel channel = transactionOptions.getChannel();

    if (orderers.isEmpty()) {
        throw new InvalidArgumentException("No orderer specified");
    }

    if (userContext == null) {
        throw new InvalidArgumentException("User context not specified");
    }

    if (channel == null) {
        throw new InvalidArgumentException("Channel not specified");
    }

    try {
        TransactionProposalRequest transactionProposalRequest = channel.generateTransactionProposalRequest(userContext);
        transactionProposalRequest.setSubmitted(true);

        Collection<ProposalResponse> validProposalResponses = ProposalResponseUtils.getValidProposalResponses(
                proposalResponses,
                transactionOptions.getEndorsementPolicy(),
                orderers.size());

        if (validProposalResponses.size() < orderers.size()) {
            throw new InvalidArgumentException("Not enough valid proposal responses for orderer endorsements");
        }

        Channel.NOfEvents nOfEvents = transactionOptions.getNOfEvents();
        if (nOfEvents == null) {
            nOfEvents = Channel.NOfEvents.createNofEvents();
        }

        orderers.forEach(orderer -> {
            try {
                channel.sendTransaction(
                        validProposalResponses,
                        orderer,
                        nOfEvents,
                        transactionOptions.getTransactionTimeout(),
                        transactionOptions.getRetryOptions());
            } catch (InvalidArgumentException | TransactionException | InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        });

        CompletableFuture<TransactionEvent> transactionEventFuture = channel.getEventHub().getTransactionEvent(transactionProposalRequest.getTransactionID());

        if (transactionEventFuture.isDone()) {
            TransactionEvent transactionEvent = transactionEventFuture.get(transactionOptions.getTransactionTimeout(), TimeUnit.MILLISECONDS);
            if (transactionEvent.isValid()) {
                return CompletableFuture.completedFuture(transactionEvent);
            } else {
                throw new TransactionException("Transaction failed for unknown reason");
            }
        } else {
            return transactionEventFuture;
        }
    } catch (InvalidArgumentException | ProposalException | ExecutionException | InterruptedException | TimeoutException | TransactionException e) {
        throw new RuntimeException(e);
    }
}

