import java.nio.file.*;
import java.util.zip.*;

public byte[] compressDirectory(File sourceDirectory, String pathPrefix, String chaincodeMetaInf) throws IOException {
    ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    try (
        FileOutputStream fileOutputStream = new FileOutputStream(byteArrayOutputStream);
        BufferedOutputStream bufferedOutputStream = new BufferedOutputStream(fileOutputStream);
        GZIPOutputStream gzipOutputStream = new GZIPOutputStream(bufferedOutputStream);
        TarArchiveOutputStream tarArchiveOutputStream = new TarArchiveOutputStream(gzipOutputStream)
    ) {
        if(pathPrefix != null && !pathPrefix.isEmpty()) {
            pathPrefix = pathPrefix.endsWith("/") ? pathPrefix : pathPrefix + "/";
        } else {
            pathPrefix = "";
        }
        Path directoryPath = Paths.get(sourceDirectory.toURI());
        Files.walk(directoryPath)
            .filter(Files::isRegularFile)
            .forEach(filePath -> {
                try {
                    TarArchiveEntry tarArchiveEntry = new TarArchiveEntry(directoryPath.relativize(filePath).toString());
                    tarArchiveEntry.setSize(Files.size(filePath));
                    tarArchiveOutputStream.putArchiveEntry(tarArchiveEntry);
                    Files.copy(filePath, tarArchiveOutputStream);
                    tarArchiveOutputStream.closeArchiveEntry();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            });
    }
    return byteArrayOutputStream.toByteArray();
}

