public static boolean like(Class src, Class trg) {
	// Check if src is the same as trg
    if (src.equals(trg)) {
        return true;
    }
    // Check if src is a subclass of trg
    if (trg.isAssignableFrom(src)) {
        return true;
    }
    // Check if src and trg are interfaces and src implements trg
    if (src.isInterface() && trg.isInterface() && src.isAssignableFrom(trg)) {
        return true;
    }
    // Check if src and trg are interfaces and trg implements src
    if (src.isInterface() && trg.isInterface() && trg.isAssignableFrom(src)) {
        return true;
    }
    // Check if src and trg are both interfaces and have a common superinterface
    if (src.isInterface() && trg.isInterface()) {
        for (Class<?> iface : src.getInterfaces()) {
            if (trg.isAssignableFrom(iface)) {
                return true;
            }
        }
        for (Class<?> iface : trg.getInterfaces()) {
            if (src.isAssignableFrom(iface)) {
                return true;
            }
        }
    }
    return false;
}

