public List<Geometry> getXMaxima(Geometry expr, int x) {
    Envelope envelope = expr.getEnvelopeInternal();
    List<Geometry> maxima = new ArrayList<>();

    if (envelope != null) {
        PriorityQueue<Geometry> queue = new PriorityQueue<>(Comparator.comparing(Geometry::getArea).reversed());

        // Add the geometry and its subgeometries to the queue
        queue.addAll(Arrays.asList(expr, expr.getInteriorRingN(0), expr.getBoundary()));
        for (int i = 0; i < expr.getNumGeometries(); i++) {
            queue.addAll(Arrays.asList(expr.getGeometryN(i), expr.getGeometryN(i).getInteriorRingN(0), expr.getGeometryN(i).getBoundary()));
        }

        // Process the queue and extract the first X maxima
        while (!queue.isEmpty() && maxima.size() < x) {
            Geometry candidate = queue.poll();
            if (envelope.equals(candidate.getEnvelopeInternal())) {
                maxima.add(candidate);
            } else if (candidate.getNumGeometries() > 1) {
                // If the geometry is a collection, add its subgeometries to the queue
                for (int i = 0; i < candidate.getNumGeometries(); i++) {
                    queue.add(candidate.getGeometryN(i));
                }
            }
        }
    }

    return maxima;
}

