import java.util.Random;

public class RandomRotation {
    private final double[][] rotationMatrix;

    public RandomRotation() {
        Random random = new Random();
        double theta = random.nextDouble() * Math.PI * 2;
        double phi = random.nextDouble() * Math.PI * 2;

        double[][] xRotationMatrix = {{1, 0, 0}, {0, Math.cos(theta), -Math.sin(theta)}, {0, Math.sin(theta), Math.cos(theta)}};
        double[][] yRotationMatrix = {{Math.cos(phi), 0, Math.sin(phi)}, {0, 1, 0}, {-Math.sin(phi), 0, Math.cos(phi)}};

        rotationMatrix = matrixMultiplication(xRotationMatrix, yRotationMatrix);
    }

    private static double[][] matrixMultiplication(double[][] a, double[][] b) {
        int aRows = a.length;
        int aColumns = a[0].length;
        int bColumns = b[0].length;

        double[][] c = new double[aRows][bColumns];
        for (int i = 0; i < aRows; i++) {
            for (int j = 0; j < bColumns; j++) {
                for (int k = 0; k < aColumns; k++) {
                    c[i][j] += a[i][k] * b[k][j];
                }
            }
        }

        return c;
    }

    public double[] randomlyRotate(double[] vector) {
        double[] rotatedVector = new double[3];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                rotatedVector[i] += rotationMatrix[i][j] * vector[j];
            }
        }
        return rotatedVector;
    }
}

