public int getRelativeDayOfWeek(int year, int month, int day, String dayOfWeek, boolean yearly) {
    Calendar date = Calendar.getInstance(); // Get calendar instance
    date.set(year, month - 1, day); // Set the specified date

    int targetDayOfWeek = getDayOfWeek(dayOfWeek); // Get target day of week

    int currentYear = date.get(Calendar.YEAR); // Get current year
    int currentMonth = date.get(Calendar.MONTH) + 1; // Get current month
    int currentDay = date.get(Calendar.DAY_OF_MONTH); // Get current day

    if (yearly) {
        // Yearly relative day of week
        if (currentMonth > month || (currentMonth == month && currentDay >= day)) {
            date.set(currentYear + 1, month - 1, day); // Set the target date to next year
        } else {
            date.set(currentYear, month - 1, day); // Set the target date to current year
        }
        return (targetDayOfWeek - date.get(Calendar.DAY_OF_WEEK) + 7) % 7 + 1; // Return relative day of week
    } else {
        // Monthly relative day of week
        date.set(Calendar.DAY_OF_MONTH, 1); // Set the day to the first day of the month
        int firstDayOfWeek = date.get(Calendar.DAY_OF_WEEK); // Get the day of the week of the first day of the month
        int offset = targetDayOfWeek - firstDayOfWeek; // Calculate the offset
        if (offset < 0) { // If the offset is negative, add 7 to wrap around to the next week
            offset += 7;
        }
        return offset + 1; // Return relative day of week
    }
}

private int getDayOfWeek(String dayOfWeek) {
    switch (dayOfWeek.toLowerCase()) {
        case "sunday":
            return Calendar.SUNDAY;
        case "monday":
            return Calendar.MONDAY;
        case "tuesday":
            return Calendar.TUESDAY;
        case "wednesday":
            return Calendar.WEDNESDAY;
        case "thursday":
            return Calendar.THURSDAY;
        case "friday":
            return Calendar.FRIDAY;
        case "saturday":
            return Calendar.SATURDAY;
        default:
            throw new IllegalArgumentException("Invalid day of week: " + dayOfWeek);
    }
}

