        boolean lastCharWasWhitespace = false;
        boolean changed = false;
        char[] characters = orig.toCharArray();
        for (int i = 0; i < characters.length; i++) {
            if (Character.isWhitespace(characters[i])) {
                if (lastCharWasWhitespace) {

