public static <T> Stream<List<T>> groupData(Stream<T> stream, BiPredicate<T, T> predicate) {
    return stream.collect(
        Collector.of(
            ArrayList::new, 
            (list, item) -> {
                if (!list.isEmpty() && !predicate.test(list.get(list.size()-1), item)) {
                    list = new ArrayList<>();
                }
                list.add(item);
            }, 
            (list1, list2) -> {
                if (list1.isEmpty()) {
                    return list2;
                }
                if (list2.isEmpty()) {
                    return list1;
                }
                if (!predicate.test(list1.get(list1.size()-1), list2.get(0))) {
                    List<T> combined = new ArrayList<>(list1);
                    combined.addAll(list2);
                    return combined;
                }
                List<T> merged = new ArrayList<>(list1);
                merged.addAll(list2.subList(1, list2.size()));
                merged.set(merged.size()-1, list2.get(0));
                return List.of(merged);
            }
        )
    ).stream();
}

