        System.out.println("Printing filenames in directory recursively");
        printFilenames(directory);
        System.out.println("Printing filenames in unsorted order");
        printFilenamesUnsorted(directory);
        System.out.println("Printing filenames in default sorted order");
        printFilenamesDefaultSorted(directory);
        System.out.println("Printing filenames in FileComparator sorted order");
        printFilenamesCustomSorted(directory);
    }

    private static void printFilenames(File directory) {
        if (directory.isDirectory()) {
            System.out.println(directory.getName() + " ");
            File[] subFiles = directory.listFiles();
            if (subFiles != null && subFiles.length > 0) {
                for (File file : subFiles) {
                    if (file.isDirectory()) {
                        System.out.print("  ");
                        printFilenames(file);
                    } else {
                        System.out.println(file.getName() + " ");
                    }
                }
            }
        }
    }

    private static void printFilenamesUnsorted(File directory) {
        if (directory.isDirectory()) {
            System.out.println(directory.getName() + " ");
            File[] subFiles = directory.listFiles();
            if (subFiles != null && subFiles.length > 0) {
                for (File file : subFiles) {
                    if (file.isDirectory()) {
                        System.out.print("  ");
                        printFilenamesUnsorted(file);
                    } else {
                        System.out.println(file.getName() + " ");
                    }
                }
            }
        }
    }

    private static void printFilenamesDefaultSorted(File directory) {
        if (directory.isDirectory()) {
            System.out.println(directory.getName() + " ");
            File[] subFiles = directory.listFiles();
            if (subFiles != null && subFiles.length > 0) {
                Arrays.sort(subFiles);
                for (File file : subFiles) {
                    if (file.isDirectory()) {
                        System.out.print("  ");
                        printFilenamesDefaultSorted(file);
                    } else {
                        System.out.println(file.getName() + " ");
                    }
                }
            }
        }
    }

    private static void printFilenamesCustomSorted(File directory) {
        if (directory.isDirectory()) {
            System.out.println(directory.getName() + " ");
            File[] subFiles = directory.listFiles();
            if (subFiles != null && subFiles.length > 0) {
                Arrays.sort(subFiles, new FileComparator());
                for (File file : subFiles) {
                    if (file.isDirectory()) {
                        System.out.print("  ");
                        printFilenamesCustomSorted(file);
                    } else {
                        System.out.println(file.getName() + " ");
                    }
                }
            }
        }
    }

    static class FileComparator implements Comparator<File> {

        @Override
        public int compare(File file1, File file2) {
            if (file1.isDirectory() && file2.isFile()) {
                // Directory before file
                return -1;
            } else if (file1.isFile() && file2.isDirectory()) {
                // File after directory
                return 1;
            } else {
                // Ascending order of name
                return file1.getName().compareTo(file2.getName());
            }
        }
    }
}

