public String applyLinkTransformation(String content, Map<String, String> references) {
    Pattern p = Pattern.compile("\\[([^\\]]+)\\]\\[([^\\]]+)\\]");
    Matcher m = p.matcher(content);
    StringBuffer sb = new StringBuffer();
    while(m.find()) {
        String link = m.group(1);
        String ref = m.group(2);
        String url = references.get(ref);
        if (url != null) {
            m.appendReplacement(sb, "[" + link + "](" + url + ")");
        }
    }
    m.appendTail(sb);
    return sb.toString();
}

