public class CommandOutputChecker {

    public static boolean checkCommandOutput(String command, String search) throws IOException {
        ProcessBuilder processBuilder = new ProcessBuilder();

        // Run a shell command
        processBuilder.command("bash", "-c", command);

        Process process = processBuilder.start();
        StringBuilder output = new StringBuilder();

        BufferedReader reader = new BufferedReader(
                new InputStreamReader(process.getInputStream()));

        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line + "\n");
        }

        int exitVal = process.waitFor();
        if (exitVal == 0) {
            // Check if the output contains the search text
            return output.toString().contains(search);
        } else {
            System.out.println("Command execution failed.");
            return false;
        }
    }

