private static void mergeField(final Tokenizer tokenizer, final ExtensionRegistry extensionRegistry, final Message.Builder builder) throws ParseException {
	final String name = tokenizer.nextName();
    final FieldDescriptor field = builder.getDescriptorForType().findFieldByName(name);
    if (field == null) {
        throw new ParseException("Unknown field: " + name);
    }
    if (field.isRepeated()) {
        mergeRepeatedField(tokenizer, extensionRegistry, builder, field);
    } else {
        mergeSingleField(tokenizer, extensionRegistry, builder, field);
    }
}

private static void mergeRepeatedField(final Tokenizer tokenizer, final ExtensionRegistry extensionRegistry, final Message.Builder builder, final FieldDescriptor field) throws ParseException {
    while (tokenizer.hasNext()) {
        final Object value = parseField(tokenizer, extensionRegistry, field);
        builder.addRepeatedField(field, value);
    }
}

private static void mergeSingleField(final Tokenizer tokenizer, final ExtensionRegistry extensionRegistry, final Message.Builder builder, final FieldDescriptor field) throws ParseException {
    final Object value = parseField(tokenizer, extensionRegistry, field);
    builder.setField(field, value);
}

private static Object parseField(final Tokenizer tokenizer, final ExtensionRegistry extensionRegistry, final FieldDescriptor field) throws ParseException {
    switch (field.getType()) {
        case DOUBLE:
            return tokenizer.nextDouble();
        case FLOAT:
            return tokenizer.nextFloat();
        case INT64:
        case SINT64:
        case SFIXED64:
            return tokenizer.nextLong();
        case UINT64:
