    BigInteger right = evalExpression(exprAst.getRight());
    return left.or(right);
}

private BigInteger evalXorExpression(AstNode exprAst) { 
    BigInteger left = evalExpression(exprAst.getLeft());
    BigInteger right = evalExpression(exprAst.getRight());
    return left.xor(right);
}

private BigInteger evalNotExpression(AstNode exprAst) { 
