    return operand.not();
}

private BigInteger evalShiftLeftExpression(AstNode exprAst) { 
    BigInteger left = evalExpression(exprAst.getLeft());
    BigInteger right = evalExpression(exprAst.getRight());
    return left.shiftLeft(right.intValueExact());
}

private BigInteger evalShiftRightExpression(AstNode exprAst) { 
    BigInteger left = evalExpression(exprAst.getLeft());
    BigInteger right = evalExpression(exprAst.getRight());
    return left.shiftRight(right.intValueExact());
