private BigInteger evalExpression(AstNode exprAst) {
    switch (exprAst.getType()) {
        case AND:
            return evalAndExpression(exprAst);
        case OR:
            return evalOrExpression(exprAst);
        case XOR:
            return evalXorExpression(exprAst);
        case NOT:
            return evalNotExpression(exprAst);
        case SHIFT_LEFT:
            return evalShiftLeftExpression(exprAst);
        case SHIFT_RIGHT:
