import java.util.Map;
import java.util.Properties;

public class ThriftToPropertiesConverter {

    public static Properties convert(String prefix, Map<String, Object> thrift, Properties properties) throws Exception {
        if (thrift == null || properties == null) {
            throw new Exception("Thrift and Properties objects must not be null");
        }

        for (Map.Entry<String, Object> entry : thrift.entrySet()) {
            String key = prefix == null ? entry.getKey() : prefix + "." + entry.getKey();
            Object value = entry.getValue();

            if (value instanceof Map) {
                convert(key, (Map<String, Object>) value, properties);
            } else {
                properties.put(key, value.toString());
            }
        }

        return properties;
    }

    public static void main(String[] args) throws Exception {
        // Example usage
        Map<String, Object> thrift = new HashMap<>();
        thrift.put("key1", "value1");
        thrift.put("key2", "value2");

        Properties properties = new Properties();
        properties = convert(null, thrift, properties);

        for (String key : properties.stringPropertyNames()) {
            System.out.println(key + " = " + properties.getProperty(key));
        }
    }
}

