public static double kendallsCorrelationDistance(int[] x, int[] y) {
    int n = x.length;
    // compute number of concordant and discordant pairs
    int concordant = 0;
    int discordant = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            if ((x[i] < x[j] && y[i] < y[j]) || (x[i] > x[j] && y[i] > y[j])) {
                concordant++;
            } else if ((x[i] < x[j] && y[i] > y[j]) || (x[i] > x[j] && y[i] < y[j])) {
                discordant++;
            }
        }
    }
    // compute Kendall's tau coefficient
    double tau = (concordant - discordant) / Math.sqrt((concordant + discordant + (n * (n-1) / 2)));
    // compute Kendall's rank correlation distance
    double kendallDist = 1 - tau;
    return kendallDist;
}

