import java.util.zip.*;

public class FolderCompressor {

    public static void compressFolder(String srcFolder, String destZipFile, boolean addBaseFolder) throws IOException {
        ZipOutputStream zipOut = new ZipOutputStream(new FileOutputStream(destZipFile));
        File folderToCompress = new File(srcFolder);
        String basePath = addBaseFolder ? folderToCompress.getParent() : folderToCompress.getPath();

        compressFolderHelper(folderToCompress, basePath, zipOut);
        zipOut.close();
    }

    private static void compressFolderHelper(File folder, String basePath, ZipOutputStream zipOut) throws IOException {
        for (File file : folder.listFiles()) {
            if (file.isDirectory()) {
                compressFolderHelper(file, basePath, zipOut);
            } else {
                String relativePath = file.getPath().substring(basePath.length() + 1);
                zipOut.putNextEntry(new ZipEntry(relativePath));
                FileInputStream fileIn = new FileInputStream(file);
                byte[] buffer = new byte[1024];
                int len;
                while ((len = fileIn.read(buffer)) > 0) {
                    zipOut.write(buffer, 0, len);
                }
                fileIn.close();
                zipOut.closeEntry();
            }
        }
    }
}

