public void expandBoundingBox(BoundingBox boundingBox, Shape shape) {
    // Get the bounding box of the shape
    Rectangle shapeBounds = shape.getBounds();

    // Expand the bounding box to include the shape
    if (shapeBounds.x < boundingBox.x) {
        boundingBox.width += boundingBox.x - shapeBounds.x;
        boundingBox.x = shapeBounds.x;
    }
    if (shapeBounds.y < boundingBox.y) {
        boundingBox.height += boundingBox.y - shapeBounds.y;
        boundingBox.y = shapeBounds.y;
    }
    if (shapeBounds.x + shapeBounds.width > boundingBox.x + boundingBox.width) {
        boundingBox.width = shapeBounds.x + shapeBounds.width - boundingBox.x;
    }
    if (shapeBounds.y + shapeBounds.height > boundingBox.y + boundingBox.height) {
        boundingBox.height = shapeBounds.y + shapeBounds.height - boundingBox.y;
    }
}

