    } else if (channelId < 320) {
        channelId -= 64;
        encoded[index++] = 0;
        encoded[index++] = (byte) channelId;
    } else {
        channelId -= 64;
        encoded[index++] = (byte) 1;
        encoded[index++] = (byte) (channelId & 0xff);
        encoded[index++] = (byte) ((channelId >> 8) & 0xff);
    }

    if (header.getLength() >= 63) {
        encoded[index++] = (byte) 0xff;
        encoded[index++] = (byte) ((header.getLength() >> 16) & 0xff);
        encoded[index++] = (byte) ((header.getLength() >> 8) & 0xff);
        encoded[index++] = (byte) (header.getLength() & 0xff);
