        encoded[index++] = (byte) (header.getTimeStamp() & 0xff);
    }

    if (header.getMessageType() == RtmpMessageType.TYPE_0_FULL || header.getMessageType() == RtmpMessageType.TYPE_1_PARTIAL) {
