public static String normalizePath(String repoPath) {
    // Replace consecutive slashes with a single slash
    String normalizedPath = repoPath.replaceAll("/+", "/");

    // Remove trailing slash
    if (normalizedPath.endsWith("/")) {
        normalizedPath = normalizedPath.substring(0, normalizedPath.length() - 1);
    }

    // Remove unnecessary dot and dot-dot components
    List<String> components = new ArrayList<>(Arrays.asList(normalizedPath.split("/")));
    ListIterator<String> iterator = components.listIterator();
    while(iterator.hasNext()) {
        String component = iterator.next();
        if (component.equals(".")) {
            iterator.remove();
        } else if (component.equals("..")) {
            int previousIndex = iterator.previousIndex();
            if (previousIndex >= 0) {
                iterator.remove();
                iterator.previous();
                iterator.remove();
            } else {
                // Path tries to go outside the repository boundary
                throw new IllegalArgumentException("Invalid path " + repoPath);
            }
        }
    }

    // Concatenate the components back into a path
    StringBuilder builder = new StringBuilder();
    components.forEach(c -> builder.append(c).append("/"));
    String finalPath = builder.toString();

    // Remove trailing slash, if present
    if (finalPath.endsWith("/")) {
        finalPath = finalPath.substring(0, finalPath.length() - 1);
    }

    return finalPath;
}

