    StringBuilder builder = new StringBuilder();
    boolean isCJK = Character.UnicodeBlock.of(chars[cjkidx]).equals(Character.UnicodeBlock.CJK_UNIFIED_IDEOGRAPHS);
    builder.append(chars[cjkidx]);
    int i = cjkidx + 1;
    while (i < chars.length) {
        boolean isCharCJK = Character.UnicodeBlock.of(chars[i]).equals(Character.UnicodeBlock.CJK_UNIFIED_IDEOGRAPHS);
        if (isCharCJK != isCJK) break;
        builder.append(chars[i]);
        i++;
    }
    if (builder.length() == 1) return null;
    return builder.toString();
