@Override
public Sql[] generateSql(final InsertStatement statement, final Database database, final SqlGeneratorChain sqlGeneratorChain) {
	final Sql[] sqls = sqlGeneratorChain.next(statement, database);
    for (Sql sql : sqls) {
        if (sql instanceof InsertSql) {
            final InsertSql insertSql = (InsertSql) sql;
            final List<ColumnValue> columnValues = insertSql.getColumnValues();
            for (final ColumnValue columnValue : columnValues) {
                final String value = columnValue.getValue();
                if (value != null && (value.startsWith("POINT(") || value.startsWith("LINESTRING(") || value.startsWith("POLYGON(") || value.startsWith("SRID="))) {
                    final String dbSpecificValue = convertToDatabaseSpecificValue(value, database);
                    columnValue.setValue(dbSpecificValue);
                }
            }
        }
    }
    return sqls;
}

private String convertToDatabaseSpecificValue(final String value, final Database database) {
    switch (database.getType()) {
        case POSTGRESQL:
            return value; // PostgreSQL supports WKT and EWKT natively
        case ORACLE:
            return "SDO_GEOMETRY(" + value + ")"; // Oracle uses SDO_GEOMETRY for spatial data
        case SQLSERVER:
            return "geometry::STGeomFromText('" + value + "', 0)"; // SQL Server uses geometry::STGeomFromText for spatial data
        case MYSQL:
            return "ST_GeomFromText('" + value + "')"; // MySQL uses ST_GeomFromText for spatial data
        default:
            throw new UnsupportedOperationException("Database type " + database.getType() + " is not supported for spatial data conversion.");
    }
}

