        if (shape.length != 2) {
            throw new IllegalArgumentException("Shape must be a 2D array");
        }

        double[][] data = new double[shape[0]][shape[1]];
        for (int i = 0; i < shape[0]; i++) {
            for (int j = 0; j < shape[1]; j++) {
