public ColorImg getPhaseSpectrumImg() {
    int width = img.getWidth();
    int height = img.getHeight();
    float[] phaseData = new float[width * height];
    float maxPhase = Float.MIN_VALUE;
    float minPhase = Float.MAX_VALUE;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            float phase = img.getPixel(x, y).phase();
            phaseData[y * width + x] = phase;
            maxPhase = Math.max(maxPhase, phase);
            minPhase = Math.min(minPhase, phase);
        }
    }

    float range = maxPhase - minPhase;
    ColorImg resultImg = ColorImg.createWithSize(width, height);
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            float phase = phaseData[y * width + x];
            float hue = (phase - minPhase) / range;
            resultImg.setPixel(x, y, LCHColor.fromLAB(100, Math.cos(phase) * 128, Math.sin(phase) * 128).toRGB());
        }
    }
    return resultImg;
}

