        String pkgPath = pkgDoc.replace(".", File.separator);
        String workingDir = System.getProperty("user.dir");
        String pkgAbsoluteDiskPath = workingDir + File.separator + "src" + File.separator + pkgPath;
        File directory = new File(pkgAbsoluteDiskPath);
        List<String> classNames = new ArrayList<>();
        if(directory.exists()) {
            File[] files = directory.listFiles();
