import java.util.regex.Matcher;
import java.util.regex.Pattern;

public String replacePortTokens(String value) {
    // Regular expression pattern for port tokens
    Pattern pattern = Pattern.compile("\\$\\{PORT_(\\d+|\\?)\\?(\\d+)?\\}");
    Matcher matcher = pattern.matcher(value);

    // Replace each match with the desired value
    StringBuffer buffer = new StringBuffer();
    while (matcher.find()) {
        String port = matcher.group(1);
        if ("?".equals(port)) {
            port = matcher.group(2);
        }
        matcher.appendReplacement(buffer, "PORT_" + port);
    }
    matcher.appendTail(buffer);

    return buffer.toString();
}

