public static int getLocalVariableIndex(Method method, String variableName) {
    LocalVariableTableParameterNameDiscoverer discoverer = new LocalVariableTableParameterNameDiscoverer();
    String[] parameterNames = discoverer.getParameterNames(method);

    int index = -1;
    for (int i = 0; i < parameterNames.length; i++) {
        if (variableName.equals(parameterNames[i])) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        LocalVariableTable table = getLocalVariableTable(method);
        for (LocalVariableTableEntry entry : table.getEntries()) {
            if (entry.getName().equals(variableName)) {
                index = entry.getIndex() - method.getParameterCount();
                break;
            }
        }
    }

    if (index == -1) {
        throw new IllegalArgumentException("No such variable found: " + variableName);
    }

    return index;
}

private static LocalVariableTable getLocalVariableTable(Method method) {
    try {
        Class<?> declaringClass = method.getDeclaringClass();
        ClassReader classReader = new ClassReader(declaringClass.getName());
        ClassNode classNode = new ClassNode();
        classReader.accept(classNode, 0);

        MethodNode methodNode = null;
        for (Object obj : classNode.methods) {
            MethodNode node = (MethodNode) obj;
            if (node.name.equals(method.getName()) && node.desc.equals(Type.getMethodDescriptor(method))) {
                methodNode = node;
                break;
            }
        }

        if (methodNode == null) {
            throw new IllegalArgumentException("No such method found: " + method);
        }

        LocalVariableTable table = methodNode.localVariables;

        if (table == null) {
            throw new IllegalArgumentException("No local variable table found");
        }

        return table;
    } catch (IOException e) {
        throw new IllegalArgumentException("Could not read class file", e);
    }
}

