import com.google.common.collect.HashMultimap;
import com.google.common.collect.Multimap;
import com.google.inject.TypeLiteral;
import java.util.Arrays;
import java.util.List;

public Multimap<TypeLiteral<?>, Class<?>> resolveBindingDefinitions(Class<?> injecteeClass, List<Class<?>> implClasses) {
    Multimap<TypeLiteral<?>, Class<?>> hierarchyMap = HashMultimap.create();
    for (Class<?> implClass : implClasses) {
        Class<?> superclass = implClass.getSuperclass();
        while (superclass != null && !superclass.equals(injecteeClass)) {
            superclass = superclass.getSuperclass();
        }
        if (superclass != null) {
            hierarchyMap.put(TypeLiteral.get(superclass), implClass);
        } else {
            TypeLiteral<?>[] implementedInterfaces = TypeLiteral.get(implClass).getTypes().interfaces.toArray(new TypeLiteral<?>[0]);
            TypeLiteral<?>[] injecteeInterfaces = TypeLiteral.get(injecteeClass).getTypes().interfaces.toArray(new TypeLiteral<?>[0]);
            if (implementedInterfaces.length > 0 && injecteeInterfaces.length > 0) {
                Arrays.stream(implementedInterfaces)
                        .map(injecteeInterface -> matchIfAssignable(injecteeInterface, injecteeInterfaces))
                        .forEach(foundInterface -> {
                            if (foundInterface != null) {
                                hierarchyMap.put(foundInterface, implClass);
                            }
                        });
            }
        }
    }
    return hierarchyMap;
}

private TypeLiteral<?> matchIfAssignable(TypeLiteral<?> implementedInterface, TypeLiteral<?>[] injecteeInterfaces) {
    for (TypeLiteral<?> injecteeInterface : injecteeInterfaces) {
        if (implementedInterface.getRawType().isAssignableFrom(injecteeInterface.getRawType())) {
            return injecteeInterface;
        }
    }
    return null;
}

