  private StatusFromTrailers() {
  }

  /**
   * Extracts the google.rpc.Status from trailers, and makes sure they match the gRPC
   * {@code status}.
   *
   * @return the embedded google.rpc.Status or {@code null} if it is not present.
   * @since 1.11.0
   */
  public static Status parseFromGrpcStatusHeaders(Metadata trailers) {
    Preconditions.checkNotNull(trailers, "trailers");
    String grpcStatus = trailers.get(io.grpc.Status.CODE_KEY);
    if (Strings.isNullOrEmpty(grpcStatus)) {
      return null;
    }
    if (!io.grpc.Status.Code.OK.value().equals(grpcStatus)) {
      String message = trailers.get(io.grpc.Status.MESSAGE_KEY);
      if (Strings.isNullOrEmpty(message)) {
        message = grpcStatus;
      }
      return fromThrowable(
          io.grpc.Status.fromCodeValue(Integer.parseInt(grpcStatus)).withDescription(message)
              .asRuntimeException());
