      if (name.equals(io.grpc.Status.CODE_KEY) || name.equals(io.grpc.Status.MESSAGE_KEY)) {
        continue;
      }
      for (String value : trailers.getAll(Metadata.Key.of(name, Metadata.ASCII_STRING_MARSHALLER))) {
        if (name.equals(StatusProto.TRAILERS_KEY)) {
          try {
            Any any = Any.parseFrom(value.getBytes(Charsets.ISO_8859_1));
            if (Any.pack(status).equals(any)) {
