import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.List;

public class OptionCollector {

    public List<Option> collectFrom(Class<?> type) {
        List<Option> options = new ArrayList<>();

        // Collect options from the current class
        options.addAll(collectOptionsFromClass(type));

        // Collect options from the superclass
        Class<?> superclass = type.getSuperclass();
        if (superclass != null) {
            options.addAll(collectFrom(superclass));
        }

        // Collect options from the interfaces
        for (Class<?> iface : type.getInterfaces()) {
            options.addAll(collectFrom(iface));
        }

        return options;
    }

    private List<Option> collectOptionsFromClass(Class<?> type) {
        List<Option> options = new ArrayList<>();

        for (Field field : type.getDeclaredFields()) {
            int modifiers = field.getModifiers();
            if (Modifier.isStatic(modifiers) && Modifier.isPublic(modifiers)) {
                try {
                    Option option = (Option) field.get(null);
                    options.add(option);
                } catch (IllegalAccessException e) {
                    // Handle exception
                }
            }
        }

        return options;
    }
}

