    public Tree putObject(String path, Object value) {
        String[] parts = path.split("\\.");
        Tree node = this;
        for (int i = 0; i < parts.length; i++) {
            String part = parts[i];
            if (i == parts.length - 1) {
                // This is the last part of the path, so set the value
                node.value = value;
            } else {
                // This is not the last part of the path, so navigate to the next node
                node = node.children.computeIfAbsent(part, k -> new Tree());
            }
        }
        return this;
    }
}

