    // Read the header line
    String header = reader.readLine();
    String[] splitHeader = header.split("\\s+");

    // Parse the number of rows, columns, and entries
    int numRows = Integer.parseInt(splitHeader[0]);
    int numCols = Integer.parseInt(splitHeader[1]);
    int numEntries = Integer.parseInt(splitHeader[2]);

    // Allocate space for the matrix
    double[][] matrix = new double[numRows][numCols];

    // Loop over the entries and fill the matrix
    for (int i = 0; i < numEntries; i++) {
        String line = reader.readLine();
        String[] splitLine = line.split("\\s+");

        int row = Integer.parseInt(splitLine[0]) - 1;
        int col = Integer.parseInt(splitLine[1]) - 1;
        double value = Double.parseDouble(splitLine[2]);

        matrix[row][col] = value;
    }

    return matrix;
}

