public static double[][] hessenberg(double[][] matrix) {

    int n = matrix.length;
    double[][] H = new double[n][n];
    double[] u = new double[n-1];

    for (int k = 0; k < n-2; k++) {
        double[] x = new double[n-k];
        for (int i = k+1; i < n; i++) {
            x[i-k-1] = matrix[i][k];
        }
        double beta = 0;
        for (int i = 0; i < n-k-1; i++) {
            beta += x[i]*x[i];
        }
        beta = Math.sqrt(beta);
        if (x[0] > 0) {
            beta = -beta;
        }
        for (int i = 0; i < n-k-1; i++) {
            u[i] = x[i];
        }
        u[0] -= beta;

        double[] v = new double[n-k];
        for (int i = 0; i < n-k; i++) {
            v[i] = 0;
            for (int j = 0; j < n-k-1; j++) {
                v[i] += matrix[k+1+j][i+k]*u[j];
            }
        }
        double gamma = 0;
        for (int i = 0; i < n-k-1; i++) {
            gamma += u[i]*v[i];
        }

        for (int i = 0; i < n-k-1; i++) {
            v[i] -= gamma*u[i];
        }

        for (int i = k+1; i < n; i++) {
            for (int j = k; j < n; j++) {
                H[i][j] = matrix[i][j];
            }
        }

        for (int i = k+1; i < n; i++) {
            for (int j = k; j < n; j++) {
                H[i][j] -= (2*v[i-k-1]*u[j-k]+2*u[i-k-1]*v[j-k]);
            }
        }

        for (int i = k+1; i < n; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = H[i][j];
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = k+1; j < n; j++) {
                matrix[i][j] = H[i][j];
            }
        }

        matrix[k+1][k] = beta;
        matrix[k][k+1] = beta;
    }

    return matrix;
}

