public int findPeak(double[] meanColor, double[][] imageData) {
    double[] prevMean;
    double[] currMean = meanColor;
    do {
        prevMean = currMean;
        double[] numerator = new double[prevMean.length];
        double denominator = 0;
        for(double[] data: imageData) {
            double distSq = 0;
            for(int i = 0; i < data.length; i++) {
                distSq += Math.pow(data[i] - prevMean[i], 2);
            }
            double kernel = gaussianKernel(distSq);
            for(int i = 0; i < numerator.length; i++) {
                numerator[i] += kernel * data[i];
            }
            denominator += kernel;
        }
        currMean = new double[numerator.length];
        for(int i = 0; i < currMean.length; i++) {
            currMean[i] = numerator[i] / denominator;
        }
    } while(distance(prevMean, currMean) > 0.00000001);
    double minDist = Double.POSITIVE_INFINITY;
    int peakIndex = -1;
    for(int i = 0; i < imageData.length; i++) {
        double distSq = 0;
        for(int j = 0; j < imageData[i].length; j++) {
            distSq += Math.pow(imageData[i][j] - currMean[j], 2);
        }
        if(distSq < minDist) {
            minDist = distSq;
            peakIndex = i;
        }
    }
    return peakIndex;
}

private double gaussianKernel(double x) {
    return Math.exp(-0.5 * x) / Math.sqrt(2 * Math.PI);
}

private double distance(double[] a, double[] b) {
    double distSq = 0;
    for(int i = 0; i < a.length; i++) {
        distSq += Math.pow(a[i] - b[i], 2);
    }
    return Math.sqrt(distSq);
}

