public Document manipulateWhitespace(Document originalDoc) {
    if(XMLUnit.getIgnoreWhitespace()) {
        NodeList nodeList = originalDoc.getChildNodes();
        for (int i = 0; null != nodeList && i < nodeList.getLength(); i++) {
            Node node = nodeList.item(i);
            if (node.getNodeType() == Node.TEXT_NODE) {
                String trimmed = node.getNodeValue().trim();
                if (trimmed.length() == 0) {
                    originalDoc.removeChild(node);
                } else {
                    node.setNodeValue(trimmed);
                }
            }
        }
    }
    return originalDoc;
}

