public void writeFileToResponse(HttpServletRequest req, HttpServletResponse res, File file, String contentType) throws IOException {
    if (file.exists()) {
        if (!file.isDirectory()) {
            long fileSize = file.length();
            long fromPos = 0, toPos = fileSize - 1;

            String range = req.getHeader("Range");
            if (range != null) {
                if (range.startsWith("bytes=")) {
                    String[] values = range.split("=")[1].split("-");
                    fromPos = Long.parseLong(values[0]);
                    if (values.length > 1) {
                        toPos = Long.parseLong(values[1]);
                    }
                }
            }

            long contentLength = toPos - fromPos + 1;
            res.setHeader("Content-Length", contentLength + "");
            res.setHeader("Content-Range", "bytes " + fromPos + "-" + toPos + "/" + fileSize);

            FileInputStream fileInputStream = new FileInputStream(file);
            fileInputStream.skip(fromPos);
            res.setContentType(contentType);
            res.setStatus(HttpServletResponse.SC_PARTIAL_CONTENT);

            byte[] buffer = new byte[1024];
            int count;
            while ((count = fileInputStream.read(buffer)) != -1) {
                if (contentLength >= count) {
                    res.getOutputStream().write(buffer, 0, count);
                    contentLength -= count;
                } else {
                    res.getOutputStream().write(buffer, 0, (int) contentLength);
                    break;
                }
            }
            fileInputStream.close();
        } else {
            throw new IOException(file.getAbsolutePath() + " is a directory, cannot read as a file");
        }
    } else {
        throw new IOException(file.getAbsolutePath() + " does not exist");
    }
}

