public static void shiftZeroFrequencyComponent(double[] x, int direction) {
    int n = x.length;
    int mid = n / 2;
    if (n % 2 == 1 && direction == 1) {
        mid++;
    }
    for (int i = 0; i < mid; i++) {
        int j = (i + mid) % n;
        double temp = x[i];
        x[i] = x[j];
        x[j] = temp;
    }
}

