private boolean getWeightRanges(long lowerLimit, long upperLimit) {
	// Calculate the number of bytes needed for the upper limit
    int upperBytes = (Long.SIZE - Long.numberOfLeadingZeros(upperLimit)) / 8;
    // Calculate the number of bytes needed for the lower limit
    int lowerBytes = (Long.SIZE - Long.numberOfLeadingZeros(lowerLimit)) / 8;
    // Determine the maximum number of ranges
    int maxRanges = 2 * Math.min(upperBytes, lowerBytes) - 1;
    // Initialize an array to store the ranges
    long[] ranges = new long[maxRanges];
    // Calculate the ranges
    for (int i = 0; i < maxRanges; i++) {
        // Calculate the start of the range
        long start = lowerLimit + (i * (upperLimit - lowerLimit) / maxRanges);
        // Calculate the end of the range
        long end = lowerLimit + ((i + 1) * (upperLimit - lowerLimit) / maxRanges);
        // Store the range in the array
        ranges[i] = end - start;
    }
    // Print the ranges
    for (long range : ranges) {
        System.out.println(range);
    }
    // Return true if the ranges were calculated successfully
    return true;
}

