private boolean hasNestedObject(Field field) {
	// Check if the field is a struct
    if (field.getType().isAnnotationPresent(Struct.class)) {
        return true;
    }
    // Check if the field is a list/set of structs
    if (Collection.class.isAssignableFrom(field.getType())) {
        Type genericType = field.getGenericType();
        if (genericType instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericType;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            for (Type type : actualTypeArguments) {
                if (type instanceof Class && ((Class<?>) type).isAnnotationPresent(Struct.class)) {
                    return true;
                }
            }
        }
    }
    // Check if the field is a Map
    if (Map.class.isAssignableFrom(field.getType())) {
        Type genericType = field.getGenericType();
        if (genericType instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericType;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            for (Type type : actualTypeArguments) {
                if (type instanceof Class && ((Class<?>) type).isAnnotationPresent(Struct.class)) {
                    return true;
                }
            }
        }
    }
    return false;
}

