public String invokeExternalProgram(long timeout, String directory, String command, String... arguments) throws IOException, InterruptedException {
    ProcessBuilder processBuilder = new ProcessBuilder(command, arguments);

    if (directory != null) {
        processBuilder.directory(new File(directory));
    }

    Process process = processBuilder.start();
    boolean completed = process.waitFor(timeout, TimeUnit.MILLISECONDS);

    if (!completed) {
        process.destroy();
        throw new InterruptedException("External program did not complete within timeout.");
    }

    BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
    StringBuilder responseBuilder = new StringBuilder();
    String line;

    while((line = reader.readLine()) != null) {
        responseBuilder.append(line);
        responseBuilder.append(System.getProperty("line.separator"));
    }

    return responseBuilder.toString();
}

