public static void powerIterations(double[][] imat, double[] evs, double[] lambda) {
    int n = imat.length;
    double eps = 10e-8;

    // Initialize evs with random values
    for (int i = 0; i < n; i++) {
        evs[i] = Math.random();
    }

    // Iteratively compute eigenvectors and eigenvalues
    double normEvs = 0;
    double diffNorm = eps + 1;
    while (diffNorm > eps) {
        double[] newEvs = new double[n];
        double newNormEvs = 0;

        // Compute new eigenvector
        for (int i = 0; i < n; i++) {
            double sum = 0;
            for (int j = 0; j < n; j++) {
                sum += imat[i][j] * evs[j];
            }
            newEvs[i] = sum;
            newNormEvs += newEvs[i]*newEvs[i];
        }

        // Compute new eigenvalue
        double newLambda = 0;
        for (int i = 0; i < n; i++) {
            newLambda += evs[i] * newEvs[i];
        }

        // Normalize new eigenvector
        newNormEvs = Math.sqrt(newNormEvs);
        for (int i = 0; i < n; i++) {
            newEvs[i] /= newNormEvs;
        }

        // Compute norm and difference
        diffNorm = Math.abs(newNormEvs - normEvs);
        normEvs = newNormEvs;

        // Update eigenvector and eigenvalue
        evs = newEvs;
        lambda[0] = newLambda;
    }
}

