public RedeemData getRedeemDataFromOutput(TransactionOutput output, NetworkParameters params) throws ScriptException {
    Script script = output.getScriptPubKey();
    Script.ScriptType type = script.getScriptType();
    switch (type) {
        case P2PKH:
            // parse P2PKH script
            Address address = output.getAddressFromP2PKHScript(params);
            ECKey pubkey = output.getPubKey();
            RedeemData data = RedeemData.of(pubkey, address);
            return data;
        case P2WPKH:
            // parse P2WPKH script
            byte[] pubkeyHash = ScriptChunk.copyOfRange(script.getChunks().get(1).data(), 2, 22);
            Address segwitAddress = SegwitAddress.builder()
                    .networkParams(params)
                    .addPubkeyHash(pubkeyHash)
                    .bech32()
                    .build();
            ECKey pubkeyW = output.getPubKey();
            RedeemData dataW = RedeemData.of(pubkeyW, segwitAddress);
            return dataW;
        case P2PK:
            // parse P2PK script
            ECKey pubkeyP = output.getPubKey();
            RedeemData dataP = RedeemData.of(pubkeyP, null);
            return dataP;
        case P2SH:
            // parse P2SH script
            byte[] redeemScriptBytes = ScriptChunk.copyOfRange(script.getChunks().get(script.getChunks().size()-2).data(), 0, -1);
            Script redeemScript = new Script(redeemScriptBytes);
            Script.ScriptType redeemScriptType = redeemScript.getScriptType();
            switch (redeemScriptType) {
                case P2PKH:
                    // parse P2SH(P2PKH) script
                    Address p2pkhAddress = redeemScript.getToAddress(params);
                    RedeemData p2pkhData = RedeemData.of(redeemScript.getPubKey(), p2pkhAddress);
                    return p2pkhData;
                case P2WPKH:
                    // parse P2SH(P2WPKH) script
                    byte[] p2wpkhPubkeyHash = ScriptChunk.copyOfRange(redeemScript.getChunks().get(1).data(), 2, 22);
                    Address p2wpkhSegwitAddress = SegwitAddress.builder()
