                            .addPubkeyHash(p2wpkhPubkeyHash)
                            .bech32()
                            .build();
                    RedeemData p2wpkhData = RedeemData.of(redeemScript.getPubKey(), p2wpkhSegwitAddress);
                    return p2wpkhData;
                default:
                    throw new ScriptException("Unknown P2SH script type");
            }
        default:
            throw new ScriptException("Unknown script type");
    }
