import java.io.OutputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class ObservableOutputStream extends OutputStream {
    private List<OutputObserver> observers = new ArrayList<>();

    public void addObserver(OutputObserver observer) {
        observers.add(observer);
    }

    @Override
    public void write(int b) throws IOException {
        // Write the byte to the output stream
        super.write(b);

        // Notify the observers
        for (OutputObserver observer : observers) {
            observer.onWrite(b);
        }
    }

    @Override
    public void close() throws IOException {
        super.close();

        // Remove the observers when the stream is closed
        observers.clear();
    }
}

interface OutputObserver {
