            boolean found = false;
            for (int i = 0; i < mainTable.length; i++) {
                if (mainTable[i] == c) {
                    found = true;
                    chCnt++;
                    if (chCnt > charCount) {
                        chCnt = 1;
                        res.add(sb.toString());
                        sb = new StringBuilder();
                    }
                    sb.append(c);
                    break;
                }
            }
            if (!found && extentionTable != null) {
                for (int i = 0; i < extentionTable.length; i++) {
                    if (extentionTable[i] == c) {
                        found = true;
                        chCnt += 2;
                        if (chCnt > charCount) {
                            chCnt = 2;
                            res.add(sb.toString());
                            sb = new StringBuilder();
