import java.util.zip.GZIPInputStream;

public RandomAccessFile uncompress(RandomAccessFile inputRaf, String ufilename) throws IOException {
    // Create a GZIPInputStream to read the compressed data
    GZIPInputStream gzis = new GZIPInputStream(new FileInputStream(inputRaf.getFD()));

    // Create a FileOutputStream to write the uncompressed data
    FileOutputStream out = new FileOutputStream(new File(ufilename));

    // Buffer to hold the data
    byte[] buffer = new byte[1024];
    int len;

    // Read the data from the GZIPInputStream and write it to the FileOutputStream
    while ((len = gzis.read(buffer)) > 0) {
        out.write(buffer, 0, len);
    }

    // Close the streams
    gzis.close();
    out.close();

    // Return a new RandomAccessFile for the uncompressed file
    return new RandomAccessFile(new File(ufilename), "r");
}

