public void gatherPkFields(ClassDef classDef) throws ConstraintException {
    // Get the pk fields from the given class
    List<Field> pkFields = classDef.getPkFields();

    // Check for conflicts in pk fields
    for (Field pkField : pkFields) {
        for (ClassDef subClass : classDef.getSubClasses()) {
            if (subClass.hasField(pkField.getName())) {
                throw new ConstraintException("Conflict in pk field: " + pkField.getName());
            }
        }
    }

    // Copy pk fields into the class
    for (Field pkField : pkFields) {
        classDef.addField(pkField);
    }
}

