public double[][] calculatePseudoInverse(double[][] matrix) {

    double[][] transpose = new double[matrix[0].length][matrix.length];

    double[][] product = new double[matrix.length][matrix.length];
    double[][] inverse = new double[matrix.length][matrix.length];

    double[][] temp = new double[matrix.length][matrix[0].length];
    double[][] temp1 = new double[matrix.length][matrix[0].length];

    for (int i = 0; i < matrix.length; i++) {
        for (int j = 0; j < matrix[0].length; j++) {
            transpose[j][i] = matrix[i][j];
        }
    }

    // A * A(transpose)
    for (int i = 0; i < matrix.length; i++) {
        for (int j = 0; j < matrix.length; j++) {
            double sum = 0;
            for (int k = 0; k < matrix[0].length; k++) {
                sum += matrix[i][k] * transpose[k][j];
            }
            product[i][j] = sum;
        }
    }

    // calculating inverse
    inverse = new Matrix(product).inverse().getArray();

    // Pseudo Inverse P = A(transpose) * (A * A(transpose))^(-1)
    for (int i = 0; i < matrix[0].length; i++) {
        for (int j = 0; j < matrix.length; j++) {
            double sum = 0;
            for (int k = 0; k < matrix.length; k++) {
                sum += transpose[i][k] * inverse[k][j];
            }
            temp[i][j] = sum;
        }
    }

    // calculating pseudo-inverse P' = (A * A(transpose))^(-1) * A(transpose)
    for (int i = 0; i < matrix.length; i++) {
        for (int j = 0; j < matrix[0].length; j++) {
            double sum = 0;
            for (int k = 0; k < matrix.length; k++) {
                sum += product[i][k] * matrix[k][j];
            }
            temp1[i][j] = sum;
        }
    }

    int m = matrix.length;
    int n = matrix[0].length;

    double[][] pseudoInverse = new double[n][m];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            pseudoInverse[i][j] = temp[i][j];
        }
    }

    return pseudoInverse;
}

