public Music transformNotes(Music music) {
        String musicContents = music.getContents();
        StringBuilder transformedMusicContents = new StringBuilder();

        for (int i = 0; i < musicContents.length(); i++) {
            char currentChar = musicContents.charAt(i);
            if (currentChar == '+') {
                switch (musicContents.charAt(i + 1)) {
                    case 't':
                        int tillNoteIndex = musicContents.indexOf("+", i + 1);
                        char tillNote = musicContents.charAt(tillNoteIndex + 1);
                        transformedMusicContents.append(tillTranformation(tillNote));
                        i = tillNoteIndex;
                        break;
                    case 'm':
                        int mordantsIndex = musicContents.indexOf("+", i + 1);
                        char mordantsNote = musicContents.charAt(mordantsIndex + 1);
                        transformedMusicContents.append(mordantsTranformation(mordantsNote));
                        i = mordantsIndex;
                        break;
                    case 'g':
                        transformedMusicContents.append("G");
                        break;
                    case 'a':
                        transformedMusicContents.append("AGFEDCBA");
                        break;
                    case 's':
                        transformedMusicContents.append("z");
                        break;
                    default:
                        transformedMusicContents.append(currentChar);
                        break;
                }
            } else {
                transformedMusicContents.append(currentChar);
            }
        }

        music.setContents(transformedMusicContents.toString());

        return music;
    }

    private String tillTranformation(char note) {
        String transformedTill = "";
        transformedTill += Character.toUpperCase(note) + "C" + Character.toUpperCase(note) + "D";
        return transformedTill;
    }

    private String mordantsTranformation(char note) {
        String transformedMordants = "";
        transformedMordants += Character.toUpperCase(note) + "DC";
        return transformedMordants;
    }

