import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public static String createEncryptor(String password) throws Exception {
    // Converts the password into a 16-byte key
    SecretKeySpec secretKeySpec = new SecretKeySpec(password.getBytes(), "AES");

    // Initializes the cipher object with the secret key
    Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5PADDING");
    cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

    // Returns the encryptor's hex-encoded key
    return javax.xml.bind.DatatypeConverter.printHexBinary(cipher.doFinal());
}

