protected boolean prepare(final Context2D context, final Attributes attr, final double alpha) {
	// Check if the video is looping
    boolean isLooping = attr.getBoolean("loop", false);

    // Get the current frame index
    int currentFrameIndex = getCurrentFrameIndex();

    // Get the total number of frames in the video
    int totalFrames = getTotalFrames();

    // If looping is enabled and we've reached the end of the video, reset the frame index
    if (isLooping && currentFrameIndex >= totalFrames) {
        currentFrameIndex = 0;
    }

    // Draw the current frame
    drawFrame(context, currentFrameIndex);

    // Return true if the video is still playing or looping
    return isLooping || currentFrameIndex < totalFrames;
