public static void extractTarFile(InputStream _in, File directory, Compression compression) throws IOException {
    try (InputStream in = compression.getDecompressor().decompress(_in)) {
        try (TarInputStream tarIn = new TarInputStream(in)) {
            TarEntry entry;
            while ((entry = tarIn.getNextEntry()) != null) {
                File file = new File(directory, entry.getName());
                if (entry.isDirectory()) {
                    file.mkdirs();
                } else {
                    file.getParentFile().mkdirs();
                    extractFile(tarIn, file);
                }
            }
        }
    }
}

private static void extractFile(InputStream in, File file) throws IOException {
    byte[] buffer = new byte[8192];
    try (OutputStream out = new FileOutputStream(file)) {
        int len;
        while ((len = in.read(buffer)) != -1) {
            out.write(buffer, 0, len);
        }
    }
}

