            futures.add(execSvc.submit(callable));
        }
        for (Future<T> future : futures) {
            try {
                T result = future.get(1, TimeUnit.MINUTES);
                results.add(result);
            } catch (InterruptedException | ExecutionException | TimeoutException ignored) { }
        }
        return results;
    }
}

