import java.io.File; 
import java.io.IOException; 
import org.apache.thrift.protocol.TBinaryProtocol; 
import org.apache.thrift.protocol.TProtocol; 
import org.apache.thrift.transport.TIOStreamTransport; 
import org.apache.thrift.transport.TTransportException; 
import org.apache.thrift.protocol.TSimpleJSONProtocol; 
import org.apache.thrift.TException; 
import org.apache.thrift.transport.TFileTransport;

public class ProgramTypeRegistry {

    private static final String FILE_FORMAT = "json";
    private static final String TYPE_REGISTRY_FILENAME = "type_registry";

    public static ThriftProgramTypeRegistry getProgramTypeRegistry(String path) throws IOException, TException {

        File file = new File(path);
        if (!file.exists()) {
            throw new IOException("File not found: " + file.getAbsolutePath());
        }

        String filePath = file.getAbsolutePath();
        String registryFilename = getTypeRegistryFilename(filePath);
        File registryFile = new File(registryFilename);

        if (registryFile.exists()) {
            return readProgramTypeRegistry(registryFile);
        } else {
            ThriftProgramTypeRegistry registry = new ThriftProgramTypeRegistry();
            writeProgramTypeRegistry(registry, registryFile);
            return registry;
        }
    }

    private static String getTypeRegistryFilename(String filePath) {
        String dirPath = new File(filePath).getParent();
        return String.format("%s/%s.%s", dirPath, TYPE_REGISTRY_FILENAME, FILE_FORMAT);
    }

    private static ThriftProgramTypeRegistry readProgramTypeRegistry(File file) throws TException {
        final TIOStreamTransport transport = new TIOStreamTransport(new TFileTransport(file.getAbsolutePath()));
        final TProtocol protocol = new TBinaryProtocol(transport);
        final ThriftProgramTypeRegistry programTypeRegistry = new ThriftProgramTypeRegistry();
        protocol.readStruct(programTypeRegistry);
        return programTypeRegistry;
    }

    private static void writeProgramTypeRegistry(ThriftProgramTypeRegistry programTypeRegistry, File file) throws TException {
        final TIOStreamTransport transport = new TIOStreamTransport(new TFileTransport(file.getAbsolutePath()));
        final TProtocol protocol = new TSimpleJSONProtocol(transport);
        protocol.writeStruct(programTypeRegistry);
        transport.flush();
    }
}

