public Point3d[] calculateNewPoints(Point3d aPoint, Point3d bPoint, Point3d cPoint, double length, double angle) {
    Point3d[] newPoints = new Point3d[2];
    Vector3d bAVector = new Vector3d(bPoint);
    bAVector.sub(aPoint);

    Vector3d bCVector = new Vector3d(cPoint);
    bCVector.sub(bPoint);

    Vector3d xVector = new Vector3d(bCVector);
    xVector.normalize();
    xVector.scale(length);

    Matrix3d rotationMatrix = new Matrix3d();
    rotationMatrix.setIdentity();
    rotationMatrix.setColumn(0, bAVector);
    rotationMatrix.setColumn(1, xVector);
    rotationMatrix.setColumn(2, new Vector3d());
    Transform3D transform = new Transform3D(rotationMatrix);

    double angleRadiant = Math.toRadians(angle);
    Quat4d rotationQuat = new Quat4d();
    rotationQuat.set(new AxisAngle4d(bAVector, angleRadiant));
    Transform3D rotationTransform = new Transform3D(rotationQuat);

    transform.mul(rotationTransform);

    Vector3d newXVector = new Vector3d(xVector);
    Vector3d newYVector = new Vector3d(bAVector);
    newYVector.scale(-1);

    Matrix3d inverseMatrix = new Matrix3d();
    transform.get(inverseMatrix);
    inverseMatrix.invert();

    inverseMatrix.transform(newXVector);
    inverseMatrix.transform(newYVector);

    Point3d newPoint1 = new Point3d(aPoint);
    newPoint1.add(newXVector);
    newPoint1.add(newYVector);

    Point3d newPoint2 = new Point3d(aPoint);
    newPoint2.add(newXVector);
    newPoint2.sub(newYVector);

    newPoints[0] = newPoint1;
    newPoints[1] = newPoint2;

    return newPoints;
}

