    }
    byte[] pageData = new byte[PAGE_SIZE];
    try {
        file.seek(pageNumber * PAGE_SIZE);
        file.readFully(pageData);
    } catch (IOException e) {
        throw new DBException("Error reading page " + pageNumber, e);
    }
    return pageData;
}

public void writePage(int pageNumber, byte[] pageData) throws DBException {
    if (!isOpen) {
        throw new DBException("File is not open");
    }
    if (pageData.length != PAGE_SIZE) {
        throw new DBException("Page data must be exactly " + PAGE_SIZE + " bytes");
    }
    try {
        file.seek(pageNumber * PAGE_SIZE);
        file.write(pageData);
    } catch (IOException e) {
        throw new DBException("Error writing page " + pageNumber, e);
    }
}

