        String tok = stok.nextToken();
        if (tok.length() == 2 && tok.charAt(1) == 'S') {
            tok = tok.charAt(0) + tok.substring(2);
        }
        buf.append(tok);
        if (stok.hasMoreTokens()) {
            buf.append(" ");
        }
    }
}

