private static boolean looksLikeTask(String taskname) {
    return !looksLikeHelp(taskname) && !looksLikeVersion(taskname) && !looksLikeExit(taskname);
}

private static void handleTask(String taskname) {
    if (looksLikeHelp(taskname)) {
        System.out.println("Help information goes here.");
    } else if (looksLikeVersion(taskname)) {
        System.out.println("Version information goes here.");
    } else if (looksLikeExit(taskname)) {
        System.out.println("Exiting the application.");
        System.exit(0);
    } else if (looksLikeTask(taskname)) {
        System.out.println("Handling task: " + taskname);
    } else {
        System.out.println("Unknown command: " + taskname);
    }
}

