public static List<String> getCipherListIfAlpnEnabled(SSLSocket socket){
    try {
        SSLSession session = socket.getSession();
        List<String> protocols = session.getProtocolPreferences();
        if (protocols.contains("TLSv1.3")) {
            SSLSessionContext ctx = socket.getSession().getSessionContext();
            String[] names = ctx.getAlpnProtocols();
            if (names != null && names.length > 0) {
                List<String> alpnList = new ArrayList<String>();
                for (String name : names) {
                    alpnList.add(name);
                }
                return alpnList;
            }
        }
    } catch (SSLPeerUnverifiedException | IOException e) {
        e.printStackTrace();
    }
    return null;
}

