import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class EventBus {
    private Map<Enum<?>, List<EventHandler>> handlers = new HashMap<>();
    private ExecutorService executor = Executors.newCachedThreadPool();

    public EventBus emitAsync(Enum<?> event, Object... args) {
        List<EventHandler> eventHandlers = handlers.get(event);
        if (eventHandlers != null) {
            for (EventHandler handler : eventHandlers) {
                executor.submit(() -> handler.handleEvent(args));
            }
        }
        return this;
    }

    public EventBus on(Enum<?> event, EventHandler handler) {
        handlers.computeIfAbsent(event, k -> new ArrayList<>()).add(handler);
        return this;
    }

    public interface EventHandler {
        void handleEvent(Object... args);
    }
}

