    boolean inQuotes = false;
    boolean escape = false;
    while (true) {
        int c = read(); // Assume read() reads the next character as an int
        if (c == -1) {
            throw new IllegalStateException("Unexpected end of input");
        }
        if (escape) {
            escape = false;
            switch (c) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '"':
                    sb.append('"');
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence: \\" + (char) c);
            }
        } else if (c == '\\') {
            escape = true;
        } else if (c == '"') {
            if (inQuotes) {
                return sb.toString();
            } else {
                inQuotes = true;
            }
        } else {
            sb.append((char) c);
        }
    }
}

