public class Exporter {
    public static Map<String, Object> export(final Object obj, final String prefix) {
        final Class<?> clazz = obj.getClass();
        final Map<String, Object> result = new HashMap<String, Object>();

        for (final Field field : clazz.getFields()) {
            if (field.isAnnotationPresent(Export.class)) {
                try {
                    result.put(prefix + field.getName(), field.get(null));
                } catch (final IllegalAccessException e) {
                    System.err.println("Error exporting field " + field.getName() + ": " + e);
                }
            }
        }

        for (final Method method : clazz.getMethods()) {
            if (method.isAnnotationPresent(Export.class)) {
                try {
                    final Object value = method.invoke(obj);
                    result.put(prefix + method.getName(), value);
                } catch (final IllegalAccessException e) {
                    System.err.println("Error exporting method " + method.getName() + ": " + e);
                } catch (final InvocationTargetException e) {
                    System.err.println("Error exporting method " + method.getName() + ": " + e);
                }
            }
        }

        for (final Class<?> ifc : clazz.getInterfaces()) {
            for (final Method method : ifc.getMethods()) {
                if (method.isAnnotationPresent(Export.class)) {
                    try {
                        final Object value = method.invoke(obj);
                        result.put(prefix + method.getName(), value);
                    } catch (final IllegalAccessException e) {
                        System.err.println("Error exporting method " + method.getName() + ": " + e);
                    } catch (final InvocationTargetException e) {
                        System.err.println("Error exporting method " + method.getName() + ": " + e);
                    }
                }
            }
        }

        return result;
    }
}

