private CompletableFuture<Void> bootstrapServer() {
	// Create a server socket channel
    ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
    serverSocketChannel.configureBlocking(false);

    // Bind the server socket channel to all interfaces on port 8080
    serverSocketChannel.bind(new InetSocketAddress(8080));

    // Register the server socket channel with the selector
    Selector selector = Selector.open();
    serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

    // Create a completable future to be completed once the server has been bound
    CompletableFuture<Void> future = new CompletableFuture<>();

    // Start a new thread to handle the selector
    new Thread(() -> {
        try {
            while (true) {
                selector.select();
                Set<SelectionKey> selectedKeys = selector.selectedKeys();
                Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

                while (keyIterator.hasNext()) {
                    SelectionKey key = keyIterator.next();

                    if (key.isAcceptable()) {
                        // Accept the new connection
                        SocketChannel clientSocketChannel = serverSocketChannel.accept();
                        clientSocketChannel.configureBlocking(false);

                        // Register the new connection with the selector
                        clientSocketChannel.register(selector, SelectionKey.OP_READ);
                    } else if (key.isReadable()) {
                        // Read data from the client
                        SocketChannel clientSocketChannel = (SocketChannel) key.channel();
                        ByteBuffer buffer = ByteBuffer.allocate(256);
                        int bytesRead = clientSocketChannel.read(buffer);

                        if (bytesRead == -1) {
                            // Close the connection if the client has closed it
                            clientSocketChannel.close();
                        } else {
                            // Process the data
                            buffer.flip();
