public MatrixStatistics extractMatrixStatistics(MatrixFile inputMatrixFile, Format format) {
    double[][] matrix = inputMatrixFile.getMatrix();
    int rows = matrix.length;
    int cols = matrix[0].length;
    double[] rowSum = new double[rows];
    double[] colSum = new double[cols];
    double matrixSum = 0.0;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            double element = matrix[i][j];
            rowSum[i] += element;
            colSum[j] += element;
            matrixSum += element;
        }
    }
    return new MatrixStatistics(rowSum, colSum, matrixSum);
}

