    String result = "";
    try {
        //Create connection to remote node
        Connection conn = node.getConnection();

        //Construct the command to be executed
        String command = "sh " + filepath + " " + String.join(" ", args);

        //Execute the command on remote node
        Session session = conn.openSession();
        session.execCommand(command);

        //Read the output of the command
        InputStream stdout = new StreamGobbler(session.getStdout());
        BufferedReader br = new BufferedReader(new InputStreamReader(stdout));
        String line = null;
        while ((line = br.readLine()) != null) {
            result += line + "\n";
        }

        //Check for errors
        InputStream stderr = new StreamGobbler(session.getStderr());
        BufferedReader err = new BufferedReader(new InputStreamReader(stderr));
        while ((line = err.readLine()) != null) {
            throw new NodeStepException(line);
        }

        session.close();
        conn.close();

    } catch (IOException e) {
        throw new NodeStepException(e);
    }

    return result;
}

