    List<String> methodsList = new ArrayList<>();
    for (InterfaceInfo interfaceInfo : interfaceInfoList) {
        Class<?> interfaceClass;
        try {
            interfaceClass = Class.forName(interfaceInfo.getName());
        } catch (ClassNotFoundException e) {
            e.printStackTrace();
            continue;
        }
        Method[] declaredMethods = interfaceClass.getDeclaredMethods();
        for (Method method : declaredMethods) {
            String methodName = method.getName();
            methodsList.add(methodName);
        }
        Class<?>[] interfaces = interfaceClass.getInterfaces();
        for (Class<?> extendedInterface : interfaces) {
            InterfaceInfo extendedInterfaceInfo = findInterfaceInfo(extendedInterface.getName(), interfaceInfoList);
            if(extendedInterfaceInfo != null)
