public int getMaxLines() {
    int height = getHeight() - getPaddingTop() - getPaddingBottom();
    Layout layout = getLayout();

    if (layout == null || height <= 0) {
        return -1;
    }

    int lines = layout.getLineCount();
    int ellipsisCount = 0;
    int lastLineVisibleChar = layout.getLineVisibleEnd(lines - 1);
    CharSequence text = getText();

    if (text instanceof Spanned) {
        ellipsisCount = ((Spanned) text).getSpanEnd(TextUtils.TruncateAt.END);
    }

    if (lines > 0 && ellipsisCount > 0 && lastLineVisibleChar >= ellipsisCount) {
        lines--;
    }

    return lines;
}

