import java.lang.reflect.Method;

public class CategoryMethods {
    public static void extendObjectWithCategoryMethods(Class<?> self, Class<?>... categoryClasses) {
        // Get all the methods for given class and all super classes
        Method[] methods = self.getMethods();
        while ((self = self.getSuperclass()) != null) {
            methods = concat(methods, self.getMethods());
        }

        // Add all the methods to the object
        for (Method method : methods) {
            for (Class<?> categoryClass : categoryClasses) {
                try {
                    Method categoryMethod = categoryClass.getMethod(method.getName(), method.getParameterTypes());
                    if (!categoryMethod.getDeclaringClass().equals(Object.class)) {
                        method.setAccessible(true);
                        categoryMethod.setAccessible(true);
                        method.invoke(null, categoryMethod.invoke(null));
                    }
                } catch (Exception e) {
                    // ignore exceptions
                }
            }
        }
    }

    private static Method[] concat(Method[] a, Method[] b) {
        Method[] result = new Method[a.length + b.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }
}

