public GeometryCollection forceDimension(GeometryCollection gc, int dimension) {
    GeometryFactory gf = gc.getFactory();
    int oldDim = gc.getDimension();
    CoordinateList coordinates = new CoordinateList();
    for (int i = 0; i < gc.getNumGeometries(); i++) {
        Geometry geom = gc.getGeometryN(i);
        Coordinate[] oldCoords = geom.getCoordinates();
        for (int j = 0; j < oldCoords.length; j++) {
            Coordinate newCoord = new Coordinate(oldCoords[j]);
