public class ParameterExtractor {
  public static ImmutableSet<String> getParameterNames(AbstractCompiler compiler, Node externs, Node ast) {
    final Set<String> parameterNames = new LinkedHashSet<>();
    NodeTraversal.traverse(compiler, ast, new NodeTraversal.Callback() {
      @Override
      public boolean shouldTraverse(NodeTraversal nodeTraversal, Node node, Node parent) {
        switch (node.getToken()) {
