            while (child != null) {
              if (child.getToken() == Token.NAME) {
                parameterNames.add(child.getString());
              }
              child = child.getNext();
            }
            break;
        }
        return true;
      }
      @Override
      public void visit(NodeTraversal nodeTraversal, Node node, Node parent) {}
    });
    // Return an immutable set of the parameter names.
    return ImmutableSet.copyOf(parameterNames);
  }
