public Duration convertIntegerToDuration(int totalTime, String format) {
    long hours = TimeUnit.MINUTES.toHours(totalTime);
    long minutes = totalTime - TimeUnit.HOURS.toMinutes(hours);
    long seconds = TimeUnit.MINUTES.toSeconds(totalTime - TimeUnit.HOURS.toMinutes(hours) - minutes);

    Duration duration = Duration.ZERO;
    switch (format) {
        case "H":
            duration = Duration.ofHours(hours);
            break;
        case "M":
            duration = Duration.ofMinutes(totalTime);
            break;
        case "S":
            duration = Duration.ofSeconds(seconds);
            break;
    }
    return duration;
}

