    double r21 = R[1][0], r22 = R[1][1], r23 = R[1][2];
    double r31 = R[2][0], r32 = R[2][1], r33 = R[2][2];

    double trace = r11+r22+r33;
    double qw, qx, qy, qz;

    if (trace > 0.0) {
        double s = Math.sqrt(trace + 1.0);
        qw = 0.5 * s;
        s = 0.5 / s;
        qx = (r23 - r32) * s;
        qy = (r31 - r13) * s;
        qz = (r12 - r21) * s;
    } else {
        int[] nxt = {1, 2, 0};
        double[] q = new double[4];
        int i = 0, j, k;

        if (r22 > r11) {
            i = 1;
        }
        if (r33 > R[i][i]) {
            i = 2;
        }
        j = nxt[i];
        k = nxt[j];
        double s = Math.sqrt((R[i][i] - (R[j][j] + R[k][k])) + 1.0);

        q[i] = 0.5 * s;
