        }

        q[j] = (R[j][i] + R[i][j]) * s;
        q[k] = (R[k][i] + R[i][k]) * s;
        qw = (R[k][j] - R[j][k]) * s;
        qx = q[0];
        qy = q[1];
        qz = q[2];
    }

    double magnitude = Math.sqrt(qw * qw + qx * qx + qy * qy + qz * qz);
    if (magnitude > 0.0) {
