public static void normalizeByPearson(Matrix m, boolean saveNegatives) {
    int rows = m.getRowDimension();
    int columns = m.getColumnDimension();
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < columns; j++) {
            double value = m.get(i, j);
            if (value != 0) {
                double sigmaX = 0;
                double sigmaY = 0;
                double sigmaXY = 0;
                double sigmaX2 = 0;
                double sigmaY2 = 0;
                for (int k = 0; k < rows; k++) {
                    double x = m.get(k, j);
                    double y = m.get(k, i);
                    sigmaX += x;
                    sigmaY += y;
                    sigmaXY += x * y;
                    sigmaX2 += x * x;
                    sigmaY2 += y * y;
                }
                double numerator = (rows * sigmaXY) - (sigmaX * sigmaY);
                double denominator = Math.sqrt((rows * sigmaX2 - (sigmaX * sigmaX)) * (rows * sigmaY2 - (sigmaY * sigmaY)));
                double correlation = (denominator != 0) ? numerator / denominator : 0;
                if (correlation < 0 && !saveNegatives) {
                    correlation = 0;
                }
                m.set(i, j, correlation);
            }
        }
    }
}

