public class Timer {
    private final String name;
    private final Map<String, Monitor> monitors;

    public Timer(String name, Context context) {
        this.name = name;
        this.monitors = new ConcurrentHashMap<>();
        update(context);
    }

    public void update(Context context) {
        String tagsKey = getTagsKey(context);
        monitors.computeIfAbsent(tagsKey, key -> new Monitor()).update();
    }

    private String getTagsKey(Context context) {
        return context.getTags().stream()
                .map(tag -> tag.getKey() + ":" + tag.getValue())
                .sorted()
                .collect(Collectors.joining(","));
    }

    private static class Monitor {
        private final AtomicLong count = new AtomicLong();
        private final AtomicLong totalTime = new AtomicLong();

        public void update() {
            count.incrementAndGet();
            totalTime.addAndGet(System.nanoTime());
        }

        public double getAverageTime() {
            long currentCount = count.get();
            if (currentCount == 0) {
                return Double.NaN;
            }
            return (double) totalTime.get() / currentCount;
        }

        public long getCount() {
            return count.get();
        }
    }
}

