public static DownloadResponse exportFile(Drive drive, File file, String format) throws IOException {
	// Check if the file can be exported to the requested format
    if (!file.getExportLinks().containsKey(format)) {
        throw new IllegalArgumentException("File cannot be exported to the specified format: " + format);
    }

    // Get the export link for the requested format
    String exportLink = file.getExportLinks().get(format);

    // Make a request to the export link to get the file data
    HttpResponse<InputStream> response = drive.getRequestFactory().buildGetRequest(new GenericUrl(exportLink)).execute();

    // Check if the request was successful
    if (response.getStatusCode() != 200) {
        throw new IOException("Failed to export file: " + response.getStatusMessage());
    }

    // Return the exported data
    return new DownloadResponse(response.getContent());
}

