import difflib
import java.util.ArrayList;
import java.util.List;

public List<String> buildUnifiedDiff(String previous, String next) {
    List<String> result = new ArrayList<>();    
    List<String> previousLines = difflib.Splitter.on('\n').splitToList(previous+'\n');
    List<String> nextLines = difflib.Splitter.on('\n').splitToList(next+'\n');    
    Patch<String> patch = DiffUtils.diff(previousLines, nextLines);
    List<Delta<String>> deltas = patch.getDeltas();    
    for (Delta<String> delta : deltas) {
        ExtendedDiffRowGenerator rowGenerator = new ExtendedDiffRowGenerator.Builder().build();
        List<DiffRow> diffRows = rowGenerator.generateDiffRows(delta.getOriginal().getLines(), delta.getRevised().getLines());
        StringBuilder builder = new StringBuilder();
        builder.append("@@ -").append(delta.getOriginal().getPosition()).append(",").append(delta.getOriginal().getLines().size()).append(" +").append(delta.getRevised().getPosition()).append(",").append(delta.getRevised().getLines().size()).append(" @@\n");
        for (DiffRow diffRow : diffRows) {
            if (diffRow.getTag() != DiffRow.Tag.EQUAL) {
                builder.append(diffRow.getTag().getTag()).append(diffRow.getText()).append('\n');
            }
        }
        result.add(builder.toString());
    }    
    return result;
}

