public class DestinationSubclassHeader {

  /**
   * Creates destination subclass header from current target class. 
   * Destination name is created from targets by adding a suffix and, optionally, a number. 
   * Destination extends the target.
   *
   * @param target         The target class to extend.
   * @param suffix         The suffix to add to the target class name.
   * @param addNumber      Indicates whether to add a unique number to the destination name or not.
   * @return               The destination subclass header.
   */
  public String createHeader(Class<?> target, String suffix, boolean addNumber) {
    String destinationName = target.getSimpleName() + suffix;

    if (addNumber) {
      int i = 1;
      while (ClassExists(destinationName + i)) {
        i++;
      }

      destinationName += i;
    }

    String header = "public class " + destinationName + " extends " + target.getSimpleName() + " {\n\n}";

    return header;
  }

  //Helper function that checks if a class with the specified name exists
  private boolean ClassExists(String className) {
    try {
      Class.forName(className);
      return true;
    } catch(ClassNotFoundException e) {
      return false;
    }
  }
}

