public class DateFunctionBuilder {

    public static Function<LocalDate, List<LocalDate>> constructDateFunction(int[] dates, LocalDate dtStart) {
        return (LocalDate dt) -> {
            List<LocalDate> datesList = new ArrayList<>();
            for (int date : dates) {
                LocalDate newDt = dt.with(TemporalAdjusters.lastDayOfMonth()).plusDays(date);
                if (newDt.isBefore(dtStart.with(TemporalAdjusters.lastDayOfMonth()))) {
                    newDt = dtStart.with(TemporalAdjusters.lastDayOfMonth()).plusDays(date);
                }
                datesList.add(newDt);
            }
            return datesList;
        };
    }
}

