        float x1 = positions[i];
        float y1 = positions[i + 1];
        float z1 = positions[i + 2];
        float x2 = positions[i + 3];
        float y2 = positions[i + 4];
        float z2 = positions[i + 5];
        float x3 = positions[i + 6];
        float y3 = positions[i + 7];
        float z3 = positions[i + 8];
        float ux = x2 - x1;
        float uy = y2 - y1;
        float uz = z2 - z1;
        float vx = x3 - x1;
        float vy = y3 - y1;
        float vz = z3 - z1;
        float nx = (uy * vz) - (uz * vy);
        float ny = (uz * vx) - (ux * vz);
        float nz = (ux * vy) - (uy * vx);
        float length = (float) Math.sqrt(nx * nx + ny * ny + nz * nz);
        nx /= length;
        ny /= length;
        nz /= length;

        // Update the normals for the 3 vertices of the triangle
        normals.set(indices[i], normals.get(indices[i]) + nx);
        normals.set(indices[i + 1], normals.get(indices[i + 1]) + ny);
