        normals.set(indices[i + 5], normals.get(indices[i + 5]) + nz);

        normals.set(indices[i + 6], normals.get(indices[i + 6]) + nx);
        normals.set(indices[i + 7], normals.get(indices[i + 7]) + ny);
        normals.set(indices[i + 8], normals.get(indices[i + 8]) + nz);
