  int endLoop = functionString.indexOf("__LOOP_END");

  while (startLoop != -1 && endLoop != -1) {
    functionString = functionString.substring(0, startLoop) + functionString.substring(startLoop, endLoop).replace("__LOOP_BODY", "") + functionString.substring(endLoop + 10);
