    endLoop = functionString.indexOf("__LOOP_END");
  }

  int endFunction = functionString.lastIndexOf("}");
  int startReturn = functionString.lastIndexOf("return ");
  if (startReturn > endFunction) {
    functionString = functionString.substring(0, startReturn + 7) + "returned" + functionString.substring(startReturn + 7);
  }

  return functionString;
}

