import org.apache.avro.Schema;

public static boolean areSchemasEqual(Schema schema1, Schema schema2) {
    if (schema1 == null || schema2 == null) {
        return schema1 == schema2;   // if both null, return true, else false
    }
    if (schema1.getType() != schema2.getType()) {
        return false;
    }
    if (!schema1.getFullName().equals(schema2.getFullName())) {
        return false;
    }
    if (schema1.getFields().size() != schema2.getFields().size()) {
        return false;
    }
    if (schema1.getObjectProps().size() != schema2.getObjectProps().size()) {
        return false;
    }
    // check for field by field conformance or object props equality
    for (int i = 0; i < schema1.getFields().size(); i++) {
        if (!areFieldsEqual(schema1.getFields().get(i), schema2.getFields().get(i))) {
            return false;
        }
    }
    for (String key : schema1.getObjectProps().keySet()) {
        if (!schema1.getObjectProp(key).equals(schema2.getObjectProp(key))) {
            return false;
        }
    }
    return true;
}

private static boolean areFieldsEqual(Schema.Field field1, Schema.Field field2) {
    if (!field1.name().equals(field2.name())) {
        return false;
    }
    return areSchemasEqual(field1.schema(), field2.schema());
}

