public Element createOrUpdateElement(Object parent, String name, String type, Style style) {
	// Check if the parent is a valid group
    if (!(parent instanceof Group)) {
        return null;
    }

    Group group = (Group) parent;
    Element existingElement = group.getElementById(name);

    // If the element exists, update it
    if (existingElement != null) {
        existingElement.setType(type);
        existingElement.setStyle(style);
        return existingElement;
    }

    // If the element does not exist, create a new one
    Element newElement = new Element(type);
    newElement.setId(name);
    newElement.setStyle(style);

    // Generate a unique id for the element
    String uniqueId = generateUniqueId();
    newElement.setUniqueId(uniqueId);

    // Add the new element to the group
    group.addElement(newElement);
    return newElement;
}

private String generateUniqueId() {
    // Generate a unique id using a random number generator
    return "id" + System.currentTimeMillis() + (int) (Math.random() * 1000);
}

