                .childOption(ChannelOption.SO_KEEPALIVE, true);

        serverChannel = serverBootstrap.bind(socketAddress).syncUninterruptibly().channel();
    }

    public void stop() {
        serverChannel.close();
        acceptGroup.shutdownGracefully();
        clientGroup.shutdownGracefully();
    }
}

