    public static List<String> constructWindows(List<String> words, int windowSize) {
        List<String> windows = new ArrayList<>();
        int wordCount = words.size();
        for (int i = 0; i < wordCount; i++) {
            StringBuilder windowBuilder = new StringBuilder();
            for (int j = i - windowSize + 1; j <= i + windowSize - 1; j++) {
                if (j >= 0 && j < wordCount) {
                    windowBuilder.append(words.get(j));
                } else {
                    windowBuilder.append("PAD");
                }
                windowBuilder.append(" ");
            }
