public List<LineString> extractSections(List<Coordinate> coordinates, double width) {
    List<LineString> sections = new ArrayList<>();

    for (int i = 0; i < coordinates.size() - 1; i++) {
        Coordinate start = coordinates.get(i);
        Coordinate end = coordinates.get(i + 1);

        double angle = Math.atan2(end.y - start.y, end.x - start.x);

        double x1 = start.x - 0.5 * width * Math.sin(angle);
        double x2 = end.x - 0.5 * width * Math.sin(angle);
        double x3 = end.x + 0.5 * width * Math.sin(angle);
        double x4 = start.x + 0.5 * width * Math.sin(angle);

        double y1 = start.y + 0.5 * width * Math.cos(angle);
        double y2 = end.y + 0.5 * width * Math.cos(angle);
        double y3 = end.y - 0.5 * width * Math.cos(angle);
        double y4 = start.y - 0.5 * width * Math.cos(angle);

        sections.add(GEOMETRY_FACTORY.createLineString(new Coordinate[]{
                new Coordinate(x1, y1),
                new Coordinate(x2, y2),
                new Coordinate(x3, y3),
                new Coordinate(x4, y4),
                new Coordinate(x1, y1)
        }));
    }

    return sections;
}

