public ElemVariable getReferencedVariable(SourceLocator locator) {
    if (locator instanceof ElemTemplateElement) {
        ElemTemplateElement parent = (ElemTemplateElement) locator;
        while (parent != null) {
            if (parent instanceof ElemForEach) {
                // check if this sub-expression belongs to a variable reference in a for-each instruction
                final ElemForEach forEach = (ElemForEach) parent;
                final QName attributeName = getAttributeName();
                if (attributeName != null && attributeName.equals(Constants.ATTRNAME_SELECT)) {
                    final String select = getValue();
                    if (select != null) {
                        final StringTokenizer tokenizer = new StringTokenizer(select, "{}", true);
                        String token;
                        boolean insideBraces = false;
                        while (tokenizer.hasMoreTokens()) {
                            token = tokenizer.nextToken();
                            if (token.equals("{")) {
                                insideBraces = true;
                            } else if (token.equals("}")) {
                                insideBraces = false;
                            } else if (!insideBraces) {
                                // found a sub-expression that is not inside braces, it must reference a variable
                                final ElemVariable variable = forEach.getVariableOrParam(QName.get(token, parent));
                                if (variable != null) {
                                    return variable;
                                }
                            }
                        }
                    }
                }
            }
            // loop up to the nearest ElemTemplateElement to check if it defines the referenced variable
            parent = parent.getParentElem();
            if (parent instanceof ElemTemplate) {
                final ElemVariable variable = ((ElemTemplate) parent).getVariableOrParam(getVariableQName());
                if (variable != null) {
                    return variable;
                }
            }
        }
    }
    return null;
}

