public void verifyParameters(Map<String, String> parameters, String url, String method, String secret) throws LtiVerificationException {
    try {
        StringBuilder sb = new StringBuilder();
        sb.append(method.toUpperCase()).append("&")
          .append(URLEncoder.encode(url, "UTF-8")).append("&");

        SortedMap<String, String> sorted = new TreeMap<>(parameters);
        Iterator<Map.Entry<String, String>> it = sorted.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, String> entry = it.next();
            String key = entry.getKey();
            String value = entry.getValue();
            sb.append(URLEncoder.encode(key, "UTF-8")).append("=")
              .append(URLEncoder.encode(value, "UTF-8"));
            if (it.hasNext()) {
                sb.append("&");
            }
        }

        String calculatedSignature = calculateSignature(sb.toString(), secret);
        String receivedSignature = parameters.get("oauth_signature");
        if (!calculatedSignature.equals(receivedSignature)) {
            throw new LtiVerificationException("Failed to verify oauth_signature");
        }
    } catch (UnsupportedEncodingException e) {
        throw new LtiVerificationException("Failed to verify parameters", e);
    }
}

private String calculateSignature(String baseString, String keyString) throws LtiVerificationException {
    try {
        SecretKey key = new SecretKeySpec((keyString).getBytes("UTF-8"), "HmacSHA1");
        Mac mac = Mac.getInstance("HmacSHA1");
        mac.init(key);
        byte[] bytes = mac.doFinal(baseString.getBytes("UTF-8"));
        return Base64.getEncoder().encodeToString(bytes);
    } catch (NoSuchAlgorithmException | InvalidKeyException | UnsupportedEncodingException e) {
        throw new LtiVerificationException("Failed to calculate signature", e);
    }
}

