public String getValueBySchemaType(Object value, Schema schema) {
    if(value == null || schema == null) {
        return null;
    }
    String schemaType = schema.getType();
    switch(schemaType) {
        case "string":
            return String.valueOf(value);
        case "number":
            return String.valueOf(value);
        case "integer":
            return String.valueOf(value);
        case "boolean":
            return String.valueOf(value);
        case "array":
            if (value instanceof ArrayList) {
                ArrayList<Object> list = (ArrayList<Object>) value;
                if (!list.isEmpty()) {
                    return getValueBySchemaType(list.get(0), schema.getItemSchema());
                }
            }
            break;
        case "object":
            if (value instanceof Map) {
                Map<Object, Object> map = (Map<Object, Object>) value;
                Schema propertySchema = schema.getPropertySchema();
                if(propertySchema != null) {
                    for (Map.Entry<Object, Object> entry : map.entrySet()) {
                        Object key = entry.getKey();
                        if (key instanceof String && propertySchema.containsProperty((String) key)) {
                            return getValueBySchemaType(entry.getValue(), propertySchema.getPropertySchema((String) key));
                        }
                    }
                }
            }
            break;
        default:
            break;
    }
    return null;
}

