        CallNode callNode = (CallNode) n;
        if ("valueOf".equals(callNode.getName()) && callNode.getArguments().size() == 1) {
            Node argument = callNode.getArguments().get(0);
            if (argument instanceof StringLiteral) {
                StringLiteral stringLiteral = (StringLiteral) argument;
                return new StringLiteral(stringLiteral.getValue());
            } else if (argument instanceof NullLiteral) {
                return new StringLiteral("null");
            } else if (argument instanceof UndefinedLiteral) {
                return new StringLiteral("null");
            } else if (argument instanceof BinaryExpression) {
                BinaryExpression binaryExpression = (BinaryExpression) argument;
                if (binaryExpression.getOperator() == Operator.PLUS) {
                    Node left = binaryExpression.getLeft();
                    Node right = binaryExpression.getRight();
                    if (left instanceof StringLiteral || right instanceof StringLiteral) {
                        return new StringLiteral(binaryExpression.toString());
                    }
                }
            }
        }
    }
    return n;
}

