public void deactivateLicas(AdManagerServices adManagerServices, Session session, long lineItemId) throws ApiException, RemoteException {
    LineItemServiceInterface lineItemService = adManagerServices.get(session, LineItemServiceInterface.class);
    LineItemPage page = lineItemService.getLineItemsByStatement(new StatementBuilder()
            .where("id = " + lineItemId)
            .toStatement());
    if (page.getResults() == null) {
        System.out.println("No line items found for ID " + lineItemId);
        return;
    }

    LineItem lineItem = page.getResults()[0];
    System.out.println("Deactivating LICAs for line item with ID " + lineItemId);

    if (lineItem.getIsDfpCreativeAllowed()) {
        System.out.println("Line item allows only DFP hosted creatives. Skipping.");
        return;
    }

    // Remove all LICAs.
    List<Long> licasToRemove = new ArrayList<>();
    for (Long licaId : lineItem.getLineItemCreativeAssociationIds()) {
        licasToRemove.add(licaId);
    }

    // Deactivate the LICAs.
    List<LineItemCreativeAssociationOperation> licaOps = new ArrayList<>();
    for (Long licaId : licasToRemove) {
        LineItemCreativeAssociation lineItemCreativeAssociation = new LineItemCreativeAssociation();
        lineItemCreativeAssociation.setLineItemId(lineItemId);
        lineItemCreativeAssociation.setCreativeId(-1L); // Deactivate.
        lineItemCreativeAssociation.setId(licaId);
        lineItemCreativeAssociation.setStatus(CreativeWrapperStatus.NON_WRAPPER);
        licaOps.add(new LineItemCreativeAssociationOperation(lineItemCreativeAssociation, new StatementBuilder()
                .toStatement()));
    }

    // Update the LICAs on the server.
    lineItemCreativeAssociationService.performLineItemCreativeAssociationAction(licaOps.toArray(new LineItemCreativeAssociationOperation[licaOps.size()]));
    System.out.println("Deactivated " + licaOps.size() + " LICAs from line item with ID " + lineItemId);
}

