public static void copyDeclaredMethods(Class<?> source, Class<?> destination, Class<?>... exceptions) {
    Method[] methods = source.getDeclaredMethods();
    for (Method method : methods) {
        if (exceptions.length > 0) {
            boolean found = false;
            for (Class<?> exception : exceptions) {
                if (Arrays.asList(method.getExceptionTypes()).contains(exception)) {
                    found = true;
                    break;
                }
            }
            if (!found) continue;
        }
        int modifiers = method.getModifiers();
        if (Modifier.isStatic(modifiers) || Modifier.isPrivate(modifiers)) continue;
        Method newMethod = null;
        try {
            newMethod = destination.getMethod(method.getName(), method.getParameterTypes());
            if (newMethod.getReturnType() != method.getReturnType()) continue;
        } catch (NoSuchMethodException e) {
            // do nothing
        }
        if (newMethod == null) {
            try {
                newMethod = destination.getDeclaredMethod(method.getName(), method.getParameterTypes());
                newMethod.setAccessible(true);
            } catch (NoSuchMethodException e) {
                // do nothing
            }
        }
        if (newMethod == null) continue;
        if (Modifier.isFinal(newMethod.getModifiers())) continue;
        newMethod.setAccessible(true);
        try {
            MethodAccessor methodAccessor = MethodAccessorGenerator.generateMethodAccessor(method);
            MethodAccessor newMethodAccessor = MethodAccessorGenerator.generateMethodAccessor(newMethod);
            for (int i = 0; i < method.getParameterTypes().length; i++) {
                Class<?> paramType = method.getParameterTypes()[i];
                if (paramType.isPrimitive()) continue;
                Class<?> newParamType = newMethod.getParameterTypes()[i];
                if (!paramType.isAssignableFrom(newParamType)) continue;
                Object defaultValue = methodAccessor.invokeDefault(method.getDefaultValue(), i);
                newMethodAccessor.invokeDefault(newMethod.getDefaultValue(), i, defaultValue);
            }
        } catch (Throwable e) {
            // do nothing
        }
    }
}

