        op = 1;
        for (oi = 0; oi < oldnd; oi++) {
            op *= olddims[oi];
        }
        if (np != op) {

            return null;
        }
        if (np == 0) {

            return null;
        }

        oi = 0;
        oj = 1;
        ni = 0;
        nj = 1;
