    for (int row = 0; row < rectGrid.length; row++) {
        for (int col = 0; col < rectGrid[0].length; col++) {
            double lat = rectGrid[row][col].getLat();
            double lon = rectGrid[row][col].getLon();
            double distance = Math.sqrt(Math.pow(wantLat - lat, 2) + Math.pow(wantLon - lon, 2));
            if (distance < bestDistance) {
                bestDistance = distance;
                bestRow = row;
                bestCol = col;
            }
        }
    }

    rectIndex[0] = bestRow;
    rectIndex[1] = bestCol;

    return (bestRow != -1 && bestCol != -1);
}

