import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.GZIPOutputStream;

public void prepareLogFilesForTransfer(String logDirectory) {
    File dir = new File(logDirectory);

    for (File file : dir.listFiles()) {
        if (file.getName().endsWith(".log") && !file.getName().endsWith(".gz")) {
            try {
                // Open the file for reading
                FileInputStream in = new FileInputStream(file);

                // Create a new GZIPped file for writing
                File outFile = new File(file.getAbsolutePath() + ".gz.tmp");
                GZIPOutputStream out = new GZIPOutputStream(new FileOutputStream(outFile));

                // Stream the original file contents into the new GZIPped file
                byte[] buffer = new byte[8192];
                int length;
                while ((length = in.read(buffer)) > 0) {
                    out.write(buffer, 0, length);
                }

                // Close the streams
                out.close();
                in.close();

                // Rename the original file to include .old in the filename
                File oldFile = new File(file.getAbsolutePath() + ".old.tmp");
                file.renameTo(oldFile);

                // Rename the new GZIPped file to replace the original file
                outFile.renameTo(file);

                // Rename the original file to include .gz in the filename
                oldFile.renameTo(new File(file.getAbsolutePath() + ".gz"));
            } catch (IOException e) {
                // If the operation fails, the original file is unmodified and we move on to the next file
                continue;
            }
        }
    }
}

