public static void sort(int[] data, int start, int end, IntComparator comp) {
    if (start < end) {
        int pivotIndex = partition(data, start, end, comp);
        sort(data, start, pivotIndex, comp);
        sort(data, pivotIndex + 1, end, comp);
    }
}

private static int partition(int[] data, int start, int end, IntComparator comp) {
    int pivot = data[start];
    int i = start - 1;
    int j = end + 1;

    while (true) {
        do {
            i++;
        } while (comp.compare(data[i], pivot) < 0);

        do {
            j--;
        } while (comp.compare(data[j], pivot) > 0);

        if (i >= j) {
            return j;
        }

        swap(data, i, j);
    }
}

private static void swap(int[] data, int i, int j) {
    int temp = data[i];
    data[i] = data[j];
    data[j] = temp;
}

