public static <T> List<T> actualTopologicalSort(Graph<T> graph, TopologicalSortType type) throws CyclePresentException, IllegalArgumentException {
    if (!graph.isDirected() || graph.hasSelfLoops()) {
        throw new IllegalArgumentException("Graph must be directed and free of self-loops");
    }

    List<T> sorted = new ArrayList<>();
    Map<T, Integer> inDegree = new HashMap<>();
    Queue<T> queue = new LinkedList<>();
    for (T node : graph.getAllNodes()) {
        inDegree.put(node, graph.getInDegree(node));
        if (inDegree.get(node) == 0) {
            queue.add(node);
        }
    }

    while (!queue.isEmpty()) {
        T node = queue.remove();
        sorted.add(node);
        for (T neighbor : graph.getNeighbors(node)) {
            int newDegree = inDegree.get(neighbor) - 1;
            if (newDegree < 0) {
                throw new CyclePresentException("Cycle found in the graph");
            }
            inDegree.put(neighbor, newDegree);
            if (newDegree == 0) {
                queue.add(neighbor);
            }
        }
    }

    if (sorted.size() != graph.getAllNodes().size()) {
        throw new CyclePresentException("Cycle found in the graph");
    }

    if (type == TopologicalSortType.REVERSE_POST_ORDER) {
        Collections.reverse(sorted);
    }

    return sorted;
}

