public static Bitmap stackBlurByJniBitmap(Bitmap original, int radius, int parts) {

    // Calculate the increment size for each part
    int increment = (int) (original.getWidth() / (float) parts);

    // Ensure increment is at least 1
    if (increment < 1) {
        increment = 1;
    }

    // Create a new bitmap to store the result
    Bitmap bitmap = Bitmap.createBitmap(original.getWidth(), original.getHeight(), original.getConfig());

    // Apply blur to each part
    for (int i = 0; i < parts; i++) {
        int x = i * increment;
        int width = increment;
        if (i == parts - 1) {
            width = original.getWidth() - x;
        }

        // Get the part of the bitmap to blur
        Bitmap partBitmap = Bitmap.createBitmap(original, x, 0, width, original.getHeight());

        // Apply the StackBlur algorithm to the part
        partBitmap = StackBlur.blurNatively(partBitmap, radius, false);

        // Draw the part onto the result bitmap
        Canvas canvas = new Canvas(bitmap);
        canvas.drawBitmap(partBitmap, x, 0, null);
    }

    // Return the blurred bitmap
    return bitmap;
}

