        for (TimephasedData timephasedData : list) {
            if (currentDate.after(timephasedData.getStart()) && currentDate.before(timephasedData.getEnd())) {
                TimephasedData dataToAdd = new TimephasedData();
                dataToAdd.setStart(currentDate);
                dataToAdd.setEnd(getEndOfDay(currentDate));
                dataToAdd.setWork(timephasedData.getWork() / getDaysBetween(timephasedData.getStart(), timephasedData.getEnd()));
                outputList.add(dataToAdd);
            }
        }
        cal.add(Calendar.DAY_OF_MONTH, 1);
        currentDate = cal.getTime();
    }
    return outputList;
}

private int getDaysBetween(Date start, Date end) {
    long diff = end.getTime() - start.getTime();
    return (int) TimeUnit.DAYS.convert(diff, TimeUnit.MILLISECONDS);
}

private Date getEndOfDay(Date date) {
    Calendar calendar = Calendar.getInstance();
    calendar.setTime(date);
    calendar.set(Calendar.HOUR_OF_DAY, 23);
    calendar.set(Calendar.MINUTE, 59);
    calendar.set(Calendar.SECOND, 59);
    calendar.set(Calendar.MILLISECOND, 999);
    return calendar.getTime();
}

