import com.datastax.driver.core.HostDistance;

import java.util.function.Predicate;

private Predicate<Host> getHostFilterPredicate(String hostFilterPolicy) {
    switch (hostFilterPolicy) {
        case "LOCAL":
            return host -> host.getDatacenter() != null && host.getDatacenter().equals("local");
        case "REMOTE":
            return host -> host.getDatacenter() != null && !host.getDatacenter().equals("local");
        case "NEAREST":
            return host -> host.getDistance(HostDistance.LOCAL) == HostDistance.LOCAL;
        default:
            throw new IllegalArgumentException("Invalid host filter policy: " + hostFilterPolicy);
    }
}

