public static void sortAndFollow(int[] values, int[] valuesToFollow) {
    int n = values.length;
    int tempValue, tempIndex;

    for (int i = 0; i < n-1; i++) {
        for (int j = 0; j < n-i-1; j++) {
            if (values[j] > values[j+1]) {
                // swap values[j] and values[j+1]
                tempValue = values[j];
                values[j] = values[j+1];
                values[j+1] = tempValue;

                // swap the corresponding values in valuesToFollow array
                if (valuesToFollow != null) {
                    tempIndex = valuesToFollow[j];
                    valuesToFollow[j] = valuesToFollow[j+1];
                    valuesToFollow[j+1] = tempIndex;
                }
            }
        }
    }
}

