import java.util.*;

public class IteratorRemoveDuplicates<T> implements Iterator<T> {

    private final Iterator<T> originalIterator;
    private final Comparator<T> comparator;
    private T nextUnique;

    public IteratorRemoveDuplicates(Iterator<T> originalIterator, Comparator<T> comparator) {
        this.originalIterator = originalIterator;
        this.comparator = comparator;
    }

    @Override
    public boolean hasNext() {
        while (nextUnique == null && originalIterator.hasNext()) {
            nextUnique = originalIterator.next();
            while (originalIterator.hasNext() && comparator.compare(nextUnique, originalIterator.peek()) == 0) {
                originalIterator.next();
            }
        }

        return nextUnique != null;
    }

    @Override
    public T next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }

        T toReturn = nextUnique;
        nextUnique = null;
        return toReturn;
    }

    @Override
    public void remove() {
        throw new UnsupportedOperationException("IteratorRemoveDuplicates does not support remove()");
    }
}

