import java.util.*;

public class HuffmanTree {
    private Node root;

    private static class Node implements Comparable<Node> {
        private final int count;
        private final char value;
        private final Node left;
        private final Node right;

        Node(int count, char value, Node left, Node right) {
            this.count = count;
            this.value = value;
            this.left = left;
            this.right = right;
        }

        boolean isLeaf() {
            return left == null && right == null;
        }

        @Override
        public int compareTo(Node other) {
            return this.count - other.count;
        }
    }

    public HuffmanTree(Map<Character, Integer> freqMap) {
        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (Map.Entry<Character, Integer> entry : freqMap.entrySet()) {
            pq.offer(new Node(entry.getValue(), entry.getKey(), null, null));
        }

        while (pq.size() > 1) {
            Node left = pq.poll();
            Node right = pq.poll();
            Node parent = new Node(left.count + right.count, '\0', left, right);
            pq.offer(parent);
        }

        root = pq.poll();
    }

    public Map<Character, String> encode() {
        Map<Character, String> map = new HashMap<>();
        encode(root, "", map);
        return map;
    }

    private void encode(Node node, String prefix, Map<Character, String> map) {
        if (node == null) {
            return;
        }
        if (node.isLeaf()) {
            map.put(node.value, prefix);
        }
        encode(node.left, prefix + "0", map);
        encode(node.right, prefix + "1", map);
    }
}

