import javax.xml.bind.DatatypeConverter;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public static boolean verifyPasswordSha(String rawPassword, String encodedPassword) {
    String algorithm = "SHA";
    if (encodedPassword.startsWith("{SSHA}")) {
        algorithm = "SHA-1";
        encodedPassword = encodedPassword.substring(6);
    }

    byte[] decoded = DatatypeConverter.parseBase64Binary(encodedPassword);
    byte[] salt = null;
    byte[] hash = null;

    if (algorithm.equals("SHA-1")) {
        int len = decoded.length;
        salt = new byte[len - 20];
        hash = new byte[20];
        System.arraycopy(decoded, 0, salt, 0, len - 20);
        System.arraycopy(decoded, len - 20, hash, 0, 20);
    } else {
        salt = new byte[8];
        System.arraycopy(decoded, 0, salt, 0, 8);
        hash = new byte[decoded.length - 8];
        System.arraycopy(decoded, 8, hash, 0, decoded.length - 8);
    }

    MessageDigest md = null;
    try {
        md = MessageDigest.getInstance(algorithm);
        md.reset();
        md.update(rawPassword.getBytes());
        md.update(salt);
    } catch (NoSuchAlgorithmException e) {
        e.printStackTrace();
    }
    byte[] digest = md.digest();

    if (algorithm.equals("SHA-1")) {
        if (MessageDigest.isEqual(digest, hash)) {
            return true;
        } else {
            md.reset();
            md.update(rawPassword.getBytes());
            md.update(salt);
            byte[] altDigest = md.digest();
            byte[] altHash = new byte[20];
            System.arraycopy(hash, 0, altHash, 0, 20);
            if (MessageDigest.isEqual(altDigest, altHash)) {
                return true;
            }
        }
    } else {
        if (MessageDigest.isEqual(digest, hash)) {
            return true;
        }
    }
    return false;
}

