import org.bouncycastle.crypto.macs.HMac;
import org.bouncycastle.crypto.params.KeyParameter;
import org.bouncycastle.util.encoders.Hex;

public boolean matches(CharSequence rawPassword, String encodedPassword) {
    if (!encodedPassword.toLowerCase().startsWith("{ssha}")) {
        return false;
    }

    byte[] salt = Hex.decode(encodedPassword.substring(6));
    byte[] passwordBytes = new byte[rawPassword.length()];
    for (int i = 0; i < rawPassword.length(); i++) {
        passwordBytes[i] = (byte) rawPassword.charAt(i);
    }

    HMac hmac = new HMac(new SHA1Digest());
    hmac.init(new KeyParameter(salt));
    hmac.update(passwordBytes, 0, passwordBytes.length);

    byte[] out = new byte[hmac.getMacSize()];
    hmac.doFinal(out, 0);

    String expected = "{SSHA}" + Hex.toHexString(out);
    return expected.equalsIgnoreCase(encodedPassword);
}

