public static long parseDuration(String duration) {
    long millis = 0;
    Pattern p = Pattern.compile("(\\d+)([a-z]{1,2})");
    Matcher m = p.matcher(duration);
    while(m.find()){
        int value = Integer.parseInt(m.group(1));
        String unit = m.group(2);
        switch(unit){
            case "d":
                millis += value * 86400000;
                break;
            case "h":
                millis += value * 3600000;
                break;
            case "mn":
                millis += value * 60000;
                break;
            case "s":
                millis += value * 1000;
                break;
            case "ms":
                millis += value;
                break;
            default:
                throw new IllegalArgumentException("Invalid duration unit: " + unit);
        }
    }
    return millis;
}

