    double b = p2.x - p3.x;
    double c = p1.y - p0.y;
    double d = p2.y - p3.y;

    double det = a*d - b*c;
    if (det == 0) {
        return null;
    }

    double e = p2.x - p0.x;
    double f = p2.y - p0.y;

    double t = (e*d - b*f) / det;
    double s = (a*f - e*c) / det;

    if (s < 0) {
        s = 0;
    } else if (s > 1) {
        s = 1;
    }

    if (t < 0) {
        t = 0;
    } else if (t > 1) {
