public static int findMarkdownLink(StringBuilder aOut, String sIn, int nStart, char eToken) {
    int nLength = sIn.length();
    if (nStart >= nLength) {
        return -1;
    }
    int nEnd = sIn.indexOf(eToken, nStart);
    if (nEnd == -1 || nEnd == nStart+1) {
        return -1;
    }
    String sLink = sIn.substring(nStart+1, nEnd);
    int nLinkLen = sLink.length();
    if (nLinkLen == 0) {
        return -1;
    }
    if (sLink.charAt(0) == '^' || sLink.charAt(0) == '~' ) {
        sLink = sLink.substring(1);
        nLinkLen--;
    }
    if (nLinkLen == 0) {
        return -1;
    }
    char c = sLink.charAt(0);
    int nPos = 1;
    while (nPos < nLinkLen && (c == '#' || c == '.' || Character.isWhitespace(c))) {
        c = sLink.charAt(nPos++);
    }
    if (c == ':') {
        aOut.append(sIn, nStart, nEnd+1);
        return nEnd+1;
    }
    return -1;
}

