    // Check if the string is long enough to contain a valid link
    if (nStart + 4 > sIn.length()) {
        return -1;
    }

    // Check if the string starts with a valid link
    if (!sIn.substring(nStart, nStart + 4).equals("[[")) {
        return -1;
    }

    // Find the end of the link
    int nEnd = sIn.indexOf("]]", nStart);
    if (nEnd == -1) {
        return -1;
    }

    // Check if the link is valid
    String link = sIn.substring(nStart + 2, nEnd);
    if (link.indexOf("|") == -1) {
        return -1;
    }

    // Add the link to the output
    aOut.append(link);

    // Return the new position
    return nEnd + 2;
}

