public String runProductInfoCommand(String installDirectory, String action) throws PluginExecutionException {
    String command = installDirectory + "/bin/productInfo " + action;
    String output = "";
    try {
        Process process = Runtime.getRuntime().exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            output += line + "\n";
        }
        process.waitFor();
        if (process.exitValue() != 0) {
            throw new PluginExecutionException("productInfo command exited with non-zero status: " + process.exitValue());
        }
    } catch (IOException e) {
        throw new PluginExecutionException("Error executing productInfo command: " + e.getMessage(), e);
    } catch (InterruptedException e) {
        throw new PluginExecutionException("Execution of productInfo command interrupted: " + e.getMessage(), e);
    }
    return output;
}

